	/**
	 * Actualiza un registro de CEDIS en xxcm_historico_correos con fecha anterior al 2025-05-30
	 * y devuelve la fecha utilizada en formato yyyy-MM-dd.
	 *
	 * @param usuario usuario a consultar en BD
	 * @return fecha utilizada en formato yyyy-MM-dd
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	public String actualizarRegistroCedisConFechaAnterior(String usuario) throws Exception {
	    String dbUrl = GlobalVariables.DB_URL_Cometa;
	    String dbUser = GlobalVariables.DB_USER_Cometa;
	    String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	    String PCPERFIL =
	            "select key_value from xxcm_user_keys " +
	            "where short_name = 'PCPERFIL' " +
	            "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

	    String PCRFC =
	            "select key_value from xxcm_user_keys " +
	            "where short_name in ('PCRFC', 'PCSUPPLIERID') " +
	            "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "') " +
	            "limit 1;";

	    String fechaObjetivo = "2025-05-29";

	    try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	         Statement stmt = connection.createStatement();
	         ResultSet rsPerfil = stmt.executeQuery(PCPERFIL)) {

	        String perfil = null;
	        if (rsPerfil.next()) {
	            perfil = rsPerfil.getString("key_value");
	        }

	        String rfc = null;
	        if (perfil == null || (!"ADMIN".equalsIgnoreCase(perfil) && !"OXXO_OS".equalsIgnoreCase(perfil))) {
	            try (ResultSet rsRfc = stmt.executeQuery(PCRFC)) {
	                if (rsRfc.next()) {
	                    rfc = rsRfc.getString("key_value");
	                } else {
	                    throw new Exception("No se obtuvo PCRFC o PCSUPPLIERID para el usuario: " + usuario);
	                }
	            }
	        }

	        String selectId;
	        if (perfil != null && ("ADMIN".equalsIgnoreCase(perfil) || "OXXO_OS".equalsIgnoreCase(perfil))) {
	            selectId =
	                    "select id " +
	                    "from xxcm_historico_correos " +
	                    "where origen = 'cedis' " +
	                    "order by id desc " +
	                    "limit 1;";
	        } else {
	            selectId =
	                    "select id " +
	                    "from xxcm_historico_correos " +
	                    "where origen = 'cedis' " +
	                    "and supplier_id = '" + rfc + "' " +
	                    "order by id desc " +
	                    "limit 1;";
	        }

	        String idRegistro;
	        try (ResultSet rsId = stmt.executeQuery(selectId)) {
	            if (!rsId.next()) {
	                throw new Exception("No se obtuvo ID en xxcm_historico_correos para origen cedis.");
	            }
	            idRegistro = rsId.getString("id");
	        }

	        String updateFecha =
	                "UPDATE xxcm_historico_correos " +
	                "SET body = jsonb_set( " +
	                "        body, '{Fecha_Encabezado}', " +
	                "        to_jsonb('" + fechaObjetivo + "'::date) " +
	                "    ), " +
	                "    created_at = '" + fechaObjetivo + "'::timestamp(3), " +
	                "    fecha_registro = '" + fechaObjetivo + "'::timestamp(3) " +
	                "WHERE id = " + idRegistro + " " +
	                "  AND origen = 'cedis';";

	        int updated = stmt.executeUpdate(updateFecha);
	        if (updated <= 0) {
	            throw new Exception("No se actualizo ningun registro CEDIS con la fecha objetivo.");
	        }

	        return fechaObjetivo;
	    }
	}
