	/**
	 * Selecciona una fecha exacta en el calendario y consulta comprobantes
	 *
	 * @param fechainicio fecha inicial en formato yyyy-MM-dd o yyyy-MM-dd HH:mm:ss
	 * @param screenshot true o false para guardar evidencia
	 * @return true si la consulta se ejecuta correctamente
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Octubre 2025
	 */
	public boolean busquedaFiltroFechaExacta(String fechainicio, boolean screenshot) throws Exception{
		try {

	        String fechaOriginal = fechainicio;
	        LocalDate fechaConvert;

	        try {
	        	fechaConvert = LocalDateTime.parse(fechaOriginal, DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")).toLocalDate();
	        } catch (Exception ex) {
	        	fechaConvert = LocalDate.parse(fechaOriginal, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	        }

	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
	        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

	        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
	        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

	        By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
	        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

	        if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	        }

	        clickYear(driver, wait, fechaConvert.getYear());
	        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());
	        clickDay(driver, wait, fechaConvert.minusDays(1).getDayOfMonth());
	        clickDay(driver, wait, fechaConvert.getDayOfMonth());

	        wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));
	        
	        if (consultarComprobantes(true)) {
	        	return true;
	        } else {
	        	return false;
	        }

		}catch (Exception e) {			
			testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
			throw new Exception ("Error " + e.getMessage());			
		}
	}
	/**
	 * Metodo para validar la busqueda con filtro de fecha en calendario
	 * considerando solo registros <= 999 y no mayor a 3 meses,
	 * tomando en cuenta los valores seleccionados en los dropdowns del filtro.
	 *
	 * @param usuario Usuario a validar en BD para obtener perfil y RFC/Plaza
	 * @param screenshot true o false para registrar evidencia
	 * @return true si el filtro de fechas se visualiza y se selecciona correctamente
	 * @throws Exception en caso de error en BD o UI
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	public boolean SelecFechaConFiltrosDropdown(String usuario, boolean screenshot) throws Exception {
	    try {
	        boolean result = false;

	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	        String dbUser = GlobalVariables.DB_USER_Cometa;
	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	        String FechaBD = null;

	        if (!u.isDisplayed(xmlRangoFechas)) {
	            return false;
	        }

	        u.highLight(xmlRangoFechas);

	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Se visualiza el filtro del rango de fechas");
	            testCase.addScreenShotCurrentStep(u, "FiltroFechas");
	        }

	        u.unhighLight(xmlRangoFechas);
	        result = true;

	        List<String> proveedores = obtenerValoresSeleccionadosNgSelect("Proveedor");
	        List<String> fuentesAbasto = obtenerValoresSeleccionadosNgSelect("FA (Fuente de Abasto)");
	        List<String> zonas = obtenerValoresSeleccionadosNgSelect("Zona");
	        List<String> regiones = obtenerValoresSeleccionadosNgSelect("Región");
	        List<String> plazas = obtenerValoresSeleccionadosNgSelect("Plaza");
	        List<String> tiendas = obtenerValoresSeleccionadosNgSelect("Tienda");

	        System.out.println("Proveedor seleccionado: " + proveedores);
	        System.out.println("FA seleccionada: " + fuentesAbasto);
	        System.out.println("Zona seleccionada: " + zonas);
	        System.out.println("Region seleccionada: " + regiones);
	        System.out.println("Plaza seleccionada: " + plazas);
	        System.out.println("Tienda seleccionada: " + tiendas);

	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword)) {

	            String perfil = obtenerKeyUsuario(connection, usuario, "PCPERFIL");
	            System.out.println("Perfil usuario: " + perfil);

	            StringBuilder sql = new StringBuilder();
	            List<String> params = new ArrayList<>();

	            sql.append("select date(fecha)::text as fecha ")
	               .append("from public.xxcm_dv ")
	               .append("where 1=1 ");
	            if (perfil != null && !"ADMIN".equalsIgnoreCase(perfil) && !"OXXO_OS".equalsIgnoreCase(perfil)) {

	                if ("OXXO_PLAZA".equalsIgnoreCase(perfil)) {
	                    String plazaUsuario = obtenerKeyUsuario(connection, usuario, "PCPLAZA");
	                    if (plazaUsuario == null || plazaUsuario.trim().isEmpty()) {
	                        System.out.println("No se obtuvo PCPLAZA para el usuario");
	                        return false;
	                    }
	                    sql.append("and cr_desc_plaza = ? ");
	                    params.add(plazaUsuario.trim());
	                } else {
	                    String rfcUsuario = obtenerKeyUsuario(connection, usuario, "PCRFC");
	                    if (rfcUsuario == null || rfcUsuario.trim().isEmpty()) {
	                        rfcUsuario = obtenerKeyUsuario(connection, usuario, "PCSUPPLIERID");
	                    }

	                    if (rfcUsuario == null || rfcUsuario.trim().isEmpty()) {
	                        System.out.println("No se obtuvo PCRFC o PCSUPPLIERID para el usuario");
	                        return false;
	                    }

	                    sql.append("and proveedor_rfc = ? ");
	                    params.add(rfcUsuario.trim());
	                }
	            }

	            agregarFiltroIn(sql, params, "proveedor", proveedores);
	            agregarFiltroIn(sql, params, "fuente_de_abasto", fuentesAbasto);
	            agregarFiltroIn(sql, params, "zona", zonas);
	            agregarFiltroIn(sql, params, "region", regiones);
	            agregarFiltroIn(sql, params, "plaza", plazas);
	            agregarFiltroIn(sql, params, "tienda", tiendas);

	            sql.append("group by 1 ")
	               .append("having count(*) < 1000 ")
	               .append("order by 1 desc ")
	               .append("limit 1");

	            System.out.println("SQL final: " + sql);

	            try (PreparedStatement ps = connection.prepareStatement(sql.toString())) {

	                for (int i = 0; i < params.size(); i++) {
	                    ps.setString(i + 1, params.get(i));
	                    System.out.println("Parametro " + (i + 1) + ": " + params.get(i));
	                }

	                try (ResultSet rsFecha = ps.executeQuery()) {
	                    if (rsFecha.next()) {
	                        FechaBD = rsFecha.getString("fecha");
	                        System.out.println("Fecha seleccionada BD: " + FechaBD);
	                    } else {
	                        System.out.println("Sin fecha valida con los filtros seleccionados");
	                        return false;
	                    }
	                }
	            }
	        }

	        if (FechaBD == null || FechaBD.trim().isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("No se obtuvo fecha valida desde BD");
	            return false;
	        }

	        centroDescargasFiltradoFecha = FechaBD;

	        LocalDate fechaConvert = LocalDate.parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd"));

	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
	        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

	        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
	        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

	        By btnPeriodo = By.xpath(
	            "//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]"
	        );

	        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

	        if (driver.findElements(
	                By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")
	            ).isEmpty()) {
	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	        }

	        clickYear(driver, wait, fechaConvert.getYear());
	        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

	        clickDay(driver, wait, fechaConvert.getDayOfMonth());
	        clickDay(driver, wait, fechaConvert.getDayOfMonth());

	        wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));

	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep(
	                "Se selecciono rango de fechas: " +
	                fechaConvert.minusDays(1) + " a " + fechaConvert +
	                " considerando los filtros seleccionados en los dropdowns"
	            );
	            testCase.addScreenShotCurrentStep(u, "RangoFechasSeleccionado");
	        }

	        return result;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error en SelecFechaConFiltrosDropdown: " + e.getMessage());
	    }
	}

	/**
	 * Obtiene los valores seleccionados de un ng-select a partir del placeholder visible.
	 *
	 * @param placeholder Texto del placeholder del dropdown
	 * @return Lista de valores seleccionados en el ng-select
	 * @throws Exception en caso de error al obtener los elementos
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private List<String> obtenerValoresSeleccionadosNgSelect(String placeholder) throws Exception {
	    List<String> valores = new ArrayList<>();

	    String xpath = "//ng-select[.//div[contains(@class,'ng-placeholder') and normalize-space()='" + placeholder + "']]"
	                 + "//span[contains(@class,'ng-value-label')]";

	    List<WebElement> elementos = u.getDriver().findElements(By.xpath(xpath));

	    for (WebElement elemento : elementos) {
	        String texto = elemento.getText();
	        if (texto != null && !texto.trim().isEmpty()) {
	            valores.add(texto.trim());
	        }
	    }

	    return valores;
	}

	/**
	 * Agrega un filtro tipo IN a la consulta SQL de forma dinamica.
	 *
	 * @param sql StringBuilder con la consulta SQL
	 * @param params Lista de parametros de la consulta
	 * @param columna Nombre de la columna en BD
	 * @param valores Valores seleccionados para filtrar
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private void agregarFiltroIn(StringBuilder sql, List<String> params, String columna, List<String> valores) {
	    if (valores == null || valores.isEmpty()) {
	        return;
	    }

	    sql.append("and ").append(columna).append(" in (");

	    for (int i = 0; i < valores.size(); i++) {
	        sql.append("?");
	        if (i < valores.size() - 1) {
	            sql.append(", ");
	        }
	        params.add(valores.get(i));
	    }

	    sql.append(") ");
	}

	/**
	 * Obtiene el valor de una llave del usuario desde xxcm_user_keys.
	 *
	 * @param connection Conexion activa a la BD
	 * @param usuario Usuario a consultar
	 * @param shortName Llave a buscar en xxcm_user_keys
	 * @return Valor de la llave o null si no existe
	 * @throws Exception en caso de error al consultar
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private String obtenerKeyUsuario(Connection connection, String usuario, String shortName) throws Exception {
	    String sql =
	        "select uk.key_value " +
	        "from xxcm_user_keys uk " +
	        "inner join xxcm_usuarios u on u.usuario_id = uk.usuario_id " +
	        "where u.usuario = ? and uk.short_name = ? " +
	        "limit 1";

	    try (PreparedStatement ps = connection.prepareStatement(sql)) {
	        ps.setString(1, usuario);
	        ps.setString(2, shortName);

	        try (ResultSet rs = ps.executeQuery()) {
	            if (rs.next()) {
	                return rs.getString("key_value");
	            }
	        }
	    }

	    return null;
	}
	/**
	 * Obtiene la lista ordenada de cantidades quantity_items desde la base de datos
	 * usando la funcion public.get_cambios_fisicos_directos_pendientes_paginated,
	 * aplicando automaticamente los filtros correspondientes al usuario.
	 *
	 * La logica de filtros considera el perfil del usuario:
	 * ADMIN y OXXO_OS sin filtros,
	 * OXXO_PLAZA por PCPLAZA,
	 * y el resto por PCRFC.
	 *
	 * El orden de los registros se conserva exactamente como lo devuelve la funcion.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param dbUrl url de conexion a la base de datos
	 * @param dbUser usuario de la base de datos
	 * @param dbPassword password de la base de datos
	 * @param usuario usuario con el que se obtendran las llaves de configuracion
	 * @param screenshot true o false para saber si se guardara evidencia
	 * @return Lista ordenada con los valores quantity_items obtenidos de la BD
	 * @throws Exception
	 */
	private List<String> obtenerCantidadesPendientesDesdeBD(String dbUrl, String dbUser, String dbPassword, String usuario, boolean screenshot) throws Exception {
	    List<String> cantidades = new ArrayList<>();

	    String sqlPerfil =
	        "select key_value " +
	        "from xxcm_user_keys " +
	        "where short_name = 'PCPERFIL' " +
	        "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

	    String sqlKeys =
	        "select short_name, key_value " +
	        "from xxcm_user_keys " +
	        "where short_name in ('PCRFC','PCSUPPLIERID','PCPLAZA') " +
	        "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

	    String sqlFuncion =
	        "select * from public.get_cambios_fisicos_directos_pendientes_paginated(" +
	        "?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?" +
	        ");";

	    String sqlCantidad =
	        "select quantity_items " +
	        "from xxcm_cambios_fisicos_pendientes " +
	        "where id = ?";

	    try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	         Statement stmt = connection.createStatement();
	         ResultSet rsPerfil = stmt.executeQuery(sqlPerfil)) {

	        if (!rsPerfil.next()) {
	            if (screenshot) {
	                testCase.addTextEvidenceCurrentStep("No se obtuvo PCPERFIL para el usuario: " + usuario);
	            }
	            return cantidades;
	        }

	        String perfil = rsPerfil.getString("key_value");
	        if (perfil == null) perfil = "";
	        String perfilUp = perfil.trim().toUpperCase();

	        boolean esAdminGlobal = "ADMIN".equals(perfilUp) || "OXXO_OS".equals(perfilUp);

	        String pcrfc = null;
	        String pcsupplierid = null;
	        String pcplaza = null;

	        try (ResultSet rsKeys = stmt.executeQuery(sqlKeys)) {
	            while (rsKeys.next()) {
	                String sn = rsKeys.getString("short_name");
	                String kv = rsKeys.getString("key_value");
	                if (sn == null) {
	                    continue;
	                }

	                if ("PCRFC".equalsIgnoreCase(sn)) {
	                    pcrfc = kv;
	                } else if ("PCSUPPLIERID".equalsIgnoreCase(sn)) {
	                    pcsupplierid = kv;
	                } else if ("PCPLAZA".equalsIgnoreCase(sn)) {
	                    pcplaza = kv;
	                }
	            }
	        }

	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Keys usuario: PCRFC=" + safeTxt(pcrfc)
	                    + " PCSUPPLIERID=" + safeTxt(pcsupplierid)
	                    + " PCPLAZA=" + safeTxt(pcplaza));
	        }

	        int pPage = 1;
	        int pPageSize = 999999;

	        Array pRfcArray = null;
	        Array pCrDescPlazasArray = null;

	        if (!esAdminGlobal) {
	            if ("OXXO_PLAZA".equalsIgnoreCase(perfilUp)) {
	                if (pcplaza == null || pcplaza.trim().isEmpty()) {
	                    if (screenshot) {
	                        testCase.addTextEvidenceCurrentStep("Perfil OXXO_PLAZA sin PCPLAZA para usuario: " + usuario);
	                    }
	                    return cantidades;
	                }
	                pCrDescPlazasArray = connection.createArrayOf("text", new String[] { pcplaza.trim() });
	            } else {
	                if (pcrfc == null || pcrfc.trim().isEmpty()) {
	                    if (screenshot) {
	                        testCase.addTextEvidenceCurrentStep("Perfil " + perfil + " sin PCRFC para usuario: " + usuario);
	                    }
	                    return cantidades;
	                }

	                String[] rfcs = splitValores(pcrfc);
	                pRfcArray = connection.createArrayOf("text", rfcs);
	            }
	        }

	        try (PreparedStatement psFuncion = connection.prepareStatement(sqlFuncion)) {
	            psFuncion.setInt(1, pPage);
	            psFuncion.setInt(2, pPageSize);

	            if (pRfcArray != null) psFuncion.setArray(3, pRfcArray);
	            else psFuncion.setNull(3, java.sql.Types.ARRAY);

	            psFuncion.setNull(4, java.sql.Types.ARRAY);
	            psFuncion.setNull(5, java.sql.Types.ARRAY);
	            psFuncion.setNull(6, java.sql.Types.ARRAY);
	            psFuncion.setNull(7, java.sql.Types.ARRAY);
	            psFuncion.setNull(8, java.sql.Types.ARRAY);

	            if (pCrDescPlazasArray != null) psFuncion.setArray(9, pCrDescPlazasArray);
	            else psFuncion.setNull(9, java.sql.Types.ARRAY);

	            psFuncion.setNull(10, java.sql.Types.ARRAY);
	            psFuncion.setNull(11, java.sql.Types.ARRAY);
	            psFuncion.setNull(12, java.sql.Types.DATE);
	            psFuncion.setNull(13, java.sql.Types.DATE);
	            psFuncion.setNull(14, java.sql.Types.VARCHAR);

	            try (ResultSet rsFuncion = psFuncion.executeQuery();
	                 PreparedStatement psCantidad = connection.prepareStatement(sqlCantidad)) {

	                while (rsFuncion.next()) {
	                    String id = rsFuncion.getString(1);

	                    psCantidad.setString(1, id);

	                    try (ResultSet rsCantidad = psCantidad.executeQuery()) {
	                        if (rsCantidad.next()) {
	                            cantidades.add(rsCantidad.getString("quantity_items"));
	                        } else {
	                            cantidades.add("");
	                        }
	                    }
	                }
	            }
	        }
	    }

	    return cantidades;
	}
	/**
	 * Valida que la columna "Cantidad" mostrada en el grid de Cambios Fisicos Pendientes
	 * coincida exactamente con el campo "quantity_items" obtenido desde la base de datos
	 * PostgreSQL, respetando el mismo orden de los registros que devuelve la funcion
	 * public.get_cambios_fisicos_directos_pendientes_paginated.
	 *
	 * La comparacion se realiza por posicion, considerando todas las paginas del grid.
	 * Los filtros requeridos para ejecutar la funcion se obtienen automaticamente
	 * a partir del usuario y sus llaves de configuracion en BD.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param screenshot true o false para saber si se guardara screenshot en el reporte de evidencia
	 * @param usuario usuario con el que se obtendran PCPERFIL, PCRFC y PCPLAZA
	 * @return True/False - Indica si todas las cantidades del grid coinciden con quantity_items de la BD
	 * @throws Exception
	 */
	public boolean validarCantidadGridVsBDCFPendientes(boolean screenshot, String usuario) throws Exception {
	    try {
	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	        String dbUser = GlobalVariables.DB_USER_Cometa;
	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	        List<DetalleCFGrid> registrosGrid = obtenerTodosLosDetallesGridCFdet(false);

	        if (registrosGrid == null || registrosGrid.isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("No se encontraron registros en el grid para validar la columna Cantidad contra la BD");
	            return false;
	        }

	        List<String> cantidadesBD = obtenerCantidadesPendientesDesdeBD(dbUrl, dbUser, dbPassword, usuario, screenshot);

	        if (cantidadesBD == null || cantidadesBD.isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("No se obtuvieron registros desde la BD para validar quantity_items");
	            return false;
	        }

	        if (registrosGrid.size() != cantidadesBD.size()) {
	            String msg = "La cantidad de registros no coincide entre grid y BD. Grid: "
	                    + registrosGrid.size() + " BD: " + cantidadesBD.size();
	            testCase.addTextEvidenceCurrentStep(msg);
	            System.out.println(msg);
	            return false;
	        }

	        List<String> diferencias = new ArrayList<>();

	        for (int i = 0; i < registrosGrid.size(); i++) {
	            DetalleCFGrid registroGrid = registrosGrid.get(i);

	            String cantidadGrid = limpiarNumero(registroGrid.getCantidad());
	            String cantidadBD = limpiarNumero(cantidadesBD.get(i));

	            if (!cantidadGrid.equals(cantidadBD)) {
	                diferencias.add("Fila " + (i + 1)
	                        + " Cantidad Grid=" + registroGrid.getCantidad()
	                        + " BD quantity_items=" + cantidadesBD.get(i));
	            }
	        }

	        if (!diferencias.isEmpty()) {
	            StringBuilder sb = new StringBuilder();
	            sb.append("Se encontraron diferencias entre la columna Cantidad del grid y quantity_items de la BD. Total diferencias: ")
	              .append(diferencias.size());

	            int limite = Math.min(diferencias.size(), 10);
	            for (int i = 0; i < limite; i++) {
	                sb.append("\n").append(diferencias.get(i));
	            }

	            testCase.addCodeEvidenceCurrentStep(sb.toString());
	            System.out.println(sb.toString());
	            return false;
	        }

	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("La columna Cantidad del grid coincide con quantity_items de la BD en todos los registros y paginas");
	            testCase.addScreenShotCurrentStep(u, "Cantidad_Grid_vs_BD_CF_Pendientes");
	        }

	        System.out.println("La columna Cantidad del grid coincide con quantity_items de la BD");
	        return true;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error al validar la columna Cantidad del grid contra quantity_items de la BD: " + e.getMessage());
	    }
	}

	/**
	 * Limpia un valor numerico representado como texto para facilitar la comparacion.
	 * Elimina espacios al inicio y fin. Si el valor es null regresa cadena vacia.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param valor valor numerico en texto
	 * @return valor limpio para comparacion
	 * @throws Exception
	 */
	private String limpiarNumero(String valor) throws Exception {
	    if (valor == null) {
	        return "";
	    }
	    return valor.trim();
	}
	/**
	 * DTO para almacenar un registro del grid de Cambios Fisicos Detalles.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	public static class DetalleCFGrid {

	    private String crTienda;
	    private String nombreTienda;
	    private String remision;
	    private String fechaProgramacion;
	    private String sku;
	    private String descripcion;
	    private String diasTranscurridos;
	    private String cantidad;
	    private String costo;

	    public DetalleCFGrid(String crTienda, String nombreTienda, String remision, String fechaProgramacion,
	            String sku, String descripcion, String diasTranscurridos, String cantidad, String costo) {
	        this.crTienda = limpiarTexto(crTienda);
	        this.nombreTienda = limpiarTexto(nombreTienda);
	        this.remision = limpiarTexto(remision);
	        this.fechaProgramacion = normalizarFechaTexto(fechaProgramacion);
	        this.sku = limpiarTexto(sku);
	        this.descripcion = limpiarTexto(descripcion);
	        this.diasTranscurridos = normalizarEnteroTexto(diasTranscurridos);
	        this.cantidad = normalizarEnteroTexto(cantidad);
	        this.costo = normalizarMonedaTexto(costo);
	    }

	    public String getCrTienda() {
	        return crTienda;
	    }

	    public String getNombreTienda() {
	        return nombreTienda;
	    }

	    public String getRemision() {
	        return remision;
	    }

	    public String getFechaProgramacion() {
	        return fechaProgramacion;
	    }

	    public String getSku() {
	        return sku;
	    }

	    public String getDescripcion() {
	        return descripcion;
	    }

	    public String getDiasTranscurridos() {
	        return diasTranscurridos;
	    }

	    public String getCantidad() {
	        return cantidad;
	    }

	    public String getCosto() {
	        return costo;
	    }

	    public String getLlaveComparacion() {
	        return crTienda + "||" + nombreTienda + "||" + remision + "||" + fechaProgramacion + "||" + sku + "||"
	                + descripcion + "||" + diasTranscurridos + "||" + cantidad + "||" + costo;
	    }

	    @Override
	    public String toString() {
	        return "CR=" + crTienda
	                + ", Tienda=" + nombreTienda
	                + ", Remision=" + remision
	                + ", Fecha=" + fechaProgramacion
	                + ", SKU=" + sku
	                + ", Descripcion=" + descripcion
	                + ", Dias=" + diasTranscurridos
	                + ", Cantidad=" + cantidad
	                + ", Costo=" + costo;
	    }

	    @Override
	    public int hashCode() {
	        return Objects.hash(getLlaveComparacion());
	    }

	    @Override
	    public boolean equals(Object obj) {
	        if (!(obj instanceof DetalleCFGrid)) {
	            return false;
	        }
	        DetalleCFGrid other = (DetalleCFGrid) obj;
	        return Objects.equals(this.getLlaveComparacion(), other.getLlaveComparacion());
	    }
	}
	/**
	 * Obtiene todos los registros visibles del grid de Cambios Fisicos Detalles recorriendo
	 * todas las paginas del paginador de izquierda a derecha.
	 *
	 * Se posiciona primero en la primera pagina y despues avanza con el boton "siguiente"
	 * hasta agotar todas las paginas disponibles.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param screenshot true o false para saber si se guardara screenshot en el reporte de evidencia
	 * @return Lista con todos los registros encontrados en todas las paginas del grid
	 * @throws Exception
	 */
	private List<DetalleCFGrid> obtenerTodosLosDetallesGridCFdet(boolean screenshot) throws Exception {
	    try {
	        List<DetalleCFGrid> registros = new ArrayList<>();
	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(15));

	        By tabla = By.xpath("//table[contains(@class,'mat-mdc-table')]");
	        By filas = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[contains(@class,'mat-mdc-row')]");
	        By btnSiguiente = xmlPaginaSiguienteButtonCFdet;

	        u.waitWebElement(tabla, 60, 5);
	        u.scrollToElement(tabla);

	        if (!MensajeEspereDesaparece(false)) {
	            testCase.addTextEvidenceCurrentStep("Fallo al desaparecer el mensaje espere un momento antes de leer el grid");
	            return registros;
	        }

	        try {
	            WebElement botonPrimero = driver.findElement(xmlPaginaPrimeraPaginaButtonCFdet);
	            if (botonPrimero.isDisplayed() && botonPrimero.isEnabled()) {
	                clickBotonPaginacionCFdet("primero", false);
	                if (!MensajeEspereDesaparece(false)) {
	                    testCase.addTextEvidenceCurrentStep("Fallo al desaparecer el mensaje espere un momento al ir a la primera pagina");
	                    return registros;
	                }
	            }
	        } catch (Exception e) {
	            System.out.println("No fue posible ir a la primera pagina, se continuara desde la actual: " + e.getMessage());
	        }

	        boolean continuar = true;
	        int pagina = 1;

	        while (continuar) {
	            wait.until(ExpectedConditions.visibilityOfElementLocated(tabla));
	            wait.until(ExpectedConditions.presenceOfAllElementsLocatedBy(filas));
	            u.scrollToElement(tabla);

	            List<WebElement> filasPagina = driver.findElements(filas);
	            System.out.println("Pagina " + pagina + " - filas encontradas: " + filasPagina.size());

	            for (int i = 0; i < filasPagina.size(); i++) {
	                List<WebElement> celdas = filasPagina.get(i).findElements(By.xpath("./td"));

	                if (celdas.size() < 9) {
	                    System.out.println("Fila " + (i + 1) + " ignorada por no tener las 9 columnas esperadas. Columnas encontradas: " + celdas.size());
	                    continue;
	                }

	                String crTienda = celdas.get(0).getText();
	                String nombreTienda = celdas.get(1).getText();
	                String remision = celdas.get(2).getText();
	                String fechaProgramacion = celdas.get(3).getText();
	                String sku = celdas.get(4).getText();
	                String descripcion = celdas.get(5).getText();
	                String diasTranscurridos = celdas.get(6).getText();
	                String cantidad = celdas.get(7).getText();
	                String costo = celdas.get(8).getText();

	                DetalleCFGrid detalle = new DetalleCFGrid(
	                        crTienda,
	                        nombreTienda,
	                        remision,
	                        fechaProgramacion,
	                        sku,
	                        descripcion,
	                        diasTranscurridos,
	                        cantidad,
	                        costo
	                );

	                registros.add(detalle);
	            }

	            boolean botonSiguienteHabilitado = false;
	            try {
	                WebElement siguiente = driver.findElement(btnSiguiente);
	                botonSiguienteHabilitado = siguiente.isDisplayed() && siguiente.isEnabled();
	            } catch (Exception e) {
	                botonSiguienteHabilitado = false;
	            }

	            if (!botonSiguienteHabilitado) {
	                continuar = false;
	            } else {
	                String labelAntes = driver.findElement(xmlPaginacionLabelOFCFdet).getText().trim();

	                boolean pagino = clickBotonPaginacionCFdet("siguiente", false);
	                if (!pagino) {
	                    continuar = false;
	                } else {
	                    String labelDespues = driver.findElement(xmlPaginacionLabelOFCFdet).getText().trim();
	                    if (labelAntes.equals(labelDespues)) {
	                        continuar = false;
	                    } else {
	                        pagina++;
	                    }
	                }
	            }
	        }

	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Se obtuvieron " + registros.size() + " registros del grid de Cambios Fisicos Detalles en todas sus paginas");
	            testCase.addScreenShotCurrentStep(u, "Grid completo CF Detalles");
	        }

	        System.out.println("Total de registros obtenidos del grid CF detalles: " + registros.size());
	        return registros;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error al obtener todos los detalles del grid de Cambios Fisicos: " + e.getMessage());
	    }
	}
	/**
	 * Valida que el Excel descargado de Cambios Fisicos Detalles contenga exactamente
	 * los mismos registros mostrados en el grid, considerando todas las paginas.
	 *
	 * Se ignora la primera columna "Retek" del Excel y se comparan unicamente estas columnas:
	 * CR Tienda, Nombre de la tienda, Remision, Fecha de programacion, SKU, Descripcion,
	 * Dias transcurridos, Cantidad y Costo.
	 *
	 * La comparacion se realiza por contenido completo de cada fila, incluyendo registros repetidos.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param screenshot true o false para saber si se guardara screenshot en el reporte de evidencia
	 * @return True/False - Indica si el Excel contiene exactamente los mismos datos que el grid
	 * @throws Exception
	 */
	public boolean validarExcelVsGridCFDetalles(boolean screenshot) throws Exception {
	    FileInputStream fis = null;
	    Workbook workbook = null;

	    try {
	        List<DetalleCFGrid> registrosGrid = obtenerTodosLosDetallesGridCFdet(false);

	        if (registrosGrid == null || registrosGrid.isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("No se encontraron registros en el grid de Cambios Fisicos Detalles para comparar contra el Excel");
	            return false;
	        }

	        String nombreExcel = getLastDownloadedFileName();
	        if (nombreExcel == null || nombreExcel.trim().isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("No se encontro el nombre del Excel descargado");
	            return false;
	        }

	        String rutaDescargas = System.getProperty("user.home") + "\\Downloads\\";
	        File archivoExcel = new File(rutaDescargas + nombreExcel);

	        System.out.println("Ruta completa Excel: " + archivoExcel.getAbsolutePath());

	        if (!archivoExcel.exists()) {
	            testCase.addTextEvidenceCurrentStep("No existe el archivo Excel a validar: " + archivoExcel.getAbsolutePath());
	            return false;
	        }

	        fis = new FileInputStream(archivoExcel);
	        workbook = WorkbookFactory.create(fis);

	        Sheet sheet = workbook.getSheetAt(0);
	        DataFormatter formatter = new DataFormatter(new Locale("es", "MX"));

	        int headerRowIndex = encontrarFilaEncabezadosCFDetalles(sheet, formatter);
	        if (headerRowIndex == -1) {
	            testCase.addTextEvidenceCurrentStep("No se encontro la fila de encabezados esperada en el Excel");
	            return false;
	        }

	        Map<String, Integer> columnas = obtenerMapaColumnasCFDetalles(sheet.getRow(headerRowIndex), formatter);

	        String[] encabezadosEsperados = {
	                "CR TIENDA",
	                "NOMBRE DE LA TIENDA",
	                "REMISION",
	                "FECHA DE PROGRAMACION",
	                "SKU",
	                "DESCRIPCION",
	                "DIAS TRANSCURRIDOS",
	                "CANTIDAD",
	                "COSTO"
	        };

	        for (String encabezado : encabezadosEsperados) {
	            if (!columnas.containsKey(encabezado)) {
	                testCase.addTextEvidenceCurrentStep("No se encontro la columna obligatoria en el Excel: " + encabezado);
	                return false;
	            }
	        }

	        List<DetalleCFGrid> registrosExcel = new ArrayList<>();

	        for (int i = headerRowIndex + 1; i <= sheet.getLastRowNum(); i++) {
	            Row row = sheet.getRow(i);
	            if (row == null) {
	                continue;
	            }

	            String crTienda = obtenerValorCelda(row, columnas.get("CR TIENDA"), formatter);
	            String nombreTienda = obtenerValorCelda(row, columnas.get("NOMBRE DE LA TIENDA"), formatter);
	            String remision = obtenerValorCelda(row, columnas.get("REMISION"), formatter);
	            String fechaProgramacion = obtenerValorCelda(row, columnas.get("FECHA DE PROGRAMACION"), formatter);
	            String sku = obtenerValorCelda(row, columnas.get("SKU"), formatter);
	            String descripcion = obtenerValorCelda(row, columnas.get("DESCRIPCION"), formatter);
	            String diasTranscurridos = obtenerValorCelda(row, columnas.get("DIAS TRANSCURRIDOS"), formatter);
	            String cantidad = obtenerValorCelda(row, columnas.get("CANTIDAD"), formatter);
	            String costo = obtenerValorCelda(row, columnas.get("COSTO"), formatter);

	            boolean filaVacia = limpiarTexto(crTienda).isEmpty()
	                    && limpiarTexto(nombreTienda).isEmpty()
	                    && limpiarTexto(remision).isEmpty()
	                    && limpiarTexto(fechaProgramacion).isEmpty()
	                    && limpiarTexto(sku).isEmpty()
	                    && limpiarTexto(descripcion).isEmpty()
	                    && limpiarTexto(diasTranscurridos).isEmpty()
	                    && limpiarTexto(cantidad).isEmpty()
	                    && limpiarTexto(costo).isEmpty();

	            if (filaVacia) {
	                continue;
	            }

	            DetalleCFGrid detalleExcel = new DetalleCFGrid(
	                    crTienda,
	                    nombreTienda,
	                    remision,
	                    fechaProgramacion,
	                    sku,
	                    descripcion,
	                    diasTranscurridos,
	                    cantidad,
	                    costo
	            );

	            registrosExcel.add(detalleExcel);
	        }

	        if (registrosGrid.size() != registrosExcel.size()) {
	            testCase.addTextEvidenceCurrentStep("La cantidad de registros no coincide. Grid: " + registrosGrid.size()
	                    + " Excel: " + registrosExcel.size());
	            System.out.println("La cantidad de registros no coincide. Grid: " + registrosGrid.size()
	                    + " Excel: " + registrosExcel.size());
	            return false;
	        }

	        Map<String, Integer> conteoGrid = generarConteoRegistros(registrosGrid);
	        Map<String, Integer> conteoExcel = generarConteoRegistros(registrosExcel);

	        List<String> diferencias = new ArrayList<>();

	        for (Map.Entry<String, Integer> entry : conteoGrid.entrySet()) {
	            String llave = entry.getKey();
	            int cantidadGrid = entry.getValue();
	            int cantidadExcel = conteoExcel.containsKey(llave) ? conteoExcel.get(llave) : 0;

	            if (cantidadGrid != cantidadExcel) {
	                diferencias.add("Diferencia en registro: [" + llave + "] Grid=" + cantidadGrid + " Excel=" + cantidadExcel);
	            }
	        }

	        for (Map.Entry<String, Integer> entry : conteoExcel.entrySet()) {
	            String llave = entry.getKey();
	            if (!conteoGrid.containsKey(llave)) {
	                diferencias.add("Registro extra en Excel: [" + llave + "] cantidad=" + entry.getValue());
	            }
	        }

	        if (!diferencias.isEmpty()) {
	            StringBuilder sb = new StringBuilder();
	            sb.append("Se encontraron diferencias entre el grid y el Excel. Total diferencias: ").append(diferencias.size());

	            int limite = Math.min(diferencias.size(), 10);
	            for (int i = 0; i < limite; i++) {
	                sb.append("\n").append(diferencias.get(i));
	            }

	            testCase.addCodeEvidenceCurrentStep(sb.toString());
	            System.out.println(sb.toString());
	            return false;
	        }

	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("El Excel descargado contiene exactamente los mismos registros que el grid de Cambios Fisicos Detalles en todas las paginas");
	            testCase.addScreenShotCurrentStep(u, "Excel vs Grid CF Detalles");
	        }

	        System.out.println("El Excel coincide exactamente con el grid de Cambios Fisicos Detalles");
	        return true;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error al validar Excel vs Grid de Cambios Fisicos Detalles: " + e.getMessage());
	    } finally {
	        try {
	            if (workbook != null) {
	                workbook.close();
	            }
	        } catch (Exception e) {
	            System.out.println("No se pudo cerrar workbook: " + e.getMessage());
	        }
	        try {
	            if (fis != null) {
	                fis.close();
	            }
	        } catch (Exception e) {
	            System.out.println("No se pudo cerrar FileInputStream: " + e.getMessage());
	        }
	    }
	}
	/**
	 * Encuentra la fila de encabezados del Excel de Cambios Fisicos Detalles.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param sheet hoja del Excel a inspeccionar
	 * @param formatter formatter para obtener texto de las celdas
	 * @return indice de la fila de encabezados o -1 si no se encontro
	 */
	private int encontrarFilaEncabezadosCFDetalles(Sheet sheet, DataFormatter formatter) {
	    for (int i = 0; i <= Math.min(sheet.getLastRowNum(), 15); i++) {
	        Row row = sheet.getRow(i);
	        if (row == null) {
	            continue;
	        }

	        String c1 = normalizarNombreColumna(obtenerValorCelda(row, 1, formatter));
	        String c2 = normalizarNombreColumna(obtenerValorCelda(row, 2, formatter));
	        String c3 = normalizarNombreColumna(obtenerValorCelda(row, 3, formatter));
	        String c4 = normalizarNombreColumna(obtenerValorCelda(row, 4, formatter));

	        if ("CR TIENDA".equals(c1)
	                && "NOMBRE DE LA TIENDA".equals(c2)
	                && "REMISION".equals(c3)
	                && "FECHA DE PROGRAMACION".equals(c4)) {
	            return i;
	        }
	    }
	    return -1;
	}
	/**
	 * Obtiene el mapa de columnas del encabezado del Excel usando el nombre normalizado
	 * del encabezado como llave.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param headerRow fila de encabezados
	 * @param formatter formatter para obtener texto de las celdas
	 * @return mapa nombre de columna normalizado vs indice
	 */
	private Map<String, Integer> obtenerMapaColumnasCFDetalles(Row headerRow, DataFormatter formatter) {
	    Map<String, Integer> columnas = new LinkedHashMap<>();

	    for (int i = 0; i < headerRow.getLastCellNum(); i++) {
	        String nombre = normalizarNombreColumna(obtenerValorCelda(headerRow, i, formatter));
	        if (!nombre.isEmpty()) {
	            columnas.put(nombre, i);
	        }
	    }

	    return columnas;
	}
	/**
	 * Genera un mapa de conteo para comparar registros incluyendo duplicados.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param registros lista de registros a contar
	 * @return mapa llave de comparacion vs cantidad
	 */
	private Map<String, Integer> generarConteoRegistros(List<DetalleCFGrid> registros) {
	    Map<String, Integer> conteo = new LinkedHashMap<>();

	    for (DetalleCFGrid detalle : registros) {
	        String llave = detalle.getLlaveComparacion();
	        conteo.put(llave, conteo.getOrDefault(llave, 0) + 1);
	    }

	    return conteo;
	}
	/**
	 * Obtiene el texto de una celda del Excel.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param row fila a leer
	 * @param cellIndex indice de la celda
	 * @param formatter formatter para convertir la celda a texto
	 * @return valor de la celda como texto
	 */
	private String obtenerValorCelda(Row row, Integer cellIndex, DataFormatter formatter) {
	    try {
	        if (row == null || cellIndex == null) {
	            return "";
	        }
	        Cell cell = row.getCell(cellIndex);
	        if (cell == null) {
	            return "";
	        }
	        return formatter.formatCellValue(cell).trim();
	    } catch (Exception e) {
	        return "";
	    }
	}
	/**
	 * Normaliza el nombre de una columna para facilitar su comparacion.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param texto nombre original de la columna
	 * @return nombre normalizado
	 */
	private String normalizarNombreColumna(String texto) {
	    String valor = limpiarTexto(texto).toUpperCase();
	    valor = valor.replace("Ó", "O");
	    valor = valor.replace("Í", "I");
	    valor = valor.replace("Á", "A");
	    valor = valor.replace("É", "E");
	    valor = valor.replace("Ú", "U");
	    return valor;
	}
	/**
	 * Limpia un texto quitando espacios sobrantes y saltos de linea.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param texto texto original
	 * @return texto limpio
	 */
	private static String limpiarTexto(String texto) {
	    if (texto == null) {
	        return "";
	    }
	    return texto.replace("\n", " ")
	            .replace("\r", " ")
	            .replaceAll("\\s+", " ")
	            .trim();
	}
	/**
	 * Normaliza un texto de fecha al formato dd/MM/yyyy.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param fecha texto de fecha
	 * @return fecha normalizada
	 */
	private static String normalizarFechaTexto(String fecha) {
	    String valor = limpiarTexto(fecha).replace("-", "/");
	    return valor;
	}
	/**
	 * Normaliza un numero entero representado como texto.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param valor texto original
	 * @return valor entero normalizado sin decimales innecesarios
	 */
	private static String normalizarEnteroTexto(String valor) {
	    String texto = limpiarTexto(valor);
	    if (texto.isEmpty()) {
	        return "";
	    }

	    texto = texto.replace(",", "");

	    try {
	        BigDecimal bd = new BigDecimal(texto);
	        bd = bd.stripTrailingZeros();
	        return bd.toPlainString();
	    } catch (Exception e) {
	        return texto;
	    }
	}
	/**
	 * Normaliza un valor monetario dejando solo el numero con 2 decimales.
	 *
	 * Ejemplos:
	 * "$ 164.44" -> "164.44"
	 * "164.4400" -> "164.44"
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param valor texto monetario
	 * @return monto normalizado
	 */
	private static String normalizarMonedaTexto(String valor) {
	    String texto = limpiarTexto(valor);
	    if (texto.isEmpty()) {
	        return "";
	    }

	    texto = texto.replace("$", "")
	            .replace(",", "")
	            .trim();

	    try {
	        BigDecimal bd = new BigDecimal(texto).setScale(2, RoundingMode.HALF_UP);
	        return bd.toPlainString();
	    } catch (Exception e) {
	        return texto;
	    }
	}
