	/**
	 * Metodo que valida que las URLs de evidencia mostradas en la vista preliminar
	 * coincidan con las URLs incrustadas dentro del PDF correspondiente a la misma
	 * transferencia, localizado dentro del ultimo archivo ZIP descargado.
	 *
	 * El metodo obtiene todas las URLs de imagen provenientes de Azure Blob Storage
	 * desde la vista preliminar, obtiene automaticamente el numero de transferencia
	 * a partir del texto mostrado en pantalla, busca el ultimo ZIP descargado,
	 * lo descomprime, localiza el PDF correspondiente a la transferencia y valida
	 * que las URLs encontradas en las anotaciones del PDF coincidan con las del preview.
	 *
	 * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
	 * @return true si todas las URLs coinciden entre la vista preliminar y el PDF localizado dentro del ZIP, false si alguna no coincide
	 * @throws Exception si ocurre algun error durante la validacion
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	public boolean validarUrlsEvidenciaPDFvsPreviewMasiva(boolean screenshot) throws Exception {

	    try {

	        WebDriver driver = u.getDriver();

	        // 1. OBTENER URLS DE LA VISTA PRELIMINAR
	        List<WebElement> links = driver.findElements(By.xpath("//a[contains(@href,'blob.core.windows.net')]"));
	        List<String> urlsPreview = new ArrayList<>();

	        for (WebElement l : links) {
	            String href = l.getAttribute("href");
	            if (href != null && !href.trim().isEmpty()) {
	                href = href.replace("&amp;", "&").trim();
	                if (!urlsPreview.contains(href)) {
	                    urlsPreview.add(href);
	                }
	            }
	        }

	        System.out.println("URLs encontradas en preview: " + urlsPreview.size());

	        if (urlsPreview.isEmpty()) {
	            return false;
	        }

	        // 2. OBTENER NUMERO DE TRANSFERENCIA DESDE LA VISTA PRELIMINAR
	        String textoPreview = driver.findElement(By.tagName("body")).getText();
	        String numeroTransferencia = obtenerNumeroTransferenciaDesdePreview(textoPreview, urlsPreview);

	        System.out.println("Numero de transferencia detectado: " + numeroTransferencia);

	        if (numeroTransferencia == null || numeroTransferencia.trim().isEmpty()) {
	            return false;
	        }

	        // 3. OBTENER ULTIMO ZIP DESCARGADO
	        File carpeta = new File(System.getProperty("user.home") + "/Downloads");
	        File[] zips = carpeta.listFiles((dir, name) -> name.toLowerCase().endsWith(".zip"));

	        if (zips == null || zips.length == 0) {
	            return false;
	        }

	        File ultimoZip = Arrays.stream(zips)
	                .max(Comparator.comparingLong(File::lastModified))
	                .orElse(null);

	        if (ultimoZip == null) {
	            return false;
	        }

	        System.out.println("ZIP encontrado: " + ultimoZip.getName());

	        // 4. DESCOMPRIMIR ZIP Y BUSCAR PDF DE LA TRANSFERENCIA
	        File carpetaExtraida = descomprimirZipEnCarpetaTemporal(ultimoZip);

	        if (carpetaExtraida == null || !carpetaExtraida.exists()) {
	            return false;
	        }

	        File pdfTransferencia = buscarPdfPorTransferencia(carpetaExtraida, numeroTransferencia);

	        if (pdfTransferencia == null || !pdfTransferencia.exists()) {
	            if (screenshot) {
	                testCase.addScreenShotCurrentStep(u, "PDF_transferencia_no_encontrado_en_ZIP");
	            }
	            return false;
	        }

	        System.out.println("PDF encontrado: " + pdfTransferencia.getName());

	        // 5. EXTRAER URLS DESDE EL PDF (ANOTACIONES)
	        List<String> urlsPdf = extraerUrlsDesdeAnotacionesPDF(pdfTransferencia);

	        System.out.println("URLs encontradas en PDF (anotaciones): " + urlsPdf.size());

	        if (urlsPdf.isEmpty()) {
	            if (screenshot) {
	                testCase.addScreenShotCurrentStep(u, "PDF_sin_URLs_anotaciones");
	            }
	            return false;
	        }

	        // 6. VALIDAR URLS PREVIEW EXISTAN EN PDF
	        for (String urlPreview : urlsPreview) {

	            String up = urlPreview.replace("&amp;", "&").trim();
	            boolean found = false;

	            for (String urlPdf : urlsPdf) {
	                String pdfu = urlPdf.replace("&amp;", "&").trim();

	                if (pdfu.equals(up)) {
	                    found = true;
	                    break;
	                }
	            }

	            System.out.println("URL PREVIEW: " + up);
	            System.out.println("COINCIDE EN PDF (anotaciones): " + found);

	            if (!found) {
	                if (screenshot) {
	                    testCase.addScreenShotCurrentStep(u, "URL_no_coincide_con_anotaciones_PDF");
	                }
	                return false;
	            }
	        }

	        // 7. ABRIR PDF PARA EVIDENCIA
	        try {

	            Desktop.getDesktop().open(pdfTransferencia);
	            u.hardWait(4);

	            if (screenshot) {
	                testCase.addScreenShotCurrentStep("PDF_abierto_validacion_URLs_masiva");
	            }

	            Robot r = new Robot();
	            r.keyPress(KeyEvent.VK_ALT);
	            r.keyPress(KeyEvent.VK_F4);
	            r.keyRelease(KeyEvent.VK_F4);
	            r.keyRelease(KeyEvent.VK_ALT);

	            u.hardWait(2);

	        } catch (Exception e) {
	            System.err.println("No se pudo abrir o cerrar el PDF: " + e.getMessage());
	        }

	        return true;

	    } catch (Exception e) {

	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
	/**
	 * Metodo que obtiene el numero de transferencia a partir del texto completo
	 * de la vista preliminar y, en caso de no localizarlo ahi, intenta obtenerlo
	 * desde la primera URL encontrada en el preview.
	 *
	 * @param textoPreview texto completo visible en la vista preliminar
	 * @param urlsPreview lista de URLs encontradas en la vista preliminar
	 * @return numero de transferencia detectado o cadena vacia si no fue posible obtenerlo
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private String obtenerNumeroTransferenciaDesdePreview(String textoPreview, List<String> urlsPreview) {

	    if (textoPreview != null && !textoPreview.trim().isEmpty()) {

	        Pattern p = Pattern.compile("\\b\\d{10}\\b");
	        Matcher m = p.matcher(textoPreview);

	        while (m.find()) {
	            String candidato = m.group();
	            if (candidato != null && candidato.length() == 10) {
	                return candidato;
	            }
	        }
	    }

	    if (urlsPreview != null && !urlsPreview.isEmpty()) {

	        String url = urlsPreview.get(0).replace("&amp;", "&").trim();
	        Pattern p = Pattern.compile("xxbdo-cedis/(\\d+)/");
	        Matcher m = p.matcher(url);

	        if (m.find()) {
	            return m.group(1);
	        }
	    }

	    return "";
	}
	/**
	 * Metodo que descomprime un archivo ZIP dentro de una carpeta con el mismo
	 * nombre base del archivo comprimido.
	 *
	 * @param zip archivo ZIP a descomprimir
	 * @return carpeta donde fue extraido el contenido del ZIP
	 * @throws Exception si ocurre un error durante la descompresion
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private File descomprimirZipEnCarpetaTemporal(File zip) throws Exception {

	    String nombreZip = zip.getName();
	    String nombreBase = nombreZip.substring(0, nombreZip.lastIndexOf("."));
	    File carpetaDestino = new File(zip.getParentFile(), nombreBase);

	    if (!carpetaDestino.exists()) {
	        carpetaDestino.mkdirs();
	    }

	    byte[] buffer = new byte[4096];

	    ZipInputStream zis = new ZipInputStream(new FileInputStream(zip));
	    ZipEntry entry = zis.getNextEntry();

	    while (entry != null) {

	        File archivoDestino = new File(carpetaDestino, entry.getName());

	        if (entry.isDirectory()) {
	            archivoDestino.mkdirs();
	        } else {
	            File parent = archivoDestino.getParentFile();
	            if (parent != null && !parent.exists()) {
	                parent.mkdirs();
	            }

	            FileOutputStream fos = new FileOutputStream(archivoDestino);
	            int len;

	            while ((len = zis.read(buffer)) > 0) {
	                fos.write(buffer, 0, len);
	            }

	            fos.close();
	        }

	        zis.closeEntry();
	        entry = zis.getNextEntry();
	    }

	    zis.close();

	    return carpetaDestino;
	}
	/**
	 * Metodo que busca de forma recursiva el PDF correspondiente a una transferencia
	 * dentro de la carpeta descomprimida del ZIP.
	 *
	 * El patron esperado es Verificacion_numeroTransferencia_fecha.pdf.
	 *
	 * @param carpeta raiz donde se buscara el PDF
	 * @param numeroTransferencia numero de transferencia a localizar
	 * @return archivo PDF encontrado o null si no existe
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private File buscarPdfPorTransferencia(File carpeta, String numeroTransferencia) {

	    if (carpeta == null || !carpeta.exists()) {
	        return null;
	    }

	    File[] archivos = carpeta.listFiles();

	    if (archivos == null || archivos.length == 0) {
	        return null;
	    }

	    for (File f : archivos) {

	        if (f.isDirectory()) {
	            File encontrado = buscarPdfPorTransferencia(f, numeroTransferencia);
	            if (encontrado != null) {
	                return encontrado;
	            }
	        } else {
	            String nombre = f.getName();
	            if (nombre.toLowerCase().endsWith(".pdf")
	                    && nombre.contains("Verificacion_")
	                    && nombre.contains("_" + numeroTransferencia + "_")) {
	                return f;
	            }
	        }
	    }

	    return null;
	}
