	/**
	 * Metodo para extraer todas las URLs tipo http/https incrustadas en el PDF
	 * a traves de anotaciones de tipo Link (acciones URI), evitando problemas de
	 * texto partido por columnas o saltos de linea.
	 *
	 * @param pdf archivo PDF
	 * @return lista unica de URLs encontradas como hipervinculos
	 * @throws Exception si ocurre un error leyendo el PDF
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private List<String> extraerUrlsDesdeAnotacionesPDF(File pdf) throws Exception {

	    List<String> urls = new ArrayList<>();

	    PDDocument doc = Loader.loadPDF(pdf);

	    for (PDPage page : doc.getPages()) {

	        List<PDAnnotation> annots = page.getAnnotations();

	        for (PDAnnotation a : annots) {

	            if (a instanceof PDAnnotationLink) {

	                PDAnnotationLink link = (PDAnnotationLink) a;

	                if (link.getAction() instanceof PDActionURI) {

	                    PDActionURI uri = (PDActionURI) link.getAction();

	                    String u = uri.getURI();

	                    if (u != null) {
	                        u = u.trim().replace("&amp;", "&");
	                        if (!u.isEmpty() && !urls.contains(u)) {
	                            urls.add(u);
	                        }
	                    }
	                }
	            }
	        }
	    }

	    doc.close();

	    return urls;
	}

	/**
	 * Metodo para realizar la busqueda en el portal utilizando los filtros
	 * de "Tienda" y rango de "Fecha" en el modulo de recepcion de transferencias CEDIS.
	 *
	 * La informacion utilizada para los filtros se obtiene desde base de datos,
	 * consultando los registros con origen "cedis-devolucion" y fecha_registro
	 * mayor o igual al 01-06-2025. En base a este resultado se obtiene:
	 *
	 * - La tienda (cr_tienda) para aplicar en el filtro "Tienda".
	 * - La fecha_registro para aplicar en el filtro de calendario.
	 *
	 * Si el usuario tiene perfil ADMIN u OXXO_OS, la consulta no se limita por supplier,
	 * permitiendo utilizar cualquier registro disponible. Para otros perfiles se utiliza
	 * el supplier_id asociado al usuario para filtrar la informacion correspondiente.
	 *
	 * Antes de aplicar los filtros se valida que la tabla principal del modulo
	 * se encuentre visible en pantalla para asegurar que el contenido haya cargado.
	 *
	 * Finalmente se ejecuta la consulta en el portal utilizando los filtros aplicados
	 * y se generan evidencias visuales en caso de habilitar la captura de pantalla.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @return True/False - Indica si la busqueda con filtros de Tienda y Fecha
	 *         se ejecuto correctamente en el portal
	 * @throws Exception
	 * @param screenshot - true o false para saber si se guardara screenshot
	 *         en el reporte de evidencia
	 */
	public boolean busquedaFiltroPlazaFechaCedisVerif(String usuario, boolean screenshot) throws Exception {
	    try {
	        boolean result = true;

	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	        String dbUser = GlobalVariables.DB_USER_Cometa;
	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	        // Antes de tocar filtros, esperar a que cargue la tabla
	        By tablaCedis = By.xpath("/html/body/app-root/app-recepcion-de-transferencias/main/div[3]/mat-tab-group/div/mat-tab-body/div/div/app-tabla-entrega/div/table");
	        u.waitWebElement(tablaCedis, 120, 10);
	        String PCPERFIL = "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' "
	                + "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

	        String PCRFC = "select key_value "
	                + "from xxcm_user_keys "
	                + "where usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "') "
	                + "  and short_name in ('PCRFC','PCSUPPLIERID') "
	                + "order by case when short_name = 'PCRFC' then 0 else 1 end "
	                + "limit 1";

	        String perfil = null;
	        String supplierId = null;
	        boolean esAdmin = false;

	        String FechaBD = null;
	        String crTienda = null;

	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	             Statement stmt = connection.createStatement();
	             ResultSet rsPerfil = stmt.executeQuery(PCPERFIL)) {

	            if (rsPerfil.next()) {
	                perfil = rsPerfil.getString("key_value");
	                System.out.println("Usuario con perfil: " + perfil);
	            }

	            esAdmin = (perfil != null) && ("ADMIN".equalsIgnoreCase(perfil) || "OXXO_OS".equalsIgnoreCase(perfil));

	            if (!esAdmin) {
	                try (ResultSet rs2 = stmt.executeQuery(PCRFC)) {
	                    if (!rs2.next()) {
	                        System.out.println("No se encontró PCRFC/PCSUPPLIERID para el usuario: " + usuario);
	                        return false;
	                    }
	                    supplierId = rs2.getString("key_value");
	                }

	                if (supplierId == null || supplierId.trim().isEmpty()) {
	                    System.out.println("PCRFC/PCSUPPLIERID vacío para el usuario: " + usuario);
	                    return false;
	                }
	                supplierId = supplierId.trim();
	            }

	            String sql = ""
	                    + "SELECT h.id, h.fecha_registro, h.cr_tienda "
	                    + "FROM public.xxcm_historico_correos h "
	                    + "WHERE h.transferencia IN ( "
	                    + "    SELECT t.transferencia "
	                    + "    FROM public.xxcm_historico_cedis_view t "
	                    + "    WHERE t.fecha_registro::DATE >= ? "
	                    + "    GROUP BY t.transferencia "
	                    + ") "
	                    + "AND h.origen = ? ";

	            if (!esAdmin) {
	                sql += "AND h.suppliable_id = ? ";
	            }

	            sql += "ORDER BY h.fecha_registro DESC LIMIT 1;";

	            try (PreparedStatement ps = connection.prepareStatement(sql)) {
	                int idx = 1;
	                ps.setDate(idx++, java.sql.Date.valueOf(LocalDate.of(2025, 6, 1)));
	                ps.setString(idx++, "cedis-devolucion");
	                if (!esAdmin) {
	                	ps.setLong(idx++, Long.parseLong(supplierId));
	                }

	                try (ResultSet rs = ps.executeQuery()) {
	                    if (!rs.next()) {
	                        System.out.println("No se obtuvo registro para origen cedis-devolucion con fecha >= 2025-06-01."
	                                + (!esAdmin ? (" suppliable_id=" + supplierId) : " (ADMIN)"));
	                        return false;
	                    }

	                    java.sql.Timestamp ts = rs.getTimestamp("fecha_registro");
	                    if (ts == null) {
	                        System.out.println("fecha_registro viene null.");
	                        return false;
	                    }

	                    crTienda = rs.getString("cr_tienda");
	                    if (crTienda == null || crTienda.trim().isEmpty()) {
	                        System.out.println("cr_tienda viene vacio.");
	                        return false;
	                    }

	                    FechaBD = ts.toString();
	                    crTienda = crTienda.trim();

	                    System.out.println("Fecha seleccionada (fecha_registro): " + FechaBD);
	                    System.out.println("CR tienda (cr_tienda): " + crTienda);
	                }
	            }
	        }

	        LocalDate fechaConvert;
	        try {
	            fechaConvert = LocalDateTime.parse(FechaBD.replace(' ', 'T').substring(0, 19)).toLocalDate();
	        } catch (Exception ex) {
	            try {
	                fechaConvert = LocalDate.parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	            } catch (Exception ex2) {
	                fechaConvert = LocalDate.parse(FechaBD.substring(0, 10), DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	            }
	        }

	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	        // FILTRO TIENDA
	        By xmlFiltroTienda = By.xpath("//ng-select[.//div[contains(@class,'ng-placeholder') and normalize-space()='Tienda']]");
	        By inputTienda = By.xpath("//ng-select[.//div[contains(@class,'ng-placeholder') and normalize-space()='Tienda']]//input[@type='text']");
	        By opcionTienda = By.xpath("//div[contains(@class,'ng-option') and starts-with(normalize-space(),'" + crTienda + "')]");

	        if (!u.isDisplayed(xmlFiltroTienda)) {
	            System.out.println("No se encuentra el filtro Tienda en el portal.");
	            return false;
	        }

	        u.mouseOverAndClick(xmlFiltroTienda);
	        wait.until(ExpectedConditions.visibilityOfElementLocated(inputTienda));
	        driver.findElement(inputTienda).clear();
	        driver.findElement(inputTienda).sendKeys(crTienda);

	        wait.until(ExpectedConditions.visibilityOfElementLocated(opcionTienda));
	        if (screenshot) {
	            testCase.addScreenShotCurrentStep(u, "Dropdown_Tienda");
	        }
	        u.click(opcionTienda);
	        driver.findElement(By.tagName("body")).click();

	        // FILTRO FECHA
	        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
	        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

	        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
	        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

	        By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
	        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

	        if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	        }

	        clickYear(driver, wait, fechaConvert.getYear());

	        // Si tu helper es 0-based, cambia a (fechaConvert.getMonthValue() - 1)
	        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

	        clickDay(driver, wait, fechaConvert.getDayOfMonth());
	        clickDay(driver, wait, fechaConvert.getDayOfMonth());

	        wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));

	        consultarComprobantes(true);

	        return result;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}



	/**
	 * Metodo para validar los datos de las columnas "Fecha" y "Fecha ADMVA"
	 * en el Excel Masivo del registro seleccionado.
	 *
	 * Se valida que las fechas se encuentren en formato español (dd-MM-yyyy),
	 * normalizando previamente el valor en caso de venir en formato ISO (yyyy-MM-dd).
	 *
	 * La comparacion se realiza utilizando el "Folio" como llave principal,
	 * validando unicamente el registro seleccionado en el grid.
	 *
	 * Se abre el ultimo Excel descargado para generar evidencia (screenshot)
	 * y se cierra automaticamente al finalizar la validacion.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @return True/False - Indica si las columnas "Fecha" y "Fecha ADMVA"
	 *         cumplen con el formato español esperado
	 * @throws Exception
	 * @param screenshot - true o false para saber si se guardara screenshot en el reporte de evidencia
	 */
	public boolean validarFechaYFechaAdmvaExcelMasivo(boolean screenshot) {
	    FileInputStream fis = null;
	    Workbook wb = null;

	    try {
	        // Obtener ultimo Excel descargado
	        String home = System.getProperty("user.home") + "\\Downloads";
	        File last = getLastModified(home);
	        if (last == null || !last.exists()) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se encontro el ultimo archivo descargado en Downloads.");
	            return false;
	        }

	        fis = new FileInputStream(last);
	        wb = WorkbookFactory.create(fis);

	        Sheet sheet = wb.getSheetAt(0);
	        if (sheet == null) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se pudo abrir la hoja 0 del Excel.");
	            return false;
	        }

	        int colFolio = -1;
	        int colFecha = -1;
	        int colFechaAdmva = -1;

	        Row header = sheet.getRow(sheet.getFirstRowNum());
	        if (header != null) {
	            colFolio = findColumnIndex(header, "Folio");
	            colFecha = firstColIndex(header, new String[] { "Fecha" });
	            colFechaAdmva = firstColIndex(header, new String[] { "FECHA ADMVA", "Fecha ADMVA", "FECHA ADMVA ", "Fecha de Captura", "FECHA DE CAPTURA" });
	        }

	        if (colFolio < 0 || colFecha < 0 || colFechaAdmva < 0) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep(
	                "No se encontraron columnas requeridas en Excel. FolioIndex=" + colFolio +
	                " FechaIndex=" + colFecha + " FechaAdmvaIndex=" + colFechaAdmva
	            );
	            return false;
	        }

	        DataFormatter fmt = new DataFormatter();

	        int lastRow = sheet.getLastRowNum();
	        boolean encontro = false;

	        for (int r = header.getRowNum() + 1; r <= lastRow; r++) {
	            Row row = sheet.getRow(r);
	            if (row == null) continue;

	            String folioCell = getCellString(row.getCell(colFolio), fmt);
	            String folioExcel = extraerSoloDigitos(folioCell);

	            // Validar solo el folio seleccionado en el grid
	            String folioGrid = (ultimaDevolucionSeleccionada != null) ? extraerSoloDigitos(ultimaDevolucionSeleccionada.folio) : null;
	            if (folioGrid == null || folioGrid.trim().isEmpty()) {
	                if (screenshot) testCase.addTextEvidenceCurrentStep("No hay folio previo del grid para validar Fecha/Fecha ADMVA.");
	                return false;
	            }

	            if (folioExcel != null && folioExcel.equals(folioGrid)) {
	                encontro = true;

	                String fechaRaw = getCellString(row.getCell(colFecha), fmt);
	                String fechaAdmvaRaw = getCellString(row.getCell(colFechaAdmva), fmt);

	                String fechaNorm = normalizarFechaEspanol(fechaRaw);
	                String fechaAdmvaNorm = normalizarFechaEspanol(fechaAdmvaRaw);
	             // Obtener fechas del PDF
	                String texto = capturarTextoPDFVisible();

	                String fechaPDFRaw = lineaValorFuzzy(texto, "fecha");
	                String fechaPDF = normalizarFechaEspanol(fechaPDFRaw);

	                String fechaAdmvaPDFRaw = lineaValorFuzzy(texto, "fecha admva");
	                String fechaAdmvaPDF = normalizarFechaEspanol(fechaAdmvaPDFRaw);

	                // Validar coincidencia con PDF
	                if (!fechaNorm.equals(fechaPDF)) {
	                    if (screenshot) testCase.addTextEvidenceCurrentStep(
	                        "Mismatch FECHA -> Excel=[" + fechaNorm + "] PDF=[" + fechaPDF + "]"
	                    );
	                    return false;
	                }

	                if (!fechaAdmvaNorm.equals(fechaAdmvaPDF)) {
	                    if (screenshot) testCase.addTextEvidenceCurrentStep(
	                        "Mismatch FECHA ADMVA -> Excel=[" + fechaAdmvaNorm + "] PDF=[" + fechaAdmvaPDF + "]"
	                    );
	                    return false;
	                }
	                if (fechaNorm == null || fechaAdmvaNorm == null) {
	                    if (screenshot) testCase.addTextEvidenceCurrentStep(
	                        "No se pudieron normalizar fechas. Folio=" + folioGrid +
	                        " | FechaRaw=[" + safe(fechaRaw) + "]" +
	                        " | FechaAdmvaRaw=[" + safe(fechaAdmvaRaw) + "]"
	                    );
	                    return false;
	                }

	                // Validar formato español dd-MM-yyyy
	                if (!fechaNorm.matches("\\d{2}-\\d{2}-\\d{4}")) {
	                    if (screenshot) testCase.addTextEvidenceCurrentStep(
	                        "Formato incorrecto en columna Fecha. Folio=" + folioGrid +
	                        " | Valor=[" + fechaNorm + "]"
	                    );
	                    return false;
	                }

	                if (!fechaAdmvaNorm.matches("\\d{2}-\\d{2}-\\d{4}")) {
	                    if (screenshot) testCase.addTextEvidenceCurrentStep(
	                        "Formato incorrecto en columna FECHA ADMVA. Folio=" + folioGrid +
	                        " | Valor=[" + fechaAdmvaNorm + "]"
	                    );
	                    return false;
	                }

	                if (screenshot) {
	                    testCase.addTextEvidenceCurrentStep(
	                        "Validacion Fecha/Fecha ADMVA OK. Folio=" + folioGrid +
	                        " | Fecha=[" + fechaNorm + "]" +
	                        " | Fecha ADMVA=[" + fechaAdmvaNorm + "]"
	                    );
	                }

	                // Solo valida el primer match del folio (registro clicado)
	                break;
	            }
	        }

	        if (!encontro) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se encontro el folio del grid en el Excel para validar fechas.");
	            return false;
	        }

	        return true;

	    } catch (Exception e) {
	        testCase.addTextEvidenceCurrentStep("Error en validarFechaYFechaAdmvaExcelMasivo: " + e.getMessage());
	        return false;
	    } finally {
	        try { if (wb != null) wb.close(); } catch (Exception ex) {}
	        try { if (fis != null) fis.close(); } catch (Exception ex) {}
	    }
	}
	/**
	 * Metodo para normalizar una fecha al formato español (dd-MM-yyyy).
	 *
	 * Soporta los siguientes formatos de entrada:
	 * - dd/MM/yyyy
	 * - dd-MM-yyyy
	 * - yyyy-MM-dd
	 *
	 * Si la fecha viene en formato ISO (yyyy-MM-dd),
	 * se convierte automaticamente a formato español (dd-MM-yyyy)
	 * para permitir validaciones consistentes en el Excel.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param s cadena que contiene la fecha a normalizar
	 * @return fecha en formato dd-MM-yyyy o null si no se puede interpretar
	 */
	private String normalizarFechaEspanol(String s) {
	    if (s == null) return null;
	    String x = s.trim();
	    x = x.replace("/", "-");

	    // dd-MM-yyyy
	    java.util.regex.Matcher m1 = java.util.regex.Pattern.compile("(\\d{2}-\\d{2}-\\d{4})").matcher(x);
	    if (m1.find()) return m1.group(1);

	    // yyyy-MM-dd -> dd-MM-yyyy
	    java.util.regex.Matcher m2 = java.util.regex.Pattern.compile("(\\d{4}-\\d{2}-\\d{2})").matcher(x);
	    if (m2.find()) {
	        String iso = m2.group(1);
	        String[] p = iso.split("-");
	        return p[2] + "-" + p[1] + "-" + p[0];
	    }

	    return null;
	}
	/**
	 * Metodo para validar que los datos de la columna "Precio" en el Excel Masivo
	 * coincidan con los precios mostrados en la vista preliminar del registro seleccionado.
	 *
	 * La comparacion se realiza utilizando el "Folio" como llave principal,
	 * validando que los precios coincidan exactamente incluyendo los centavos.
	 *
	 * Se abre el ultimo Excel descargado para generar evidencia (screenshot)
	 * y se cierra automaticamente al finalizar la validacion.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @return True/False - Indica si los precios del Excel coinciden con la vista preliminar
	 * @throws Exception
	 * @param screenshot - true o false para saber si se guardara screenshot en el reporte de evidencia
	 */
	public boolean validarPrecioYValTotalVistaPreliminarVsExcelMasivo(boolean screenshot) {
	    FileInputStream fis = null;
	    Workbook wb = null;

	    try {
	        if (ultimaDevolucionSeleccionada == null ||
	            ultimaDevolucionSeleccionada.folio == null ||
	            ultimaDevolucionSeleccionada.folio.trim().isEmpty()) {

	            if (screenshot) testCase.addTextEvidenceCurrentStep("No hay folio previo del grid para comparar contra Excel.");
	            return false;
	        }

	        String folioGrid = extraerSoloDigitos(ultimaDevolucionSeleccionada.folio);

	        String texto = capturarTextoPDFVisible();
	        if (texto == null) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se pudo leer texto de la vista preliminar.");
	            return false;
	        }

	        // Extraer lista de precios desde la vista preliminar (seccion RESUMEN DEVOLUCIONES)
	        List<BigDecimal> preciosPreview = extraerPreciosDeResumenDevoluciones(texto);
	        if (preciosPreview.isEmpty()) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se encontraron precios en la vista preliminar (RESUMEN DEVOLUCIONES).");
	            return false;
	        }

	        // Extraer Valor Total desde la vista preliminar (totales)
	        String valorTotalPDFRaw = firstNonNull(lineaValorFuzzy(texto, "valor total"), lineaValorFuzzy(texto, "val. total"));
	        BigDecimal valorTotalPDF = parseMoneyToBigDecimal(valorTotalPDFRaw);
	        if (valorTotalPDF == null) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se pudo obtener 'Valor Total' del PDF. Raw=[" + safe(valorTotalPDFRaw) + "]");
	            return false;
	        }

	        // Obtener ultimo Excel descargado
	        String home = System.getProperty("user.home") + "\\Downloads";
	        File last = getLastModified(home);
	        if (last == null || !last.exists()) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se encontro el ultimo archivo descargado en Downloads.");
	            return false;
	        }
	        // Leer Excel y filtrar filas por folio, recolectar precios y sumar Val. Total
	        fis = new FileInputStream(last);
	        wb = WorkbookFactory.create(fis);

	        Sheet sheet = wb.getSheetAt(0);
	        if (sheet == null) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se pudo abrir la hoja 0 del Excel.");
	            return false;
	        }

	        int colFolio = -1;
	        int colPrecio = -1;
	        int colValTotal = -1;

	        Row header = sheet.getRow(sheet.getFirstRowNum());
	        if (header != null) {
	            colFolio = findColumnIndex(header, "Folio");
	            colPrecio = findColumnIndex(header, "Precio");
	            colValTotal = firstColIndex(header, new String[] { "Val. Total", "Val. Tot.", "Val Tot", "Val. Tot" });
	        }

	        if (colFolio < 0 || colPrecio < 0 || colValTotal < 0) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep(
	                "No se encontraron columnas requeridas en Excel. FolioIndex=" + colFolio +
	                " PrecioIndex=" + colPrecio + " ValTotalIndex=" + colValTotal
	            );
	            return false;
	        }

	        List<BigDecimal> preciosExcel = new ArrayList<BigDecimal>();
	        DataFormatter fmt = new DataFormatter();
	        BigDecimal sumaValTotalExcel = new BigDecimal("0.00");

	        int lastRow = sheet.getLastRowNum();
	        for (int r = header.getRowNum() + 1; r <= lastRow; r++) {
	            Row row = sheet.getRow(r);
	            if (row == null) continue;

	            String folioCell = getCellString(row.getCell(colFolio), fmt);
	            String folioExcel = extraerSoloDigitos(folioCell);

	            if (folioExcel != null && folioExcel.equals(folioGrid)) {

	                // Precio
	                String precioCell = getCellString(row.getCell(colPrecio), fmt);
	                BigDecimal precio = parseMoneyToBigDecimal(precioCell);
	                if (precio != null) {
	                    preciosExcel.add(precio);
	                }

	                // Val. Total (sumatoria por folio)
	                String valTotalCell = getCellString(row.getCell(colValTotal), fmt);
	                BigDecimal valTotal = parseMoneyToBigDecimal(valTotalCell);
	                if (valTotal != null) {
	                    sumaValTotalExcel = sumaValTotalExcel.add(valTotal).setScale(2, RoundingMode.HALF_UP);
	                }
	            }
	        }

	        if (preciosExcel.isEmpty()) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se encontraron filas en Excel para el folio: " + folioGrid);
	            return false;
	        }

	        // Comparar listas de precios (considera multiples articulos)
	        Collections.sort(preciosPreview);
	        Collections.sort(preciosExcel);

	        boolean preciosIguales = preciosPreview.equals(preciosExcel);
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep(
	                "Comparacion precios (con centavos) -> Folio: " + folioGrid +
	                " | Preview: " + preciosPreview +
	                " | Excel: " + preciosExcel
	            );
	        }
	        if (!preciosIguales) {
	            return false;
	        }

	        // Comparar Valor Total PDF vs suma de Val. Total Excel
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep(
	                "Comparacion VAL TOTAL -> Folio: " + folioGrid +
	                " | PDF: " + valorTotalPDF +
	                " | ExcelSumaValTotal: " + sumaValTotalExcel
	            );
	        }

	        if (valorTotalPDF.compareTo(sumaValTotalExcel) != 0) {
	            return false;
	        }

	        return true;

	    } catch (Exception e) {
	        testCase.addTextEvidenceCurrentStep("Error en validarPrecioYValTotalVistaPreliminarVsExcelMasivo: " + e.getMessage());
	        return false;
	    } finally {
	        try { if (wb != null) wb.close(); } catch (Exception ex) {}
	        try { if (fis != null) fis.close(); } catch (Exception ex) {}
	    }
	}

	/**
	 * Metodo para obtener el indice de la primera columna que coincida con alguno de los nombres esperados
	 * ignorando mayusculas/minusculas y espacios al inicio/fin.
	 *
	 * @param header fila de encabezado del Excel
	 * @param candidates lista de nombres posibles de la columna
	 * @return indice de la primera coincidencia o -1 si no se encuentra
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private int firstColIndex(Row header, String[] candidates) {
	    DataFormatter fmt = new DataFormatter();
	    for (int c = 0; c < header.getLastCellNum(); c++) {
	        String val = getCellString(header.getCell(c), fmt);
	        if (val == null) continue;
	        String hv = val.trim();

	        for (int i = 0; i < candidates.length; i++) {
	            if (hv.equalsIgnoreCase(candidates[i].trim())) {
	                return c;
	            }
	        }
	    }
	    return -1;
	}
	/**
	 * Metodo para obtener el indice de una columna dentro del encabezado del Excel,
	 * buscando por nombre exacto de columna (ignorando mayusculas/minusculas).
	 *
	 * @param header fila de encabezado del Excel
	 * @param expectedHeader nombre de la columna a buscar
	 * @return indice de la columna si se encuentra, -1 si no existe
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private int findColumnIndex(Row header, String expectedHeader) {
	    DataFormatter fmt = new DataFormatter();
	    for (int c = 0; c < header.getLastCellNum(); c++) {
	        String val = getCellString(header.getCell(c), fmt);
	        if (val != null && val.trim().equalsIgnoreCase(expectedHeader.trim())) {
	            return c;
	        }
	    }
	    return -1;
	}
	/**
	 * Metodo para obtener el valor de una celda del Excel como cadena formateada.
	 *
	 * Utiliza DataFormatter para respetar el formato visible en Excel,
	 * incluyendo valores numericos con decimales.
	 *
	 * @param cell celda a leer
	 * @param fmt formateador de datos de Apache POI
	 * @return valor de la celda como String o null si la celda es null
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private String getCellString(Cell cell, DataFormatter fmt) {
	    if (cell == null) return null;
	    String s = fmt.formatCellValue(cell);
	    return (s != null) ? s.trim() : null;
	}
	/**
	 * Metodo para convertir un valor monetario en formato String a BigDecimal
	 * conservando los centavos.
	 *
	 * Elimina simbolos como "$", separadores de miles y espacios,
	 * permitiendo comparar valores monetarios con precision de 2 decimales.
	 *
	 * @param s cadena que contiene el valor monetario
	 * @return BigDecimal con escala de 2 decimales o null si no es valido
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private BigDecimal parseMoneyToBigDecimal(String s) {
	    if (s == null) return null;

	    // Quitar simbolos y espacios, conservar digitos, coma y punto
	    String x = s.replace("$", "").trim();

	    // Si trae separador de miles con coma, eliminar comas
	    x = x.replace(",", "").trim();

	    // Extraer primer numero con decimales opcionales
	    Matcher m = Pattern.compile("(\\d+(?:\\.\\d{1,2})?)").matcher(x);
	    if (!m.find()) return null;

	    try {
	        BigDecimal bd = new BigDecimal(m.group(1));
	        return bd.setScale(2, RoundingMode.HALF_UP);
	    } catch (Exception ex) {
	        return null;
	    }
	}

	/**
	 * Metodo para extraer los precios mostrados en la seccion
	 * "RESUMEN DEVOLUCIONES" dentro del texto capturado
	 * de la vista preliminar (PDF en pantalla).
	 *
	 * Se identifican los valores numericos con dos decimales
	 * correspondientes a la columna "Precio" y se devuelven
	 * como lista de BigDecimal para su comparacion contra Excel.
	 *
	 * @param texto contenido completo capturado de la vista preliminar
	 * @return lista de precios encontrados con precision de 2 decimales
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private List<BigDecimal> extraerPreciosDeResumenDevoluciones(String texto) {
	    List<BigDecimal> out = new ArrayList<BigDecimal>();
	    if (texto == null) return out;

	    String upper = texto.toUpperCase();

	    int idxIni = upper.indexOf("RESUMEN DEVOLUCIONES");
	    if (idxIni < 0) idxIni = upper.indexOf("RESUMEN DEVOLUCION");
	    if (idxIni < 0) return out;

	    int idxFin = upper.indexOf("TOTAL DE TASA", idxIni);
	    if (idxFin < 0) idxFin = upper.indexOf("TOTAL DE ARTICULOS", idxIni);
	    if (idxFin < 0) idxFin = Math.min(texto.length(), idxIni + 1200);

	    String bloque = texto.substring(idxIni, idxFin);

	    // Buscar montos con 2 decimales dentro del bloque (ej: 32.50)
	    Matcher m = Pattern.compile("(\\d+\\.\\d{2})").matcher(bloque);
	    while (m.find()) {
	        try {
	            BigDecimal bd = new BigDecimal(m.group(1)).setScale(2, RoundingMode.HALF_UP);
	            out.add(bd);
	        } catch (Exception ex) {
	            // ignore
	        }
	    }

	    // Filtrar duplicados de totales si el bloque trae VAL TOT igual al precio:
	    // Si en tu caso siempre hay 1 articulo, se quedaran 2 valores (precio y val tot).
	    // Para comparar "Precio" unicamente, nos quedamos con los primeros N precios detectados
	    // donde N = numero de articulos en resumen (columna #).
	    // Heuristica simple: si se repite exacto, dejamos una sola ocurrencia por fila.
	    if (!out.isEmpty()) {
	        List<BigDecimal> uniq = new ArrayList<BigDecimal>();
	        for (BigDecimal v : out) {
	            if (!uniq.contains(v)) uniq.add(v);
	        }
	        out = uniq;
	    }

	    return out;
	}
	/**
 	* Metodo para cerrar el popup que existe despues de descargar algun archivo desde devoluciones
 	* @author Alejandro Valdez - Jose Pecina
 	* @return True si se localiza el archivo físico con la nomenclatura y extensión correctas; False si el archivo no existe o ocurre una excepción.
 	* @date Octubre 2025
 	*/
 	public boolean CerrarPopUpCentroDescargayComputoDEV(boolean screenshot) {
 		 try {
 		 if (!MensajeEspereDesaparece(false)) {
	            testCase.addTextEvidenceCurrentStep("Falló al desaparecer el mensaje espere un momento");
	            return false;
	        }
 	   By mensajeDescarga = By.xpath(
	            "//app-info-download-dialog//p[contains(normalize-space(),'La información se visualizará en el centro de descarga')]"
	        );

	        u.waitWebElement(mensajeDescarga, 60, 5);
	        u.highLight(mensajeDescarga);
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Se muestra pop up de La información se visualizara en el centro de descarga y en tu equipo de computo");
	            testCase.addScreenShotCurrentStep(u, "clickContainer");
	        }
	        u.unhighLight(mensajeDescarga);

	        By botoncerrar = By.xpath("//app-info-download-dialog//button[@aria-label='Cerrar']");

	        u.highLight(botoncerrar);
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Se da clic en la X del pop up");
	            testCase.addScreenShotCurrentStep(u, "clickContainer");
	        }
	        u.unhighLight(botoncerrar);
	        u.click(botoncerrar);
	        return true;
 		 } catch (Exception e) {
 	        return false;
 	    }
 	    }
	/**
	 * Metodo para obtener el locator del boton de paginacion segun su nombre utilizando los By de Devoluciones.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param boton nombre del boton: primero, anterior, siguiente, ultimo
	 * @return By correspondiente o null si el nombre no existe
	 * @throws Exception
	 */
	private By getBotonPaginacionLocatorDevoluciones(String boton) throws Exception {
	    if (boton == null) return null;

	    switch (boton.toLowerCase()) {
	        case "primero":
	            return xmlPaginaPrimeraPaginaButtonDevoluciones;
	        case "anterior":
	            return xmlPaginaAnteriorButtonDevoluciones;
	        case "siguiente":
	            return xmlPaginaSiguienteButtonDevoluciones;
	        case "ultimo":
	            return xmlPaginaUltimaPaginaButtonDevoluciones;
	        default:
	            return null;
	    }
	}

	/**
	 * Metodo para validar si un boton de paginacion esta habilitado usando los locators de Devoluciones.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param boton nombre del boton a validar: primero, anterior, siguiente, ultimo
	 * @return true si esta habilitado, false si esta deshabilitado o no existe
	 * @throws Exception
	 */
	private boolean botonPaginacionHabilitadoDevoluciones(String boton) throws Exception {
	    try {
	        By botonLocator = getBotonPaginacionLocatorDevoluciones(boton);
	        if (botonLocator == null) return false;

	        WebDriver driver = u.getDriver();
	        List<WebElement> els = driver.findElements(botonLocator);
	        if (els == null || els.isEmpty()) return false;

	        WebElement el = els.get(0);

	        String ariaDisabled = el.getAttribute("aria-disabled");
	        String disabled = el.getAttribute("disabled");

	        if (disabled != null) return false;
	        if (ariaDisabled != null && ariaDisabled.trim().equalsIgnoreCase("true")) return false;

	        return el.isEnabled();
	    } catch (Exception e) {
	        return false;
	    }
	}

	/**
	 * Metodo para dar clic en el boton de paginacion indicado usando los locators de Devoluciones.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param boton nombre del boton a clickar: primero, anterior, siguiente, ultimo
	 * @throws Exception
	 */
	private void clickBotonPaginacionDevoluciones(String boton) throws Exception {
	    By botonLocator = getBotonPaginacionLocatorDevoluciones(boton);
	    if (botonLocator == null) return;

	    u.waitWebElement(botonLocator, 30, 2);
	    u.scrollToElement(botonLocator);
	    u.click(botonLocator);
	    if (!MensajeEspereDesaparece(false)) {
            testCase.addTextEvidenceCurrentStep("Fallo al desaparecer el mensaje espere un momento");            
        }
	}

	/**
	 * Metodo para esperar a que cambie el folio de la primera fila despues de paginar.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param folioAnterior Folio antes de paginar
	 * @param timeoutSegundos Tiempo maximo de espera en segundos
	 * @return true si cambio, false si no cambio en el tiempo esperado
	 * @throws Exception
	 */
	private boolean esperarCambioFolioPrimeraFila(String folioAnterior, int timeoutSegundos) throws Exception {
	    long end = System.currentTimeMillis() + (timeoutSegundos * 1000L);

	    while (System.currentTimeMillis() < end) {
	        String folioActual = getTdText(1, 8);
	        if (!normalizeKey(folioActual).equals(normalizeKey(folioAnterior))) {
	            return true;
	        }
	        u.hardWait(1);
	    }
	    return false;
	}

	/**
	 * Metodo para indexar el grid de devoluciones por Folio recorriendo paginado con botones de Devoluciones.
	 * Se detiene cuando ya no existe boton siguiente habilitado, cuando se encuentran todos los folios,
	 * o cuando se alcanza el maximo de paginas configurado.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param foliosEsperados Set de folios (normalizados) que se desean encontrar en el grid
	 * @param maxPaginas Numero maximo de paginas a recorrer como limite de seguridad
	 * @param screenshot true/false para evidencia
	 * @return Mapa FolioNormalizado -> Datos de fila del grid
	 * @throws Exception
	 */
	private Map<String, GridRowDev> indexarGridDevolucionesPorFolioConPaginacionDevoluciones(Set<String> foliosEsperados, int maxPaginas, boolean screenshot) throws Exception {
	    Map<String, GridRowDev> out = new HashMap<>();
	    Set<String> restantes = new HashSet<>();
	    if (foliosEsperados != null) restantes.addAll(foliosEsperados);

	    if (botonPaginacionHabilitadoDevoluciones("primero")) {
	        clickBotonPaginacionDevoluciones("primero");
	        if (!MensajeEspereDesaparece(false)) return out;
	        u.hardWait(1);
	    }

	    int pagina = 1;

	    while (pagina <= maxPaginas) {

	        int rowCount = obtenerConteoFilasGrid();
	        if (rowCount > 0) {
	            for (int i = 1; i <= rowCount; i++) {

	                String folio = getTdText(i, 8);
	                String folioKey = normalizeKey(folio);
	                if (folioKey.isEmpty()) continue;

	                GridRowDev r = new GridRowDev();
	                r.crTienda = getTdText(i, 5);
	                r.nombreTienda = getTdText(i, 6);
	                r.fecha = getTdText(i, 7);

	                out.put(folioKey, r);
	                restantes.remove(folioKey);
	            }
	        }

	        if (restantes.isEmpty()) {
	            return out;
	        }

	        if (!botonPaginacionHabilitadoDevoluciones("siguiente")) {
	            return out;
	        }

	        String folioAntes = getTdText(1, 8);

	        clickBotonPaginacionDevoluciones("siguiente");

	        if (!MensajeEspereDesaparece(false)) {
	            return out;
	        }

	        esperarCambioFolioPrimeraFila(folioAntes, 20);

	        pagina++;
	    }

	    if (screenshot) {
	        testCase.addTextEvidenceCurrentStep("Aviso: Se alcanzo el maximo de paginas recorridas: " + maxPaginas);
	        testCase.addScreenShotCurrentStep(u, "MaxPaginas_Paginacion_Devoluciones");
	    }

	    return out;
	}

	
	/**
	 * Metodo para abrir el Excel recien descargado y validar la columna "Nombre de Tienda" contra el grid del portal.
	 * Se valida que el nombre sea correcto y que NO venga concatenado con el "CR Tienda".
	 * La comparacion se realiza por "Folio" como llave principal.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @return True/False - Se obtiene respuesta de si el Excel coincide con el grid en "Nombre de Tienda" sin CR concatenado
	 * @throws Exception
	 * @param screenshot - true or false para saber si se guardara screenshot en el reporte de evidencia o no
	 */
	public boolean ValidarNombreTiendaExcelVsGrid(boolean screenshot) throws Exception {
	    try {
	        if (!MensajeEspereDesaparece(false)) {
	            testCase.addTextEvidenceCurrentStep("Fallo al desaparecer el mensaje espere un momento");
	            return false;
	        }
	        
	        u.waitWebElement(xmlDatosTablaDirect, 60, 5);
	        u.scrollToElement(xmlDatosTablaDirect);

	        String rutaExcel = obtenerUltimoArchivoDescargado();
	        if (rutaExcel == null || rutaExcel.trim().isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("Error: No se encontro ningun archivo Excel descargado");
	            return false;
	        }

	        ExcelData excel = leerExcelComoLista(rutaExcel);
	        if (excel == null || excel.rows == null || excel.rows.isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("Error: El Excel no contiene filas para comparar: " + new File(rutaExcel).getName());
	            return false;
	        }

	        int colFolioExcel = excel.getColIndex("Folio");
	        int colNombreTiendaExcel = excel.getColIndex("Nombre de Tienda");

	        if (colFolioExcel < 0 || colNombreTiendaExcel < 0) {
	            testCase.addTextEvidenceCurrentStep("Error: No se encontraron columnas en Excel: Folio / Nombre de Tienda");
	            return false;
	        }

	        Set<String> foliosExcel = new HashSet<>();
	        for (List<String> excelRow : excel.rows) {
	            String folioExcel = safeGet(excelRow, colFolioExcel);
	            String folioKey = normalizeKey(folioExcel);
	            if (!folioKey.isEmpty()) foliosExcel.add(folioKey);
	        }

	        Map<String, GridRowDev> gridPorFolio = indexarGridDevolucionesPorFolioConPaginacionDevoluciones(foliosExcel, 50, screenshot);

	        boolean ok = true;

	        for (List<String> excelRow : excel.rows) {
	            String folioExcel = safeGet(excelRow, colFolioExcel);
	            String folioKey = normalizeKey(folioExcel);
	            if (folioKey.isEmpty()) continue;

	            GridRowDev grid = gridPorFolio.get(folioKey);
	            if (grid == null) {
	                ok = false;
	                testCase.addTextEvidenceCurrentStep("No se encontro Folio en grid. Folio=" + cleanForEvidence(folioExcel));
	                continue;
	            }

	            String nombreExcel = safeGet(excelRow, colNombreTiendaExcel);

	            if (!normalizeText(nombreExcel).equals(normalizeText(grid.nombreTienda))) {
	                ok = false;
	                testCase.addTextEvidenceCurrentStep(
	                    "Nombre de Tienda no coincide. Folio=" + cleanForEvidence(folioExcel) +
	                    " Excel=" + cleanForEvidence(nombreExcel) +
	                    " Grid=" + cleanForEvidence(grid.nombreTienda)
	                );
	            }

	            if (!normalizeText(grid.crTienda).isEmpty() && contieneCrConcatenado(nombreExcel, grid.crTienda)) {
	                ok = false;
	                testCase.addTextEvidenceCurrentStep(
	                    "Nombre de Tienda contiene CR concatenado. Folio=" + cleanForEvidence(folioExcel) +
	                    " NombreExcel=" + cleanForEvidence(nombreExcel) +
	                    " CR=" + cleanForEvidence(grid.crTienda)
	                );
	            }
	        }

	        if (screenshot) {
	            testCase.addBoldTextEvidenceCurrentStep("Validacion Excel vs Grid: Nombre de Tienda sin CR concatenado");
	            testCase.addScreenShotCurrentStep(u, "Validacion_NombreTienda_Excel_Grid");
	        }

	        return ok;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
	/**
	 * Metodo para validar los datos de la columna "Fecha" del Excel resumen recien descargado.
	 * Se valida que la columna "Fecha" exista y que el formato sea espanol dd-MM-yyyy.
	 * La columna "Fecha" se compara contra la fecha mostrada en el grid del portal.
	 * La comparacion se realiza utilizando el "Folio" como llave principal.
	 * La columna "FECHA ADMVA" no es obligatoria en este tipo de archivo.
	 * 
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @return True/False - Indica si las fechas del Excel resumen son validas y coinciden con el grid
	 * @throws Exception
	 * @param screenshot - true o false para saber si se guardara screenshot en el reporte de evidencia
	 */
	public boolean ValidarFechasExcelVsGridResumen(boolean screenshot) throws Exception {
	    try {
	        if (!MensajeEspereDesaparece(false)) {
	            testCase.addTextEvidenceCurrentStep("Fallo al desaparecer el mensaje espere un momento");
	            return false;
	        }

	        u.waitWebElement(xmlDatosTablaDirect, 60, 5);
	        u.scrollToElement(xmlDatosTablaDirect);

	        String rutaExcel = obtenerUltimoArchivoDescargado();
	        if (rutaExcel == null || rutaExcel.trim().isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("Error: No se encontro ningun archivo Excel descargado");
	            return false;
	        }

	        ExcelData excel = leerExcelComoLista(rutaExcel);
	        if (excel == null || excel.rows == null || excel.rows.isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("Error: El Excel no contiene filas para comparar: " + new File(rutaExcel).getName());
	            return false;
	        }

	        int colFolioExcel = excel.getColIndex("Folio");
	        int colFechaExcel = excel.getColIndex("Fecha");
	        int colFechaAdmvaExcel = excel.getColIndex("FECHA ADMVA");

	        if (colFolioExcel < 0 || colFechaExcel < 0) {
	            testCase.addTextEvidenceCurrentStep("Error: No se encontraron columnas obligatorias en Excel: Folio / Fecha");
	            return false;
	        }

	        Set<String> foliosExcel = new HashSet<>();
	        for (List<String> excelRow : excel.rows) {
	            String folioExcel = safeGet(excelRow, colFolioExcel);
	            String folioKey = normalizeKey(folioExcel);
	            if (!folioKey.isEmpty()) {
	                foliosExcel.add(folioKey);
	            }
	        }

	        Map<String, GridRowDev> gridPorFolio = indexarGridDevolucionesPorFolioConPaginacionDevoluciones(foliosExcel, 50, screenshot);

	        SimpleDateFormat fmt = new SimpleDateFormat("dd-MM-yyyy");
	        fmt.setLenient(false);

	        boolean ok = true;

	        for (List<String> excelRow : excel.rows) {
	            String folioExcel = safeGet(excelRow, colFolioExcel);
	            String folioKey = normalizeKey(folioExcel);
	            if (folioKey.isEmpty()) {
	                continue;
	            }

	            GridRowDev grid = gridPorFolio.get(folioKey);
	            if (grid == null) {
	                ok = false;
	                testCase.addTextEvidenceCurrentStep("No se encontro Folio en grid para comparar fechas. Folio=" + cleanForEvidence(folioExcel));
	                continue;
	            }

	            String fechaExcel = safeGet(excelRow, colFechaExcel);

	            if (!esFechaValida(fechaExcel, fmt)) {
	                ok = false;
	                testCase.addTextEvidenceCurrentStep("Formato Fecha invalido en Excel (dd-MM-yyyy). Folio=" + cleanForEvidence(folioExcel) + " FechaExcel=" + cleanForEvidence(fechaExcel));
	            }

	            if (!esFechaValida(grid.fecha, fmt)) {
	                ok = false;
	                testCase.addTextEvidenceCurrentStep("Formato Fecha invalido en Grid (dd-MM-yyyy). Folio=" + cleanForEvidence(folioExcel) + " FechaGrid=" + cleanForEvidence(grid.fecha));
	            }

	            if (esFechaValida(fechaExcel, fmt) && esFechaValida(grid.fecha, fmt)) {
	                Date dExcel = fmt.parse(normalizeDateString(fechaExcel));
	                Date dGrid = fmt.parse(normalizeDateString(grid.fecha));
	                if (!dExcel.equals(dGrid)) {
	                    ok = false;
	                    testCase.addTextEvidenceCurrentStep("Fecha no coincide. Folio=" + cleanForEvidence(folioExcel) + " Excel=" + cleanForEvidence(fechaExcel) + " Grid=" + cleanForEvidence(grid.fecha));
	                }
	            }

	            if (colFechaAdmvaExcel >= 0) {
	                String fechaAdmvaExcel = safeGet(excelRow, colFechaAdmvaExcel);
	                if (!fechaAdmvaExcel.trim().isEmpty() && !esFechaValida(fechaAdmvaExcel, fmt)) {
	                    ok = false;
	                    testCase.addTextEvidenceCurrentStep("Formato FECHA ADMVA invalido en Excel (dd-MM-yyyy). Folio=" + cleanForEvidence(folioExcel) + " FECHA_ADMVA=" + cleanForEvidence(fechaAdmvaExcel));
	                }
	            }
	        }

	        if (screenshot) {
	            testCase.addBoldTextEvidenceCurrentStep("Validacion Excel resumen vs Grid: columna Fecha obligatoria");
	            testCase.addScreenShotCurrentStep(u, "Validacion_Fechas_Excel_Grid_Resumen");
	        }

	        return ok;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
