	/**
	 * Metodo para indexar el grid de devoluciones por Folio tomando los valores desde el DOM.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param rowCount Numero de filas a leer del grid
	 * @return Mapa FolioNormalizado -> Datos de fila del grid
	 * @throws Exception
	 */
	private Map<String, GridRowDev> indexarGridDevolucionesPorFolio(int rowCount) throws Exception {
	    Map<String, GridRowDev> out = new HashMap<>();
	    for (int i = 1; i <= rowCount; i++) {
	        String folio = getTdText(i, 8);
	        String folioKey = normalizeKey(folio);
	        if (folioKey.isEmpty()) continue;

	        GridRowDev r = new GridRowDev();
	        r.crTienda = getTdText(i, 5);
	        r.nombreTienda = getTdText(i, 6);
	        r.fecha = getTdText(i, 7);

	        out.put(folioKey, r);
	    }
	    return out;
	}

