	/**
	 * Metodo para validar si el Nombre de Tienda del Excel contiene el CR concatenado como token.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param nombreTienda Valor de Nombre de Tienda del Excel
	 * @param crTienda Valor de CR Tienda del grid
	 * @return true si el nombre contiene el CR concatenado, false en caso contrario
	 * @throws Exception
	 */
	private boolean contieneCrConcatenado(String nombreTienda, String crTienda) throws Exception {
	    String n = normalizeText(nombreTienda);
	    String cr = normalizeText(crTienda);
	    if (n.isEmpty() || cr.isEmpty()) return false;
	    return n.matches(".*\\b" + Pattern.quote(cr) + "\\b.*");
	}

	/**
	 * Metodo para validar que una fecha sea valida y cumpla el formato dd-MM-yyyy.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param fecha Texto de fecha
	 * @param fmt Formateador dd-MM-yyyy
	 * @return true si es valida, false si no cumple formato o no es parseable
	 * @throws Exception
	 */
	private boolean esFechaValida(String fecha, SimpleDateFormat fmt) throws Exception {
	    if (fecha == null) return false;
	    String f = normalizeDateString(fecha);
	    if (f.isEmpty()) return false;
	    try {
	        fmt.parse(f);
	        return f.matches("\\d{2}-\\d{2}-\\d{4}");
	    } catch (ParseException e) {
	        return false;
	    }
	}

	/**
	 * Metodo para normalizar fecha: separador "-" y sin espacios.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param fecha Texto de fecha
	 * @return Fecha normalizada
	 * @throws Exception
	 */
	private String normalizeDateString(String fecha) throws Exception {
	    if (fecha == null) return "";
	    String f = fecha.trim();
	    f = f.replace("/", "-");
	    f = f.replaceAll("\\s+", "");
	    return f;
	}

	/**
	 * Metodo para obtener un valor seguro de una fila del Excel.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param row Fila del Excel como lista
	 * @param idx Indice de columna
	 * @return Valor de celda o string vacio si no existe
	 * @throws Exception
	 */
	private String safeGet(List<String> row, int idx) throws Exception {
	    if (row == null || idx < 0 || idx >= row.size()) return "";
	    return row.get(idx) == null ? "" : row.get(idx);
	}

	/**
	 * Metodo para normalizar texto para comparacion: quita acentos, normaliza espacios y convierte a mayusculas.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param s Texto de entrada
	 * @return Texto normalizado
	 * @throws Exception
	 */
	private String normalizeText(String s) throws Exception {
	    if (s == null) return "";
	    String t = Normalizer.normalize(s, Normalizer.Form.NFD);
	    t = t.replaceAll("\\p{M}", "");
	    t = t.replaceAll("[\\p{C}]", "");
	    t = t.replaceAll("\\s+", " ").trim();
	    return t.toUpperCase();
	}

	/**
	 * Metodo para normalizar llaves (Folio) eliminando espacios y normalizando texto.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param s Texto de llave
	 * @return Llave normalizada
	 * @throws Exception
	 */
	private String normalizeKey(String s) throws Exception {
	    return normalizeText(s).replace(" ", "");
	}

	/**
	 * Metodo para limpiar texto para evidencia evitando caracteres raros y normalizando espacios.
	 * @author Jose Pecina
	 * @date Febrero 2026
	 * @param texto Texto original
	 * @return Texto limpio
	 * @throws Exception
	 */
	private String cleanForEvidence(String texto) throws Exception {
	    if (texto == null) return "";
	    String limpio = Normalizer.normalize(texto, Normalizer.Form.NFD)
	        .replaceAll("\\p{M}", "")
	        .replaceAll("[\\p{C}]", "")
	        .replaceAll("\\s+", " ")
	        .trim();
	    return limpio;
	}

