	/**
	 * Metodo para ejecutar la funcion paginated en BD usando p_zonas (2 zonas)
	 * y validar que las primeras filas del grid existan en el resultado de BD.
	 *
	 * Obtiene perfil y llaves del usuario para armar parametros, ejecuta la funcion
	 * get_cambios_fisicos_directos_pendientes_paginated y compara grid vs BD con una key.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param screenshot - true o false para indicar si se guardara evidencia en el reporte
	 * @param usuario - Usuario usado para obtener perfil y llaves y ejecutar la funcion
	 * @param zonasSeleccionadas - Lista con 2 zonas a enviar en el parametro p_zonas
	 * @return True si no hay mismatches entre grid y BD; False si no hay filas o hay diferencias
	 * @throws Exception - Se lanza si falla la conexion o no se obtienen datos requeridos del usuario
	 */

	private boolean ejecutarFuncionPaginatedYValidarContraGrid_Zona(boolean screenshot, String usuario, List<String> zonasSeleccionadas) throws Exception {
	    String dbUrl = GlobalVariables.DB_URL_Cometa;
	    String dbUser = GlobalVariables.DB_USER_Cometa;
	    String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	    String sqlFuncion =
	        "select * " +
	        "from public.get_cambios_fisicos_directos_pendientes_paginated(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);";

	    WebDriver driver = u.getDriver();
	    WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(20));

	    // Asegura que el grid exista
	    wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody")));

	    // Lee N filas del grid para comparar
	    List<GridRow> gridRows = leerPrimerasFilasGrid(driver, 10);

	    if (gridRows.isEmpty()) {
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("El grid no tiene filas para comparar contra BD con las zonas seleccionadas: " + zonasSeleccionadas);
	            testCase.addScreenShotCurrentStep("Grid_Sin_Filas_Zona");
	        }
	        return false;
	    }

	    try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPassword)) {

	        String perfil = obtenerPerfilUsuario(conn, usuario);
	        if (perfil == null) throw new Exception("No se obtuvo PCPERFIL para usuario: " + usuario);

	        boolean esAdmin = "ADMIN".equalsIgnoreCase(perfil) || "OXXO_OS".equalsIgnoreCase(perfil);

	        String rfc = null;
	        String pcplaza = null;
	        String pcsupplier = null;

	        if (!esAdmin) {
	            rfc = obtenerKey(conn, usuario, "PCRFC");
	            pcplaza = obtenerKey(conn, usuario, "PCPLAZA");
	            pcsupplier = obtenerKey(conn, usuario, "PCSUPPLIERID");
	        }

	        Integer pPage = 1;
	        Integer pPageSize = 200;

	        Array pRfcArray = null;
	        Array pCrDescPlazasArray = null;

	        if (!esAdmin) {
	            if ("OXXO_PLAZA".equalsIgnoreCase(perfil)) {
	                if (pcplaza == null || pcplaza.trim().isEmpty()) return false;
	                pCrDescPlazasArray = conn.createArrayOf("varchar", new String[] { pcplaza.trim() });
	            } else if ("OXXO_PROVEEDOR".equalsIgnoreCase(perfil)) {
	                if (pcsupplier == null || pcsupplier.trim().isEmpty()) return false;
	            } else {
	                if (rfc == null || rfc.trim().isEmpty()) return false;
	                pRfcArray = conn.createArrayOf("varchar", new String[] { rfc.trim() });
	            }
	        }

	        // p_zonas (2 zonas)
	        String[] zonasArr = new String[] { zonasSeleccionadas.get(0), zonasSeleccionadas.get(1) };
	        Array pZonasArray = conn.createArrayOf("varchar", zonasArr);

	        List<DbRow> dbRows = new ArrayList<>();

	        try (PreparedStatement ps = conn.prepareStatement(sqlFuncion)) {

	            ps.setInt(1, pPage);
	            ps.setInt(2, pPageSize);

	            if (pRfcArray != null) ps.setArray(3, pRfcArray);
	            else ps.setNull(3, java.sql.Types.ARRAY);

	            
	            // 4 null, 5 null, 6 p_zonas, 7 null, 8 null
	            ps.setNull(4, java.sql.Types.ARRAY); 
	            ps.setNull(5, java.sql.Types.ARRAY); 
	            ps.setArray(6, pZonasArray);         

	            ps.setNull(7, java.sql.Types.ARRAY);
	            ps.setNull(8, java.sql.Types.ARRAY);

	            if (pCrDescPlazasArray != null) ps.setArray(9, pCrDescPlazasArray);
	            else ps.setNull(9, java.sql.Types.ARRAY);

	            ps.setNull(10, java.sql.Types.ARRAY);
	            ps.setNull(11, java.sql.Types.ARRAY);

	            ps.setNull(12, java.sql.Types.DATE);
	            ps.setNull(13, java.sql.Types.DATE);
	            ps.setNull(14, java.sql.Types.VARCHAR);

	            try (ResultSet rs = ps.executeQuery()) {
	                while (rs.next()) {
	                    DbRow r = new DbRow();

	                    r.crTienda = normalizarTexto(getStringByAny(rs, "cr_tienda"));
	                    r.remision = normalizarTexto(getStringByAny(rs, "remision_number"));
	                    r.sku = normalizarTexto(getStringByAny(rs, "sku"));
	                    r.fechaProgramacion = normalizarTexto(getStringByAny(rs, "created_datetime_business"));
	                    r.descripcion = normalizarTexto(getStringByAny(rs, "description"));

	                    r.diasTranscurridos = normalizarTexto(getStringByAny(rs, "dias_transcurridos"));
	                    r.cantidad = normalizarTexto(getStringByAny(rs, "quantity_items"));
	                    r.costo = normalizarTexto(getStringByAny(rs, "total_amount"));

	                    dbRows.add(r);
	                }
	            }
	        }

	        if (dbRows.isEmpty()) {
	            if (screenshot) {
	                testCase.addTextEvidenceCurrentStep("La funcion paginated no regreso filas para p_zonas=" + zonasSeleccionadas);
	                testCase.addScreenShotCurrentStep("Funcion_Sin_Filas_Zona");
	            }
	            return false;
	        }

	        // Arma set de keys BD
	        java.util.Set<String> dbKeys = new java.util.HashSet<>();
	        for (DbRow r : dbRows) {
	            dbKeys.add(buildKey(
	                r.crTienda,
	                r.remision,
	                r.fechaProgramacion,
	                r.sku,
	                r.descripcion
	            ));
	        }

	        // Compara: cada fila del grid debe existir en BD
	        int mismatches = 0;
	        for (GridRow g : gridRows) {
	            String keyGrid = buildKey(
	                g.crTienda,
	                g.remision,
	                g.fechaProgramacion,
	                g.sku,
	                g.descripcion
	            );
	            if (!dbKeys.contains(keyGrid)) mismatches++;
	        }

	        if (screenshot) {
	            testCase.addBoldTextEvidenceCurrentStep("Zonas seleccionadas (p_zonas): " + zonasSeleccionadas);
	            testCase.addBoldTextEvidenceCurrentStep("Grid filas comparadas: " + gridRows.size());
	            testCase.addBoldTextEvidenceCurrentStep("BD filas retornadas: " + dbRows.size());
	            testCase.addBoldTextEvidenceCurrentStep("Mismatches grid vs BD: " + mismatches);
	        }

	        return mismatches == 0;
	    }
	}

