	/**
	 * Selecciona dos opciones y valida multiseleccion si el filtro lo permite.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param ddl locator del dropdown a validar
	 * @param nombreFiltro nombre del filtro para evidencia y mensajes
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si la validacion aplica o se omite sin error, false en caso contrario
	 * @throws Exception si ocurre un error durante la ejecucion
	 */
	private boolean seleccionarDosYValidarMultiplesSiAplica(By ddl, String nombreFiltro, boolean screenshot) throws Exception {
	    WebDriver driver = u.getDriver();
	    WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(15));

	    // Abrir dropdown
	    wait.until(ExpectedConditions.elementToBeClickable(ddl)).click();

	    By panel = By.xpath("//ng-dropdown-panel[contains(@class,'ng-dropdown-panel')]");
	    wait.until(ExpectedConditions.visibilityOfElementLocated(panel));

	    // Opciones habilitadas (div)
	    By opcionesDiv = By.xpath("//ng-dropdown-panel//div[contains(@class,'ng-option') and not(contains(@class,'ng-option-disabled'))]");
	    wait.until(ExpectedConditions.presenceOfAllElementsLocatedBy(opcionesDiv));

	    List<WebElement> opts = driver.findElements(opcionesDiv);

	    // Si hay menos de 2, no falla, solo omite
	    if (opts.size() < 2) {
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Filtro " + nombreFiltro + " omitido: no tiene 2 opciones (encontradas: " + opts.size() + ").");
	            testCase.addScreenShotCurrentStep("MultiSelect_Omitido_" + normalizarNombrePaso(nombreFiltro));
	        }
	        new Actions(driver).sendKeys(Keys.ESCAPE).perform();
	        wait.until(ExpectedConditions.invisibilityOfElementLocated(panel));
	        return true;
	    }

	    // Click a los checkboxes de las primeras 2 opciones
	    WebElement opt1 = opts.get(0);
	    WebElement opt2 = opts.get(1);

	    String op1 = normalizarTexto(opt1.getText());
	    String op2 = normalizarTexto(opt2.getText());

	    By chkRel = By.xpath(".//input[@type='checkbox']");

	    List<WebElement> chk1 = opt1.findElements(chkRel);
	    List<WebElement> chk2 = opt2.findElements(chkRel);

	    if (chk1.isEmpty() || chk2.isEmpty()) {
	        // Si por alguna razon no hay checkbox, clic al div
	        opt1.click();
	        opt2.click();
	    } else {
	        chk1.get(0).click();
	        chk2.get(0).click();
	    }

	    if (screenshot) {
	        testCase.addTextEvidenceCurrentStep("Seleccionados en " + nombreFiltro + ": " + op1 + " | " + op2);
	        testCase.addScreenShotCurrentStep("MultiSelect_" + normalizarNombrePaso(nombreFiltro));
	    }

	    // Cerrar dropdown
	    new Actions(driver).sendKeys(Keys.ESCAPE).perform();
	    wait.until(ExpectedConditions.invisibilityOfElementLocated(panel));

	    // Validar texto mostrado en el control: buscamos dentro del mismo ng-select del placeholder
	    By valorMostrado = By.xpath(
	        "//ng-select[.//div[contains(@class,'ng-placeholder') and normalize-space()='" + nombreFiltro + "']]//div[contains(@class,'ng-value-container')]"
	    );

	    String mostrado = "";
	    List<WebElement> val = driver.findElements(valorMostrado);
	    if (!val.isEmpty()) mostrado = normalizarTexto(val.get(0).getText());

	    if (screenshot) {
	        testCase.addTextEvidenceCurrentStep("Texto mostrado en control (" + nombreFiltro + "): " + mostrado);
	    }

	    String low = mostrado.toLowerCase();
	    boolean ok = low.contains("múltiples seleccionados") || low.contains("multiples seleccionados");

	    // Si no cumplió, aquí sí falla porque el filtro SI tenía 2 opciones
	    if (!ok && screenshot) {
	        testCase.addTextEvidenceCurrentStep("Fallo CA08 en " + nombreFiltro + ": se seleccionaron 2 opciones pero no mostró 'Múltiples Seleccionados'.");
	    }

	    return ok;
	}

	/**
	 * Normaliza un texto para usarlo como nombre de paso o archivo.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param s texto a normalizar
	 * @return texto normalizado sin acentos ni caracteres especiales
	 */
	private String normalizarNombrePaso(String s) { if (s == null) return "NA"; return s.trim() .replace("ó", "o").replace("Ó", "O") .replace("í", "i").replace("Í", "I") .replace("á", "a").replace("Á", "A") .replace("é", "e").replace("É", "E") .replace("ú", "u").replace("Ú", "U") .replaceAll("[^a-zA-Z0-9 _-]", "") .replaceAll("\\s+", "_"); }

