	/**
	 * Abre un dropdown y obtiene las opciones visibles habilitadas.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param ddl locator del dropdown a abrir
	 * @param nombreFiltro nombre del filtro para evidencia
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return lista de textos de las opciones encontradas
	 * @throws Exception si ocurre un error durante la ejecucion
	 */
	private List<String> abrirDropdownYObtenerOpciones(By ddl, String nombreFiltro, boolean screenshot) throws Exception {
	    WebDriver driver = u.getDriver();
	    WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(15));

	    wait.until(ExpectedConditions.elementToBeClickable(ddl)).click();

	    By panelAbierto = By.xpath("//ng-dropdown-panel[contains(@class,'ng-dropdown-panel')]");
	    wait.until(ExpectedConditions.visibilityOfElementLocated(panelAbierto));

	    By opciones = By.xpath("//ng-dropdown-panel//div[contains(@class,'ng-option') and not(contains(@class,'ng-option-disabled'))]");
	    wait.until(ExpectedConditions.presenceOfAllElementsLocatedBy(opciones));

	    List<WebElement> elems = driver.findElements(opciones);
	    List<String> textos = new ArrayList<>();

	    for (WebElement e : elems) {
	        String t = e.getText();
	        if (t != null) {
	            t = t.trim().replaceAll("\\s+", " ");
	            if (!t.isEmpty()) textos.add(t);
	        }
	    }

	    if (screenshot) {
	        testCase.addBoldTextEvidenceCurrentStep("Filtro " + nombreFiltro + " opciones encontradas: " + textos.size());
	        testCase.addScreenShotCurrentStep("Dropdown_" + normalizarNombrePaso(nombreFiltro));
	    }

	    new Actions(driver).sendKeys(Keys.ESCAPE).perform();
	    wait.until(ExpectedConditions.invisibilityOfElementLocated(panelAbierto));

	    return textos;
	}
	
	/**
	 * Valida que los valores de base de datos existan en las opciones del dropdown.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param opcionesUI lista de opciones obtenidas desde la interfaz
	 * @param esperadosDB lista de valores esperados desde base de datos
	 * @param nombreFiltro nombre del filtro para evidencia
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si existen coincidencias entre UI y base de datos, false en caso contrario
	 */
	private boolean validarQueDBEsteEnDropdown(List<String> opcionesUI, List<String> esperadosDB, String nombreFiltro, boolean screenshot) {

	    if (opcionesUI == null || opcionesUI.isEmpty()) {
	        if (screenshot) testCase.addTextEvidenceCurrentStep("Dropdown " + nombreFiltro + " sin opciones en UI.");
	        return false;
	    }

	    if (esperadosDB == null || esperadosDB.isEmpty()) {
	        if (screenshot) testCase.addTextEvidenceCurrentStep("No se obtuvieron valores desde funcion para " + nombreFiltro);
	        return false;
	    }

	    Set<String> setUI = new HashSet<>();
	    for (String x : opcionesUI) {
	        if (x != null) setUI.add(x.toLowerCase().trim());
	    }

	    int matches = 0;
	    List<String> noEncontrados = new ArrayList<>();

	    for (String e : esperadosDB) {
	        if (e == null) continue;
	        String key = e.toLowerCase().trim();
	        if (setUI.contains(key)) {
	            matches++;
	        } else {
	            noEncontrados.add(e);
	        }
	    }

	    // Regla: mínimo 1 match para validar origen (evita fallos por virtualización)
	    boolean ok = matches >= 1;

	    if (!ok) {
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep(
	                "No hubo coincidencias entre DB y UI en " + nombreFiltro +
	                ". DB muestra: " + String.join(" | ", esperadosDB) +
	                " | UI tamaño: " + opcionesUI.size()
	            );
	        }
	        return false;
	    }

	    if (screenshot) {
	        testCase.addBoldTextEvidenceCurrentStep("Dropdown " + nombreFiltro + " OK. Coincidencias DB vs UI: " + matches + " de " + esperadosDB.size());
	        if (!noEncontrados.isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("Valores DB no encontrados (posible virtualizacion): " + String.join(" | ", noEncontrados));
	        }
	    }

	    return true;
	}

	/**
	 * Obtiene una muestra de valores distinct de un filtro desde base de datos segun el perfil del usuario.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @param usuario usuario para obtener perfil y llaves de acceso
	 * @param colName nombre de columna a consultar en la funcion de filtros
	 * @param limite numero maximo de registros a retornar
	 * @return lista de valores distinct obtenidos desde base de datos
	 * @throws Exception si ocurre un error durante la ejecucion
	 */
	private List<String> obtenerMuestraFiltersDistinctPorUsuario(
	        boolean screenshot,
	        String usuario,
	        String colName,
	        int limite) throws Exception {

	    String dbUrl = GlobalVariables.DB_URL_Cometa;
	    String dbUser = GlobalVariables.DB_USER_Cometa;
	    String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	    List<String> out = new ArrayList<>();

	    try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPassword)) {

	        String perfil = obtenerPerfilUsuario(conn, usuario);
	        if (perfil == null || perfil.trim().isEmpty()) {
	            throw new Exception("No se obtuvo PCPERFIL para usuario: " + usuario);
	        }
	        perfil = perfil.trim();

	        boolean esAdminTotal = "ADMIN".equalsIgnoreCase(perfil) || "OXXO_OS".equalsIgnoreCase(perfil);

	        String rfc = null;
	        String pcplaza = null;

	        if (!esAdminTotal) {
	            rfc = obtenerKey(conn, usuario, "PCRFC");
	            pcplaza = obtenerKey(conn, usuario, "PCPLAZA");
	        }

	        String base =
	            "select distinct " + colName + " as v " +
	            "from public.get_cambios_fisicos_directos_pendientes_filters() " +
	            "where " + colName + " is not null ";

	        String wherePerfil = "";
	        List<Object> params = new ArrayList<>();

	        if (!esAdminTotal) {

	            if ("OXXO_PLAZA".equalsIgnoreCase(perfil)) {
	                if (pcplaza == null || pcplaza.trim().isEmpty()) {
	                    throw new Exception("Perfil OXXO_PLAZA sin PCPLAZA.");
	                }

	                // En tu UI de Plaza se vio formato "32XAP 10CAN Xcaret" que es campo "plaza"
	                // Entonces filtramos por plaza. Si tu PCPLAZA trae ese mismo formato, esto jala.
	                if ("plaza".equalsIgnoreCase(colName)) {
	                    wherePerfil = " and plaza = ? ";
	                } else {
	                    // Para otros campos, igual filtramos por plaza para acotar el dataset del usuario
	                    wherePerfil = " and plaza = ? ";
	                }

	                params.add(pcplaza.trim());

	            } else {
	                // Default: ADMIN_OPERATIVO / COMERCIAL => RFC
	                if (rfc == null || rfc.trim().isEmpty()) {
	                    throw new Exception("Perfil no admin sin PCRFC.");
	                }
	                wherePerfil = " and rfc = ? ";
	                params.add(rfc.trim());
	            }
	        }

	        String sql =
	            base + wherePerfil +
	            " order by 1 " +
	            " limit ?;";

	        try (PreparedStatement ps = conn.prepareStatement(sql)) {
	            int idx = 1;
	            for (Object p : params) {
	                ps.setString(idx++, String.valueOf(p));
	            }
	            ps.setInt(idx, limite);

	            try (ResultSet rs = ps.executeQuery()) {
	                while (rs.next()) {
	                    String v = rs.getString("v");
	                    if (v != null) {
	                        v = v.trim().replaceAll("\\s+", " ");
	                        if (!v.isEmpty()) out.add(v);
	                    }
	                }
	            }
	        }

	        if (screenshot) {
	            testCase.addBoldTextEvidenceCurrentStep("Perfil: " + perfil);
	            testCase.addBoldTextEvidenceCurrentStep("DB distinct " + colName + ": " + out.size());
	            if (!out.isEmpty()) testCase.addTextEvidenceCurrentStep("Ejemplo DB " + colName + ": " + out.get(0));
	        }
	    }

	    return out;
	}

	/**
	 * Obtiene el valor de una llave de usuario desde base de datos.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param conn conexion activa a base de datos
	 * @param usuario usuario a consultar
	 * @param shortName nombre corto de la llave
	 * @return valor de la llave o null si no existe
	 * @throws Exception si ocurre un error durante la ejecucion
	 */
	private String obtenerKey(Connection conn, String usuario, String shortName) throws Exception {
	    String sql =
	        "select k.key_value " +
	        "from xxcm_user_keys k " +
	        "where k.short_name = '" + shortName + "' " +
	        "and k.usuario_id = (select u.usuario_id from xxcm_usuarios u where u.usuario = '" + usuario + "');";

	    try (Statement st = conn.createStatement();
	         ResultSet rs = st.executeQuery(sql)) {
	        if (rs.next()) return rs.getString("key_value");
	    }
	    return null;
	}

	/**
	 * Obtiene el perfil del usuario desde base de datos.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param conn conexion activa a base de datos
	 * @param usuario usuario a consultar
	 * @return perfil del usuario o null si no existe
	 * @throws Exception si ocurre un error durante la ejecucion
	 */
	private String obtenerPerfilUsuario(Connection conn, String usuario) throws Exception {
	    return obtenerKey(conn, usuario, "PCPERFIL");
	}

	/**
	 * Valida el tooltip de los botones de paginacion en la vista de ticket CF detalle.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param boton nombre del boton de paginacion a validar
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si el tooltip es correcto, false en caso contrario
	 */
	public boolean validarTooltipBotonPaginacionTicketCFdet(String boton, boolean screenshot) {
		try {
	        WebDriver driver = u.getDriver();

	        // Elegir el botón según el nombre
	        By botonLocator;
	        switch (boton.toLowerCase()) {
	            case "primero":
	                botonLocator = xmlPaginaPrimeraPaginaButtonCFdet;
	                break;
	            case "anterior":
	                botonLocator = xmlPaginaAnteriorButtonCFdet;
	                break;
	            case "siguiente":
	                botonLocator = xmlPaginaSiguienteButtonCFdet;
	                break;
	            case "ultimo":
	                botonLocator = xmlPaginaUltimaPaginaButtonCFdet;
	                break;
	            default:
	                System.out.println("No existe ese botón de paginación: " + boton);
	                return false;
	        }

	        // Asegurar visibilidad del botón en viewport
	        u.waitWebElement(botonLocator, 30, 2);
	        u.scrollToElement(botonLocator);
	        WebElement botonWeb = driver.findElement(botonLocator);

	        if (!botonWeb.isDisplayed()) {
	            System.out.println("El botón '" + boton + "' no es visible");
	            return false;
	        }

	        // Tomar el texto esperado del aria-label del propio botón
	        String esperado = botonWeb.getAttribute("aria-label");
	        if (esperado == null) esperado = "";
	        esperado = esperado.trim();

	        // Hover para disparar el tooltip
	        
	        u.highLight(botonLocator);
	        org.openqa.selenium.interactions.Actions actions = new org.openqa.selenium.interactions.Actions(driver);
	        actions.moveToElement(botonWeb).perform();
	        // pequeño nudge por si el hover necesita movimiento
	        actions.moveByOffset(1, 1).perform();

	        // Esperar a que aparezca el tooltip en el overlay (Angular Material MDC)
	        java.time.Duration timeout = java.time.Duration.ofSeconds(5);
	        org.openqa.selenium.support.ui.WebDriverWait wait = new org.openqa.selenium.support.ui.WebDriverWait(driver, timeout);

	        // Selectores posibles de tooltip
	        By tooltipSelector = By.cssSelector(
	            ".mat-mdc-tooltip .mat-mdc-tooltip-surface, " +     // Angular Material MDC
	            ".mat-mdc-tooltip .mdc-tooltip__surface, " +        // Variante MDC
	            ".mat-tooltip-panel .mat-tooltip"                    // Legacy
	        );

	        WebElement tooltipEl = wait.until(
	            org.openqa.selenium.support.ui.ExpectedConditions.visibilityOfElementLocated(tooltipSelector)
	        );

	        // Obtener el texto mostrado
	        String mostrado = tooltipEl.getText();
	        if (mostrado == null || mostrado.trim().isEmpty()) {
	            // Fallback: a veces el texto se refleja como aria-label/title del botón
	            String fallback = botonWeb.getAttribute("title");
	            if (fallback == null || fallback.trim().isEmpty()) {
	                mostrado = "";
	            } else {
	                mostrado = fallback.trim();
	            }
	        } else {
	            mostrado = mostrado.trim();
	        }

	        boolean coincide = !mostrado.isEmpty() && (esperado.isEmpty() ? true : mostrado.equals(esperado));

	        

	        if (!coincide) {
	            System.out.println("Tooltip no coincide. Mostrado='" + mostrado + "' Esperado='" + esperado + "'");
	            return false;
	        } else {
	            System.out.println("Tooltip OK. '" + mostrado + "'");
	        }
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Se visualiza el tool tip: '" + mostrado + "'");
	            testCase.addScreenShotCurrentStep(u, "Tooltip paginación");
	        }
	        u.unhighLight(botonLocator);
	        return coincide;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error en validarTooltipBotonPaginacion: " + e.getMessage());
	        System.out.println("Error en validarTooltipBotonPaginacion: " + e.getMessage());
	        return false;
	    }
	}
