 	/**
 	 * Da click a un boton de paginacion en CF detalle y valida que cambie el rango mostrado.
 	 *
 	 * @author Jose Pecina
 	 * @date Enero 2026
 	 * @param boton nombre del boton de paginacion a seleccionar
 	 * @param screenshot indica si se toma evidencia en el reporte
 	 * @return true si la paginacion cambia correctamente, false en caso contrario
 	 */
 	public boolean clickBotonPaginacionCFdet(String boton, boolean screenshot) {
 	    try {
 	        boolean result = true;
 	        WebDriver driver = u.getDriver();
 	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));

 	        By botonLocator = null;
 	        switch (boton.toLowerCase()) {
 	            case "primero":
 	                botonLocator = xmlPaginaPrimeraPaginaButtonCFdet;
 	                break;
 	            case "anterior":
 	                botonLocator = xmlPaginaAnteriorButtonCFdet;
 	                break;
 	            case "siguiente":
 	                botonLocator = xmlPaginaSiguienteButtonCFdet;
 	                break;
 	            case "ultimo":
 	                botonLocator = xmlPaginaUltimaPaginaButtonCFdet;
 	                break;
 	            default:
 	                System.out.println("No existe ese botón de paginación: " + boton);
 	                return false;
 	        }

 	        // Validar visible/habilitado
 	        u.scrollToElement(botonLocator);
 	        WebElement botonWeb = wait.until(ExpectedConditions.visibilityOfElementLocated(botonLocator));

 	        if (!botonWeb.isDisplayed()) {
 	            System.out.println("El botón '" + boton + "' no es visible");
 	            return false;
 	        }
 	        if (!botonWeb.isEnabled()) {
 	            System.out.println("El botón '" + boton + "' está deshabilitado");
 	            return false;
 	        }

 	        // Estado inicial (NUMERACION): range label del paginator
 	        String labelInicial = wait.until(ExpectedConditions.visibilityOfElementLocated(xmlPaginacionLabelOFCFdet))
 	                                  .getText().trim();

 	        // Click con evidencia
 	        u.scrollToElement(botonLocator);
 	        u.highLight(botonLocator);
 	        if (screenshot) {
 	            testCase.addTextEvidenceCurrentStep("Click en botón " + boton);
 	            testCase.addScreenShotCurrentStep(u, "Click paginacion " + boton);
 	        }
 	        u.unhighLight(botonLocator);

 	        wait.until(ExpectedConditions.elementToBeClickable(botonLocator)).click();
 	       if (!MensajeEspereDesaparece(false)) {
	            testCase.addTextEvidenceCurrentStep("Falló al desaparecer el mensaje espere un momento");
	            return false;
	        }
 	        // Esperar a que cambie el range label (si no cambia, no paginó)
 	        wait.until(ExpectedConditions.not(
 	            ExpectedConditions.textToBePresentInElementLocated(xmlPaginacionLabelOFCFdet, labelInicial)
 	        ));

 	        String labelNuevo = driver.findElement(xmlPaginacionLabelOFCFdet).getText().trim();

 	        if (labelInicial.equals(labelNuevo)) {
 	            System.out.println("La paginación no cambió, sigue mostrando: " + labelInicial);
 	            result = false;
 	        } else {
 	            if (screenshot) {
 	                testCase.addTextEvidenceCurrentStep("La paginación cambió de '" + labelInicial + "' a '" + labelNuevo + "'");
 	                testCase.addScreenShotCurrentStep(u, "Paginacion cambio " + boton);
 	            }
 	            System.out.println("La paginación cambió de '" + labelInicial + "' a '" + labelNuevo + "'");
 	            result = true;
 	        }

 	        return result;

 	    } catch (Exception e) {
 	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
 	        System.out.println("Error en clickBotonPaginacionCFdet: " + e.getMessage());
 	        return false;
 	    }
 	}


