 	/**
 	 * Selecciona opciones de paginacion en CF detalle y valida que el grid respete el numero de filas.
 	 *
 	 * @author Jose Pecina
 	 * @date Enero 2026
 	 * @param screenshot indica si se toma evidencia en el reporte
 	 * @return true si la paginacion se aplica correctamente, false en caso contrario
 	 * @throws Exception si ocurre un error durante la ejecucion
 	 */
 	public boolean SelecPaginacionCFDetalle(boolean screenshot) throws Exception {
 	    try {
 	        WebDriver driver = u.getDriver();
 	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));

 	        By xmlTabla = By.xpath("//data-grid//table[contains(@class,'mat-mdc-table')]");
 	        By xmlFilasGrid = By.xpath("//data-grid//table[contains(@class,'mat-mdc-table')]//tbody//tr");
 	        By xmlSelectPaginacion = By.xpath("//data-grid//mat-paginator//mat-select");
 	        By xmlPanelAbierto = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//div[contains(@class,'mat-mdc-select-panel') and @role='listbox']");
 	        By xmlOpciones = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-option//span[contains(@class,'mdc-list-item__primary-text')]");

 	        wait.until(ExpectedConditions.visibilityOfElementLocated(xmlTabla));

 	        List<String> opcionesPaginacion = Arrays.asList("5", "10", "15", "20");

 	        for (String opcion : opcionesPaginacion) {

 	            u.scrollToElement(xmlSelectPaginacion);
 	            wait.until(ExpectedConditions.elementToBeClickable(xmlSelectPaginacion)).click();
 	           if (!MensajeEspereDesaparece(false)) {
		            testCase.addTextEvidenceCurrentStep("Falló al desaparecer el mensaje espere un momento");
		            return false;
		        }
 	            wait.until(ExpectedConditions.visibilityOfElementLocated(xmlPanelAbierto));
 	            List<WebElement> opciones = wait.until(ExpectedConditions.visibilityOfAllElementsLocatedBy(xmlOpciones));

 	            boolean opcionEncontrada = false;
 	            for (WebElement opt : opciones) {
 	                if (opt.getText().trim().equals(opcion)) {
 	                    opt.click();
 	                    opcionEncontrada = true;
 	                    break;
 	                }
 	            }

 	            if (!opcionEncontrada) {
 	                testCase.addTextEvidenceCurrentStep("Opcion de paginacion no encontrada: " + opcion);
 	                driver.findElement(By.tagName("body")).sendKeys(org.openqa.selenium.Keys.ESCAPE);
 	                return false;
 	            }

 	            // Esperar refresco: que el page-size mostrado ya sea el seleccionado
 	            By xmlPageSizeMostrado = By.xpath("//data-grid//mat-paginator//mat-select//span[contains(@class,'mat-mdc-select-min-line')]");
 	            wait.until(ExpectedConditions.textToBePresentInElementLocated(xmlPageSizeMostrado, opcion));

 	            // Margen de render del grid
 	            u.hardWait(1);

 	            int totalFilas = driver.findElements(xmlFilasGrid).size();

 	            // Validacion: nunca debe haber mas filas que la opcion
 	            if (totalFilas <= Integer.parseInt(opcion)) {
 	            	u.scrollToElement(xmlSelectPaginacion);
 	                u.highLight(xmlSelectPaginacion);
 	                if (screenshot) {
 	                    testCase.addTextEvidenceCurrentStep("Opcion " + opcion + ". Filas visibles: " + totalFilas);
 	                    testCase.addScreenShotCurrentStep(u, "Paginacion opcion " + opcion);
 	                }
 	                u.unhighLight(xmlSelectPaginacion);

 	            } else {
 	                testCase.addTextEvidenceCurrentStep("Error. Opcion " + opcion + " pero filas visibles: " + totalFilas);
 	                return false;
 	            }
 	        }

 	        return true;

 	    } catch (Exception e) {
 	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
 	        throw new Exception("Error " + e.getMessage());
 	    }
 	}


 	/**
 	 * Valida que el selector de paginacion muestre las opciones esperadas en CF.
 	 *
 	 * @author Jose Pecina
 	 * @date Enero 2026
 	 * @param screenshot indica si se toma evidencia en el reporte
 	 * @return true si se encuentran todas las opciones esperadas, false en caso contrario
 	 * @throws Exception si ocurre un error durante la ejecucion
 	 */
	public boolean OpcionesPaginacionDispCF(boolean screenshot) throws Exception {
	    try {
	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));

	        By xmlSelectPaginacion = By.xpath("//data-grid//mat-paginator//mat-select");

	        u.scrollToElement(xmlSelectPaginacion);
	        wait.until(ExpectedConditions.elementToBeClickable(xmlSelectPaginacion)).click();

	        // Esperar panel abierto del mat-select (tu HTML: div role=listbox con class mat-mdc-select-panel)
	        By xmlPanelAbierto = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//div[contains(@class,'mat-mdc-select-panel') and @role='listbox']");
	        wait.until(ExpectedConditions.visibilityOfElementLocated(xmlPanelAbierto));

	        // Opciones: el texto real viene en span.mdc-list-item__primary-text
	        By xmlOpcionesTxt = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-option//span[contains(@class,'mdc-list-item__primary-text')]");
	        List<WebElement> opciones = wait.until(ExpectedConditions.visibilityOfAllElementsLocatedBy(xmlOpcionesTxt));

	        List<String> actualValues = new ArrayList<>();
	        for (WebElement op : opciones) {
	            actualValues.add(op.getText().trim());
	        }

	        List<String> expectedValues = Arrays.asList("5", "10", "15", "20");

	        boolean ok = actualValues.containsAll(expectedValues);

	        u.highLight(xmlSelectPaginacion);
	        if (screenshot) {
	            if (ok) {
	                testCase.addTextEvidenceCurrentStep("Opciones de paginacion encontradas: " + actualValues);
	            } else {
	                testCase.addTextEvidenceCurrentStep("Faltan opciones. Encontradas: " + actualValues);
	            }
	            testCase.addScreenShotCurrentStep(u, "Opciones paginacion");
	        }
	        u.unhighLight(xmlSelectPaginacion);

	        // Cerrar dropdown
	        driver.findElement(By.tagName("body")).sendKeys(org.openqa.selenium.Keys.ESCAPE);

	        return ok;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}



