	/**
	 * Valida que las fechas del grid en cambios fisicos detalles esten ordenadas de mas reciente a mas antiguo.
	 *
	 * @author Jose Pecina
	 * @date Noviembre 2025
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si las fechas estan en orden descendente, false en caso contrario
	 * @throws Exception si ocurre un error durante la ejecucion
	 */
 	public boolean AutoGridDirectosFechasCFDetalles(boolean screenshot) throws Exception{
 		try {
 			
 			u.waitWebElement(xmlDatosTablaDirect, 60, 5);
        	u.scrollToElement(xmlDatosTablaDirect);
        	
 			  // Base del xpath de la tabla
 		    String xpathBase = "/html/body/app-root/app-directos-cambios-fisicos-pendientes/div/div/div[2]/data-grid/div/table/tbody/tr[1]/td[4]";
 		    
 		    // Obtener todas las fechas de la columna 4
 		    List<WebElement> fechasElems = u.getDriver().findElements(By.xpath(xpathBase));
 		    List<LocalDate> fechas = new ArrayList<>();
 		    
 		    // El formato de fechas: yyyy-MM-dd
 		   DateTimeFormatter fmt = DateTimeFormatter.ofPattern("dd/MM/yyyy");

 		    // Parsear fechas
 		    for (WebElement elem : fechasElems) {
 		        String texto = elem.getText().trim();
 		        if (!texto.isEmpty()) {
 		            fechas.add(LocalDate.parse(texto, fmt));
 		        }
 		    }

 		    // Validar que estén de más reciente a más antigua
 		    for (int i = 0; i < fechas.size() - 1; i++) {
 		        if (fechas.get(i).isBefore(fechas.get(i + 1))) {
 		            System.out.println("Error: " + fechas.get(i) + " es más antigua que " + fechas.get(i+1));
 		            return false;
 		        }
 		    }
 		   if(screenshot) {
 				 testCase.addTextEvidenceCurrentStep("Se visualizan los registros de Cambios físicos ordenados del más reciente al más antiguo");
 				 testCase.addScreenShotCurrentStep(u, "Pantalla CF");
 				 }
 		    System.out.println("Todas las fechas están en orden descendente");
 		    return true;
 		}catch (Exception e) {			
 			testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
 			throw new Exception ("Error " + e.getMessage()); 			
		}
 	}
 	
 	/**
 	 * Valida el tooltip del boton Cambios fisicos pendientes al pasar el cursor.
 	 *
 	 * @author Jose Pecina
 	 * @date Enero 2026
 	 * @param screenshot indica si se toma evidencia en el reporte
 	 * @return true si el tooltip muestra el texto esperado, false en caso contrario
 	 * @throws Exception si ocurre un error durante la ejecucion
 	 */
	public boolean validarTooltipCambiosFisicos(boolean screenshot) throws Exception {
		 try {
		        WebDriver driver = u.getDriver();

		        By btnCambiosFisicosPendientes = By.xpath(
		            "//button[contains(@class,'btn-pendientes') and contains(@class,'mat-mdc-tooltip-trigger')]" +
		            "[.//span[contains(@class,'titulo') and contains(normalize-space(),'Cambios físicos')]]"
		        );

		        By tooltipSurface = By.xpath(
		            "//div[contains(@class,'cdk-overlay-container')]//div[contains(@class,'mdc-tooltip__surface') and contains(@class,'mdc-tooltip__surface-animation')]"
		        );

		        WebDriverWait waitBtn = new WebDriverWait(driver, Duration.ofSeconds(5));
		        waitBtn.until(ExpectedConditions.visibilityOfElementLocated(btnCambiosFisicosPendientes));

		        WebElement btn = driver.findElement(btnCambiosFisicosPendientes);
		        ((JavascriptExecutor) driver).executeScript("arguments[0].scrollIntoView({block:'center', inline:'center'});", btn);

		        String jsHover = ""
		            + "const el = arguments[0];"
		            + "const r = el.getBoundingClientRect();"
		            + "const x = Math.floor(r.left + (r.width/2));"
		            + "const y = Math.floor(r.top + (r.height/2));"
		            + "const opts = {bubbles:true, cancelable:true, view:window, clientX:x, clientY:y};"
		            + "el.dispatchEvent(new MouseEvent('mouseenter', opts));"
		            + "el.dispatchEvent(new MouseEvent('mouseover', opts));"
		            + "el.dispatchEvent(new MouseEvent('mousemove', opts));"
		            + "return true;";

		        ((JavascriptExecutor) driver).executeScript(jsHover, btn);

		        WebDriverWait waitTooltip = new WebDriverWait(driver, Duration.ofSeconds(5));
		        waitTooltip.until(ExpectedConditions.visibilityOfElementLocated(tooltipSurface));

		        String texto = driver.findElement(tooltipSurface).getText().trim();
		        boolean textoOk = texto.equalsIgnoreCase("Cambios físicos de hoy") || texto.equalsIgnoreCase("Cambios fisicos de hoy");

		        if (!textoOk) {
		            testCase.addTextEvidenceCurrentStep("El tooltip no mostró el texto esperado. Texto real: '" + texto + "'");
		            driver.findElement(By.tagName("body")).click();
		            return false;
		        }

		        if (screenshot) {
		            u.highLight(btnCambiosFisicosPendientes);
		            testCase.addTextEvidenceCurrentStep("Se visualiza el tooltip con el texto: 'Cambios físicos de hoy' correctamente");
		            testCase.addScreenShotCurrentStep(u, "Tooltip Cambios físicos de hoy");
		            u.unhighLight(btnCambiosFisicosPendientes);
		        } else {
		            testCase.addTextEvidenceCurrentStep("Se visualiza el tooltip con el texto: 'Cambios físicos de hoy' correctamente");
		        }

		        driver.findElement(By.tagName("body")).click();
		        return true;

		    } catch (Exception e) {
		        try {
		            u.getDriver().findElement(By.tagName("body")).click();
		        } catch (Exception ex) {
		        }
		        testCase.addTextEvidenceCurrentStep("Falló la validación del tooltip 'Cambios físicos de hoy': " + e.getMessage());
		        return false;
		    }
	}
	
	/**
	 * Valida el tiempo de aparicion y permanencia del tooltip del boton Cambios fisicos pendientes.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si el tooltip aparece en el tiempo esperado y se mantiene visible, false en caso contrario
	 * @throws Exception si ocurre un error durante la ejecucion
	 */
	public boolean validarTooltipCambiosFisicosTiempo(boolean screenshot) throws Exception {
	    try {
	        WebDriver driver = u.getDriver();

	        By btnCambiosFisicosPendientes = By.xpath(
	            "//button[contains(@class,'btn-pendientes') and contains(@class,'mat-mdc-tooltip-trigger')]" +
	            "[.//span[contains(@class,'titulo') and contains(normalize-space(),'Cambios físicos')]]"
	        );

	        By tooltipSurface = By.xpath(
	            "//div[contains(@class,'cdk-overlay-container')]//div[contains(@class,'mdc-tooltip__surface') and contains(@class,'mdc-tooltip__surface-animation')]"
	        );

	        WebDriverWait waitBtn = new WebDriverWait(driver, Duration.ofSeconds(5));
	        waitBtn.until(ExpectedConditions.visibilityOfElementLocated(btnCambiosFisicosPendientes));

	        WebElement btn = driver.findElement(btnCambiosFisicosPendientes);
	        ((JavascriptExecutor) driver).executeScript("arguments[0].scrollIntoView({block:'center', inline:'center'});", btn);

	        String jsHover = ""
	            + "const el = arguments[0];"
	            + "const r = el.getBoundingClientRect();"
	            + "const x = Math.floor(r.left + (r.width/2));"
	            + "const y = Math.floor(r.top + (r.height/2));"
	            + "const opts = {bubbles:true, cancelable:true, view:window, clientX:x, clientY:y};"
	            + "el.dispatchEvent(new MouseEvent('mouseenter', opts));"
	            + "el.dispatchEvent(new MouseEvent('mouseover', opts));"
	            + "el.dispatchEvent(new MouseEvent('mousemove', opts));"
	            + "return true;";

	        long startNs = System.nanoTime();
	        ((JavascriptExecutor) driver).executeScript(jsHover, btn);

	        WebDriverWait waitTooltip = new WebDriverWait(driver, Duration.ofMillis(500));
	        waitTooltip.pollingEvery(Duration.ofMillis(25));
	        waitTooltip.until(ExpectedConditions.visibilityOfElementLocated(tooltipSurface));

	        long elapsedMs = (System.nanoTime() - startNs) / 1_000_000;

	        WebElement tooltip = driver.findElement(tooltipSurface);
	        String texto = tooltip.getText().trim();
	        boolean textoOk = texto.equalsIgnoreCase("Cambios físicos de hoy") || texto.equalsIgnoreCase("Cambios fisicos de hoy");

	        if (!textoOk) {
	            testCase.addTextEvidenceCurrentStep("El tooltip no mostró el texto esperado. Texto real: '" + texto + "'");
	            driver.findElement(By.tagName("body")).click();
	            return false;
	        }

	        if (screenshot) {
	            u.highLight(btnCambiosFisicosPendientes);
	            u.highLight(tooltipSurface);
	            testCase.addTextEvidenceCurrentStep("Se visualiza el tooltip en un tiempo máximo de 0.5 segundos (tiempo: " + elapsedMs + " ms) y se mantiene visible mientras el cursor permanece sobre el botón");
	            testCase.addScreenShotCurrentStep(u, "Tooltip visible en 0.5s y mantenido");
	            u.unhighLight(tooltipSurface);
	            u.unhighLight(btnCambiosFisicosPendientes);
	        } else {
	            testCase.addTextEvidenceCurrentStep("Se visualiza el tooltip en un tiempo máximo de 0.5 segundos (tiempo: " + elapsedMs + " ms) y se mantiene visible mientras el cursor permanece sobre el botón");
	        }

	        u.hardWait(1);

	        List<WebElement> tooltips = driver.findElements(tooltipSurface);
	        boolean sigueVisible = !tooltips.isEmpty() && tooltips.get(0).isDisplayed();

	        if (!sigueVisible) {
	            testCase.addTextEvidenceCurrentStep("El tooltip no se mantuvo visible mientras el cursor permanecía sobre el botón");
	            driver.findElement(By.tagName("body")).click();
	            return false;
	        }

	        driver.findElement(By.tagName("body")).click();
	        return true;

	    } catch (Exception e) {
	        try { u.getDriver().findElement(By.tagName("body")).click(); } catch (Exception ex) {}
	        testCase.addTextEvidenceCurrentStep("Falló la validación de tiempo/visibilidad del tooltip: " + e.getMessage());
	        return false;
	    }
	}


