 	/**
 	 * Selecciona un rango de fechas en CF con base en una fecha obtenida de BD y valida el filtro.
 	 *
 	 * @author Jose Pecina
 	 * @date Septiembre 2025
 	 * @param usuario usuario para obtener perfil y fecha desde base de datos
 	 * @param screenshot indica si se toma evidencia en el reporte
 	 * @return true si se visualiza el filtro y se selecciona el rango correctamente, false en caso contrario
 	 * @throws Exception si ocurre un error durante la ejecucion
 	 */
 	public boolean SelecFechaCF(String usuario, boolean screenshot) throws Exception {
 	    try {
 	        boolean result;

 	        String dbUrl = GlobalVariables.DB_URL_Cometa;
 	        String dbUser = GlobalVariables.DB_USER_Cometa;
 	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

 	        String PCPERFIL =
 	            "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' " +
 	            "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

 	        String PCRFC =
 	            "select key_value from xxcm_user_keys where short_name in ('PCRFC', 'PCSUPPLIERID','PCPLAZA') " +
 	            "and usuario_id in (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

 	        String FechaBD = null;

 	        // Validar que exista el filtro de fechas
 	        if (u.isDisplayed(xmlRangoFechas)) {
 	            u.highLight(xmlRangoFechas);

 	            if (screenshot) {
 	                testCase.addTextEvidenceCurrentStep("Se visualiza el filtro del rango de fechas");
 	                testCase.addScreenShotCurrentStep(u, "FiltroFechas");
 	            }

 	            u.unhighLight(xmlRangoFechas);
 	            result = true;
 	        } else {
 	            return false;
 	        }

 	        // Obtener fecha desde BD con conteo <=999, considerando perfil
 	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
 	             Statement stmt = connection.createStatement()) {

 	            String perfil = null;

 	            try (ResultSet rsPerfil = stmt.executeQuery(PCPERFIL)) {
 	                if (rsPerfil.next()) {
 	                    perfil = rsPerfil.getString("key_value");
 	                    System.out.println("Usuario con perfil: " + perfil);
 	                }
 	            }

 	            if (perfil != null) {

 	                if (!"ADMIN".equalsIgnoreCase(perfil) && !"OXXO_OS".equalsIgnoreCase(perfil)) {

 	                    String rfc = null;
 	                    try (ResultSet rsRfc = stmt.executeQuery(PCRFC)) {
 	                        if (rsRfc.next()) {
 	                            rfc = rsRfc.getString("key_value");
 	                        } else {
 	                            System.out.println("No se obtuvo RFC.");
 	                            return false;
 	                        }
 	                    }

 	                    String sqlFechaMenor1000;

 	                    if ("OXXO_PLAZA".equalsIgnoreCase(perfil)) {
 	                        sqlFechaMenor1000 =
 	                            "select fecha " +
 	                            "from xxcm_cf " +
 	                            "where cr_desc_plaza = '" + rfc + "' " +
 	                            "group by fecha " +
 	                            "having count(*) <= 999 " +
 	                            "order by fecha desc " +
 	                            "limit 1";
 	                    } else {
 	                        sqlFechaMenor1000 =
 	                            "select fecha " +
 	                            "from xxcm_cf " +
 	                            "where proveedor_rfc = '" + rfc + "' " +
 	                            "group by fecha " +
 	                            "having count(*) <= 999 " +
 	                            "order by fecha desc " +
 	                            "limit 1";
 	                    }

 	                    try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMenor1000)) {
 	                        if (rsFecha.next()) {
 	                            FechaBD = rsFecha.getString("fecha");
 	                            System.out.println("Fecha seleccionada (<=999): " + FechaBD);
 	                        } else {
 	                            System.out.println("No se obtuvo informacion (sin fecha <=999).");
 	                            return false;
 	                        }
 	                    }

 	                } else {
 	                    // ADMIN / OXXO_OS => sin RFC
 	                    String sqlFechaMenor1000Admin =
 	                        "select fecha " +
 	                        "from xxcm_cf " +
 	                        "group by fecha " +
 	                        "having count(*) <= 999 " +
 	                        "order by fecha desc " +
 	                        "limit 1";

 	                    try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMenor1000Admin)) {
 	                        if (rsFecha.next()) {
 	                            FechaBD = rsFecha.getString("fecha");
 	                            System.out.println("Fecha seleccionada (ADMIN/OXXO_OS <=999): " + FechaBD);
 	                        } else {
 	                            System.out.println("No se obtuvo informacion (ADMIN/OXXO_OS sin fecha <=999).");
 	                            return false;
 	                        }
 	                    }
 	                }

 	            } else {
 	                // Fallback: si no hay perfil, usar RFC
 	                String rfc = null;
 	                try (ResultSet rsRfc = stmt.executeQuery(PCRFC)) {
 	                    if (rsRfc.next()) {
 	                        rfc = rsRfc.getString("key_value");
 	                    } else {
 	                        System.out.println("No se obtuvo RFC (fallback).");
 	                        return false;
 	                    }
 	                }

 	                String sqlFechaMenor1000Fallback =
 	                    "select fecha " +
 	                    "from xxcm_cf " +
 	                    "where proveedor_rfc = '" + rfc + "' " +
 	                    "group by fecha " +
 	                    "having count(*) <= 999 " +
 	                    "order by fecha desc " +
 	                    "limit 1";

 	                try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMenor1000Fallback)) {
 	                    if (rsFecha.next()) {
 	                        FechaBD = rsFecha.getString("fecha");
 	                        System.out.println("Fecha seleccionada (fallback <=999): " + FechaBD);
 	                    } else {
 	                        System.out.println("No se obtuvo informacion (fallback sin fecha <=999).");
 	                        return false;
 	                    }
 	                }
 	            }
 	        }

 	        if (FechaBD == null || FechaBD.trim().isEmpty()) {
 	            testCase.addTextEvidenceCurrentStep("No se obtuvo FechaBD valida");
 	            return false;
 	        }

 	        centroDescargasFiltradoFecha = FechaBD;

 	        // Parsear fecha
 	        LocalDate fechaConvert;
 	        try {
 	            fechaConvert = LocalDateTime
 	                .parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))
 	                .toLocalDate();
 	        } catch (Exception ex) {
 	            fechaConvert = LocalDate.parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
 	        }

 	        // Abrir datepicker y seleccionar rango
 	        WebDriver driver = u.getDriver();
 	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

 	        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
 	        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

 	        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
 	        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

 	        By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
 	        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

 	        if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
 	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
 	        }

 	        clickYear(driver, wait, fechaConvert.getYear());
 	        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

 	        clickDay(driver, wait, fechaConvert.minusDays(1).getDayOfMonth());
 	        clickDay(driver, wait, fechaConvert.getDayOfMonth());

 	        wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));

 	        if (screenshot) {
 	            testCase.addTextEvidenceCurrentStep(
 	                "Se selecciono rango de fechas: " + fechaConvert.minusDays(1) + " a " + fechaConvert + " (BD <=999 )"
 	            );
 	            testCase.addScreenShotCurrentStep(u, "RangoFechasSeleccionado");
 	        }

 	        return result;

 	    } catch (Exception e) {
 	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
 	        throw new Exception("Error " + e.getMessage());
 	    }
 	}
	
	/**
	 * Valida que la primera fila del Centro de descargas este En proceso y con fecha de hoy.
	 *
	 * @author Jose Pecina
	 * @date Enero 2026
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si la primera fila cumple estatus y fecha, false en caso contrario
	 * @throws Exception si ocurre un error durante la ejecucion
	 */
	public boolean validarPrimeraFilaEnProcesoCentroDescargas(boolean screenshot) throws Exception {
	    try {
	        String hoy = LocalDate.now().format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));

	        By tabla = By.xpath("//table[contains(@class,'mat-mdc-table')]");
	        By filas = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr");

	        By btnFirst = By.xpath("//mat-paginator//button[contains(@class,'mat-mdc-paginator-navigation-first')]");
	        By rangeLbl = By.xpath("//mat-paginator//div[contains(@class,'mat-mdc-paginator-range-label')]");

	        u.waitWebElement(tabla, 30, 5);

	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	        // Ir a primera pagina 
	        if (driver.findElements(btnFirst).size() > 0) {
	            WebElement first = driver.findElement(btnFirst);
	            if (first.isEnabled()) {
	                String rangoAntes = getSafeText(driver, rangeLbl);
	                first.click();
	                waitUntilTableRefresh(wait, rangeLbl, rangoAntes);
	            }
	        }

	        // Validar que haya filas
	        List<WebElement> listaFilas = driver.findElements(filas);
	        if (listaFilas == null || listaFilas.isEmpty()) {
	            System.out.println("No hay registros en el grid Centro de descargas.");
	            return false;
	        }

	        // Primera fila
	        int filaObjetivo = 1;

	        By filaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaObjetivo + "]");

	        By fechaFilaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaObjetivo + "]//td[contains(@class,'mat-column-fecha')]//span");
	        By moduloFilaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaObjetivo + "]//td[contains(@class,'mat-column-modulo')]//span");
	        By nombreDocFilaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaObjetivo + "]//td[contains(@class,'mat-column-nombreDocumento')]//span");

	        // Estatus: "En proceso"
	        By estatusEnProcesoFilaN = By.xpath(
	            "//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaObjetivo + "]" +
	            "//td[contains(@class,'mat-column-estatus')]//span[normalize-space()='En proceso' and contains(@class,'icon-pending')]"
	        );

	        u.scrollToElement(filaN);

	        String fecha = u.getText(fechaFilaN).trim();
	        String modulo = u.getText(moduloFilaN).trim();
	        String nombreDoc = u.getText(nombreDocFilaN).trim(); // NO se compara, sólo evidencia

	        // Validar fecha = hoy 
	        if (!fecha.equals(hoy)) {
	            System.out.println("La fecha de la primera fila no es hoy. Esperado: " + hoy + " Obtenido: " + fecha);
	            return false;
	        }

	        // Validar modulo esperado 
	        if (moduloEsperado != null && !moduloEsperado.trim().isEmpty()) {
	            if (!modulo.equalsIgnoreCase(moduloEsperado.trim())) {
	                System.out.println("El modulo origen no coincide. Esperado: " + moduloEsperado + " Obtenido: " + modulo);
	                return false;
	            }
	        }

	        // Validar estatus "En proceso"
	        if (!u.isDisplayed(estatusEnProcesoFilaN)) {
	            
	            By estatusSoloTexto = By.xpath(
	                "//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaObjetivo + "]" +
	                "//td[contains(@class,'mat-column-estatus')]//span[normalize-space()='En proceso']"
	            );

	            if (!u.isDisplayed(estatusSoloTexto)) {
	                System.out.println("La primera fila no está en estatus 'En proceso'.");
	                return false;
	            }
	        }

	        // Evidencia con highlight de texto (fecha/modulo/nombre) 
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep(
	                "Se valida que la primera fila del grid está 'En proceso'. " +
	                "Fila: " + filaObjetivo +
	                " Fecha: " + fecha +
	                " Modulo: " + modulo +
	                " Documento: " + nombreDoc
	            );

	            u.highLight(fechaFilaN);
	            u.highLight(moduloFilaN);
	            u.highLight(nombreDocFilaN);

	            testCase.addScreenShotCurrentStep(u, "Centro de descargas - primera fila En proceso");

	            u.unhighLight(fechaFilaN);
	            u.unhighLight(moduloFilaN);
	            u.unhighLight(nombreDocFilaN);
	        }

	        return true;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}

	/**
	 * Elimina una descarga con estatus Fallido y valida que ya no exista en el grid.
	 *
	 * @author Jose Pecina
	 * @date Diciembre 2025
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si se elimina correctamente una descarga fallida, false en caso contrario
	 * @throws Exception si ocurre un error durante la ejecucion
	 */
 	public boolean eliminarUnaDescargaEnFallido(boolean screenshot) throws Exception {
 	    try {

 	        if (!MensajeEspereDesaparece(false)) {
 	            testCase.addTextEvidenceCurrentStep("Falló al desaparecer el mensaje espere un momento");
 	            return false;
 	        }

 	        By tabla = By.xpath("//table[contains(@class,'mat-mdc-table')]");
 	        By filas = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr");

 	        By btnFirst = By.xpath("//mat-paginator//button[contains(@class,'mat-mdc-paginator-navigation-first')]");
 	        By btnNext  = By.xpath("//mat-paginator//button[contains(@class,'mat-mdc-paginator-navigation-next')]");
 	        By rangeLbl = By.xpath("//mat-paginator//div[contains(@class,'mat-mdc-paginator-range-label')]");

 	        u.waitWebElement(tabla, 30, 5);

 	        WebDriver driver = u.getDriver();
 	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

 	        // Ir a primera pagina (si esta habilitado)
 	        if (driver.findElements(btnFirst).size() > 0) {
 	            WebElement first = driver.findElement(btnFirst);
 	            if (first.isEnabled()) {
 	                String rangoAntes = getSafeText(driver, rangeLbl);
 	                first.click();
 	                waitUntilTableRefresh(wait, rangeLbl, rangoAntes);
 	            }
 	        }

 	        int filaEncontrada = -1;

 	        // info para evidencia
 	        String fecha = null;
 	        String hora = null;
 	        String modulo = null;
 	        String nombreDoc = null;

 	        while (true) {

 	            List<WebElement> listaFilas = driver.findElements(filas);

 	            if (listaFilas != null && !listaFilas.isEmpty()) {
 	                for (int i = 1; i <= listaFilas.size(); i++) {

 	                // Estatus "Fallido" (span con clase icon-error)
 	                	By estatusFallidoFila = By.xpath(
 	                	    "//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]" +
 	                	    "//td[contains(@class,'mat-column-estatus')]//span[contains(@class,'icon-error') and contains(normalize-space(),'Fallido')]"
 	                	);


 	                    if (driver.findElements(estatusFallidoFila).size() > 0 && u.isDisplayed(estatusFallidoFila)) {

 	                        filaEncontrada = i;

 	                        // Datos para evidencia
 	                        By fechaFila = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-fecha')]//span");
 	                        By horaFila  = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-hora')]//span");
 	                        By moduloFila = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-modulo')]//span");
 	                        By nombreDocFila = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-nombreDocumento')]//span");

 	                        fecha = safeGetText(fechaFila);
 	                        hora = safeGetText(horaFila);
 	                        modulo = safeGetText(moduloFila);
 	                        nombreDoc = safeGetText(nombreDocFila);

 	                        break;
 	                    }
 	                }
 	            }

 	            if (filaEncontrada != -1) {
 	                break; // encontrado
 	            }

 	            // avanzar pagina si se puede
 	            if (driver.findElements(btnNext).isEmpty()) {
 	                break;
 	            }

 	            WebElement next = driver.findElement(btnNext);
 	            if (!next.isEnabled()) {
 	                break; // ya no hay mas paginas
 	            }

 	            String rangoAntes = getSafeText(driver, rangeLbl);
 	            next.click();
 	            waitUntilTableRefresh(wait, rangeLbl, rangoAntes);
 	        }

 	        if (filaEncontrada == -1) {
 	            testCase.addTextEvidenceCurrentStep("No se encontró ningún registro con estatus 'En proceso' en el grid");
 	            return false;
 	        }

 	        // Locators de la fila encontrada
 	        By filaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaEncontrada + "]");

 	        By estatusFallidoFilaN = By.xpath(
 	    		    "//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaEncontrada + "]" +
 	    		    "//td[contains(@class,'mat-column-estatus')]//span[contains(@class,'icon-error') and contains(normalize-space(),'Fallido')]"
 	    		);



 	        // Botón eliminar (mat-icon con texto delete) en la columna eliminar
 	        By btnEliminarFilaN = By.xpath(
 	            "//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaEncontrada + "]" +
 	            "//td[contains(@class,'mat-column-eliminar')]//mat-icon[normalize-space()='delete']"
 	        );

 	        String nombreDocEncontrado = (nombreDoc == null ? "" : nombreDoc.trim());

 	        // Scroll a la fila
 	        u.scrollToElement(filaN);

 	        // Evidencia ANTES
 	        if (screenshot) {
 	            testCase.addTextEvidenceCurrentStep(
 	                "Se encontró un registro 'En proceso' para eliminar. " +
 	                "FilaEnPagina: " + filaEncontrada +
 	                " Fecha: " + (fecha == null ? "" : fecha) +
 	                " Hora: " + (hora == null ? "" : hora) +
 	                " Modulo: " + (modulo == null ? "" : modulo) +
 	                " Documento: " + nombreDocEncontrado
 	            );

 	            u.highLight(estatusFallidoFilaN);
 	            u.highLight(btnEliminarFilaN);
 	            testCase.addScreenShotCurrentStep(u, "Centro de descargas - ANTES de eliminar (Fallido)");
 	            u.unhighLight(estatusFallidoFilaN);
 	            u.unhighLight(btnEliminarFilaN);
 	        }

 	        // Click eliminar
 	        u.waitWebElement(btnEliminarFilaN, 15, 2);
 	        WebElement deleteIcon = driver.findElement(btnEliminarFilaN);
 	        try {
 	            deleteIcon.click();
 	        } catch (Exception ex) {
 	            ((JavascriptExecutor) driver).executeScript("arguments[0].click();", deleteIcon);
 	        }

 	        // Modal mensaje éxito 
 	        By modalEliminar = By.xpath("//app-info-download-dialog[contains(@class,'mat-mdc-dialog-component-host')]");
 	        By lblMensajeEliminar = By.xpath("//app-info-download-dialog//p[normalize-space()='El documento se ha eliminado con exito']");
 	        By btnCerrarModalX = By.xpath("//app-info-download-dialog//button[contains(@class,'close-btn') and @aria-label='Cerrar']");

 	        // Esperar a que aparezca el modal y el mensaje
 	        u.waitWebElement(modalEliminar, 20, 2);
 	        u.waitWebElement(lblMensajeEliminar, 20, 2);
 	        u.waitWebElement(btnCerrarModalX, 20, 2);

 	        // Evidencia del mensaje antes de cerrar
 	        if (screenshot) {
 	            testCase.addTextEvidenceCurrentStep("Se mostró mensaje de eliminación exitosa: 'El documento se ha eliminado con exito'");
 	            u.highLight(lblMensajeEliminar);
 	            u.highLight(btnCerrarModalX);
 	            testCase.addScreenShotCurrentStep(u, "Centro de descargas - Mensaje de eliminación (antes de cerrar)");
 	            u.unhighLight(lblMensajeEliminar);
 	            u.unhighLight(btnCerrarModalX);
 	        }

 	        // Cerrar modal con X
 	        try {
 	            driver.findElement(btnCerrarModalX).click();
 	        } catch (Exception ex) {
 	            ((JavascriptExecutor) driver).executeScript("arguments[0].click();", driver.findElement(btnCerrarModalX));
 	        }

 	        // Esperar a que desaparezca el modal
 	        wait.until(ExpectedConditions.invisibilityOfElementLocated(modalEliminar));

 	        // Esperar refresh del grid
 	        String rangoAntesEliminar = getSafeText(driver, rangeLbl);
 	        u.hardWait(3);
 	        waitUntilTableRefresh(wait, rangeLbl, rangoAntesEliminar);

 	        // Confirmar que ya no existe ese registro (mismo documento) con "En proceso"
 	        boolean sigueExistiendo = existeRegistroEnProcesoPorNombre(nombreDocEncontrado, driver);

 	        // Evidencia DESPUÉS
 	        if (screenshot) {
 	            testCase.addTextEvidenceCurrentStep(
 	                "" + (sigueExistiendo ? "AÚN existe (FALLA)" : "Se elimina correctamente del grid")
 	            );
 	            testCase.addScreenShotCurrentStep(u, "Centro de descargas - DESPUÉS de eliminar (registro no debe existir)");
 	        }

 	        return !sigueExistiendo;

 	    } catch (Exception e) {
 	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
 	        throw new Exception("Error " + e.getMessage());
 	    }
 	}
 	
