 	/**
 	 * Busca en el grid si existe un registro Fallido con el mismo nombre de documento.
 	 *
 	 * @author Jose Pecina
 	 * @date Diciembre 2025
 	 * @param nombreDocumento nombre del documento a buscar
 	 * @param driver instancia de WebDriver en uso
 	 * @return true si existe el registro fallido, false en caso contrario
 	 * @throws Exception si ocurre un error durante la ejecucion
 	 */
 	private boolean existeRegistroFallidoPorNombre(String nombreDocumento, WebDriver driver) throws Exception {

 	    if (nombreDocumento == null || nombreDocumento.trim().isEmpty()) {
 	        return true; // no se puede confirmar borrado
 	    }

 	    By filas = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr");

 	    By btnFirst = By.xpath("//mat-paginator//button[contains(@class,'mat-mdc-paginator-navigation-first')]");
 	    By btnNext  = By.xpath("//mat-paginator//button[contains(@class,'mat-mdc-paginator-navigation-next')]");
 	    By rangeLbl = By.xpath("//mat-paginator//div[contains(@class,'mat-mdc-paginator-range-label')]");

 	    WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

 	    // ir a primera pagina
 	    if (driver.findElements(btnFirst).size() > 0) {
 	        WebElement first = driver.findElement(btnFirst);
 	        if (first.isEnabled()) {
 	            String rangoAntes = getSafeText(driver, rangeLbl);
 	            first.click();
 	            waitUntilTableRefresh(wait, rangeLbl, rangoAntes);
 	        }
 	    }

 	    while (true) {

 	        List<WebElement> listaFilas = driver.findElements(filas);

 	        if (listaFilas != null && !listaFilas.isEmpty()) {
 	            for (int i = 1; i <= listaFilas.size(); i++) {

 	                By nombreDocFila = By.xpath(
 	                    "//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]" +
 	                    "//td[contains(@class,'mat-column-nombreDocumento')]//span"
 	                );

 	                String docTmp = safeGetText(nombreDocFila);

 	                if (docTmp != null && docTmp.trim().equals(nombreDocumento.trim())) {

 	                    // Estatus "Fallido" (span con clase icon-error)
 	                    By estatusFallidoFila = By.xpath(
 	                        "//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]" +
 	                        "//td[contains(@class,'mat-column-estatus')]//span[contains(@class,'icon-error') and contains(normalize-space(),'Fallido')]"
 	                    );

 	                    if (driver.findElements(estatusFallidoFila).size() > 0 && u.isDisplayed(estatusFallidoFila)) {
 	                        return true;
 	                    }
 	                }
 	            }
 	        }

 	        // siguiente pagina
 	        if (driver.findElements(btnNext).isEmpty()) {
 	            break;
 	        }

 	        WebElement next = driver.findElement(btnNext);
 	        if (!next.isEnabled()) {
 	            break;
 	        }

 	        String rangoAntes = getSafeText(driver, rangeLbl);
 	        next.click();
 	        waitUntilTableRefresh(wait, rangeLbl, rangoAntes);
 	    }

 	    return false;
 	}

 	/**
 	 * Busca en el grid si existe un registro En proceso con el mismo nombre de documento.
 	 *
 	 * @author Jose Pecina
 	 * @date Diciembre 2025
 	 * @param nombreDocumento nombre del documento a buscar
 	 * @param driver instancia de WebDriver en uso
 	 * @return true si existe el registro en proceso, false en caso contrario
 	 * @throws Exception si ocurre un error durante la ejecucion
 	 */
 	private boolean existeRegistroEnProcesoPorNombre(String nombreDocumento, WebDriver driver) throws Exception {

 	    if (nombreDocumento == null || nombreDocumento.trim().isEmpty()) {
 	        return true; // no se puede confirmar borrado
 	    }

 	    By filas = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr");

 	    By btnFirst = By.xpath("//mat-paginator//button[contains(@class,'mat-mdc-paginator-navigation-first')]");
 	    By btnNext  = By.xpath("//mat-paginator//button[contains(@class,'mat-mdc-paginator-navigation-next')]");
 	    By rangeLbl = By.xpath("//mat-paginator//div[contains(@class,'mat-mdc-paginator-range-label')]");

 	    WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

 	    // ir a primera pagina
 	    if (driver.findElements(btnFirst).size() > 0) {
 	        WebElement first = driver.findElement(btnFirst);
 	        if (first.isEnabled()) {
 	            String rangoAntes = getSafeText(driver, rangeLbl);
 	            first.click();
 	            waitUntilTableRefresh(wait, rangeLbl, rangoAntes);
 	        }
 	    }

 	    while (true) {

 	        List<WebElement> listaFilas = driver.findElements(filas);

 	        if (listaFilas != null && !listaFilas.isEmpty()) {
 	            for (int i = 1; i <= listaFilas.size(); i++) {

 	                By nombreDocFila = By.xpath(
 	                    "//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]" +
 	                    "//td[contains(@class,'mat-column-nombreDocumento')]//span"
 	                );

 	                String docTmp = safeGetText(nombreDocFila);

 	                if (docTmp != null && docTmp.trim().equals(nombreDocumento.trim())) {

 	                    By estatusEnProcesoFila = By.xpath(
 	                        "//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]" +
 	                        "//td[contains(@class,'mat-column-estatus')]//span[contains(@class,'icon-pending') and normalize-space()='En proceso']"
 	                    );

 	                    if (driver.findElements(estatusEnProcesoFila).size() > 0 && u.isDisplayed(estatusEnProcesoFila)) {
 	                        return true;
 	                    }
 	                }
 	            }
 	        }

 	        // siguiente pagina
 	        if (driver.findElements(btnNext).isEmpty()) {
 	            break;
 	        }

 	        WebElement next = driver.findElement(btnNext);
 	        if (!next.isEnabled()) {
 	            break;
 	        }

 	        String rangoAntes = getSafeText(driver, rangeLbl);
 	        next.click();
 	        waitUntilTableRefresh(wait, rangeLbl, rangoAntes);
 	    }

 	    return false;
 	}
 	
 	/**
 	 * Obtiene el texto de un elemento de forma segura evitando excepciones.
 	 *
 	 * @author Jose Pecina
 	 * @date Diciembre 2025
 	 * @param locator locator del elemento a consultar
 	 * @return texto del elemento o null si no se puede obtener
 	 */
 	private String safeGetText(By locator) {
 	    try {
 	        String t = u.getText(locator);
 	        return t == null ? null : t.trim();
 	    } catch (Exception e) {
 	        return null;
 	    }
 	}


	/**
	  * Actualiza el estatus del último registro de Centro de Descargas
	  * asociado a un usuario específico.
	  * Si el estatus es ERROR, inserta el mensaje de error correspondiente.
	  *
	  * @param usuario Login del usuario (ej. 5555555)
	  * @param estatus ERROR | SUCCESS | PENDING
	  * @author Alejandro Valdez
	  * @date Diciembre 2025
	  * @return True si se realiza el cambiop de estatus correctamente
	  * @throws Exception
	  */
	 public boolean actualizarEstatusCentroDescargasPorUsuario(String usuario, String estatus) throws Exception {
		 
	     String dbUrl = GlobalVariables.DB_URL_Cometa;
	     String dbUser = GlobalVariables.DB_USER_Cometa;
	     String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	     String sqlUsuarioId =
	         "SELECT DISTINCT k.usuario_id " +
	         "FROM xxcm_user_keys k " +
	         "JOIN xxcm_usuarios u ON k.usuario_id = u.usuario_id " +
	         "WHERE u.usuario = ?";

	     String sqlSelectCentroDescargas =
	         "SELECT id FROM xxcm_centro_descargas " +
	         "WHERE usuario_id = ? " +
	         "ORDER BY fecha DESC LIMIT 1";

	     String sqlUpdate =
	         "UPDATE xxcm_centro_descargas SET estatus = ? WHERE id = ?";

	     String sqlInsertError =
	         "INSERT INTO xxcm_centro_descargas_error " +
	         "(id, centro_descargas_id, message, \"exception\") " +
	         "VALUES (?, ?, ?, ?)";

	     Connection connection = null;

	     try {
	         connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	         connection.setAutoCommit(false);

	         Integer usuarioId;
	         UUID centroDescargasId;

	         //Obtener usuario_id
	         try (PreparedStatement ps = connection.prepareStatement(sqlUsuarioId)) {
	             ps.setString(1, usuario);

	             try (ResultSet rs = ps.executeQuery()) {
	                 if (!rs.next()) {
	                     System.out.println("ERROR: No se encontró usuario_id para usuario " + usuario);
	                     connection.rollback();
	                     return false;
	                 }
	                 usuarioId = rs.getInt(1);
	             }
	         }

	         //Obtener último registro de centro de descargas
	         try (PreparedStatement ps = connection.prepareStatement(sqlSelectCentroDescargas)) {
	             ps.setInt(1, usuarioId);

	             try (ResultSet rs = ps.executeQuery()) {
	                 if (!rs.next()) {
	                     System.out.println("ERROR: No hay registros de Centro de Descargas para el usuario");
	                     connection.rollback();
	                     return false;
	                 }
	                 centroDescargasId = UUID.fromString(rs.getString(1));
	             }
	         }

	         //Update estatus (SIEMPRE)
	         try (PreparedStatement ps = connection.prepareStatement(sqlUpdate)) {
	             ps.setString(1, estatus);
	             ps.setObject(2, centroDescargasId);
	             ps.executeUpdate();
	         }

	         //Insertar error SOLO si estatus = ERROR
	         if ("ERROR".equalsIgnoreCase(estatus)) {
	             try (PreparedStatement ps = connection.prepareStatement(sqlInsertError)) {
	                 ps.setObject(1, UUID.randomUUID());
	                 ps.setObject(2, centroDescargasId);
	                 ps.setString(3, "Este es un error de prueba");
	                 ps.setString(4, "IndexOutOfBoundException");
	                 ps.executeUpdate();
	             }
	         }

	         connection.commit();
	         u.hardWait(10);
	         System.out.println("Estatus [" + estatus + "] aplicado correctamente al usuario: " + usuario);
	         return true;

	     } catch (Exception e) {
	         if (connection != null) {
	             connection.rollback();
	         }
	         System.out.println("[ERROR] Error al actualizar estatus Centro Descargas: " + e.getMessage());
	         e.printStackTrace();
	         return false;

	     } finally {
	         if (connection != null) {
	             connection.close();
	         }
	     }
	 }
	 
