	/**
	 * Valida que el contador de la campanita de devoluciones cambie y registra la evidencia.
	 *
	 * @author Jose Pecina
	 * @date Diciembre 2025
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si el contador cambia correctamente, false en caso contrario
	 * @throws Exception si ocurre un error durante la ejecucion
	 */
	public boolean validarCampanitaDescargasFinalizadasDiferentedevo(boolean screenshot) throws Exception {
	    try {
	        boolean result = true;

	        // Espera a que overlay de "espere un momento" se quite de pantalla para continuar
	        if (!MensajeEspereDesaparece(false)) {
	            testCase.addTextEvidenceCurrentStep("Fallo al desaparecer el mensaje espere un momento");
	            return false;
	        }

	        By btnCampanita = By.cssSelector("button.bell-btn[aria-label='Notificaciones']");
	        By badgeCampanita = By.cssSelector("button.bell-btn[aria-label='Notificaciones'] span.badge");
	        By headerDescargasFinalizadas = By.cssSelector("div.dropdown .header");
	        By liDevoluciones = By.xpath("//div[contains(@class,'dropdown')]//li[contains(normalize-space(.),'Devoluciones')]");

	        u.waitWebElement(btnCampanita, 60, 5);
	        u.scrollToElement(btnCampanita);
	        u.getDriver().findElement(By.tagName("body")).click();
	        u.highLight(btnCampanita);
	        if (screenshot) {
	            testCase.addScreenShotCurrentStep("Campanita_Notificaciones");
	        }

	        boolean dropdownAbierto = false;

	        
	        for (int intento = 1; intento <= 3; intento++) {
	            try {
	                u.click(btnCampanita);
	                                
	                u.waitWebElement(headerDescargasFinalizadas, 5, 1);	                
	                dropdownAbierto = true;
	                break;

	            } catch (Exception ex) {
	                
	                if (screenshot) {
	                    testCase.addTextEvidenceCurrentStep("No se abrio dropdown de campanita. Reintento: " + intento);
	                    testCase.addScreenShotCurrentStep("Campanita_Reintento_" + intento);
	                }
	                u.hardWait(1);
	            }
	        }

	        u.unhighLight(btnCampanita);

	        if (!dropdownAbierto) {
	            testCase.addTextEvidenceCurrentStep("No se pudo abrir el dropdown de la campanita de notificaciones");
	            return false;
	        }

	        
	        u.scrollToElement(headerDescargasFinalizadas);

	        
	        u.hardWait(2);

	        int badgeActual = extraerEnteroSeguro(u.getDriver().findElement(badgeCampanita).getText());
	        int headerActual = extraerEnteroEntreParentesis(u.getDriver().findElement(headerDescargasFinalizadas).getText());
	        int devolucionesActual = extraerEnteroDespuesDeDosPuntos(u.getDriver().findElement(liDevoluciones).getText());

	        // Validaciones base
	        if (badgeActual < 0 || headerActual < 0 || devolucionesActual < 0) {
	            throw new Exception("Valores invalidos detectados. badge=" + badgeActual
	                    + ", header=" + headerActual
	                    + ", devoluciones=" + devolucionesActual);
	        }

	        int numDescargasPrevio = Numdescargas;

	        // Regla principal: debe ser diferente (menor o mayor)
	        if (badgeActual == numDescargasPrevio) {
	            throw new Exception("El numero de descargas no cambio. Valor previo="
	                    + numDescargasPrevio + ", valor actual=" + badgeActual);
	        }

	        // Evidencia y log
	        u.highLight(headerDescargasFinalizadas);
	        u.highLight(liDevoluciones);

	        if (badgeActual < numDescargasPrevio) {
	            if (screenshot) {
	                testCase.addBoldTextEvidenceCurrentStep("Descargas disminuyeron: " + numDescargasPrevio + " -> " + badgeActual);
	                testCase.addScreenShotCurrentStep("Dropdown_Descargas_Finalizadas");
	            }
	            System.out.println("Descargas disminuyeron: " + numDescargasPrevio + " -> " + badgeActual);

	        } else if (badgeActual > numDescargasPrevio) {
	            if (screenshot) {
	                testCase.addBoldTextEvidenceCurrentStep("Descargas aumentaron: " + numDescargasPrevio + " -> " + badgeActual);
	                testCase.addScreenShotCurrentStep("Dropdown_Descargas_Finalizadas");
	            }
	            System.out.println("Descargas aumentaron: " + numDescargasPrevio + " -> " + badgeActual);

	        } else {
	            result = false;
	            System.out.println("Descargas sin cambios: " + numDescargasPrevio + " -> " + badgeActual);
	        }

	        u.unhighLight(headerDescargasFinalizadas);
	        u.unhighLight(liDevoluciones);

	        // Actualizar el valor global al nuevo
	        Numdescargas = badgeActual;

	        return result;

	    } catch (Exception e) {
	        throw e;
	    }
	}
	
