	/**
	 * Extrae el primer valor entero de un texto de forma segura.
	 *
	 * @author Jose Pecina
	 * @date Diciembre 2025
	 * @param txt texto a procesar
	 * @return valor entero encontrado o -1 si no existe
	 */
	private int extraerEnteroSeguro(String txt) {
	    if (txt == null) return -1;
	    Matcher m = Pattern.compile("(\\d+)").matcher(txt);
	    return m.find() ? Integer.parseInt(m.group(1)) : -1;
	}
	/**
	 * Extrae un valor entero contenido entre parentesis.
	 *
	 * @author Jose Pecina
	 * @date Diciembre 2025
	 * @param txt texto a procesar
	 * @return valor entero encontrado o -1 si no existe
	 */
	private int extraerEnteroEntreParentesis(String txt) {
	    if (txt == null) return -1;
	    Matcher m = Pattern.compile("\\((\\d+)\\)").matcher(txt);
	    return m.find() ? Integer.parseInt(m.group(1)) : -1;
	}
	/**
	 * Extrae un valor entero despues de dos puntos en un texto.
	 *
	 * @author Jose Pecina
	 * @date Diciembre 2025
	 * @param txt texto a procesar
	 * @return valor entero encontrado o -1 si no existe
	 */
	private int extraerEnteroDespuesDeDosPuntos(String txt) {
	    if (txt == null) return -1;
	    Matcher m = Pattern.compile(":\\s*(\\d+)").matcher(txt);
	    return m.find() ? Integer.parseInt(m.group(1)) : -1;
	}
	
