 	/**
 	 * Valida que el ultimo archivo descargado exista y sea xlsx o zip y lo abre
 	 *
 	 * @param screenshot indica si se toma evidencia en el reporte
 	 * @return true si el archivo se encuentra, se abre y es valido
 	 * @throws Exception en caso de error durante la validacion o apertura
 	 *
 	 * @author Jose Pecina
 	 * @date Diciembre 2025
 	 */
	public boolean openLastDownloadedFileXlsxOrZip(boolean screenshot) throws Exception {
	    try {
	        String home = System.getProperty("user.home") + "\\Downloads";
	        File lastFile = getLastModified(home);

	        if (lastFile == null || !lastFile.exists()) {
	            System.out.println("No se encontró último archivo en: " + home);
	            return false;
	        }

	        if (!java.awt.Desktop.isDesktopSupported()) {
	            System.out.println("Desktop is not supported");
	            return false;
	        }

	        String fileName = lastFile.getName().toLowerCase();

	        // xlsx o zip
	        boolean esZip = fileName.endsWith(".zip");
	        boolean esXlsx = fileName.endsWith(".xlsx");

	        if (!esZip && !esXlsx) {
	            System.out.println("El último archivo no es .zip ni .xlsx: " + lastFile.getName());
	            return false;
	        }

	        java.awt.Desktop.getDesktop().open(lastFile);

	        if (esZip) {
	            u.hardWait(4);
	            if (screenshot) {
	                testCase.addTextEvidenceCurrentStep("Se abre archivo ZIP correctamente: " + lastFile.getName());
	                testCase.addScreenShotCurrentStep("Archivo");
	            }

	            // Cerrar ventana del ZIP
	            Robot robot = new Robot();
	            robot.keyPress(KeyEvent.VK_ALT);
	            robot.keyPress(KeyEvent.VK_F4);
	            robot.keyRelease(KeyEvent.VK_F4);
	            robot.keyRelease(KeyEvent.VK_ALT);

	            return true;
	        }

	        // XLSX
	        u.hardWait(10);
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Se abre archivo Excel correctamente: " + lastFile.getName());
	            testCase.addScreenShotCurrentStep("Archivo");
	        }

	        // Cerrar Excel
	        Runtime.getRuntime().exec("cmd /c taskkill /f /im excel.exe");
	        return true;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
	
	/**
	 * Da clic en descargar para el ultimo documento generado en Centro de descargas
	 * Omite registros con estatus Fallido o En proceso y selecciona el primer registro descargable que coincida
	 *
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si encuentra el registro esperado y da clic en descargar
	 * @throws Exception en caso de error durante la busqueda o el clic
	 *
	 * @author Jose Pecina
	 * @date Diciembre 2025
	 */
	public boolean clickDescargarUltimoDocumentoGenerado(boolean screenshot) throws Exception {
	    try {
	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(15));
	        JavascriptExecutor js = (JavascriptExecutor) driver;

	        String docEsperado = normalizarNombreDescarga(getLastDownloadedFileName());
	        String hoy = LocalDate.now().format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));

	        By tabla = By.xpath("//table[contains(@class,'mat-mdc-table')]");
	        By filas = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr");

	        By lblRango = By.xpath("//mat-paginator[contains(@class,'mat-mdc-paginator')]//div[contains(@class,'mat-mdc-paginator-range-label')]");
	        By btnFirst = By.xpath("//mat-paginator[contains(@class,'mat-mdc-paginator')]//button[contains(@class,'mat-mdc-paginator-navigation-first')]");
	        By btnNext = By.xpath("//mat-paginator[contains(@class,'mat-mdc-paginator')]//button[contains(@class,'mat-mdc-paginator-navigation-next')]");

	        wait.until(ExpectedConditions.visibilityOfElementLocated(tabla));

	        if (docEsperado == null || docEsperado.trim().isEmpty()) {
	            throw new Exception("El nombreDocumentoEsperado viene vacio o nulo.");
	        }

	        if (!driver.findElements(btnFirst).isEmpty()) {
	            WebElement first = driver.findElement(btnFirst);
	            String ariaDisabledFirst = first.getAttribute("aria-disabled");

	            if (first.isEnabled() && !"true".equalsIgnoreCase(ariaDisabledFirst)) {
	                String rangoAntes = getSafeText(driver, lblRango);
	                js.executeScript("arguments[0].scrollIntoView({block:'center'});", first);
	                u.hardWait(1);

	                try {
	                    first.click();
	                } catch (Exception ex) {
	                    js.executeScript("arguments[0].click();", first);
	                }

	                waitUntilTableRefresh(wait, lblRango, rangoAntes);
	            }
	        }

	        int paginasRecorridas = 0;
	        int maxPaginas = 50;

	        while (paginasRecorridas < maxPaginas) {

	            wait.until(ExpectedConditions.visibilityOfElementLocated(tabla));
	            List<WebElement> trs = driver.findElements(filas);

	            for (int i = 1; i <= trs.size(); i++) {

	                By nombreDocFila = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-nombreDocumento')]//span");
	                By fechaFila = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-fecha')]//span");
	                By moduloFila = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-modulo')]//span");

	                By textoEnProceso = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-estatus')]//span[contains(@class,'icon-pending') and contains(normalize-space(),'En proceso')]");
	                By textoFallido = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-estatus')]//span[contains(@class,'icon-error') and contains(normalize-space(),'Fallido')]");

	                By celdaDescarga = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-descarga')]");
	                By iconoDescarga = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-descarga')]//mat-icon[normalize-space()='cloud_download']");

	                if (driver.findElements(nombreDocFila).isEmpty()) {
	                    continue;
	                }

	                WebElement nombreElemento = driver.findElement(nombreDocFila);
	                js.executeScript("arguments[0].scrollIntoView({block:'center'});", nombreElemento);
	                u.hardWait(1);

	                String docTmp = "";
	                try {
	                    docTmp = normalizarNombreDescarga(u.getText(nombreDocFila).trim());
	                } catch (Exception ex) {
	                    continue;
	                }

	                if (!docTmp.equals(docEsperado)) {
	                    continue;
	                }

	                String fechaTmp = driver.findElements(fechaFila).isEmpty() ? "" : u.getText(fechaFila).trim();
	                fechaTmp = fechaTmp.replaceAll("[^0-9/\\-]", "");

	                if (fechaTmp.isEmpty() || !fechaTmp.equals(hoy)) {
	                    continue;
	                }

	                if (moduloEsperado != null && !moduloEsperado.trim().isEmpty()) {
	                    String moduloTmp = driver.findElements(moduloFila).isEmpty() ? "" : u.getText(moduloFila).trim();
	                    if (moduloTmp.isEmpty() || !moduloTmp.equalsIgnoreCase(moduloEsperado.trim())) {
	                        continue;
	                    }
	                }

	                boolean esFallido = !driver.findElements(textoFallido).isEmpty();
	                boolean esEnProceso = !driver.findElements(textoEnProceso).isEmpty();

	                if (esFallido || esEnProceso) {
	                    continue;
	                }

	                if (driver.findElements(celdaDescarga).isEmpty() || driver.findElements(iconoDescarga).isEmpty()) {
	                    continue;
	                }

	                if (screenshot) {
	                    testCase.addTextEvidenceCurrentStep(
	                        "Se da clic en descargar al documento esperado. " +
	                        "Fila: " + i +
	                        " Fecha: " + fechaTmp +
	                        " Documento: " + docTmp
	                    );

	                    u.highLight(nombreDocFila);
	                    if (!driver.findElements(fechaFila).isEmpty()) {
	                        u.highLight(fechaFila);
	                    }
	                    if (!driver.findElements(moduloFila).isEmpty()) {
	                        u.highLight(moduloFila);
	                    }

	                    testCase.addScreenShotCurrentStep(u, "Centro de descargas registro esperado a descargar");

	                    u.unhighLight(nombreDocFila);
	                    if (!driver.findElements(fechaFila).isEmpty()) {
	                        u.unhighLight(fechaFila);
	                    }
	                    if (!driver.findElements(moduloFila).isEmpty()) {
	                        u.unhighLight(moduloFila);
	                    }
	                }

	                WebElement descarga = driver.findElement(celdaDescarga);
	                js.executeScript("arguments[0].scrollIntoView({block:'center', inline:'center'});", descarga);
	                u.hardWait(1);

	                try {
	                    wait.until(ExpectedConditions.visibilityOf(descarga));
	                    descarga.click();
	                } catch (Exception ex1) {
	                    try {
	                        js.executeScript("arguments[0].click();", descarga);
	                    } catch (Exception ex2) {
	                        throw new Exception("No fue posible dar clic en la descarga del documento esperado. " + ex2.getMessage());
	                    }
	                }

	                return true;
	            }

	            if (driver.findElements(btnNext).isEmpty()) {
	                break;
	            }

	            WebElement next = driver.findElement(btnNext);
	            String ariaDisabledNext = next.getAttribute("aria-disabled");

	            if (!next.isEnabled() || "true".equalsIgnoreCase(ariaDisabledNext)) {
	                break;
	            }

	            String rangoAntes = getSafeText(driver, lblRango);
	            js.executeScript("arguments[0].scrollIntoView({block:'center'});", next);
	            u.hardWait(1);

	            try {
	                next.click();
	            } catch (Exception ex) {
	                js.executeScript("arguments[0].click();", next);
	            }

	            waitUntilTableRefresh(wait, lblRango, rangoAntes);
	            paginasRecorridas++;
	        }

	        System.out.println("No se encontro el registro esperado para descargar. Documento: " + docEsperado);
	        return false;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}


