	/**
	 * Valida que la ultima descarga se registre en el grid de Centro de descargas
	 *
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si encuentra el documento esperado con fecha de hoy y estatus exitoso
	 * @throws Exception en caso de error durante la busqueda o validacion del grid
	 *
	 * @author Jose Pecina
	 * @date Diciembre 2025
	 */
	public boolean validarUltimaDescargaRegistrada(boolean screenshot) throws Exception {
	    try {
	        String nombreDocumentoEsperado = normalizarNombreDescarga(getLastDownloadedFileName());
	        String hoy = LocalDate.now().format(DateTimeFormatter.ofPattern("dd/MM/yyyy"));

	        By tabla = By.xpath("//table[contains(@class,'mat-mdc-table')]");
	        By filas = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr");

	        By btnFirst = By.xpath("//mat-paginator//button[contains(@class,'mat-mdc-paginator-navigation-first')]");
	        By btnNext  = By.xpath("//mat-paginator//button[contains(@class,'mat-mdc-paginator-navigation-next')]");
	        By rangeLbl = By.xpath("//mat-paginator//div[contains(@class,'mat-mdc-paginator-range-label')]");

	        u.waitWebElement(tabla, 30, 5);

	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	        // Ir a primera pagina (si esta habilitado)
	        if (driver.findElements(btnFirst).size() > 0) {
	            WebElement first = driver.findElement(btnFirst);
	            if (first.isEnabled()) {
	                first.click();
	                waitUntilTableRefresh(wait, rangeLbl, null);
	            }
	        }

	        int filaEncontrada = -1;
	        String fecha = null;
	        String modulo = null;
	        String nombreDoc = null;

	        while (true) {

	            // Buscar en la pagina actual
	            List<WebElement> listaFilas = driver.findElements(filas);
	            if (listaFilas != null && !listaFilas.isEmpty()) {
	                for (int i = 1; i <= listaFilas.size(); i++) {

	                    By nombreDocFila = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-nombreDocumento')]//span");
	                    String docTmp = u.getText(nombreDocFila).trim();

	                    if (nombreDocumentoEsperado != null && !nombreDocumentoEsperado.trim().isEmpty()
	                            && docTmp.equals(nombreDocumentoEsperado)) {

	                        filaEncontrada = i;

	                        By fechaFila = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-fecha')]//span");
	                        By moduloFila = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + i + "]//td[contains(@class,'mat-column-modulo')]//span");

	                        fecha = u.getText(fechaFila).trim();
	                        modulo = u.getText(moduloFila).trim();
	                        nombreDoc = docTmp;

	                        break;
	                    }
	                }
	            }

	            if (filaEncontrada != -1) {
	                break; // encontrado
	            }

	            // Si no encontro, avanzar pagina si se puede
	            if (driver.findElements(btnNext).isEmpty()) {
	                break;
	            }

	            WebElement next = driver.findElement(btnNext);
	            if (!next.isEnabled()) {
	                break; // ya no hay mas paginas
	            }

	            String rangoAntes = getSafeText(driver, rangeLbl);
	            next.click();
	            waitUntilTableRefresh(wait, rangeLbl, rangoAntes);
	        }

	        if (filaEncontrada == -1) {
	            System.out.println("No se encontro en el grid el documento esperado: " + nombreDocumentoEsperado);
	            return false;
	        }

	        // Locators
	        By filaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaEncontrada + "]");
	        By fechaFilaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaEncontrada + "]//td[contains(@class,'mat-column-fecha')]//span");
	        By moduloFilaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaEncontrada + "]//td[contains(@class,'mat-column-modulo')]//span");
	        By nombreDocFilaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaEncontrada + "]//td[contains(@class,'mat-column-nombreDocumento')]//span");

	        By estatusOkFilaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaEncontrada + "]//td[contains(@class,'mat-column-estatus')]//mat-icon[normalize-space()='check_circle']");
	        By iconoDescargaFilaN = By.xpath("//table[contains(@class,'mat-mdc-table')]//tbody//tr[" + filaEncontrada + "]//td[contains(@class,'mat-column-descarga')]//mat-icon[normalize-space()='cloud_download']");

	        u.scrollToElement(filaN);

	        // Validaciones
	        if (fecha == null) fecha = u.getText(fechaFilaN).trim();
	        if (modulo == null) modulo = u.getText(moduloFilaN).trim();
	        if (nombreDoc == null) nombreDoc = u.getText(nombreDocFilaN).trim();

	        if (!fecha.equals(hoy)) {
	            System.out.println("La fecha del registro encontrado no es hoy. Esperado: " + hoy + " Obtenido: " + fecha);
	            return false;
	        }

	        if (moduloEsperado != null && !moduloEsperado.trim().isEmpty()) {
	            if (!modulo.equalsIgnoreCase(moduloEsperado.trim())) {
	                System.out.println("El modulo origen no coincide. Esperado: " + moduloEsperado + " Obtenido: " + modulo);
	                return false;
	            }
	        }

	        if (nombreDocumentoEsperado != null && !nombreDocumentoEsperado.trim().isEmpty()) {
	            if (!nombreDoc.equals(nombreDocumentoEsperado)) {
	                System.out.println("El nombre de documento no coincide. Esperado: " + nombreDocumentoEsperado + " Obtenido: " + nombreDoc);
	                return false;
	            }
	        }

	        if (!u.isDisplayed(estatusOkFilaN)) {
	            System.out.println("No se detecto estatus exitoso en el registro encontrado");
	            return false;
	        }

	        if (!u.isDisplayed(iconoDescargaFilaN)) {
	            System.out.println("No se detecto el icono de descarga en el registro encontrado");
	            return false;
	        }

	        // Evidencia con highlight de texto (fecha/modulo/nombre)
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep(
	                "Se valida descarga registrada en el grid. " +
	                "FilaEnPagina: " + filaEncontrada +
	                " Fecha: " + fecha +
	                " Modulo: " + modulo +
	                " Documento: " + nombreDoc
	            );

	            u.highLight(fechaFilaN);
	            u.highLight(moduloFilaN);
	            u.highLight(nombreDocFilaN);

	            testCase.addScreenShotCurrentStep(u, "Centro de descargas - registro validado");

	            u.unhighLight(fechaFilaN);
	            u.unhighLight(moduloFilaN);
	            u.unhighLight(nombreDocFilaN);
	        }

	        return true;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
	/**
	 * Espera a que la tabla se refresque validando el cambio del label de paginacion
	 *
	 * @param wait WebDriverWait utilizado para la espera
	 * @param rangeLbl locator del label de rango de paginacion
	 * @param oldRange valor previo del label para detectar el refresco
	 *
	 * @author Jose Pecina
	 * @date Diciembre 2025
	 */
	private void waitUntilTableRefresh(WebDriverWait wait, By rangeLbl, String oldRange) {
	    try {
	        if (oldRange == null) {
	            wait.until(ExpectedConditions.visibilityOfElementLocated(rangeLbl));
	        } else {
	            wait.until(driver -> {
	                try {
	                    String nuevo = driver.findElement(rangeLbl).getText();
	                    return nuevo != null && !nuevo.trim().isEmpty() && !nuevo.equals(oldRange);
	                } catch (Exception ex) {
	                    return false;
	                }
	            });
	        }
	    } catch (Exception ignored) {
	    }
	}
	/**
	 * Obtiene el texto de un elemento de forma segura
	 *
	 * @param driver instancia de WebDriver
	 * @param locator locator del elemento
	 * @return texto del elemento o cadena vacia si ocurre un error
	 *
	 * @author Jose Pecina
	 * @date Diciembre 2025
	 */
	private String getSafeText(WebDriver driver, By locator) {
	    try {
	        return driver.findElement(locator).getText();
	    } catch (Exception e) {
	        return "";
	    }
	}


