    /**
     * Selecciona y filtra el rango de fechas en Centro de descargas y ejecuta la consulta
     *
     * @param screenshot indica si se toma evidencia en el reporte
     * @return true si selecciona el rango de fechas y consulta correctamente
     * @throws Exception en caso de error durante la seleccion de fechas o la consulta
     *
     * @author Jose Pecina
     * @date Diciembre 2025
     */
	public boolean FiltroFechaCentroDescarga(boolean screenshot) throws Exception{
		try {
			u.hardWait(5);
			boolean result = true;
			By xmlRangoFechas = By.xpath(
				    "//mat-form-field[.//mat-label[normalize-space()='Rango de Fechas*']]"
				);
			
				u.scrollToElement(xmlRangoFechas);
				u.highLight(xmlRangoFechas);
				
	            String fechaOriginal = LocalDate.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	            LocalDate fechaConvert = LocalDate.parse(fechaOriginal, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	            //String fechaFormateada = fechaConvert.format(DateTimeFormatter.ofPattern("d/M/yyyy"));
	            // fechaOriginal puede venir como "yyyy-MM-dd HH:mm:ss" o "yyyy-MM-dd"
	           
	            try {
	            	fechaConvert = LocalDateTime.parse(fechaOriginal, DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")).toLocalDate();
	            } catch (Exception ex) {
	            	fechaConvert = LocalDate.parse(fechaOriginal, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	            }

	            WebDriver driver = u.getDriver();
	            WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	            // 2) Abrir el datepicker (usa tu locator real del botón toggle)
	            By btnToggle = By.xpath("//mat-datepicker-toggle/button");
	            wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

	            // 3) Esperar el calendario
	            By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
	            wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

	            // 4) Ir a vista de AÑOS (dar 1 o 2 clics según estado hasta ver mat-multi-year-view)
	            By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	            // Si aún no está la vista de años, clic otra vez
	            if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
	                wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	            }

	            // 5) En vista de años, paginar hasta que aparezca el año
	            clickYear(driver, wait, fechaConvert.getYear());

	            // 6) Seleccionar MES (por índice, 1..12)
	            clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

	            // 7) Seleccionar DÍA (dos veces para rango inicio/fin igual)
	            clickDay(driver, wait, fechaConvert.getDayOfMonth()); // inicio (1 día antes)
	            clickDay(driver, wait, fechaConvert.getDayOfMonth()); // fin

	            // 8) Esperar que se cierre el overlay
	            wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));
	            if (screenshot) {
		        	testCase.addBoldTextEvidenceCurrentStep("Se captura rango de fechas");	
					testCase.addScreenShotCurrentStep(u, "Busqueda completada");
		        	 }
	            consultarCentroDescargas(true);
		
			return result;
		
		}catch (Exception e) {			
			testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
			throw new Exception ("Error " + e.getMessage());			
	}
	}
