	/**
	 * Convierte una fecha del portal en formato corto en espanol a LocalDate
	 *
	 * @param texto fecha en formato dia mes anio con mes abreviado
	 * @return LocalDate correspondiente a la fecha proporcionada
	 * @throws IllegalArgumentException si el formato o el mes no son validos
	 *
	 * @author Jose Pecina
	 * @date Noviembre 2025
	 */
	private LocalDate parseFechaPortalES(String texto) {
	    if (texto == null) throw new IllegalArgumentException("Fecha nula");

	    String t = texto.trim().toLowerCase(new Locale("es", "ES")).replace(".", "");
	    String[] p = t.split("\\s+");
	    if (p.length != 3) throw new IllegalArgumentException("Formato de fecha inválido: " + texto);

	    int dia = Integer.parseInt(p[0]);
	    String mesTxt = p[1];
	    int anio = Integer.parseInt(p[2]);

	    int mes;
	    switch (mesTxt) {
	        case "ene": mes = 1; break;
	        case "feb": mes = 2; break;
	        case "mar": mes = 3; break;
	        case "abr": mes = 4; break;
	        case "may": mes = 5; break;
	        case "jun": mes = 6; break;
	        case "jul": mes = 7; break;
	        case "ago": mes = 8; break;
	        case "sep": mes = 9; break;
	        case "oct": mes = 10; break;
	        case "nov": mes = 11; break;
	        case "dic": mes = 12; break;
	        default: throw new IllegalArgumentException("Mes no reconocido: " + mesTxt + " (texto: " + texto + ")");
	    }

	    return LocalDate.of(anio, mes, dia);
	}
	/**
	 * Convierte una hora en formato 12h a formato 24h
	 *
	 * @param hora12 hora en formato 12h con AM o PM
	 * @return LocalTime en formato 24h
	 *
	 * @author Jose Pecina
	 * @date Noviembre 2025
	 */
	private LocalTime convertirHora12a24(String hora12) {
	    DateTimeFormatter formato12 = DateTimeFormatter.ofPattern("hh:mm a", Locale.ENGLISH);
	    return LocalTime.parse(hora12.toUpperCase(), formato12);
	}

	/**
	 * Selecciona los filtros de hora inicial y final en la pantalla de Liquidacion de Ruta
	 *
	 * @param screenshot indica si se toma evidencia en el reporte
	 * @return true si se seleccionan correctamente las horas en los dropdowns
	 *
	 * @author Jose Pecina
	 * @date Noviembre 2025
	 */
	public boolean llenadoFiltrosLRScreenHoraEsp(boolean screenshot) {
	    try {
	        if (!u.isDisplayed(btnHoraInicial)) return false;

	        WebDriver driver = u.getDriver();
	        JavascriptExecutor js = (JavascriptExecutor) driver;
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(20));

	        if (horaFormateada == null || horaFormateada.trim().isEmpty()) {
	            System.out.println("[ERROR] horaFormateada viene null/vacía. Ejecuta obtenerFechaRegistroRutaPropuesta() antes.");
	            testCase.addTextEvidenceCurrentStep("[ERROR] horaFormateada viene null/vacía. Ejecuta obtenerFechaRegistroRutaPropuesta() antes.");
	            return false;
	        }

	        DateTimeFormatter fmt24 = DateTimeFormatter.ofPattern("HH:mm");
	        LocalTime horaBase = LocalTime.parse(horaFormateada.trim(), fmt24);

	        String horaInicialAMPM = toAMPM(horaBase);

	        // Si quieres que el rango sea "una hora", deja +1
	        // Si quieres que sea "hasta fin del día" o algo así, cámbialo.
	        LocalTime horaFin = horaBase.plusHours(1);
	        String horaFinalAMPM = toAMPM(horaFin);

	        System.out.println("Hora BD (24h): " + horaFormateada);
	        System.out.println("Hora Inicial (dropdown): " + horaInicialAMPM);
	        System.out.println("Hora Final   (dropdown): " + horaFinalAMPM);

	        seleccionarHoraEnDropdown(driver, wait, js, btnHoraInicial, horaInicialAMPM,
	                "Hora Inicial", "HoraInicialCampo", "HoraInicialSeleccionada", screenshot);

	        seleccionarHoraEnDropdown(driver, wait, js, btnHoraFinal, horaFinalAMPM,
	                "Hora Final", "HoraFinalCampo", "HoraFinalSeleccionada", screenshot);

	        return true;

	    } catch (Exception e) {
	        System.out.println("[ERROR] Ocurrió un error durante la ejecución: " + e.getMessage());
	        testCase.addCodeEvidenceCurrentStep("[ERROR] Ocurrió un error durante la ejecución: " + e.getMessage());
	        e.printStackTrace();
	        return false;
	    }
	}

	/**
	 * Obtiene el texto visible seleccionado desde un mat form field de forma segura
	 *
	 * @param driver instancia de WebDriver
	 * @param anyChildInsideField locator de un elemento interno del campo
	 * @return texto seleccionado o cadena vacia si no se encuentra
	 *
	 * @author Jose Pecina
	 * @date Noviembre 2025
	 */
	private String getTriggerTextFromButton(WebDriver driver, By anyChildInsideField) {
	    // Sube al mat-form-field y lee el texto del trigger seleccionado
	    WebElement field = driver.findElement(anyChildInsideField).findElement(By.xpath("ancestor::mat-form-field[1]"));

	    // En Angular Material, el valor visible suele estar en mat-select-trigger
	    List<WebElement> triggers = field.findElements(By.cssSelector(".mat-mdc-select-trigger"));
	    if (!triggers.isEmpty()) {
	        String t = triggers.get(0).getText();
	        return t == null ? "" : t.trim();
	    }

	    // Fallbacks (por si cambia el markup)
	    List<WebElement> valueTexts = field.findElements(By.cssSelector(".mat-mdc-select-min-line"));
	    if (!valueTexts.isEmpty()) {
	        String t = valueTexts.get(0).getText();
	        return t == null ? "" : t.trim();
	    }

	    String t = field.getText();
	    return t == null ? "" : t.trim();
	}
