	/**
	 * Calcula un rango de horas en formato AM PM a partir de una hora en formato 24h
	 *
	 * @param hora24 hora base en formato 24h HH:mm
	 * @return arreglo con hora inicial y final en formato 12h AM PM
	 *
	 * @author Jose Pecina
	 * @date Noviembre 2025
	 */
	private String[] calcularRangoHorasAMPM(String hora24) {
	    DateTimeFormatter f24 = DateTimeFormatter.ofPattern("HH:mm");
	    DateTimeFormatter f12 = DateTimeFormatter.ofPattern("hh:mm a", Locale.US);

	    LocalTime base = LocalTime.parse(hora24, f24);

	    LocalTime inicio = base.withMinute(0).withSecond(0).withNano(0);

	    LocalTime fin;
	    if (inicio.getHour() == 23) {
	        fin = inicio; // tope del día
	    } else {
	        fin = inicio.plusHours(1);
	    }

	    return new String[] {
	        inicio.format(f12).toUpperCase(),
	        fin.format(f12).toUpperCase()
	    };
	}
