	/**
	 * Valida que la informacion de Liquidacion de Ruta CEDIS coincida con los registros obtenidos de BD
	 *
	 * @param usuario usuario para obtener perfil y RFC desde BD
	 * @return true si se obtienen transferencias de BD y se valida la informacion mostrada en el portal
	 *
	 * @author Jose Pecina
	 * @date Noviembre 2025
	 */	 
	public boolean valInformacionLiqRutaCedis(String usuario) {
	    try {

	        if (!u.isDisplayed(lbTotalTransferencias)) {
	            return false;
	        }

	        WebDriver driver = u.getDriver();
	        WebElement elemento = driver.findElement(lbTotalTransferencias);
	        String textoCompleto = elemento.getText();

	        String[] partes = textoCompleto.split("\n");
	        if (partes.length < 2) {
	            testCase.addTextEvidenceCurrentStep("No se pudo obtener el total de transferencias. Texto: " + textoCompleto);
	            System.out.println("No se pudo obtener el total de transferencias. Texto: " + textoCompleto);
	            return false;
	        }

	        String numeroStr = partes[1].trim();
	        int numero;
	        try {
	            numero = Integer.parseInt(numeroStr);
	        } catch (Exception ex) {
	            testCase.addTextEvidenceCurrentStep("No se pudo parsear el total de transferencias: " + numeroStr);
	            System.out.println("No se pudo parsear el total de transferencias: " + numeroStr);
	            return false;
	        }

	        System.out.println("Total de transferencias encontradas: " + numero);

	        Actions __actions__ = new Actions(driver);
	        List<WebElement> transferenciasDOM = driver.findElements(By.xpath("//p[contains(.,'Transferencia:')]"));

	        int index = 1;
	        for (WebElement p : transferenciasDOM) {
	            System.out.println("Procesando transferencia visual " + index + " de " + transferenciasDOM.size());

	            By xpathTransferencia = By.xpath("(//p[contains(.,'Transferencia:')])[" + index + "]");
	            u.scrollToElement(xpathTransferencia);
	            u.highLight(xpathTransferencia);

	            String textoP = p.getText().trim();
	            testCase.addTextEvidenceCurrentStep("Transferencia visible: " + textoP);

	            testCase.addScreenShotCurrentStep("Transferencia " + index + " de " + transferenciasDOM.size());

	            __actions__.scrollByAmount(0, 420).perform();
	            index++;
	        }

	        String bd = GlobalVariables.DB_URL_Cometa;
	        String user = GlobalVariables.DB_USER_Cometa;
	        String password = GlobalVariables.DB_PASSWORD_Cometa;

	        String sqlPerfil =
	                "select key_value " +
	                "from xxcm_user_keys " +
	                "where short_name = 'PCPERFIL' " +
	                "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

	        String sqlRfcSupplierPreferRFC =
	                "select key_value " +
	                "from xxcm_user_keys " +
	                "where usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "') " +
	                "  and short_name in ('PCRFC','PCSUPPLIERID') " +
	                "order by case when short_name = 'PCRFC' then 0 else 1 end " +
	                "limit 1";

	        try (Connection connection = DriverManager.getConnection(bd, user, password);
	             Statement stmt = connection.createStatement()) {

	            System.out.println("Se procesaron " + numero + " transferencias exitosamente");

	            String perfil = null;
	            try (ResultSet rsPerfil = stmt.executeQuery(sqlPerfil)) {
	                if (rsPerfil.next()) {
	                    perfil = rsPerfil.getString("key_value");
	                }
	            }

	            boolean esAdmin = (perfil != null) &&
	                    ("ADMIN".equalsIgnoreCase(perfil) || "OXXO_OS".equalsIgnoreCase(perfil));

	            String RFC = null;
	            if (!esAdmin) {
	                try (ResultSet rs2 = stmt.executeQuery(sqlRfcSupplierPreferRFC)) {
	                    if (!rs2.next()) {
	                        testCase.addTextEvidenceCurrentStep("No se encontró PCRFC/PCSUPPLIERID para el usuario: " + usuario);
	                        System.out.println("No se encontró PCRFC/PCSUPPLIERID para el usuario: " + usuario);
	                        return false;
	                    }
	                    RFC = rs2.getString("key_value");
	                }

	                if (RFC == null || RFC.trim().isEmpty()) {
	                    testCase.addTextEvidenceCurrentStep("PCRFC/PCSUPPLIERID vacío para el usuario: " + usuario);
	                    System.out.println("PCRFC/PCSUPPLIERID vacío para el usuario: " + usuario);
	                    return false;
	                }
	            }

	            String queryRegistros;
	            if (esAdmin) {
	                queryRegistros =
	                        "SELECT xhc.transferencia " +
	                        "FROM xxcm_historico_correos xhc " +
	                        "WHERE xhc.ruta_propuesta = '" + rutaPropuesta + "' " +
	                        "AND TRIM(xhc.ruta_propuesta) <> '' " +
	                        "ORDER BY xhc.fecha_registro DESC " +
	                        "LIMIT " + numero + ";";
	            } else {
	                queryRegistros =
	                        "SELECT xhc.transferencia " +
	                        "FROM xxcm_historico_correos xhc " +
	                        "WHERE xhc.ruta_propuesta = '" + rutaPropuesta + "' " +
	                        "AND TRIM(xhc.ruta_propuesta) <> '' " +
	                        "AND suppliable_id = '" + RFC + "' " +
	                        "ORDER BY xhc.fecha_registro DESC " +
	                        "LIMIT " + numero + ";";
	            }

	            boolean resultado;

	            try (ResultSet rs = stmt.executeQuery(queryRegistros)) {
	                System.out.println("Conexión exitosa con la base de datos de Cometa.");

	                List<String> transferenciasObtenidas = new ArrayList<>();
	                while (rs.next()) {
	                    transferenciasObtenidas.add(rs.getString("transferencia"));
	                }

	                if (transferenciasObtenidas.isEmpty()) {
	                    System.out.println("No se encontraron registros con la ruta propuesta = " + rutaPropuesta);
	                    resultado = false;
	                } else {
	                    testCase.addBoldTextEvidenceCurrentStep("Transferencias encontradas en la Base de Datos:");
	                    for (String t : transferenciasObtenidas) {
	                        testCase.addTextEvidenceCurrentStep(" -> " + t);
	                    }
	                    resultado = true;
	                }

	            } catch (SQLException e) {
	                System.err.println("Error al ejecutar la consulta de transferencias:");
	                e.printStackTrace();
	                resultado = false;
	            }

	            return resultado;
	        }

	    } catch (Exception e) {
	        System.out.println("[ERROR] Ocurrió un error durante la ejecución: " + e.getMessage());
	        e.printStackTrace();
	        return false;
	    }
	}



