    /**
     * Valida que los datos mostrados en Liquidacion de Ruta correspondan a los filtros aplicados
     *
     * @param screenshot indica si se toma evidencia en el reporte
     * @return true si ruta, transferencia y rango horario coinciden con los filtros
     *
     * @author Jose Pecina
     * @date Noviembre 2025
     */
	public boolean validarDatosFiltradosLR(boolean screenshot) {
	    WebDriver driver = u.getDriver();
	    try {
	        // Esperar a que cargue la sección de resultados
	        u.waitWebElement(By.tagName("app-cedis-liquidacion-ruta-detalle"), 20,5);
	        u.scrollToElement(By.tagName("app-cedis-liquidacion-ruta-detalle"));
	        // Validar la ruta visible
	        WebElement rutaElemento = driver.findElement(By.xpath("//div[contains(.,'Ruta:')]/following-sibling::div"));
	        String rutaVisible = rutaElemento.getText().trim();
	        if (!rutaVisible.equalsIgnoreCase(ruta)) {
	            System.out.println("La ruta visible (" + rutaVisible + ") no coincide con la filtrada (" + ruta + ")");
	            return false;
	        }
	        System.out.println("Ruta validada: " + rutaVisible);

	        // Validar la transferencia visible
	        WebElement transferenciaElemento = driver.findElement(By.xpath("//div[contains(.,'Transferencia') and contains(.,'" + transferencia + "')]"));
	        String transferenciaVisible = transferenciaElemento.getText().replace("Transferencia", "").trim();
	        if (!transferenciaVisible.contains(transferencia)) {
	            System.out.println("La transferencia visible (" + transferenciaVisible + ") no coincide con la filtrada (" + transferencia + ")");
	            return false;
	        }
	        System.out.println("Transferencia validada: " + transferenciaVisible);

	        //  Validar que no haya registros adicionales (más de una ruta o transferencia)
	        List<WebElement> rutasExtra = driver.findElements(By.xpath("//div[contains(.,'Ruta:')]"));
	        if (rutasExtra.size() > 1) {
	            System.out.println("Se detectaron múltiples rutas visibles en pantalla (" + rutasExtra.size() + ")");
	            return false;
	        }

	        List<WebElement> transferenciasExtra = driver.findElements(By.xpath("//div[contains(text(),'Transferencia')]"));
	        if (transferenciasExtra.size() > 1) {
	            System.out.println("Se detectaron múltiples transferencias visibles en pantalla (" + transferenciasExtra.size() + ")");
	            return false;
	        }

	        //  Validar rango de fecha/hora aplicado
	      
	        DateTimeFormatter formato = DateTimeFormatter.ofPattern("HH:mm");
	        LocalTime horaBase = LocalTime.parse(horaFormateada, formato);
	        LocalTime horaInicial = horaBase.minusHours(1);
	        LocalTime horaFinal = horaBase.plusHours(1);

	        System.out.println("Filtro de fecha: " + fechaFormateada);
	        System.out.println("Rango horario aplicado: " + horaInicial + " - " + horaFinal);

	        if (screenshot) {
	        	testCase.addBoldTextEvidenceCurrentStep("Se visualiza los registros que corresponda al rango");
	        	testCase.addTextEvidenceCurrentStep("Ruta validada: " + rutaVisible);
	        	testCase.addTextEvidenceCurrentStep("Transferencia validada: " + transferenciaVisible);
	        	testCase.addTextEvidenceCurrentStep("Rango horario aplicado: " + horaInicial + " - " + horaFinal);
	        }
	        return true;

	    } catch (Exception e) {
	        System.out.println("Fallo la validación de datos filtrados: " + e.getMessage());
	        e.printStackTrace();
	        return false;
	    }
	}

