 	/**
 	 * Obtiene la fecha de registro más reciente en la tabla xxcm_historico_correos
 	 * donde exista una ruta propuesta válida (no nula ni vacía).
 	 *
 	 * Este método se conecta a la base de datos de Cometa y ejecuta una consulta
 	 * que devuelve el valor más reciente de la columna `fecha_registro` para validar
 	 * la existencia y actualización de registros con ruta_propuesta definida.
 	 *
 	 * @return true si se obtuvo una fecha válida; false si no se encontraron registros o si ocurre un error.
 	 * @author 
 	 * Alejandro Valdez
 	 * @date 
 	 * Julio 2025
 	 */
 	public boolean obtenerFechaRegistroRutaPropuesta(String usuario) {
    boolean resultado = false;
    String bd = GlobalVariables.DB_URL_Cometa;
    String user = GlobalVariables.DB_USER_Cometa;
    String password = GlobalVariables.DB_PASSWORD_Cometa;

    String PCPERFIL =
        "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' and usuario_id = " +
        "(select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

    String PCRFC =
        "select key_value from xxcm_user_keys where short_name in ('PCRFC', 'PCSUPPLIERID') and usuario_id = " +
        "(select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

    try (Connection connection = DriverManager.getConnection(bd, user, password);
         Statement stmt = connection.createStatement();
         ResultSet rs = stmt.executeQuery(PCPERFIL)) {

        if (rs.next()) {  // hay resultado
            String keyValue = rs.getString("key_value");
            System.out.println("Usuario con perfil: " + keyValue);

            // Admin
            String queryFechaRegistro =
                "SELECT xhc.fecha_registro " +
                "FROM xxcm_historico_correos xhc " +
                "WHERE xhc.ruta_propuesta IS NOT NULL " +
                "AND TRIM(xhc.ruta_propuesta) <> '' " +
                "ORDER BY xhc.fecha_registro DESC " +
                "LIMIT 1;";

            System.out.println("Conexión exitosa con la base de datos de Cometa.");
            System.out.println("Ejecutando consulta para obtener la fecha_registro más reciente...\n");

            ResultSet rs3 = stmt.executeQuery(queryFechaRegistro);
            if (rs3.next()) {
                Timestamp fechaRegistro = rs3.getTimestamp("fecha_registro");
                if (fechaRegistro != null) {
                    // Convertir Timestamp a LocalDateTime
                    LocalDateTime fechaHora = fechaRegistro.toLocalDateTime();

                    // Formatear la fecha y quitar punto en abreviación de mes (ene. -> ene)
                    DateTimeFormatter formatoFecha = DateTimeFormatter.ofPattern("d MMM yyyy", new Locale("es", "ES"));
                    fechaFormateada = fechaHora.format(formatoFecha).replace(".", "");

                    LocalDateTime horaRedondeada = fechaHora.withMinute(0).withSecond(0).withNano(0);
                    DateTimeFormatter formatoHora = DateTimeFormatter.ofPattern("HH:mm");
                    horaFormateada = horaRedondeada.format(formatoHora);

                    System.out.println("Fecha formateada: " + fechaFormateada);
                    System.out.println("Hora formateada: " + horaFormateada);

                    resultado = true;
                } else {
                    System.out.println("[WARN] El valor de fecha_registro es nulo o inválido.");
                    resultado = false;
                }
            } else {
                System.out.println("[WARN] No se encontraron registros con ruta_propuesta válida en la tabla xxcm_historico_correos.");
                resultado = false;
            }
        } else { // CEDIS sin usuario definido

            ResultSet rs2 = stmt.executeQuery(PCRFC);
            rs2.next();
            String RFC = rs2.getString("key_value");

            String queryUpdateRuta =
                "UPDATE xxcm_historico_correos SET fecha_registro = now(), ruta_propuesta = 'ESC307' , suppliable_id = '" + RFC + "', version_documento = '2' WHERE id IN(3118);\n" +
                "UPDATE xxcm_historico_correos SET fecha_registro = now(), ruta_propuesta = 'ESC307' , suppliable_id = '" + RFC + "', version_documento = '2' WHERE id IN(3082);\n" +
                "UPDATE xxcm_historico_correos SET fecha_registro = now(), ruta_propuesta = 'ESC307' , suppliable_id = '" + RFC + "', version_documento = '2' WHERE id IN(3084);" +
                "UPDATE xxcm_historico_correos SET fecha_registro = now(), ruta_propuesta = 'NCH001' , suppliable_id = '" + RFC + "', version_documento = '2' WHERE id IN(3057);\n" +
                "UPDATE xxcm_historico_correos SET fecha_registro = now(), ruta_propuesta = 'NCH001' , suppliable_id = '" + RFC + "', version_documento = '2' WHERE id IN(2955);\n" +
                "UPDATE xxcm_historico_correos SET fecha_registro = now(), ruta_propuesta = 'NCH001' , suppliable_id = '" + RFC + "', version_documento = '2' WHERE id IN(2921);";

            stmt.executeUpdate(queryUpdateRuta);

            String queryFechaRegistro =
                "SELECT xhc.fecha_registro " +
                "FROM xxcm_historico_correos xhc " +
                "WHERE xhc.ruta_propuesta IS NOT NULL " +
                "AND TRIM(xhc.ruta_propuesta) <> '' " +
                "and xhc.suppliable_id = '" + RFC + "'" +
                "ORDER BY xhc.fecha_registro DESC " +
                "LIMIT 1;";

            ResultSet rs3 = stmt.executeQuery(queryFechaRegistro);
            if (rs3.next()) {
                Timestamp fechaRegistro = rs3.getTimestamp("fecha_registro");
                if (fechaRegistro != null) {
                    // Convertir Timestamp a LocalDateTime
                    LocalDateTime fechaHora = fechaRegistro.toLocalDateTime();

                    // Formatear la fecha y quitar punto en abreviación de mes (ene. -> ene)
                    DateTimeFormatter formatoFecha = DateTimeFormatter.ofPattern("d MMM yyyy", new Locale("es", "ES"));
                    fechaFormateada = fechaHora.format(formatoFecha).replace(".", "");

                    LocalDateTime horaRedondeada = fechaHora.withMinute(0).withSecond(0).withNano(0);
                    DateTimeFormatter formatoHora = DateTimeFormatter.ofPattern("HH:mm");
                    horaFormateada = horaRedondeada.format(formatoHora);

                    System.out.println("Fecha formateada: " + fechaFormateada);
                    System.out.println("Hora formateada: " + horaFormateada);

                    resultado = true;
                } else {
                    System.out.println("[WARN] El valor de fecha_registro es nulo o inválido.");
                    resultado = false;
                }
            } else {
                System.out.println("[WARN] No se encontraron registros con ruta_propuesta válida en la tabla xxcm_historico_correos.");
                resultado = false;
            }
        }

    } catch (SQLException e) {
        System.err.println("Ocurrió un error al ejecutar la consulta de ruta_propuesta: " + e.getMessage());
        e.printStackTrace();
        resultado = false;
    }

    return resultado;
}

