 	/**
 	 * Valida la busqueda en Directos Cambios fisicos con filtro de fecha de hace 3 anios mas 1 dia
 	 * usando una fecha ya existente en xxcm_cf. Este metodo solo consulta y selecciona
 	 * la fecha en la UI.
 	 *
 	 * @param usuario usuario para obtener perfil y datos desde BD
 	 * @param screenshot indica si se toma evidencia en el reporte
 	 * @return true si se obtiene una fecha valida, se aplica en el datepicker y se consulta correctamente
 	 * @throws Exception en caso de error durante la consulta o seleccion de fecha
 	 *
 	 * @author Jose Pecina
 	 * @date Marzo 2026
 	 */
 	public boolean busquedaFiltroFechaDevoluciones3AniosCF(String usuario, boolean screenshot) throws Exception {
 	    try {
 	        boolean result = true;

 	        String dbUrl = GlobalVariables.DB_URL_Cometa;
 	        String dbUser = GlobalVariables.DB_USER_Cometa;
 	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

 	        String perfil = null;
 	        String valorFiltro = null;
 	        LocalDate fechaConvert = null;

 	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword)) {

 	            String sqlPerfil =
 	                    "select key_value " +
 	                    "from xxcm_user_keys " +
 	                    "where short_name = 'PCPERFIL' " +
 	                    "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = ?)";

 	            try (PreparedStatement psPerfil = connection.prepareStatement(sqlPerfil)) {
 	                psPerfil.setString(1, usuario);

 	                try (ResultSet rsPerfil = psPerfil.executeQuery()) {
 	                    if (!rsPerfil.next()) {
 	                        System.out.println("No se obtuvo perfil para el usuario.");
 	                        return false;
 	                    }

 	                    perfil = rsPerfil.getString("key_value");
 	                    System.out.println("Usuario con perfil: " + perfil);
 	                }
 	            }

 	            if (!"ADMIN".equalsIgnoreCase(perfil) && !"OXXO_OS".equalsIgnoreCase(perfil)) {
 	                String shortName = "OXXO_PLAZA".equalsIgnoreCase(perfil) ? "PCPLAZA" : "PCRFC";

 	                String sqlValorFiltro =
 	                        "select key_value " +
 	                        "from xxcm_user_keys " +
 	                        "where short_name = ? " +
 	                        "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = ?)";

 	                try (PreparedStatement psValor = connection.prepareStatement(sqlValorFiltro)) {
 	                    psValor.setString(1, shortName);
 	                    psValor.setString(2, usuario);

 	                    try (ResultSet rsValor = psValor.executeQuery()) {
 	                        if (!rsValor.next()) {
 	                            System.out.println("No se obtuvo valor de filtro para el usuario.");
 	                            return false;
 	                        }

 	                        valorFiltro = rsValor.getString("key_value");
 	                    }
 	                }
 	            }

 	            StringBuilder sqlFecha = new StringBuilder();
 	            sqlFecha.append("select fecha ")
 	                    .append("from public.xxcm_cf ")
 	                    .append("where fecha = (current_date - interval '3 years' + interval '1 day')::date ");

 	            if (!"ADMIN".equalsIgnoreCase(perfil) && !"OXXO_OS".equalsIgnoreCase(perfil)) {
 	                if ("OXXO_PLAZA".equalsIgnoreCase(perfil)) {
 	                    sqlFecha.append("and cr_desc_plaza = ? ");
 	                } else {
 	                    sqlFecha.append("and proveedor_rfc = ? ");
 	                }
 	            }

 	            sqlFecha.append("order by fecha desc limit 1");

 	            try (PreparedStatement psFecha = connection.prepareStatement(sqlFecha.toString())) {
 	                if (!"ADMIN".equalsIgnoreCase(perfil) && !"OXXO_OS".equalsIgnoreCase(perfil)) {
 	                    psFecha.setString(1, valorFiltro);
 	                }

 	                try (ResultSet rsFecha = psFecha.executeQuery()) {
 	                    if (!rsFecha.next()) {
 	                        System.out.println("No se obtuvo fecha de hace 3 anios mas 1 dia en xxcm_cf.");
 	                        return false;
 	                    }

 	                    java.sql.Date fechaBD = rsFecha.getDate("fecha");
 	                    fechaConvert = fechaBD.toLocalDate();
 	                    System.out.println("Fecha obtenida para consulta: " + fechaConvert);
 	                }
 	            }
 	        }

 	        if (fechaConvert == null) {
 	            System.out.println("No se obtuvo ninguna fecha valida para continuar.");
 	            return false;
 	        }

 	        WebDriver driver = u.getDriver();
 	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

 	        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
 	        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

 	        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
 	        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

 	        By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
 	        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

 	        if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
 	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
 	        }

 	        clickYear(driver, wait, fechaConvert.getYear());
 	        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());
 	        clickDay(driver, wait, fechaConvert.getDayOfMonth());
 	        clickDay(driver, wait, fechaConvert.getDayOfMonth());

 	        try {
 	            driver.findElement(By.tagName("body")).click();
 	        } catch (Exception e) {
 	        }

 	        try {
 	            new org.openqa.selenium.interactions.Actions(driver)
 	                    .sendKeys(org.openqa.selenium.Keys.ESCAPE)
 	                    .perform();
 	        } catch (Exception e) {
 	        }

 	        WebDriverWait waitClose = new WebDriverWait(driver, Duration.ofSeconds(20));
 	        waitClose.until(d -> {
 	            java.util.List<WebElement> els = d.findElements(dpContent);
 	            if (els.isEmpty()) {
 	                return true;
 	            }
 	            try {
 	                return !els.get(0).isDisplayed();
 	            } catch (org.openqa.selenium.StaleElementReferenceException ex) {
 	                return true;
 	            }
 	        });

 	        consultarComprobantes(true);
 	        return result;

 	    } catch (Exception e) {
 	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
 	        throw new Exception("Error " + e.getMessage());
 	    }
 	}
