 	/**
 	 * Da clic en un boton de paginacion en Cambios fisicos y valida que cambie el label y el contenido del grid
 	 *
 	 * @param boton nombre del boton a presionar: primero, anterior, siguiente, ultimo
 	 * @param screenshot indica si se toma evidencia en el reporte
 	 * @return true si el label de paginacion cambia despues del clic
 	 *
 	 * @author Jose Pecina
 	 * @date Agosto 2025
 	 */
	public boolean clickBotonPaginacionCF(String boton, boolean screenshot) {
	    try {
	    	   boolean result = true;
	    	    WebDriver driver = u.getDriver();

	    	    // elegir el botón según el nombre que pasen
	    	    By botonLocator = null;
	    	    switch (boton.toLowerCase()) {
	    	        case "primero":
	    	            botonLocator = xmlPaginaPrimeraPaginaButtonCF;
	    	            break;
	    	        case "anterior":
	    	            botonLocator = xmlPaginaAnteriorButtonCF;
	    	            break;
	    	        case "siguiente":
	    	            botonLocator = xmlPaginaSiguienteButtonCF;
	    	            break;
	    	        case "ultimo":
	    	            botonLocator = xmlPaginaUltimaPaginaButtonCF;
	    	            break;
	    	        default:
	    	            System.out.println("No existe ese botón de paginación: " + boton);
	    	            return false;
	    	    }

	    	    try {
	    	        WebElement botonWeb = driver.findElement(botonLocator);
	    	        
	    	        if (!botonWeb.isDisplayed()) {
	    	            System.out.println("El botón '" + boton + "' no es visible");
	    	            return false;
	    	        }
	    	        if (!botonWeb.isEnabled()) {
	    	            System.out.println("El botón '" + boton + "' está deshabilitado");
	    	            return false;
	    	        }

	    	        // estado inicial
	    	        String labelInicial = u.getText(xmlPaginacionLabelOFCF);
	    	        u.scrollToElement(xmlPaginacionLabelOFCF);
	    	        String primerRegistroInicial = driver.findElement(xmlDatosTablaDirect).getText();

	    	        // clic
	    	        u.scrollToElement(botonLocator);
	    	        u.highLight(botonLocator);
	    	        if (screenshot) {
	    	            testCase.addTextEvidenceCurrentStep("Click en botón " + boton);
	    	            testCase.addScreenShotCurrentStep(u, "Pantalla Devoluciones");
	    	        }
	    	        u.unhighLight(botonLocator);
	    	        botonWeb.click();
	    	        u.hardWait(2);

	    	        // estado nuevo
	    	        
	    	        String labelNuevo = u.getText(xmlPaginacionLabelOFCF);
	    	        u.scrollToElement(xmlPaginacionLabelOFCF);
	    	        String primerRegistroNuevo = driver.findElement(xmlDatosTablaDirect).getText();

	    	        // validación label
	    	        if (labelInicial.equals(labelNuevo)) {
	    	            System.out.println("La paginación no cambió, sigue mostrando: " + labelInicial);
	    	            result = false;
	    	        } else {
	    	        	u.scrollToElement(xmlPaginacionLabelOFCF);
	    	        	 u.highLight(xmlPaginacionLabelOFCF);
	    	        	if (screenshot) {
		    	            testCase.addTextEvidenceCurrentStep("La paginación cambió de '" + labelInicial + "' a '" + labelNuevo + "'");
		    	            testCase.addScreenShotCurrentStep(u, "Pantalla Devoluciones");
		    	        }
	    	            System.out.println("La paginación cambió de '" + labelInicial + "' a '" + labelNuevo + "'");
	    	        }

	    	       
	    	        u.unhighLight(xmlPaginacionLabelOFCF);
	    	    } catch (Exception e) {
	    	        System.out.println("Error al hacer clic en botón " + boton + ": " + e.getMessage());
	    	        result = false;
	    	    }

	    	    return result;

	    } catch (Exception e) {
	        // Sin throw, solo deja evidencia y devuelve false
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        System.out.println("Error en clickBotonPaginacion: " + e.getMessage());
	        return false;
	    }
	}
