 	/**
 	 * Valida la paginacion en Cambios fisicos seleccionando cada opcion y contando filas del grid
 	 *
 	 * @param screenshot indica si se toma evidencia en el reporte
 	 * @return true si cada opcion de paginacion muestra filas menores o iguales al valor seleccionado
 	 * @throws Exception en caso de error durante la validacion
 	 *
 	 * @author Jose Pecina
 	 * @date Octubre 2025
 	 */
 	public boolean SelecPaginacionCF(boolean screenshot) throws Exception{
 	   try {
 		  u.scrollToElement(xmlPaginacionvalue);
 		  WebDriver driver = u.getDriver();
 		// Abrir dropdown de paginacion
 		  WebElement dropdown = driver.findElement(By.xpath("//*[@id='mat-select-0']"));
 		  dropdown.click();

 		  // Esperar a que el overlay del panel aparezca
 		  WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(5));
 		  WebElement panel = wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("mat-select-0-panel")));

 		  // Obtener todas las opciones visibles
 		  List<WebElement> opciones = wait.until(ExpectedConditions.visibilityOfAllElementsLocatedBy(
 		          By.xpath("//div[@id='mat-select-0-panel']//span[@role='option'] | //div[@id='mat-select-0-panel']//mat-option")));
 		// Lista de opciones de paginacion 
 		  List<String> opcionesPaginacion = Arrays.asList("5", "10", "15", "20");
 		  for (String opcion : opcionesPaginacion) {
 		      boolean opcionEncontrada = false;

 		      for (WebElement opt : opciones) {
 		          if (opt.getText().trim().equals(opcion)) {
 		              opt.click();
 		              opcionEncontrada = true;
 		              break;
 		          }
 		      }

 		      if (!opcionEncontrada) {
 		          System.out.println("Opcion no encontrada: " + opcion);
 		          return false;
 		      }

 		      // Esperar a que el grid se actualice
 		      u.hardWait(2); 

 		      // Contar filas visibles
 		      List<WebElement> filas = driver.findElements(By.xpath("/html/body/app-root/app-directos-cambios-fisicos/data-grid/div/table/tbody/tr"));
 		      int totalFilas = filas.size();

 		      if (totalFilas <= Integer.parseInt(opcion)) {
 		          u.scrollToElement(xmlPaginacionvalue);
 		          u.highLight(xmlPaginacionvalue);

 		          if (screenshot) {
 		              testCase.addTextEvidenceCurrentStep("Se visualizan correctamente " + totalFilas + " registros para opcion " + opcion);
 		              testCase.addScreenShotCurrentStep(u, "Pantalla Devoluciones " + opcion);
 		          }
 		          u.unhighLight(xmlPaginacionvalue);

 		          System.out.println("Correcto, opcion " + opcion + ", filas mostradas: " + totalFilas);
 		      } else {
 		          System.out.println("Error, opcion " + opcion + ", hay mas filas visibles: " + totalFilas);
 		          return false;
 		      }

 		      // Volver a abrir dropdown para siguiente iteracion
 		      dropdown.click();
 		      // Esperar a que el panel se vuelva a cargar
 		      panel = wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("mat-select-0-panel")));
 		      opciones = wait.until(ExpectedConditions.visibilityOfAllElementsLocatedBy(
 		              By.xpath("//div[@id='mat-select-0-panel']//span[@role='option'] | //div[@id='mat-select-0-panel']//mat-option")));
 		  }

 	        return true;

 	    } catch (Exception e) {
 	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
 	        throw new Exception("Error " + e.getMessage());
 	    }
 	}	
 	/**
 	 * Valida los encabezados del grid de Directos Cambios fisicos contra la lista esperada
 	 *
 	 * @param screenshot indica si se toma evidencia en el reporte
 	 * @return true si todos los encabezados coinciden con el orden y texto esperado
 	 *
 	 * @author Jose Pecina
 	 * @date Octubre 2025
 	 */
	public boolean validarEncabezadosGrid(boolean screenshot) {
	    try {
	        WebDriver driver = u.getDriver();
	        testCase.addTextEvidenceCurrentStep("Se muestra correctamente los campos en el grid");
	        By encabezadosBarra = By.xpath("//table//thead//tr");
	        u.scrollToElement(encabezadosBarra);
	        u.highLight(encabezadosBarra);
	        // Lista esperada
	        List<String> encabezadosEsperados = Arrays.asList(
	            "Fuente de Abasto",
	            "Nombre del proveedor",
	            "Región",
	            "Plaza",
	            "CR Tienda",
	            "Nombre de Tienda",
	            "Fecha",
	            "Remisión",
	            "Piezas realizadas",
	            "Precio de realizados",
	            "Piezas pendientes",
	            "Tipo de ticket"
	        );

	        // Localizamos los th de la tabla
	        List<WebElement> ths = driver.findElements(By.xpath("//table//thead//tr//th"));

	        // Extraemos el texto y normalizamos
	        List<String> encabezadosGrid = new ArrayList<>();
	        for (WebElement th : ths) {
	            String texto = th.getText();
	            if (texto != null && !texto.trim().isEmpty()) {
	                encabezadosGrid.add(texto.trim());
	            }
	        }

	        // Comparar listas
	        boolean todoCoincide = true;
	        StringBuilder resumen = new StringBuilder("Resumen encabezados GRID vs Esperado:\n");
	        for (int i = 0; i < encabezadosEsperados.size(); i++) {
	            String esperado = encabezadosEsperados.get(i);
	            String actual = i < encabezadosGrid.size() ? encabezadosGrid.get(i) : "NO EXISTE";

	            resumen.append("Posición ").append(i + 1)
	                   .append(": GRID='").append(actual)
	                   .append("', Esperado='").append(esperado)
	                   .append("'\n");

	            if (!normalize(actual).equalsIgnoreCase(normalize(esperado))) {
	                todoCoincide = false;
	                testCase.addTextEvidenceCurrentStep(
	                    "Diferencia en posición " + (i + 1) + ": GRID='" + actual + "', Esperado='" + esperado + "'"
	                );
	            } else {
	                testCase.addTextEvidenceCurrentStep(
	                    "Coincide en posición " + (i + 1) + ": " + actual
	                );
	            }
	        }

	        if (screenshot) testCase.addScreenShotCurrentStep(u, "Validacion_Encabezados_Grid");

	        return todoCoincide;

	    } catch (Exception e) {
	        testCase.addTextEvidenceCurrentStep("Error durante la validacion de encabezados: " + e.getMessage());
	        return false;
	    }
	}
	/**
	 * Metodo para validar que las fechas en el grid estén ordenadas de más recientes a más antiguas
	 * (orden descendente) en la pagina Cambios Fisicos.
	 * @author Jose Pecina
	 * @date Noviembre 2025
	 * @return True/False - True si el orden es descendente (reciente -> antiguo)
	 * @throws Exception
	 * @param screenshot - true or false para saber si se guardará screenshot en el reporte de evidencia o no
	 */
	public boolean validarPrimeros10TiposTicketContraBD(boolean screenshot) {
	    Connection connection = null;
	    PreparedStatement statement = null;
	    ResultSet resultSet = null;

	    try {
	        WebDriver driver = u.getDriver();

	        // === 1. OBTENER FILAS DEL GRID ===
	        List<String> tiposEnGrid = new ArrayList<>();
	        List<WebElement> filas = driver.findElements(By.xpath("//table//tbody//tr"));
	        int totalFilas = Math.min(filas.size(), 10);

	        for (int i = 0; i < totalFilas; i++) {
	            try {
	                List<WebElement> columnas = filas.get(i)
	                        .findElements(By.xpath(".//td[contains(@class,'mat-column-tipoTicket') or contains(@class,'cdk-column-tipoTicket')]"));
	                String valor = "";

	                if (columnas != null && !columnas.isEmpty()) {
	                    for (WebElement c : columnas) {
	                        String texto = c.getText();
	                        if (texto != null && !texto.trim().isEmpty()) {
	                            valor = texto.trim();
	                            break;
	                        }
	                    }
	                }

	                if (valor.isEmpty()) {
	                    List<WebElement> tds = filas.get(i).findElements(By.xpath(".//td"));
	                    for (WebElement td : tds) {
	                        String texto = td.getText();
	                        if (texto != null && !texto.trim().isEmpty()) {
	                            String txt = texto.toLowerCase();
	                            if (txt.contains("cambio") || txt.contains("fisico")
	                                    || txt.contains("pendiente") || txt.contains("nuevo")) {
	                                valor = texto.trim();
	                                break;
	                            }
	                        }
	                    }
	                }

	                tiposEnGrid.add(valor);

	            } catch (Exception e) {
	                tiposEnGrid.add("");
	            }
	        }

	        // === 2. OBTENER FILTROS DE LA UI ===
	        By xmlFiltroProveedor = By.xpath("//ng-select[contains(@bindlabel, 'supplierName')]");
	        By xmlFiltrofuenteDeAbasto = By.xpath("//ng-select[contains(@bindlabel, 'fuenteDeAbasto')]");
	        By xmlFiltrozona = By.xpath("//ng-select[contains(@bindlabel, 'zona')]");
	        By xmlFiltroregion = By.xpath("//ng-select[contains(@bindlabel, 'region')]");
	        By xmlFiltroplaza = By.xpath("//ng-select[contains(@bindlabel, 'plaza')]");
	        By xmlFiltrotienda = By.xpath("//ng-select[contains(@bindlabel, 'tienda')]");
	        By fechaInicioSpan = By.xpath("(//span[@class='mat-date-range-input-mirror'])[1]");
	        By fechaFinSpan = By.xpath("(//span[@class='mat-date-range-input-mirror'])[2]");

	        java.util.function.Function<WebElement, String> readValue = (elem) -> {
	            if (elem == null) return null;
	            try {
	                String v = elem.getAttribute("value");
	                if (v != null && !v.trim().isEmpty()) return v.trim();
	            } catch (Exception ignored) {}
	            try {
	                String t = elem.getText();
	                if (t != null && !t.trim().isEmpty()) return t.trim();
	            } catch (Exception ignored) {}
	            try {
	                Object o = ((JavascriptExecutor) driver)
	                        .executeScript("return (arguments[0].textContent || arguments[0].value || '').trim();", elem);
	                if (o != null && !o.toString().trim().isEmpty()) return o.toString().trim();
	            } catch (Exception ignored) {}
	            return null;
	        };

	        java.util.function.Function<By, List<String>> readNgSelectValues = (by) -> {
	            List<String> items = new ArrayList<>();
	            try {
	                WebElement sel = driver.findElement(by);
	                List<WebElement> vals = sel.findElements(By.cssSelector(".ng-value, .ng-value-label, .ng-value-item, .ng-label-text"));
	                for (WebElement v : vals) {
	                    String s = readValue.apply(v);
	                    if (s != null && !s.isEmpty()) items.add(s);
	                }
	            } catch (Exception ignored) {}
	            return items;
	        };

	        List<String> supplierNames = readNgSelectValues.apply(xmlFiltroProveedor);
	        List<String> fuenteDeAbasto = readNgSelectValues.apply(xmlFiltrofuenteDeAbasto);
	        List<String> zonas = readNgSelectValues.apply(xmlFiltrozona);
	        List<String> regiones = readNgSelectValues.apply(xmlFiltroregion);
	        List<String> plazas = readNgSelectValues.apply(xmlFiltroplaza);
	        List<String> tiendas = readNgSelectValues.apply(xmlFiltrotienda);

	        // === FECHAS ===
	        String inicioFecha = null;
	        String finFecha = null;

	        try {
	            String tInicio = readValue.apply(driver.findElement(fechaInicioSpan));
	            String tFin = readValue.apply(driver.findElement(fechaFinSpan));

	            DateTimeFormatter inFmt = DateTimeFormatter.ofPattern("d/M/yyyy");
	            DateTimeFormatter outFmt = DateTimeFormatter.ofPattern("yyyy-MM-dd");

	            if (tInicio != null) inicioFecha = LocalDate.parse(tInicio, inFmt).format(outFmt);
	            if (tFin != null) finFecha = LocalDate.parse(tFin, inFmt).format(outFmt);
	        } catch (Exception ignored) {}

	        // === 3. CONSULTAR BD ===
	        connection = DriverManager.getConnection(
	                GlobalVariables.DB_URL_Cometa,
	                GlobalVariables.DB_USER_Cometa,
	                GlobalVariables.DB_PASSWORD_Cometa
	        );

	        StringBuilder query = new StringBuilder();
	        query.append("WITH cte_data AS ( ");
	        query.append("SELECT ");
	        query.append(" t.body ->> 'Tipo' AS tipo, ");
	        query.append(" TO_DATE(t.body ->> 'Fecha_Encabezado', 'YYYY-MM-DD') AS fecha, ");
	        query.append(" t.created_at ");
	        query.append("FROM xxcm_historico_directos_cf_view t ");
	        query.append("WHERE 1=1 ");

	        if (!supplierNames.isEmpty())
	            query.append("AND supplier_name IN (")
	                    .append(supplierNames.stream().map(s -> "'" + s + "'").collect(Collectors.joining(",")))
	                    .append(") ");

	        if (!fuenteDeAbasto.isEmpty())
	            query.append("AND fuente_de_abasto IN (")
	                    .append(fuenteDeAbasto.stream().map(s -> "'" + s + "'").collect(Collectors.joining(",")))
	                    .append(") ");

	        if (!tiendas.isEmpty())
	            query.append("AND tienda IN (")
	                    .append(tiendas.stream().map(s -> "'" + s + "'").collect(Collectors.joining(",")))
	                    .append(") ");

	        if (!plazas.isEmpty())
	            query.append("AND plaza IN (")
	                    .append(plazas.stream().map(s -> "'" + s + "'").collect(Collectors.joining(",")))
	                    .append(") ");

	        if (!regiones.isEmpty())
	            query.append("AND region IN (")
	                    .append(regiones.stream().map(s -> "'" + s + "'").collect(Collectors.joining(",")))
	                    .append(") ");

	        if (!zonas.isEmpty())
	            query.append("AND zona IN (")
	                    .append(zonas.stream().map(s -> "'" + s + "'").collect(Collectors.joining(",")))
	                    .append(") ");

	        if (inicioFecha != null && finFecha != null)
	            query.append("AND TO_DATE(t.body ->> 'Fecha_Encabezado', 'YYYY-MM-DD') ")
	                    .append("BETWEEN '").append(inicioFecha).append("' AND '").append(finFecha).append("' ");

	        query.append(") ");
	        query.append("SELECT * FROM cte_data ");
	        query.append("ORDER BY fecha DESC, created_at DESC;");

	        statement = connection.prepareStatement(query.toString());
	        resultSet = statement.executeQuery();

	        List<String> tiposEnBD = new ArrayList<>();
	        int count = 0;

	        while (resultSet.next() && count < 10) {
	            String tipoBD = resultSet.getString("tipo");
	            if ("1".equals(tipoBD)) tiposEnBD.add("Cambio fisico nuevo");
	            else if ("2".equals(tipoBD)) tiposEnBD.add("Cambio fisico pendiente");
	            else tiposEnBD.add("Desconocido");
	            count++;
	        }

	        // === 4. COMPARAR ===
	        boolean todoCoincide = true;
	        StringBuilder resumen = new StringBuilder("Resumen GRID vs BD:\n");

	        for (int i = 0; i < Math.min(tiposEnGrid.size(), tiposEnBD.size()); i++) {
	            String grid = normalize(tiposEnGrid.get(i));
	            String bd = normalize(tiposEnBD.get(i));

	            resumen.append("Fila ").append(i + 1)
	                    .append(": GRID='").append(cleanForEvidence(tiposEnGrid.get(i)))
	                    .append("', BD='").append(cleanForEvidence(tiposEnBD.get(i))).append("'\n");

	            if (!grid.equals(bd)) {
	                todoCoincide = false;
	                testCase.addTextEvidenceCurrentStep(
	                        "Diferencia en fila " + (i + 1) +
	                        ": GRID='" + cleanForEvidence(tiposEnGrid.get(i)) +
	                        "', BD='" + cleanForEvidence(tiposEnBD.get(i)) + "'"
	                );
	            } else {
	                testCase.addTextEvidenceCurrentStep(
	                        "Coincide en fila " + (i + 1) + ": " +
	                        cleanForEvidence(tiposEnGrid.get(i))
	                );
	            }
	        }

	        testCase.addTextEvidenceCurrentStep(resumen.toString());

	        if (screenshot)
	            testCase.addScreenShotCurrentStep(u, "Validacion_Tipo_Ticket");

	        return todoCoincide;

	    } catch (Exception e) {
	        testCase.addTextEvidenceCurrentStep(
	                "Error durante la validacion de tipos de ticket: " + e.getMessage()
	        );
	        return false;
	    } finally {
	        try { if (resultSet != null) resultSet.close(); } catch (Exception ignored) {}
	        try { if (statement != null) statement.close(); } catch (Exception ignored) {}
	        try { if (connection != null) connection.close(); } catch (Exception ignored) {}
	    }
	}
	
	/**
	 * Normaliza un texto para comparación lógica:
	 * - Elimina acentos (normalización Unicode)
	 * - Convierte todo a minúsculas
	 * - Elimina espacios sobrantes
	 *
	 * Se usa para comparar valores del GRID contra valores esperados
	 * o de Base de Datos sin afectar por acentos, mayúsculas o formato.
	 *
	 * @param texto Texto original a normalizar
	 * @return Texto normalizado para comparación
	 * @date Noviembre 2025
	 * @author Jose Pecina
	 */
	private String normalize(String texto) {
	    if (texto == null) return "";
	    String normalizado = java.text.Normalizer.normalize(texto, java.text.Normalizer.Form.NFD)
	            .replaceAll("\\p{M}", "");
	    return normalizado.trim().toLowerCase();
	}
	
