	/**
	 * Consulta en PostgreSQL el valor de proceso_cf por folio
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @param folio folio a consultar
	 * @return origen calculado segun proceso_cf o valor por defecto
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public String ConsultaOrigenPorFolio(boolean screenshot, String folio) {
	    String origenPorDefecto = "Devoluciones ";
	    String sql = "SELECT proceso_cf " +
	                 "FROM public.xxcm_dv_detalle " +
	                 "WHERE folio = ? " +
	                 "LIMIT 1;";

	    String resultado = origenPorDefecto;

	    if (folio == null) {
	        if (screenshot) {
	            try {
	                testCase.addBoldTextEvidenceCurrentStep("Folio nulo recibido en ConsultaOrigenPorFolio.");
	            } catch (Exception e) {
	            }
	        }
	        return resultado;
	    }

	    String folioEscapado = folio.replace("'", "''");
	    String executedQueryForEvidence = sql.replace("?", "'" + folioEscapado + "'");

	    try (Connection connection = DriverManager.getConnection(
	            GlobalVariables.DB_URL_Cometa,
	            GlobalVariables.DB_USER_Cometa,
	            GlobalVariables.DB_PASSWORD_Cometa);
	         PreparedStatement ps = connection.prepareStatement(sql)) {

	        ps.setString(1, folio);

	        if (screenshot) {
	            try {
	                testCase.addBoldTextEvidenceCurrentStep("Ejecutando query para obtener proceso_cf: " + executedQueryForEvidence);
	            } catch (Exception e) {
	            }
	        }

	        try (ResultSet rs = ps.executeQuery()) {
	            if (rs.next()) {
	                String procesoCfTxt = rs.getString("proceso_cf");

	                if (procesoCfTxt != null) {
	                    String v = procesoCfTxt.trim().toLowerCase();
	                    boolean procesoCf = v.equals("true") || v.equals("t") || v.equals("1");

	                    if (procesoCf) {
	                        resultado = "Cambios Fisicos\r";
	                    } else {
	                        resultado = origenPorDefecto;
	                    }
	                } else {
	                    resultado = origenPorDefecto;
	                }
	            } else {
	                resultado = origenPorDefecto;
	                if (screenshot) {
	                    try {
	                        testCase.addBoldTextEvidenceCurrentStep("No se encontro registro para folio: " + folio);
	                    } catch (Exception e) {
	                    }
	                }
	            }
	        }

	        if (screenshot) {
	            try {
	                testCase.addBoldTextEvidenceCurrentStep("Origen calculado: " + resultado);
	                testCase.addScreenShotCurrentStep(u, "ConsultaOrigenPorFolio_" + folioEscapado);
	            } catch (Exception e) {
	            }
	        }

	    } catch (Exception e) {
	        try {
	            testCase.addCodeEvidenceCurrentStep("Error en ConsultaOrigenPorFolio: " + e.getMessage());
	        } catch (Exception ex) {
	        }
	        System.err.println("Error al consultar proceso_cf para folio " + folio + ": " + e.getMessage());
	        e.printStackTrace();
	        resultado = origenPorDefecto;
	    }

	    return resultado;
	}
	/**
	 * Valida que la columna Origen en el Excel coincida con la BD en Directos Devoluciones
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si todos los registros coinciden
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public boolean validarOrigenConExcel(boolean screenshot) throws Exception {
	    boolean todoCoincide = true;
	    String home = System.getProperty("user.home") + "\\Downloads";
	    FileInputStream fis = null;
	    Workbook wb = null;

	    try {
	        File f = new File(getLastModified(home).getAbsolutePath());
	        if (!f.exists()) {
	            throw new Exception("No existe archivo Excel en: " + home);
	        }

	        u.hardWait(2);
	        Desktop desktop = Desktop.getDesktop();
	        desktop.open(f);
	        u.hardWait(10);

	        fis = new FileInputStream(f);
	        wb = WorkbookFactory.create(fis);
	        Sheet sheet = wb.getSheetAt(0);

	        if (sheet == null) {
	            throw new Exception("Hoja no encontrada en el Excel: " + home);
	        }

	        int firstRow = 1;
	        int lastRow = sheet.getLastRowNum();

	        Row headerRow = sheet.getRow(0);
	        if (headerRow == null) {
	            throw new Exception("No se encontro la fila de encabezados en el Excel.");
	        }

	        int columnaFolio = -1;
	        int columnaOrigen = -1;

	        StringBuilder encabezadosDetectados = new StringBuilder();

	        for (int i = 0; i < headerRow.getLastCellNum(); i++) {
	            Cell headerCell = headerRow.getCell(i);
	            if (headerCell == null) {
	                encabezadosDetectados.append("[").append(i).append(": null] ");
	                continue;
	            }

	            String header = headerCell.toString();
	            if (header == null) {
	                encabezadosDetectados.append("[").append(i).append(": null] ");
	                continue;
	            }

	            header = header.trim().replace("\n", " ").replace("\r", " ");
	            header = header.replaceAll("\\s+", " ");

	            encabezadosDetectados.append("[").append(i).append(": '").append(header).append("'] ");

	            String headerUpper = header.toUpperCase();

	            if (header.equalsIgnoreCase("Folio") || headerUpper.contains("FOLIO")) {
	                columnaFolio = i;
	            }

	            if (header.equalsIgnoreCase("Origen") || headerUpper.contains("ORIGEN")) {
	                columnaOrigen = i;
	            }
	        }

	        testCase.addTextEvidenceCurrentStep("Encabezados detectados: " + encabezadosDetectados.toString());

	        if (columnaFolio == -1) {
	            throw new Exception("No se encontro la columna Folio en el Excel.");
	        }

	        if (columnaOrigen == -1) {
	            throw new Exception("No se encontro la columna Origen en el Excel.");
	        }

	        for (int r = firstRow; r <= lastRow; r++) {
	            Row row = sheet.getRow(r);
	            if (row == null) {
	                continue;
	            }

	            Cell folioCell = row.getCell(columnaFolio);
	            if (folioCell == null) {
	                if (screenshot) {
	                    try {
	                        testCase.addBoldTextEvidenceCurrentStep("Fila " + (r + 1) + ": folio vacio, se omite.");
	                    } catch (Exception e) {
	                    }
	                }
	                continue;
	            }

	            folioCell.setCellType(CellType.STRING);
	            String folio = folioCell.getStringCellValue();

	            if (folio == null || folio.trim().isEmpty()) {
	                if (screenshot) {
	                    try {
	                        testCase.addBoldTextEvidenceCurrentStep("Fila " + (r + 1) + ": folio vacio, se omite.");
	                    } catch (Exception e) {
	                    }
	                }
	                continue;
	            }

	            folio = folio.trim();

	            String origenEsperado;
	            try {
	                origenEsperado = this.ConsultaOrigenPorFolio(false, folio);
	            } catch (Exception e) {
	                origenEsperado = "Devoluciones ";
	                todoCoincide = false;
	                try {
	                    testCase.addCodeEvidenceCurrentStep("Error consultando BD para folio " + folio + ": " + e.getMessage());
	                } catch (Exception ex) {
	                }
	            }

	            Cell origenCell = row.getCell(columnaOrigen);
	            String origenActual = "";

	            if (origenCell != null) {
	                origenCell.setCellType(CellType.STRING);
	                origenActual = origenCell.getStringCellValue();
	                if (origenActual == null) {
	                    origenActual = "";
	                }
	                origenActual = origenActual.trim();
	            } else {
	                origenActual = "";
	            }

	            String esperadoNorm = normalizarOrigenComparacion(origenEsperado);
	            String actualNorm = normalizarOrigenComparacion(origenActual);

	            if (!actualNorm.equals(esperadoNorm)) {
	                String msg = String.format(
	                    "Fila %d (Folio: %s) - Origen actual: '%s' <> Esperado BD: '%s'",
	                    (r + 1), folio, origenActual, origenEsperado
	                );

	                try {
	                    testCase.addBoldTextEvidenceCurrentStep(msg);
	                } catch (Exception e) {
	                }

	                if (screenshot) {
	                    try {
	                        String ssName = "ValidacionOrigen_Fila" + (r + 1) + "_Folio_" + folio.replaceAll("[^A-Za-z0-9-_\\.]", "_");
	                        testCase.addScreenShotCurrentStep(u, ssName);
	                    } catch (Exception e) {
	                    }
	                }

	                todoCoincide = false;
	            } else {
	                if (screenshot) {
	                    try {
	                        testCase.addBoldTextEvidenceCurrentStep("Fila " + (r + 1) + " (Folio " + folio + "): Origen coincide -> " + origenActual);
	                    } catch (Exception e) {
	                    }
	                }
	            }
	        }

	        if (todoCoincide) {
	            testCase.addScreenShotCurrentStep("ExcelOrigen");
	            Runtime.getRuntime().exec("cmd /c taskkill /f /im excel.exe");
	        }

	    } catch (Exception e) {
	        try {
	            testCase.addCodeEvidenceCurrentStep("Error en validarOrigenConExcel_SoloComparar: " + e.getMessage());
	        } catch (Exception ex) {
	        }
	        throw e;
	    } finally {
	        try {
	            if (fis != null) {
	                fis.close();
	            }
	        } catch (Exception ex) {
	        }
	        try {
	            if (wb != null) {
	                wb.close();
	            }
	        } catch (Exception ex) {
	        }
	    }

	    return todoCoincide;
	}

	/**
	 * Normaliza texto para comparaciones:
	 * elimina acentos, CR/LF, espacios extra y trim.
	 *
	 * @param texto texto a normalizar
	 * @return texto normalizado
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	/**
	 * Normaliza texto para comparacion de origen (Excel vs BD),
	 * eliminando acentos, espacios, saltos de linea y caracteres especiales.
	 *
	 * @author Jose Pecina
	 * @date Marzo 2026
	 * @param texto valor a normalizar
	 * @return texto listo para comparacion
	 * @throws Exception
	 */
	private String normalizarOrigenComparacion(String texto) throws Exception {
	    if (texto == null) {
	        return "";
	    }

	    String valor = texto;

	    // Quitar saltos de linea y CR
	    valor = valor.replace("\r", "")
	                 .replace("\n", "");

	    // Quitar acentos
	    valor = java.text.Normalizer.normalize(valor, java.text.Normalizer.Form.NFD);
	    valor = valor.replaceAll("\\p{M}", "");

	    // Normalizar
	    valor = valor.trim().toUpperCase();
	    valor = valor.replaceAll("\\s+", "");
	    valor = valor.replace("-", "");

	    return valor;
	}
	/**
	 * Valida que la respuesta del grid incluya el campo id en el JSON
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si se obtiene un id en la respuesta
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public boolean obtenerIdDeGrid(boolean screenshot) {
	    WebDriver driver = null;
	    String idEncontrado = null;
	    u.scrollToElement(xmlFiltroProveedor);
	    try {
	        driver = u.getDriver();
	      
	        String token = null;
	        try {
	            JavascriptExecutor js = (JavascriptExecutor) driver;
	            String[] posiblesClaves = {"access_token","id_token","token","authToken","jwt","accessToken"};
	            for (String clave : posiblesClaves) {
	                Object valor = js.executeScript(
	                    "try {return window.localStorage.getItem(arguments[0]) || window.sessionStorage.getItem(arguments[0]);}catch(e){return null;}",
	                    clave);
	                if (valor != null && !String.valueOf(valor).trim().isEmpty() && !"null".equals(String.valueOf(valor))) {
	                    token = String.valueOf(valor);
	                    System.out.println("[INFO] Token encontrado en storage con clave: " + clave);
	                    break;
	                }
	            }
	        } catch (Exception e) {
	            System.err.println("[WARN] No se pudo leer storage: " + e.getMessage());
	        }

	        String cookieHeader = null;
	        try {
	            Set<Cookie> cookies = ((ChromeDriver) driver).manage().getCookies();
	            if (cookies != null && !cookies.isEmpty()) {
	                cookieHeader = cookies.stream()
	                        .map(c -> c.getName() + "=" + c.getValue())
	                        .collect(Collectors.joining("; "));
	            }
	        } catch (Exception e) {
	            System.err.println("[WARN] No se pudieron leer cookies: " + e.getMessage());
	        }

	        // --- Construir payload y enviar POST ---
	        String url = "https://oxzasbpocmq01.azurewebsites.net/api/directos/devoluciones/grid";
	        String postPayload = buildPostPayloadDesdeFiltros(driver);
	        System.out.println("[DEBUG] Payload construido: " + postPayload);

	        HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(15)).build();
	        HttpRequest.Builder rb = HttpRequest.newBuilder()
	                .uri(URI.create(url))
	                .timeout(Duration.ofSeconds(30))
	                .header("Accept", "application/json, text/plain, */*")
	                .header("Content-Type", "application/json")
	                .header("Origin", "https://pruebasweb.oxxo.com")
	                .header("Referer", "https://pruebasweb.oxxo.com/")
	                .header("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/141.0.0.0 Safari/537.36")
	                .header("Sec-Fetch-Dest", "empty")
	                .header("Sec-Fetch-Mode", "cors")
	                .header("Sec-Fetch-Site", "cross-site");

	        if (token != null) {
	            if (token.trim().toLowerCase().startsWith("bearer ")) {
	                rb.header("Authorization", token.trim());
	            } else {
	                rb.header("Authorization", "Bearer " + token.trim());
	            }
	        } else if (cookieHeader != null) {
	            rb.header("Cookie", cookieHeader);
	        }

	        rb.POST(HttpRequest.BodyPublishers.ofString(postPayload));
	        HttpRequest request = rb.build();
	        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

	        System.out.println("[INFO] POST status: " + response.statusCode());
	        String body = response.body();
	        System.out.println("[DEBUG] Body (primeros 1000 chars): " + (body == null ? "null" : body.substring(0, Math.min(1000, body.length()))));

	        // --- Parsear JSON y extraer primer id ---
	        if (response.statusCode() == 200) {
	            ObjectMapper mapper = new ObjectMapper();
	            JsonNode root = mapper.readTree(body);
	            JsonNode dataNode = root.isArray() ? root : root.path("data");
	            if (dataNode.isArray() && dataNode.size() > 0) {
	                JsonNode first = dataNode.get(0);
	                if (first.has("id")) {
	                    idEncontrado = first.get("id").asText();
	                    System.out.println("[INFO] Primer ID obtenido: " + idEncontrado);
	                } else {
	                    System.out.println("[WARN] El primer objeto no contiene 'id'.");
	                }
	            } else {
	                System.out.println("[WARN] No se encontraron registros en la respuesta.");
	            }
	        } else {
	            System.err.println("[ERROR] Respuesta no OK: " + response.statusCode());
	        }

	   
	        if (screenshot && testCase != null) {
	            testCase.addTextEvidenceCurrentStep("Se visualiza registros en pantalla de Devoluciones, ID: " + (idEncontrado != null ? idEncontrado : "sin ID"));
	            testCase.addScreenShotCurrentStep(u, "Grid_ID");
	        }

	        return idEncontrado != null;

	    } catch (Exception e) {
	        System.err.println("[ERROR] obtenerIdDeGrid: " + e.getMessage());
	        e.printStackTrace();

	        try {
	            if (screenshot && driver != null && testCase != null) {
	                testCase.addTextEvidenceCurrentStep("Error al obtener ID: " + e.getMessage());
	                testCase.addScreenShotCurrentStep(u, "Grid_ID_Error");
	            }
	        } catch (Exception ex) {
	            System.err.println("[WARN] No se pudo agregar screenshot de error: " + ex.getMessage());
	        }
	        return false;
	    }
	}
	/**
	 * Construye dinamicamente el JSON payload usando los filtros seleccionados en la UI
	 *
	 * @param driver WebDriver para obtener valores de los elementos
	 * @return payload en formato JSON como String
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private String buildPostPayloadDesdeFiltros(WebDriver driver) {
	    try {
	        ObjectMapper mapper = new ObjectMapper();
	        ObjectNode rootNode = mapper.createObjectNode();

	        rootNode.put("page", 1);
	        rootNode.put("size", 20);

	        ArrayNode filters = mapper.createArrayNode();

	        By xmlFiltroProveedor = By.xpath("//ng-select[contains(@bindlabel, 'supplierName')]");
	        By xmlFiltrofuenteDeAbasto = By.xpath("//ng-select[contains(@bindlabel, 'fuenteDeAbasto')]");
	        By xmlFiltrozona = By.xpath("//ng-select[contains(@bindlabel, 'zona')]");
	        By xmlFiltroregion = By.xpath("//ng-select[contains(@bindlabel, 'region')]");
	        By xmlFiltroplaza = By.xpath("//ng-select[contains(@bindlabel, 'plaza')]");
	        By xmlFiltrotienda = By.xpath("//ng-select[contains(@bindlabel, 'tienda')]");
	        By fechaInicioSpan = By.xpath("(//span[@class='mat-date-range-input-mirror'])[1]");
	        By fechaFinSpan = By.xpath("(//span[@class='mat-date-range-input-mirror'])[2]");

	        java.util.function.BiConsumer<String, List<String>> addFilter = (field, values) -> {
	            ObjectNode f = mapper.createObjectNode();
	            f.put("field", field);
	            ArrayNode arr = mapper.createArrayNode();
	            if (values != null) {
	                for (String v : values) arr.add(v);
	            }
	            f.set("value", arr);
	            filters.add(f);
	        };

	        java.util.function.Function<By, List<String>> getSelectedValues = (locator) -> {
	            List<String> results = new ArrayList<>();
	            try {
	                WebElement ng = driver.findElement(locator);
	                List<WebElement> vals = ng.findElements(By.cssSelector(".ng-value, .ng-value-label, .ng-value-item, .selected, .ng-select-container span"));
	                for (WebElement v : vals) {
	                    String text = v.getText().trim();
	                    if (text != null && !text.isEmpty() && !text.equalsIgnoreCase("Proveedor") &&
	                        !text.equalsIgnoreCase("Tienda") && !text.equalsIgnoreCase("FA (Fuente de Abasto)")) {
	                        results.add(text);
	                    }
	                }
	            } catch (Exception ignored) {}
	            return results;
	        };

	        addFilter.accept("proveedores", getSelectedValues.apply(xmlFiltroProveedor));
	        addFilter.accept("fuentesDeAbasto", getSelectedValues.apply(xmlFiltrofuenteDeAbasto));
	        addFilter.accept("zonas", getSelectedValues.apply(xmlFiltrozona));
	        addFilter.accept("regiones", getSelectedValues.apply(xmlFiltroregion));
	        addFilter.accept("plazas", getSelectedValues.apply(xmlFiltroplaza));

	        // --- OBTENER RETEKIDS ---
	        List<String> retekIds = new ArrayList<>();
	        try {
	            List<String> tiendasSeleccionadas = getSelectedValues.apply(xmlFiltrotienda);

	            if (!tiendasSeleccionadas.isEmpty()) {
	                String token = null;
	                try {
	                    JavascriptExecutor js = (JavascriptExecutor) driver;
	                    String[] posiblesClaves = {"access_token","id_token","token","authToken","jwt","accessToken"};
	                    for (String clave : posiblesClaves) {
	                        Object valor = js.executeScript(
	                            "try {return window.localStorage.getItem(arguments[0]) || window.sessionStorage.getItem(arguments[0]);}catch(e){return null;}",
	                            clave);
	                        if (valor != null && !String.valueOf(valor).trim().isEmpty() && !"null".equals(String.valueOf(valor))) {
	                            token = String.valueOf(valor);
	                            break;
	                        }
	                    }
	                } catch (Exception ignored) {}

	                String dropdownUrl = "https://oxzasbpocmq01.azurewebsites.net/api/directos/devoluciones/dropdown/all";
	                HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();
	                HttpRequest.Builder rb = HttpRequest.newBuilder()
	                        .uri(URI.create(dropdownUrl))
	                        .timeout(Duration.ofSeconds(15))
	                        .header("Accept", "application/json");

	                if (token != null) {
	                    rb.header("Authorization", token.startsWith("Bearer ") ? token : "Bearer " + token);
	                }

	                HttpRequest req = rb.GET().build();
	                HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString());

	                if (resp.statusCode() == 200) {
	                    ObjectMapper mapper2 = new ObjectMapper();
	                    JsonNode root = mapper2.readTree(resp.body());
	                    JsonNode itemsArray = root.isArray() ? root : root.path("data");

	                    for (JsonNode item : itemsArray) {
	                        String tiendaName = item.path("tienda").asText().replaceAll("\\s+", " ").trim();
	                        String idRetek = item.path("idRetek").asText();

	                        for (String uiName : tiendasSeleccionadas) {
	                            String uiNorm = uiName.replaceAll("\\s+", " ").trim();
	                            if (uiNorm.equalsIgnoreCase(tiendaName)) {
	                                retekIds.add(idRetek);
	                            }
	                        }
	                    }
	                }
	            }
	        } catch (Exception ignored) {}

	        // Eliminar duplicados
	        List<String> retekIdsUnicos = retekIds.stream()
	                .distinct()
	                .collect(java.util.stream.Collectors.toList());

	        addFilter.accept("retekIds", retekIdsUnicos);

	        // --- FECHAS ---
	        String inicio = null;
	        String fin = null;
	        try {
	            WebElement eInicio = null;
	            WebElement eFin = null;
	            try { eInicio = driver.findElement(By.xpath("(//input[@matstartdate])[1]")); } catch (Exception ignored) {}
	            try { eFin = driver.findElement(By.xpath("(//input[@matenddate])[1]")); } catch (Exception ignored) {}

	            if (eInicio == null) try { eInicio = driver.findElement(fechaInicioSpan); } catch (Exception ignored) {}
	            if (eFin == null) try { eFin = driver.findElement(fechaFinSpan); } catch (Exception ignored) {}

	            java.util.function.Function<WebElement, String> readValue = (elem) -> {
	                if (elem == null) return null;
	                try { String v = elem.getAttribute("value"); if (v != null && !v.trim().isEmpty()) return v.trim(); } catch (Exception ignored) {}
	                try { String t = elem.getText(); if (t != null && !t.trim().isEmpty()) return t.trim(); } catch (Exception ignored) {}
	                try { Object o = ((JavascriptExecutor) driver).executeScript("return (arguments[0].textContent || arguments[0].value || '').trim();", elem);
	                      if (o != null) { String s = o.toString().trim(); if (!s.isEmpty()) return s; } } catch (Exception ignored) {}
	                return null;
	            };

	            String tInicio = readValue.apply(eInicio);
	            String tFin = readValue.apply(eFin);

	            DateTimeFormatter inFmt = DateTimeFormatter.ofPattern("d/M/yyyy");
	            DateTimeFormatter outFmt = DateTimeFormatter.ofPattern("yyyy-MM-dd");
	            if (tInicio != null) { try { inicio = LocalDate.parse(tInicio, inFmt).format(outFmt); } catch (DateTimeParseException ex) { inicio = tInicio; } }
	            if (tFin != null) { try { fin = LocalDate.parse(tFin, inFmt).format(outFmt); } catch (DateTimeParseException ex) { fin = tFin; } }
	        } catch (Exception ignored) {}

	        ObjectNode fInicio = mapper.createObjectNode();
	        fInicio.put("field", "fechaInicio");
	        fInicio.put("value", inicio != null ? inicio : "");
	        filters.add(fInicio);

	        ObjectNode fFin = mapper.createObjectNode();
	        fFin.put("field", "fechaFinal");
	        fFin.put("value", fin != null ? fin : "");
	        filters.add(fFin);

	        rootNode.set("filters", filters);

	        return mapper.writeValueAsString(rootNode);

	    } catch (Exception ex) {
	        ex.printStackTrace();
	        return "{\"page\":1,\"size\":20,\"filters\":[]}";
	    }
	}

	/**
	 * Metodo para validar que al hacer click en los botones de navegacion de ticket, cambie el dato del folio
	 * @author Jose Pecina
	 * @date Agosto 2025
     * @param screenshot - true or false para saber si se guardará screenshot en el reporte de evidencia o no
	 */
	public boolean validarSiguienteYUltimoDistintosAInicial(boolean screenshot) {
	    try {
	    	// folio inicial guardado
	        if (ultimaDevolucionSeleccionada == null || ultimaDevolucionSeleccionada.folio == null ||
	            ultimaDevolucionSeleccionada.folio.trim().isEmpty()) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No hay folio inicial almacenado.");
	            return false;
	        }
	        String folioInicial = ultimaDevolucionSeleccionada.folio.trim();
	        if (screenshot) testCase.addTextEvidenceCurrentStep("Se visualiza la actualización del contenido");

	        // --- 1) Click Siguiente y validar que el folio del PDF sea distinto al inicial
	        if (!clickBotonPaginacionTicket("siguiente", false)) {
	            testCase.addTextEvidenceCurrentStep("Fallo al clickear 'siguiente'.");
	            return false;
	        }
	        
	        // Leer folio del PDF visible tras seleccionar
	        String folioPDFDespuesSiguiente = capturarTextoPDFVisible();
	        if (folioPDFDespuesSiguiente == null) {
	            testCase.addTextEvidenceCurrentStep("No se pudo leer folio del PDF tras 'siguiente'.");
	            return false;
	        }
	        

	        boolean distintoSiguiente = !folioInicial.equals(folioPDFDespuesSiguiente.trim());
	        
	        if (!distintoSiguiente) return false;
	        if (screenshot) {
	        	testCase.addTextEvidenceCurrentStep("Folio inicial: " + folioInicial + "folio actual:" + folioPDFDespuesSiguiente);
	            testCase.addScreenShotCurrentStep(u, "TicketSiguiente");
	        }
	        
	        // --- 2) Click Último y validar que el folio del PDF sea distinto al inicial
	        if (!clickBotonPaginacionTicket("ultimo", false)) {
	            testCase.addTextEvidenceCurrentStep("Fallo al clickear 'ultimo'.");
	            return false;
	        }

	        // Leer folio del PDF visible tras seleccionar en última página
	        String folioPDFDespuesUltimo = capturarTextoPDFVisible();
	        if (folioPDFDespuesUltimo == null) {
	            testCase.addTextEvidenceCurrentStep("No se pudo leer folio del PDF tras 'ultimo'.");
	            return false;
	        }
	        

	        boolean distintoUltimo = !folioInicial.equals(folioPDFDespuesUltimo.trim());
	        if (screenshot) {	   
	        	testCase.addTextEvidenceCurrentStep("Folio anterior: " + folioPDFDespuesSiguiente + "folio actual:" + folioPDFDespuesUltimo);
	            testCase.addScreenShotCurrentStep(u, "Ticketultimo");
	        }

	        return distintoSiguiente && distintoUltimo;

	    } catch (Exception e) {
	        testCase.addTextEvidenceCurrentStep("Error en validarSiguienteYUltimoDistintosAInicial: " + e.getMessage());
	        return false;
	    }
	}
	/**
	 * Valida el tooltip de los botones de paginacion en tickets
	 *
	 * @param boton nombre del boton a validar: primero, anterior, siguiente, ultimo
	 * @param screenshot true o false para guardar evidencia
	 * @return true si el tooltip coincide con el aria-label del boton
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Agosto 2025
	 */
	public boolean validarTooltipBotonPaginacionTicket(String boton, boolean screenshot) {
		try {
	        WebDriver driver = u.getDriver();

	        // Elegir el botón según el nombre
	        By botonLocator;
	        switch (boton.toLowerCase()) {
	        case "primero":
	            botonLocator = xmlPaginaPrimeraPaginaButtonTicket;
	            break;
	        case "anterior":
	            botonLocator = xmlPaginaAnteriorButtonTicket;
	            break;
	        case "siguiente":
	            botonLocator = xmlPaginaSiguienteButtonTicket;
	            break;
	        case "ultimo":
	            botonLocator = xmlPaginaUltimaPaginaButtonTicket;
	            break;
	            default:
	                System.out.println("No existe ese botón de paginación: " + boton);
	                return false;
	        }

	        // Asegurar visibilidad del botón en viewport
	        u.waitWebElement(botonLocator, 30, 2);
	        u.scrollToElement(botonLocator);
	        WebElement botonWeb = driver.findElement(botonLocator);

	        if (!botonWeb.isDisplayed()) {
	            System.out.println("El botón '" + boton + "' no es visible");
	            return false;
	        }

	        // Tomar el texto esperado del aria-label del propio botón
	        String esperado = botonWeb.getAttribute("aria-label");
	        if (esperado == null) esperado = "";
	        esperado = esperado.trim();

	        // Hover para disparar el tooltip
	        u.highLight(botonLocator);
	        org.openqa.selenium.interactions.Actions actions = new org.openqa.selenium.interactions.Actions(driver);
	        actions.moveToElement(botonWeb).perform();
	        // pequeño nudge por si el hover necesita movimiento
	        actions.moveByOffset(1, 1).perform();

	        // Esperar a que aparezca el tooltip en el overlay (Angular Material MDC)
	        java.time.Duration timeout = java.time.Duration.ofSeconds(5);
	        org.openqa.selenium.support.ui.WebDriverWait wait = new org.openqa.selenium.support.ui.WebDriverWait(driver, timeout);

	        // Selectores posibles de tooltip
	        By tooltipSelector = By.cssSelector(
	            ".mat-mdc-tooltip .mat-mdc-tooltip-surface, " +     // Angular Material MDC
	            ".mat-mdc-tooltip .mdc-tooltip__surface, " +        // Variante MDC
	            ".mat-tooltip-panel .mat-tooltip"                    // Legacy
	        );

	        WebElement tooltipEl = wait.until(
	            org.openqa.selenium.support.ui.ExpectedConditions.visibilityOfElementLocated(tooltipSelector)
	        );

	        // Obtener el texto mostrado
	        String mostrado = tooltipEl.getText();
	        if (mostrado == null || mostrado.trim().isEmpty()) {
	            // Fallback: a veces el texto se refleja como aria-label/title del botón
	            String fallback = botonWeb.getAttribute("title");
	            if (fallback == null || fallback.trim().isEmpty()) {
	                mostrado = "";
	            } else {
	                mostrado = fallback.trim();
	            }
	        } else {
	            mostrado = mostrado.trim();
	        }

	        boolean coincide = !mostrado.isEmpty() && (esperado.isEmpty() ? true : mostrado.equals(esperado));

	        

	        if (!coincide) {
	            System.out.println("Tooltip no coincide. Mostrado='" + mostrado + "' Esperado='" + esperado + "'");
	            return false;
	        } else {
	            System.out.println("Tooltip OK. '" + mostrado + "'");
	        }
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Se visualiza el tool tip: '" + mostrado + "'");
	            testCase.addScreenShotCurrentStep(u, "Tooltip paginación");
	        }
	        u.unhighLight(botonLocator);
	        return coincide;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error en validarTooltipBotonPaginacion: " + e.getMessage());
	        System.out.println("Error en validarTooltipBotonPaginacion: " + e.getMessage());
	        return false;
	    }
	}
