	/**
	 * Verifica que todos los campos de entrada esten en blanco al ingresar
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si todos los campos estan vacios, false si alguno tiene valor
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public boolean VerificarCamposEnBlanco(boolean screenshot) throws Exception{
		try {
	        WebDriver driver = u.getDriver();

	        LinkedHashMap<String, By> botones = new LinkedHashMap<>();
	        botones.put("Proveedor",  xmlFiltroProveedor);
	        botones.put("Fuente de abasto", xmlFiltrofuenteDeAbasto);
	        botones.put("Zona",        xmlFiltrozona);
	        botones.put("Region",      xmlFiltroregion);
	        botones.put("Plaza",       xmlFiltroplaza);
	        botones.put("Tienda",      xmlFiltrotienda);
	        botones.put("Fecha",       xmlRangoFechaCampo);

	        List<String> errores = new ArrayList<>();

	        // 2) Validación uno por uno
	        for (Map.Entry<String, By> entry : botones.entrySet()) {
	            String nombre = entry.getKey();
	            By by = entry.getValue();

	            // Reencuentra el elemento siempre para evitar referencias obsoletas
	            List<WebElement> encontrados = driver.findElements(by);
	            if (encontrados.isEmpty()) {
	                String msg = "No se encontró el elemento '" + nombre + "'";
	                System.out.println(msg);
	                errores.add(msg);
	                if (screenshot) {
	                    testCase.addTextEvidenceCurrentStep("FALLO: " + msg);
	                    testCase.addScreenShotCurrentStep(u, "NoSeEncontro_" + nombre.replace(" ", "_"));
	                }
	                continue; // seguir con los demás campos
	            }

	            WebElement elem = encontrados.get(0);

	            // Resaltar el elemento antes de inspeccionar
	            try { u.highLight(by); } catch (Exception ignore) {}

	            boolean estaVacio = false;
	            String valorEncontrado = null;

	            String tag = elem.getTagName().toLowerCase(Locale.ROOT);

	            // 1) Caso común: input o textarea directamente
	            if ("input".equals(tag) || "textarea".equals(tag)) {
	                valorEncontrado = elem.getAttribute("value");
	                if (valorEncontrado == null || valorEncontrado.trim().isEmpty()) {
	                    estaVacio = true;
	                }
	            } else {
	                // 2) Casos compostos (ng-select, mat-date-range, o contenedores)
	                // Intentar encontrar un input interno (p.ej. ng-select tiene <input> dentro)
	                try {
	                    WebElement innerInput = elem.findElement(By.xpath(".//input"));
	                    if (innerInput != null) {
	                        valorEncontrado = innerInput.getAttribute("value");
	                        if (valorEncontrado == null || valorEncontrado.trim().isEmpty()) {
	                            // Para ng-select múltiples, a veces el placeholder sigue visible en un span
	                            // buscar .ng-placeholder dentro del element
	                            List<WebElement> placeholder = elem.findElements(By.cssSelector(".ng-placeholder"));
	                            if (!placeholder.isEmpty()) {
	                                String ph = placeholder.get(0).getText();
	                                // Si el placeholder contiene el nombre original del campo, lo consideramos vacío
	                                if (ph != null && !ph.trim().isEmpty()) {
	                                    estaVacio = true;
	                                }
	                            } else {
	                                // input vacío + sin placeholder -> considerarlo vacío
	                                estaVacio = true;
	                            }
	                        }
	                    }
	                } catch (Exception e) {
	                    // no hay input interno o falla, seguimos con otras comprobaciones
	                }

	                // 3) Si sigue sin decidirse, comprobar si es un mat-date-range-input (dos inputs)
	                if (!estaVacio && valorEncontrado == null) {
	                    List<WebElement> startInputs = elem.findElements(By.cssSelector("input.mat-start-date, input[matstartdate]"));
	                    List<WebElement> endInputs = elem.findElements(By.cssSelector("input.mat-end-date, input[matenddate]"));

	                    if (!startInputs.isEmpty() || !endInputs.isEmpty()) {
	                        String vStart = "";
	                        String vEnd = "";
	                        try {
	                            if (!startInputs.isEmpty()) vStart = startInputs.get(0).getAttribute("value");
	                        } catch (Exception ignore) {}
	                        try {
	                            if (!endInputs.isEmpty()) vEnd = endInputs.get(0).getAttribute("value");
	                        } catch (Exception ignore) {}

	                        vStart = (vStart == null) ? "" : vStart.trim();
	                        vEnd = (vEnd == null) ? "" : vEnd.trim();

	                        if (vStart.isEmpty() && vEnd.isEmpty()) {
	                            estaVacio = true;
	                        } else {
	                            valorEncontrado = "start='" + vStart + "' end='" + vEnd + "'";
	                        }
	                    }
	                }
	                
	                if (!estaVacio && valorEncontrado == null) {
	                    try {
	                        String texto = elem.getText();
	                        if (texto == null || texto.trim().isEmpty()) {
	                            estaVacio = true;
	                        } else {
	                            valorEncontrado = texto.trim();
	                        }
	                    } catch (Exception ignore) {	                        
	                        valorEncontrado = "[no se pudo leer texto]";
	                    }
	                }
	            }

	            // Registrar resultado por campo
	            if (estaVacio) {
	                testCase.addTextEvidenceCurrentStep("OK vacío: '" + nombre + "'");
	            } else {
	                String msg = "FALLO: '" + nombre + "' tiene valor: " + (valorEncontrado == null ? "[no detectado]" : valorEncontrado);
	                System.out.println(msg);
	                errores.add(msg);
	                testCase.addTextEvidenceCurrentStep(msg);
	            }

	            // screenshot y des-resaltar por elemento
	            if (screenshot) {
	                testCase.addScreenShotCurrentStep(u, "Verificar_" + nombre.replace(" ", "_"));
	            }
	            try { u.unhighLight(by); } catch (Exception ignore) {}
	        }

	        // Resultado final
	        if (errores.isEmpty()) {
	            return true;
	        } else {
	            // agregar resumen de errores al testCase
	            StringBuilder sb = new StringBuilder();
	            sb.append("Campos no vacíos detectados:\n");
	            for (String e : errores) sb.append(" - ").append(e).append("\n");
	            testCase.addTextEvidenceCurrentStep(sb.toString());
	            if (screenshot) testCase.addScreenShotCurrentStep(u, "Validados_Fallo");
	            return false;
	        }

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
	/**
	 * Valida que los valores en PDF tengan simbolo de pesos con dos decimales
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si todos los valores tienen $ y dos decimales
	 * @throws Exception cuando ocurre un error leyendo el PDF
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public boolean validarFormatoPesosDecimalesEnPDF(boolean screenshot) {
	    // Toma el último archivo en Downloads
	    String home = System.getProperty("user.home") + "\\Downloads";
	    File file = new File(getLastModified(home).getAbsolutePath());
	    if (!file.exists()) {
	        testCase.addTextEvidenceCurrentStep("No se encontró archivo PDF en Downloads.");
	        return false;
	    }

	    PDDocument doc = null;
	    try {
	    	doc = Loader.loadPDF(file);
	        PDFTextStripper stripper = new PDFTextStripper();
	        String text = stripper.getText(doc);
	        if (text == null || text.trim().isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("No se pudo extraer texto del PDF.");
	            return false;
	        }

	        // Regex para valores con $ y 2 decimales
	        Pattern moneyPattern = Pattern.compile("\\$\\s*[0-9]{1,3}(?:[.,][0-9]{3})*(?:[.,][0-9]{2})");
	        // Regex para números con exactamente 2 decimales (ej: 72.00 o 1.029,00)
	        Pattern twoDecimalsPattern = Pattern.compile("\\b[0-9]+(?:[.,][0-9]{2})\\b");

	        Matcher mMoney = moneyPattern.matcher(text);
	        List<String> monedasEncontradas = new ArrayList<>();
	        while (mMoney.find()) {
	            monedasEncontradas.add(mMoney.group().replace('\u00A0', ' ').replaceAll("\\s+", " ").trim());
	        }

	        // Buscar tokens con 2 decimales y verificar si NO están precedidos por $
	        Matcher mTwo = twoDecimalsPattern.matcher(text);
	        List<String> decimalesSinDollar = new ArrayList<>();
	        while (mTwo.find()) {
	            String token = mTwo.group(); // e.g. "72.00" o "0.00"
	            int start = mTwo.start();
	            int end = mTwo.end();

	            // Ignorar si seguido por % (por ejemplo "0.00%")
	            boolean seguidoPorPorcentaje = (end < text.length() && text.charAt(end) == '%');
	            if (seguidoPorPorcentaje) continue;

	            // Mirar hasta 4 caracteres antes para ver si hay un $ (o espacio + $)
	            int lookBehindStart = Math.max(0, start - 6);
	            String before = text.substring(lookBehindStart, start);

	            // Si antes hay un $ en los últimos 6 caracteres, sí tiene $
	            if (before.contains("$")) {
	                continue; // está asociado a un signo de pesos
	            }

	            // Además, si el token coincide con alguno ya capturado por moneyPattern
	            boolean insideMoney = false;
	            for (String m : monedasEncontradas) {
	                // clean
	                String clean = m.replaceAll("[^0-9.,]", "");
	                String cleanToken = token.replaceAll("[^0-9.,]", "");
	                if (clean.contains(cleanToken)) {
	                    insideMoney = true;
	                    break;
	                }
	            }
	            if (!insideMoney) {
	                decimalesSinDollar.add(token + " (pos " + start + ")");
	            }
	        }

	        // Preparar reporte / evidencia
	        StringBuilder reporte = new StringBuilder();
	        reporte.append(String.format(Locale.ROOT, "Archivo PDF: %s%n", file.getName()));
	        reporte.append("Monedas detectadas (con $):\n");
	        if (monedasEncontradas.isEmpty()) {
	            reporte.append("  Ninguna encontrada.\n");
	        } else {
	            for (String s : monedasEncontradas) reporte.append("  ").append(s).append("\n");
	        }

	        testCase.addTextEvidenceCurrentStep(reporte.toString());
	        if (screenshot) testCase.addScreenShotCurrentStep("PDF_FormatoPesos");

	        // Resultado: true si no hay decimales sin $, false si existen problemas
	        if (decimalesSinDollar.isEmpty()) {
	            return true;
	        } else {
	            return false;
	        }

	    } catch (IOException e) {
	        e.printStackTrace();
	        testCase.addTextEvidenceCurrentStep("Error leyendo PDF: " + e.getMessage());
	        return false;
	    } finally {
	        try { if (doc != null) doc.close(); } catch (IOException ignore) {}
	    }
	}	
	/**
	 * Valida que el ultimo archivo en Downloads tenga el formato OC_Folio_Fecha.pdf
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si el nombre coincide con el formato esperado
	 * @throws Exception cuando ocurre un error en la validacion
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public Boolean validarNombreDescargadoPDF(boolean screenshot) {
		 final String xpathFolio = "/html/body/app-root/app-directos-devoluciones/div/directos-devoluciones-grid/div/table/tbody/tr[1]/td[8]";
		    final String xpathFecha = "/html/body/app-root/app-directos-devoluciones/div/directos-devoluciones-grid/div/table/tbody/tr[1]/td[7]";

		    try {
		        WebDriver driver = u.getDriver();
		        u.waitWebElement(By.xpath(xpathFolio), 60, 5);
		        u.waitWebElement(By.xpath(xpathFecha), 60, 5);

		        // 1) Tomar folio y fecha del grid
		        String folioTxt = driver.findElement(By.xpath(xpathFolio)).getText().trim();
		        String fechaTxt = driver.findElement(By.xpath(xpathFecha)).getText().trim(); // yyyy-MM-dd esperado
		        String folio = folioTxt.replaceAll("[^0-9]", "");
		        LocalDate fecha = LocalDate.parse(fechaTxt);

		        // 2) Construir dd_MM_yyyy
		        String fecha_dd_MM_yyyy = String.format(Locale.ROOT, "%02d_%02d_%04d",
		                fecha.getDayOfMonth(), fecha.getMonthValue(), fecha.getYear());

		        String baseEsperada = "OC_" + folio + "_" + fecha_dd_MM_yyyy;

		        // 3) Último archivo en Downloads
		        String home = System.getProperty("user.home") + "\\Downloads";
		        File archivo = new File(getLastModified(home).getAbsolutePath());
		        if (!archivo.exists()) {
		            testCase.addTextEvidenceCurrentStep("No se encontró archivo en Downloads.");
		            return false;
		        }

		        String nombre = archivo.getName();

		        // 4) Regex: permite sufijo opcional " (n)" antes de la extensión
		        String regex = "^" + Pattern.quote(baseEsperada) + "(?: \\(\\d+\\))?\\.(pdf)$";

		        if (nombre.matches(regex)) {
		            String ok = "Nombre correcto: " + nombre;
		            System.out.println(ok);
		            testCase.addTextEvidenceCurrentStep(ok);
		            if (screenshot) testCase.addScreenShotCurrentStep("NombreExcel_OK");



		            return true;
		        } else {
		            String diff =
		                "Nombre de archivo NO coincide.\n" +
		                "  Encontrado: " + nombre + "\n" +
		                "  Esperado (regex): " + baseEsperada + "( opcional ' (n)')" + ".pdf|.pdf";
		            System.out.println(diff);
		            testCase.addTextEvidenceCurrentStep(diff);
		            if (screenshot) testCase.addScreenShotCurrentStep("NombreExcel_DIF");
		            return false;
		        }


	    } catch (Exception e) {
	        e.printStackTrace();
	        testCase.addTextEvidenceCurrentStep("Error al validar nombre de Excel: " + e.getMessage());
	        return false;
	    }
	}
