	/**
	 * Valida que las columnas de precios en Excel tengan simbolo de pesos con dos decimales
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si todas las celdas cumplen el formato, false si hay inconsistencias
	 * @throws Exception cuando ocurre un error leyendo el archivo Excel
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public Boolean validarSimboloPesos(boolean screenshot) {
		// Columnas que queremos validar
	    final String[] colNamesToCheck = new String[] {
	    		"Precio",	 	       
	 	        "Val. Total",	 	       
	 	        "Valor Total",
	 	        "Total Costo"
	    };

	    String home = System.getProperty("user.home") + "\\Downloads";
	    File file = new File(getLastModified(home).getAbsolutePath());
	    if (!file.exists()) {
	        testCase.addTextEvidenceCurrentStep("No se encontró archivo en Downloads.");
	        return false;
	    }

	    FileInputStream fis = null;
	    Workbook wb = null;
	    boolean todoOk = true;
	    StringBuilder difs = new StringBuilder();
	    StringBuilder foundValues = new StringBuilder();

	    try {
	        fis = new FileInputStream(file);
	        wb = WorkbookFactory.create(fis);

	        if (wb.getNumberOfSheets() == 0) {
	            testCase.addTextEvidenceCurrentStep("El archivo no contiene hojas.");
	            return false;
	        }

	        Sheet sheet = wb.getSheetAt(0);
	        Row header = sheet.getRow(0);
	        if (header == null) {
	            testCase.addTextEvidenceCurrentStep("La fila de encabezados está vacía.");
	            return false;
	        }

	        // Encontrar índices de las columnas a validar
	        List<Integer> indices = new ArrayList<>();
	        DataFormatter fmt = new DataFormatter(Locale.ROOT);
	        for (String colName : colNamesToCheck) {
	            int idx = -1;
	            for (int i = 0; i < header.getLastCellNum(); i++) {
	                Cell hc = header.getCell(i);
	                String htext = (hc == null) ? "" : fmt.formatCellValue(hc).trim();
	                if (htext.equalsIgnoreCase(colName)) {
	                    idx = i;
	                    break;
	                }
	            }
	            if (idx == -1) {
	                testCase.addTextEvidenceCurrentStep("No se encontró la columna esperada: " + colName);
	            } else {
	                indices.add(idx);
	            }
	        }

	        if (indices.isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("No se encontraron columnas a validar en el encabezado.");
	            return false;
	        }

	        // Regex: permite varios espacios (incluye NBSP reemplazado), exige $ y 2 decimales
	        Pattern p = Pattern.compile("^\\s*\\$\\s*[0-9]{1,3}(?:[.,][0-9]{3})*(?:[.,][0-9]{2})\\s*$");

	        // Recorrer filas y validar celdas en las columnas seleccionadas
	        for (int r = 1; r <= sheet.getLastRowNum(); r++) {
	            Row row = sheet.getRow(r);
	            if (row == null) continue;
	            for (int colIndex : indices) {
	                Cell cell = row.getCell(colIndex);
	                if (cell == null) continue;
	                String visibleRaw = fmt.formatCellValue(cell);
	                if (visibleRaw == null) continue;

	                // Normalizar espacios y NBSP
	                String visible = visibleRaw.replace('\u00A0', ' ');
	                visible = visible.replaceAll("\\s+", " ").trim();

	                if (visible.isEmpty()) continue; // ignorar vacías

	                // Agregar a la lista de valores encontrados (fila, columna, valor)
	                String headerName = fmt.formatCellValue(header.getCell(colIndex)).trim();
	                foundValues.append(String.format(Locale.ROOT, "Fila %d, Col '%s' (idx %d): «%s\"%n",
	                        r+1, headerName, colIndex, visible));

	                Matcher m = p.matcher(visible);
	                if (!m.matches()) {
	                    todoOk = false;
	                    difs.append(String.format(Locale.ROOT,
	                        "Fila %d, Col '%s' (idx %d): valor visible «%s» no respeta formato $ y 2 decimales.%n",
	                        r+1, headerName, colIndex, visible));
	                }
	            }
	        }

	        if (todoOk) {
	            if (screenshot) testCase.addScreenShotCurrentStep("FormatoPesos_OK");
	            String ok = "Se visualiza en el formato del Excel signos de pesos y decimales";
	            testCase.addTextEvidenceCurrentStep(ok);
	            // Mostrar todos los valores encontrados
	            String todos = foundValues.length() == 0 ? ""
	                                                    : "Valores encontrados:\n" + foundValues.toString();
	            testCase.addTextEvidenceCurrentStep(todos);

	            return true;
	        } else {
	            testCase.addTextEvidenceCurrentStep("Diferencias encontradas en formato de pesos/decimales:\n" + difs.toString());	            
	            if (foundValues.length() > 0) {
	                testCase.addTextEvidenceCurrentStep("Valores encontrados (para análisis):\n" + foundValues.toString());
	            }
	            if (screenshot) testCase.addScreenShotCurrentStep("FormatoPesos_DIF");
	            System.out.println(difs.toString());
	            return false;
	        }

	    } catch (Exception e) {
	        e.printStackTrace();
	        testCase.addTextEvidenceCurrentStep("Error validando formato de pesos: " + e.getMessage());
	        return false;
	    } finally {
	        try { if (wb != null) wb.close(); } catch (Exception ignore) {}
	        try { if (fis != null) fis.close(); } catch (Exception ignore) {}
	    }
	}
	/**
	 * Valida la busqueda con filtro de fecha en Directos-Devoluciones de hace 3 años
	 *
	 * @param usuario usuario a consultar en BD
	 * @param screenshot true o false para guardar evidencia
	 * @return true si la busqueda y seleccion de fecha se realiza correctamente
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public boolean busquedaFiltroFechaDevoluciones3Anios(String usuario, boolean screenshot) throws Exception {
	    try {
	        boolean result = true;

	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	        String dbUser = GlobalVariables.DB_USER_Cometa;
	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	        String PCPERFIL = "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' " +
	                "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

	        // Tomar un ID existente de historico correos para el origen correcto
	        // (xxcm_dv puede estar vacío antes de sincronizar)
	        String SelectId =
	                "select id " +
	                "from xxcm_historico_correos " +
	                "where origen = 'directos-devolucion' " +
	                "order by id desc " +
	                "limit 1";

	        LocalDate fechaConvert;

	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	             Statement stmt = connection.createStatement();
	             ResultSet rs = stmt.executeQuery(PCPERFIL)) {

	            if (!rs.next()) {
	                System.out.println("No se obtuvo perfil para el usuario.");
	                return false;
	            }

	            String keyValue = rs.getString("key_value");
	            System.out.println("Usuario con perfil: " + keyValue);

	            ResultSet rsId = stmt.executeQuery(SelectId);
	            if (!rsId.next()) {
	                System.out.println("No se obtuvo ID en xxcm_historico_correos para origen directos-devolucion.");
	                return false;
	            }

	            String ID = rsId.getString("id");

	            // 1) UPDATE: mañana pero hace 3 años (Fecha_Encabezado en body) + timestamps
	            String UpdateFechaID =
	                    "UPDATE xxcm_historico_correos " +
	                    "SET body = jsonb_set( " +
	                    "        body, '{Fecha_Encabezado}', " +
	                    "        to_jsonb((now() - INTERVAL '3 years' + INTERVAL '1 day')::date) " +
	                    "    ), " +
	                    "    created_at = (now() - INTERVAL '3 years' + INTERVAL '1 day')::timestamp(3), " +
	                    "    fecha_registro = (now() - INTERVAL '3 years' + INTERVAL '1 day')::timestamp(3) " +
	                    "WHERE id IN (" + ID + ") " +
	                    "  AND origen = 'directos-devolucion';";

	            int updated = stmt.executeUpdate(UpdateFechaID);
	            if (updated <= 0) {
	                System.out.println("No se actualizó ningún registro en xxcm_historico_correos. ID=" + ID);
	                return false;
	            }

	            // 2) Proyección: truncar y sincronizar
	            stmt.execute("TRUNCATE public.xxcm_dv CASCADE;");
	            stmt.execute("CALL public.sincronizar_datos_devoluciones();");

	            // 3) Leer la fecha ya proyectada desde xxcm_dv
	            // Nota: en xxcm_dv la columna se llama "fecha" (según tu lista)
	            String SelectFechaDv = "select fecha from public.xxcm_dv where id = " + ID;

	            try (ResultSet rsFecha = stmt.executeQuery(SelectFechaDv)) {
	                if (!rsFecha.next()) {
	                    // Si no existe el id en dv, puede ser que la sincronización genere ids distintos
	                    // o que dv no use el mismo id. En ese caso, mejor leer la fecha más reciente de dv.
	                    String fallback = "select fecha from public.xxcm_dv order by fecha desc limit 1";
	                    try (ResultSet rsFallback = stmt.executeQuery(fallback)) {
	                        if (!rsFallback.next()) {
	                            System.out.println("No se pudo obtener fecha en public.xxcm_dv (ni por id ni fallback).");
	                            return false;
	                        }
	                        java.sql.Date f = rsFallback.getDate("fecha");
	                        fechaConvert = f.toLocalDate();
	                        System.out.println("Fecha tomada de public.xxcm_dv (fallback): " + fechaConvert);
	                    }
	                } else {
	                    java.sql.Date f = rsFecha.getDate("fecha");
	                    fechaConvert = f.toLocalDate();
	                    System.out.println("Fecha tomada de public.xxcm_dv por id: " + fechaConvert);
	                }
	            }
	        }

	        // 4) UI datepicker
	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
	        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

	        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
	        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

	        By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
	        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

	        if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	        }

	        clickYear(driver, wait, fechaConvert.getYear());

	        // Si tu clickMonthByIndex es 0-based, cambia a (fechaConvert.getMonthValue() - 1)
	        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

	        clickDay(driver, wait, fechaConvert.getDayOfMonth());
	        clickDay(driver, wait, fechaConvert.getDayOfMonth());

	        // Cierre robusto
	        try { driver.findElement(By.tagName("body")).click(); } catch (Exception ignore) { }
	        try {
	            new org.openqa.selenium.interactions.Actions(driver)
	                    .sendKeys(org.openqa.selenium.Keys.ESCAPE)
	                    .perform();
	        } catch (Exception ignore) { }

	        WebDriverWait waitClose = new WebDriverWait(driver, Duration.ofSeconds(20));
	        waitClose.until(d -> {
	            java.util.List<WebElement> els = d.findElements(dpContent);
	            if (els.isEmpty()) return true;
	            try { return !els.get(0).isDisplayed(); }
	            catch (org.openqa.selenium.StaleElementReferenceException ex) { return true; }
	        });

	        consultarComprobantes(true);
	        return result;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}

	/**
	 * Valida la busqueda con filtro de fecha en CEDIS-Recepcion utilizando la fecha_registro
	 * del registro mas reciente disponible en BD.
	 *
	 * @param usuario usuario a consultar en BD
	 * @param screenshot true o false para guardar evidencia
	 * @return true si se obtiene informacion de fecha correctamente
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	public boolean busquedaFiltroFechaCedis5(String usuario, boolean screenshot) throws Exception {
	    try {
	        boolean result = true;
	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	        String dbUser = GlobalVariables.DB_USER_Cometa;
	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	        String queryPerfil =
	            "select key_value " +
	            "from xxcm_user_keys " +
	            "where short_name = 'PCPERFIL' " +
	            "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = ?) " +
	            "limit 1";

	        String querySupplierId =
	            "select key_value " +
	            "from xxcm_user_keys " +
	            "where short_name = 'PCSUPPLIERID' " +
	            "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = ?) " +
	            "limit 1";

	        String queryFechaAdmin =
	            "select fecha_registro " +
	            "from xxcm_historico_cedis_view " +
	            "where fecha_registro is not null " +
	            "order by fecha_registro desc " +
	            "limit 1";

	        String queryFechaCedis =
	            "select fecha_registro " +
	            "from xxcm_historico_cedis_view " +
	            "where supplier_id = ? " +
	            "and fecha_registro is not null " +
	            "order by fecha_registro desc " +
	            "limit 1";

	        LocalDate fechaConvert = null;
	        String perfil = null;
	        Long supplierId = null;

	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword)) {

	            try (PreparedStatement psPerfil = connection.prepareStatement(queryPerfil)) {
	                psPerfil.setString(1, usuario);
	                try (ResultSet rs = psPerfil.executeQuery()) {
	                    if (rs.next()) {
	                        perfil = rs.getString("key_value");
	                    }
	                }
	            }

	            if (perfil == null || perfil.trim().isEmpty()) {
	                perfil = "CEDIS";
	            }

	            if (screenshot) {
	                testCase.addBoldTextEvidenceCurrentStep("Usuario con perfil: " + perfil);
	            }
	            System.out.println("Usuario con perfil: " + perfil);

	            boolean esAdmin =
	                "ADMIN".equalsIgnoreCase(perfil) ||
	                "OXXO_OS".equalsIgnoreCase(perfil);

	            if (esAdmin) {
	                try (PreparedStatement psFecha = connection.prepareStatement(queryFechaAdmin);
	                     ResultSet rsFecha = psFecha.executeQuery()) {

	                    if (rsFecha.next()) {
	                        Timestamp ts = rsFecha.getTimestamp("fecha_registro");
	                        fechaConvert = ts.toLocalDateTime().toLocalDate();

	                        if (screenshot) {
	                            testCase.addBoldTextEvidenceCurrentStep(
	                                "Fecha obtenida de xxcm_historico_cedis_view: " + fechaConvert
	                            );
	                        }
	                        System.out.println("Fecha obtenida de xxcm_historico_cedis_view: " + fechaConvert);
	                    } else {
	                        result = false;
	                        System.out.println("No se obtuvo informacion de fecha_registro.");
	                        return result;
	                    }
	                }
	            } else {
	                try (PreparedStatement psSupplier = connection.prepareStatement(querySupplierId)) {
	                    psSupplier.setString(1, usuario);
	                    try (ResultSet rsSupplier = psSupplier.executeQuery()) {
	                        if (rsSupplier.next()) {
	                            String supplierIdStr = rsSupplier.getString("key_value");
	                            if (supplierIdStr != null && !supplierIdStr.trim().isEmpty()) {
	                                supplierId = Long.valueOf(supplierIdStr.trim());
	                            }
	                        }
	                    }
	                }

	                if (supplierId == null) {
	                    result = false;
	                    System.out.println("No se obtuvo SupplierId para el usuario.");
	                    return result;
	                }

	                try (PreparedStatement psFecha = connection.prepareStatement(queryFechaCedis)) {
	                    psFecha.setLong(1, supplierId);
	                    try (ResultSet rsFecha = psFecha.executeQuery()) {
	                        if (rsFecha.next()) {
	                            Timestamp ts = rsFecha.getTimestamp("fecha_registro");
	                            fechaConvert = ts.toLocalDateTime().toLocalDate();

	                            if (screenshot) {
	                                testCase.addBoldTextEvidenceCurrentStep(
	                                    "Fecha obtenida de xxcm_historico_cedis_view para supplier_id " + supplierId + ": " + fechaConvert
	                                );
	                            }
	                            System.out.println("Fecha obtenida de xxcm_historico_cedis_view para supplier_id " + supplierId + ": " + fechaConvert);
	                        } else {
	                            result = false;
	                            System.out.println("No se obtuvo informacion de fecha_registro para el supplier_id.");
	                            return result;
	                        }
	                    }
	                }
	            }
	        }

	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
	        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

	        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
	        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

	        By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
	        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

	        if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	        }

	        clickYear(driver, wait, fechaConvert.getYear());
	        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

	        clickDay(driver, wait, fechaConvert.minusDays(1).getDayOfMonth());
	        clickDay(driver, wait, fechaConvert.getDayOfMonth());

	        wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));

	        consultarComprobantes(screenshot);

	        return result;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
	/**
	 * Valida que la fecha en PDF coincida con la seleccion en el grid de Devoluciones Directos
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si la fecha del PDF coincide con la del grid
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public boolean validarFechaCoincideConSeleccion(boolean screenshot){
	    try {
	        if (ultimaDevolucionSeleccionada == null ||
	            ultimaDevolucionSeleccionada.fecha == null ||
	            ultimaDevolucionSeleccionada.fecha.trim().isEmpty()) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No hay fecha previo del grid.");
	            return false;
	        }

	        String texto = capturarTextoPDFVisible();
	        if (texto == null) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se pudo leer texto del PDF en pantalla.");
	            return false;
	        }

	        String FechaPDF = lineaValor(texto, "Fecha");
	        if (FechaPDF == null || FechaPDF.trim().isEmpty()) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se encontró 'Fecha' en el PDF.");
	            return false;
	        }

	        String fechaPdfNorm = FechaPDF.trim();

	        int idxHora = fechaPdfNorm.toLowerCase(Locale.ROOT).indexOf("hora");
	        if (idxHora != -1) {
	            fechaPdfNorm = fechaPdfNorm.substring(0, idxHora).trim();
	        }

	        if (fechaPdfNorm.toLowerCase(Locale.ROOT).startsWith("fecha")) {
	            int idxDosPuntos = fechaPdfNorm.indexOf(':');
	            if (idxDosPuntos != -1) {
	                fechaPdfNorm = fechaPdfNorm.substring(idxDosPuntos + 1).trim();
	            }
	        }

	        LocalDate fechaPdfDate = null;
	        Matcher mIso = Pattern.compile("\\b(\\d{4}-\\d{2}-\\d{2})\\b").matcher(fechaPdfNorm);
	        if (mIso.find()) {
	            fechaPdfDate = LocalDate.parse(mIso.group(1), DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	        } else {
	            Matcher mAlt = Pattern.compile("\\b(\\d{2})[/-](\\d{2})[/-](\\d{4})\\b").matcher(fechaPdfNorm);
	            if (mAlt.find()) {
	                String dd = mAlt.group(1);
	                String MM = mAlt.group(2);
	                String yyyy = mAlt.group(3);
	                fechaPdfDate = LocalDate.parse(yyyy + "-" + MM + "-" + dd, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	            } else {
	                if (screenshot) {
	                    testCase.addTextEvidenceCurrentStep("No se pudo parsear fecha del PDF. Valor leído: " + FechaPDF);
	                }
	                return false;
	            }
	        }

	        String fechaGrid = ultimaDevolucionSeleccionada.fecha.trim();
	        LocalDate fechaGridDate = null;

	        try {
	            fechaGridDate = LocalDate.parse(fechaGrid, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	        } catch (Exception e1) {
	            try {
	                fechaGridDate = LocalDate.parse(fechaGrid, DateTimeFormatter.ofPattern("dd-MM-yyyy"));
	            } catch (Exception e2) {
	                try {
	                    fechaGridDate = LocalDate.parse(fechaGrid, DateTimeFormatter.ofPattern("dd/MM/yyyy"));
	                } catch (Exception e3) {
	                    if (screenshot) {
	                        testCase.addTextEvidenceCurrentStep("No se pudo parsear fecha del grid: " + fechaGrid);
	                    }
	                    return false;
	                }
	            }
	        }

	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep(
	                "Fecha PDF original: " + FechaPDF +
	                " | Fecha PDF normalizada: " + fechaPdfDate +
	                " | Fecha Grid original: " + fechaGrid +
	                " | Fecha Grid normalizada: " + fechaGridDate
	            );
	            testCase.addScreenShotCurrentStep(u, "PDFVisorDevol");
	        }

	        return fechaPdfDate.equals(fechaGridDate);

	    } catch (Exception e) {
	        testCase.addTextEvidenceCurrentStep("Error en validarFechaCoincideConSeleccion: " + e.getMessage());
	        return false;
	    }
	}
	/**
	 * Valida que el ultimo archivo en Downloads tenga el formato OC_Folio_Fecha con extension correcta
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si el nombre del archivo coincide con el formato esperado
	 * @throws Exception cuando ocurre un error en la validacion
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public Boolean validarNombreDescargado(boolean screenshot) {
	    final String xpathFolio = "/html/body/app-root/app-directos-devoluciones/div/directos-devoluciones-grid/div/table/tbody/tr[1]/td[8]";
	    final String xpathFecha = "/html/body/app-root/app-directos-devoluciones/div/directos-devoluciones-grid/div/table/tbody/tr[1]/td[7]";

	    try {
	        WebDriver driver = u.getDriver();
	        u.waitWebElement(By.xpath(xpathFolio), 60, 5);
	        u.waitWebElement(By.xpath(xpathFecha), 60, 5);

	        String folioTxt = driver.findElement(By.xpath(xpathFolio)).getText().trim();
	        String fechaTxt = driver.findElement(By.xpath(xpathFecha)).getText().trim();

	        String folio = folioTxt.replaceAll("[^0-9]", "");
	        LocalDate fecha = null;

	        DateTimeFormatter formatterDDMMYYYY = DateTimeFormatter.ofPattern("dd-MM-yyyy");
	        DateTimeFormatter formatterYYYYMMDD = DateTimeFormatter.ofPattern("yyyy-MM-dd");

	        try {
	            fecha = LocalDate.parse(fechaTxt, formatterDDMMYYYY);
	        } catch (Exception ex1) {
	            try {
	                fecha = LocalDate.parse(fechaTxt, formatterYYYYMMDD);
	            } catch (Exception ex2) {
	                throw new Exception("Formato de fecha no valido en grid: " + fechaTxt);
	            }
	        }

	        String fecha_dd_MM_yyyy = String.format(
	            Locale.ROOT,
	            "%02d_%02d_%04d",
	            fecha.getDayOfMonth(),
	            fecha.getMonthValue(),
	            fecha.getYear()
	        );

	        String baseEsperada = "OC_" + folio + "_" + fecha_dd_MM_yyyy;

	        String home = System.getProperty("user.home") + "\\Downloads";
	        File ultimoArchivo = getLastModified(home);

	        if (ultimoArchivo == null) {
	            testCase.addTextEvidenceCurrentStep("No se encontró archivo en Downloads.");
	            return false;
	        }

	        File archivo = new File(ultimoArchivo.getAbsolutePath());

	        if (!archivo.exists()) {
	            testCase.addTextEvidenceCurrentStep("No se encontró archivo en Downloads.");
	            return false;
	        }

	        String nombre = archivo.getName();

	        String regex = "^" + Pattern.quote(baseEsperada) + "(?: \\(\\d+\\))?\\.(xlsx|xls|pdf)$";

	        if (nombre.matches(regex)) {
	            String ok = "Nombre correcto: " + nombre;
	            System.out.println(ok);
	            testCase.addTextEvidenceCurrentStep(ok);
	            if (screenshot) {
	                testCase.addScreenShotCurrentStep("NombreArchivo_OK");
	            }
	            return true;
	        } else {
	            String diff =
	                "Nombre de archivo NO coincide.\n" +
	                "Encontrado: " + nombre + "\n" +
	                "Esperado (regex): " + baseEsperada + "( opcional ' (n)').xlsx|.xls|.pdf";
	            System.out.println(diff);
	            testCase.addTextEvidenceCurrentStep(diff);
	            if (screenshot) {
	                testCase.addScreenShotCurrentStep("Nombre_DIF");
	            }
	            return false;
	        }

	    } catch (Exception e) {
	        e.printStackTrace();
	        testCase.addTextEvidenceCurrentStep("Error al validar nombre del archivo: " + e.getMessage());
	        return false;
	    }
	}
	/**
	 * Valida que los encabezados del archivo Excel existan y esten en el orden esperado
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si todos los encabezados coinciden con los esperados
	 * @throws Exception cuando ocurre un error leyendo el archivo Excel
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public Boolean validarEncabezadosExcel(boolean screenshot) {
		final String[] esperados = new String[] {
			    "Fuente de Abasto",
			    "Nombre del Proveedor",
			    "Región",
			    "Plaza",
			    "Retek",
			    "CR Tienda",
			    "Nombre de Tienda",
			    "Fecha",
			    "Hora",
			    "FECHA ADMVA",
			    "Folio",
			    "Tiempo de devolución",
			    "Origen",
			    "CVE Artículo",
			    "Descripción",
			    "Precio",
			    "Cantidad a devolver",
			    "Val. Total",
			    "Total de tasa fiscal",			  
			};

	    String home = System.getProperty("user.home") + "\\Downloads";
	    File file = new File(getLastModified(home).getAbsolutePath()); 

	    if (!file.exists()) {
	        testCase.addTextEvidenceCurrentStep("No se encontró archivo en Downloads.");
	        System.out.println("Archivo no encontrado.");
	        return false;
	    }

	    FileInputStream fis = null;
	    Workbook workbook = null;

	    try {
	        fis = new FileInputStream(file);
	        workbook = WorkbookFactory.create(fis);

	        if (workbook.getNumberOfSheets() == 0) {
	            testCase.addTextEvidenceCurrentStep("El archivo no contiene hojas.");
	            return false;
	        }

	        Sheet sheet = workbook.getSheetAt(0);
	        Row headerRow = sheet.getRow(0);

	        if (headerRow == null) {
	            testCase.addTextEvidenceCurrentStep("La fila de encabezados (fila 1) está vacía.");
	            return false;
	        }

	       
	        int colsEnArchivo = headerRow.getLastCellNum(); 
	        if (colsEnArchivo < esperados.length) {
	            testCase.addTextEvidenceCurrentStep(
	                "Columnas insuficientes. Esperadas: " + esperados.length + ", encontradas: " + colsEnArchivo
	            );
	            return false;
	        }

	        boolean todoOk = true;
	        StringBuilder diferencias = new StringBuilder();

	     
	        DataFormatter fmt = new DataFormatter(Locale.ROOT);

	        for (int i = 0; i < esperados.length; i++) {
	            Cell c = headerRow.getCell(i);
	            String valor = (c == null) ? "" : fmt.formatCellValue(c).trim();
	            String esperado = esperados[i].trim();

	            if (!valor.equals(esperado)) {
	                todoOk = false;
	                diferencias.append("Columna ").append(i + 1)
	                           .append(": esperado «").append(esperado)
	                           .append("» pero se encontró «").append(valor).append("»\n");
	            }
	        }

	        if (todoOk) {
	            String okMsg = "Encabezados correctos y en el orden esperado: " + file.getName();
	            System.out.println(okMsg);
	            if (screenshot) {
	            	Desktop desktop = Desktop.getDesktop();
	            	u.hardWait(2);
                	desktop.open(file);
                    u.hardWait(10);                
	                testCase.addTextEvidenceCurrentStep(okMsg);
	                testCase.addScreenShotCurrentStep("Encabezados_OK");
	                Runtime.getRuntime().exec("cmd /c taskkill /f /im excel.exe");
	            }
	            return true;
	        } else {
	            String diffMsg = "Diferencias en encabezados del archivo: " + file.getName() + "\n" + diferencias;
	            System.out.println(diffMsg);
	            testCase.addTextEvidenceCurrentStep(diffMsg);
	            if (screenshot) {
	                testCase.addScreenShotCurrentStep("Encabezados_DIF");
	            }
	            return false;
	        }

	    } catch (Exception e) {
	        e.printStackTrace();
	        testCase.addTextEvidenceCurrentStep("Error leyendo el archivo: " + e.getMessage());
	        return false;
	    } finally {
	        try { if (fis != null) fis.close(); } catch (Exception ex) {}
	        try { if (workbook != null) workbook.close(); } catch (Exception ex) {}
	    }
	}

	/**
	 * Valida que el mensaje "Espere un momento" ya haya desaparecido en tickets de Devoluciones
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si el mensaje ya no se visualiza
	 * @throws Exception cuando ocurre un error en la validacion
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public boolean MensajeEspereDesaparece(boolean screenshot) throws Exception{
		try {
		boolean result;  
		WebDriverWait wait = new WebDriverWait(u.getDriver(), Duration.ofSeconds(360));
		 wait.until(driver -> {
		     try {
		         JavascriptExecutor js = (JavascriptExecutor) driver;
		         String script =
		             "const overlays = document.querySelectorAll('.cdk-global-overlay-wrapper');" +
		             "for (const overlay of overlays) {" +
		             "  const text = overlay.innerText || '';" +
		             "  if (text.includes('Espere un momento')) return false;" +
		             "}" +
		             "return true;";  // Si no encontró ninguno con ese texto, entonces ya desapareció
		         return Boolean.TRUE.equals(js.executeScript(script));
		     } catch (Exception e) {
		         System.out.println("Error al ejecutar JS para validar overlay: " + e.getMessage());
		         return false;
		     }
		 });
		 if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Se visualiza la ventana emergente cargando");
	            testCase.addScreenShotCurrentStep("Descarga");
	        }
		result = true;
		
		
		return result;
	}catch (Exception e) {			
			testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
			throw new Exception ("Error " + e.getMessage());			
	}
	}
