	/**
	 * Obtiene el elemento WebElement de una celda especifica en una fila
	 *
	 * @param row fila WebElement
	 * @param col nombre de la columna
	 * @return WebElement correspondiente a la celda
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private WebElement celda(WebElement row, String col) {
	    return row.findElement(By.cssSelector("td.cdk-column-" + col));
	}
	/**
	 * Obtiene el texto de una celda especifica de una fila
	 *
	 * @param row fila WebElement
	 * @param col columna a extraer
	 * @return texto de la celda, recortado
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public String txtCelda(WebElement row, String col) {
	    return celda(row, col).getText().trim();
	}

	/**
	 * Hace clic en el primer elemento del grid de Devoluciones y valida que se abra la vista de detalles
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si se abre correctamente el detalle del ticket
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public boolean abrirTicketDesdeGridYValidarVista(boolean screenshot) {
	    try {
	        WebDriver d = u.getDriver();
	        u.waitWebElement(gridTabla, 30, 5);
	        List<WebElement> filas = d.findElements(gridFilas);
	        if (filas.isEmpty()) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("Grid sin filas.");
	            return false;
	        }

	        WebElement fila = filas.get(0); // o la que necesites
	        // Guarda valores de la fila
	        DevolucionRow r = new DevolucionRow();
	        r.folio           = txtCelda(fila,"folio");
	        r.nombreProveedor = txtCelda(fila,"nombreProveedor");
	        r.region          = txtCelda(fila,"region");
	        r.plaza           = txtCelda(fila,"plaza");
	        r.crTienda        = txtCelda(fila,"crTienda");
	        r.nombreTienda    = txtCelda(fila,"nombreTienda");
	        r.fecha           = txtCelda(fila,"fecha");
	        r.valorTotal      = txtCelda(fila,"valorTotal");
	        r.costoTotal      = txtCelda(fila,"costoTotal");
	        r.totalArticulos  = txtCelda(fila,"totalArticulosDevolver");
	        r.totalPiezas     = txtCelda(fila,"totalPiezasDevolver");
	        ultimaDevolucionSeleccionada = r;

	        if (screenshot) {

	            testCase.addTextEvidenceCurrentStep("Fila seleccionada (Folio " + r.folio + ")");
	            testCase.addScreenShotCurrentStep(u, "FilaSeleccionada");
	        }


	        // Clic que dispara la carga
	        fila.click();

	        // === Espera 1: overlay “Espere un momento”===
	        try {
	            u.waitWebElement(xmlMSGDescarga, 2, 1);   
	            u.highLight(xmlMSGDescarga);
	            if (screenshot) {
	                testCase.addTextEvidenceCurrentStep("Se muestra texto: \"Espere un momento\"");
	                testCase.addScreenShotCurrentStep(u, "Overlay_EspereUnMomento");
	            }
	        } catch (Exception ignore) {}

	        if (!MensajeEspereDesaparece(false)) {
	            testCase.addTextEvidenceCurrentStep("Falló al desaparecer el mensaje espere un momento");
	            return false;
	        }
	      
	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Se visualiza el ticket de Devoluciones.");
	            testCase.addScreenShotCurrentStep(u, "Detalle_Ticket_Visible");
	        }

	        return true;

	    } catch (Exception e) {
	        System.out.println("Error en abrirTicketDesdeGridYValidarVista: " + e.getMessage());
	        return false;
	    }
	}
	/**
	 * Captura el texto visible del visor PDF en pantalla usando Robot y portapapeles
	 *
	 * @return texto copiado del PDF, o null si ocurre un error
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private String capturarTextoPDFVisible() {
	    try {
	        WebDriver d = u.getDriver();
	        JavascriptExecutor js = (JavascriptExecutor) d;

	        // Coordenadas de la ventana del navegador (en pantalla) y del viewport
	        @SuppressWarnings("unchecked")
	        java.util.Map<String, Object> w = (java.util.Map<String, Object>) js.executeScript(
	            "return {sx: window.screenX, sy: window.screenY, iw: window.innerWidth, ih: window.innerHeight};");

	        int sx = ((Number) w.get("sx")).intValue();
	        int sy = ((Number) w.get("sy")).intValue();
	        int iw = ((Number) w.get("iw")).intValue();
	        int ih = ((Number) w.get("ih")).intValue();

	        // Puntos donde vamos a clicar para asegurar foco dentro del PDF
	        // (centro, 60% altura, 40% altura — suele bastar)
	        int[][] puntos = new int[][]{
	            { sx + iw/2,         sy + ih/2 },
	            { sx + iw/2, (int) (sy + ih*0.60) },
	            { sx + iw/2, (int) (sy + ih*0.40) }
	        };

	        // Limpia el portapapeles para detectar cambios
	        Clipboard cb = Toolkit.getDefaultToolkit().getSystemClipboard();
	        cb.setContents(new StringSelection(""), null);

	        Robot r = new Robot();
	        r.setAutoDelay(70);

	        String texto = null;

	        for (int[] p : puntos) {
	            // Clic para enfocar el visor PDF
	            r.mouseMove(p[0], p[1]);
	            r.mousePress(InputEvent.BUTTON1_DOWN_MASK);
	            r.mouseRelease(InputEvent.BUTTON1_DOWN_MASK);

	            // Ctrl+A (seleccionar todo)
	            r.keyPress(KeyEvent.VK_CONTROL);
	            r.keyPress(KeyEvent.VK_A);
	            r.keyRelease(KeyEvent.VK_A);
	            r.keyRelease(KeyEvent.VK_CONTROL);

	            // Ctrl+C (copiar)
	            r.keyPress(KeyEvent.VK_CONTROL);
	            r.keyPress(KeyEvent.VK_C);
	            r.keyRelease(KeyEvent.VK_C);
	            r.keyRelease(KeyEvent.VK_CONTROL);

	            // Pequeña espera para que el visor procese la copia
	            Thread.sleep(350);

	            try {
	                Object data = cb.getData(DataFlavor.stringFlavor);
	                if (data != null) {
	                    String s = data.toString();
	                    // Si realmente copió contenido de un PDF, debe traer múltiples líneas
	                    if (s != null && s.trim().length() > 0 && s.contains("\n")) {
	                        texto = s;
	                        break;
	                    }
	                }
	            } catch (Exception ignore) {}
	        }
	        return texto;

	    } catch (Exception e) {
	        testCase.addTextEvidenceCurrentStep("Error capturando texto del visor: " + e.getMessage());
	        return null;
	    }
	}
	/**
	 * Valida que el folio en PDF coincida con el folio del ticket seleccionado en el grid de Devoluciones Directos
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si el folio del PDF coincide con el folio del grid
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public boolean validarTicketCoincideConSeleccion(boolean screenshot) {
	    try {
	        if (ultimaDevolucionSeleccionada == null ||
	            ultimaDevolucionSeleccionada.folio == null ||
	            ultimaDevolucionSeleccionada.folio.trim().isEmpty()) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No hay folio previo del grid.");
	            return false;
	        }

	        String texto = capturarTextoPDFVisible();
	        if (texto == null) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se pudo leer texto del PDF en pantalla.");
	            return false;
	        }

	        String folioPDFRaw = lineaValor(texto, "Folio");
	        String folioPDF = extraerSoloDigitos(folioPDFRaw);
	        String folioGrid = extraerSoloDigitos(ultimaDevolucionSeleccionada.folio);

	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep(
	                "Folio (PDF raw): " + folioPDFRaw +
	                " | Folio (PDF digitos): " + folioPDF +
	                " | Folio (Grid digitos): " + folioGrid
	            );
	            testCase.addScreenShotCurrentStep(u, "PDFVisorDevol");
	        }

	        return folioPDF != null && folioPDF.equals(folioGrid);

	    } catch (Exception e) {
	        testCase.addTextEvidenceCurrentStep("Error en validarTicketCoincideConSeleccion: " + e.getMessage());
	        return false;
	    }
	}
	/**
	 * Extrae unicamente los caracteres numericos (0-9) de una cadena dada.
	 *
	 * Se utiliza principalmente para normalizar valores obtenidos del PDF
	 * que pueden contener texto adicional, espacios, saltos de linea o
	 * caracteres especiales (por ejemplo "Folio: 91455" o "91455\n"),
	 * permitiendo comparar solamente el valor numerico contra el grid.
	 *
	 * @param s cadena de entrada que puede contener texto mixto
	 * @return cadena compuesta solo por digitos o null si la entrada es null
	 *         o no contiene numeros
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private String extraerSoloDigitos(String s) {
	    if (s == null) return null;
	    String d = s.replaceAll("\\D+", "").trim();
	    return d.isEmpty() ? null : d;
	}
	/**
	 * Valida que todos los datos del ticket seleccionado en el grid coincidan con la vista de detalles en Devoluciones Directos
	 *
	 * @param screenshot true o false para guardar evidencia
	 * @return true si todos los datos coinciden entre PDF y grid
	 * @throws Exception cuando ocurre un error en la validacion
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	public boolean validarDatosDeDevolucion(boolean screenshot) {
	    try {
	        String texto = capturarTextoPDFVisible();
	        if (texto == null) {
	            if (screenshot) testCase.addTextEvidenceCurrentStep("No se pudo leer texto del PDF en pantalla");
	            return false;
	        }

	        String folioPDFRaw = lineaValorFuzzy(texto, "folio");
	        String folioPDF    = extraerSoloDigitos(folioPDFRaw);
	        String fuentePDF  = lineaValorFuzzy(texto, "fuente de abasto", "fuente");
	        String provPDF    = firstNonNull(lineaValorFuzzy(texto, "nombre del proveedor"), lineaValorFuzzy(texto, "proveedor"));
	        String plazaVal   = lineaValorFuzzy(texto, "plaza");
	        String regionPDF  = firstNonNull(lineaValorFuzzy(texto, "region"), extraerRegionDePlaza(plazaVal));
	        String fechaLine  = lineaValorFuzzy(texto, "fecha");
	        String fechaPDF   = extractDate(firstNonNull(fechaLine, ""));
	        String tiempoPDF  = firstNonNull(lineaValorFuzzy(texto, "tiempo de devolucion"), lineaValorFuzzy(texto, "tiempo"));
	        String totalArt   = firstNonNull(lineaValorFuzzy(texto, "total de articulos a devolver"), lineaValorFuzzy(texto, "total de articulos"));
	        String totalPzas  = firstNonNull(lineaValorFuzzy(texto, "total de piezas a devolver"), lineaValorFuzzy(texto, "total de piezas"));
	        String valorPDF   = lineaValorFuzzy(texto, "valor total");
	        String costoPDF   = lineaValorFuzzy(texto, "total costo");

	        String crLinea    = firstNonNull(lineaValorFuzzy(texto, "cr tienda", "crtienda", "cr tienda", "cr"), null);
	        String crPDF = null;
	        String tiendaPDF = firstNonNull(lineaValorFuzzy(texto, "nombre de tienda"), null);
	        if (crLinea != null) {
	            String[] crSplit = dividirCRyTienda(crLinea);
	            crPDF = crSplit[0];
	            if (crSplit[1] != null) tiendaPDF = crSplit[1];
	        }

	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep(
	                "PDF -> Fuente: " + safe(fuentePDF) +
	                " | Proveedor: " + safe(provPDF) +
	                " | CR: " + safe(crPDF) +
	                " | Tienda: " + safe(tiendaPDF) +
	                " | Fecha: " + safe(fechaPDF) +
	                " | Folio: " + safe(folioPDF) +
	                " | Tiempo: " + safe(tiempoPDF) +
	                " | Total articulos: " + safe(totalArt) +
	                " | Total piezas: " + safe(totalPzas) +
	                " | Valor Total: " + safe(valorPDF) +
	                " | Total Costo: " + safe(costoPDF)
	            );
	        }

	        if (ultimaDevolucionSeleccionada != null) {
	        	if (!eqCI(folioPDF, extraerSoloDigitos(ultimaDevolucionSeleccionada.folio))) return false;          
	            if (!eqMoney(valorPDF, ultimaDevolucionSeleccionada.valorTotal)) return false;
	            if (!eqMoney(costoPDF, ultimaDevolucionSeleccionada.costoTotal)) return false;
	            if (!eqDigits(totalArt, ultimaDevolucionSeleccionada.totalArticulos)) return false;
	            if (!eqDigits(totalPzas, ultimaDevolucionSeleccionada.totalPiezas)) return false;

	            String fechaGrid = extractDate(firstNonNull(ultimaDevolucionSeleccionada.fecha, ""));
	            if (!(containsEitherCI(fechaPDF, fechaGrid) || containsEitherCI(firstNonNull(fechaLine, ""), fechaGrid))) return false;

	            if (ultimaDevolucionSeleccionada.tiempoDevolucion != null && tiempoPDF != null) {
	                String tPdf  = normalizeSpaces(tiempoPDF);
	                String tGrid = normalizeSpaces(ultimaDevolucionSeleccionada.tiempoDevolucion);

	                if (!containsEitherCI(tPdf, tGrid)) return false;
	            }
	            if (ultimaDevolucionSeleccionada.fuenteAbasto != null && fuentePDF != null) {
	                if (!eqDigits(fuentePDF, ultimaDevolucionSeleccionada.fuenteAbasto)) return false;
	            }
	        }

	        return true;
	    } catch (Exception e) {
	        testCase.addTextEvidenceCurrentStep("Error en validarDatosDeDevolucion: " + e.getMessage());
	        return false;
	    }
	}
	
	/**
	 * Normaliza una cadena reemplazando multiples espacios, saltos de linea y tabulaciones
	 * por un solo espacio, eliminando espacios al inicio y al final.
	 *
	 * Se utiliza para evitar diferencias de formato entre valores obtenidos del PDF
	 * y valores mostrados en el grid (por ejemplo, cuando el PDF parte el texto en
	 * varias lineas).
	 *
	 * @param s cadena a normalizar
	 * @return cadena con espacios normalizados o null si la entrada es null
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private String normalizeSpaces(String s) {
	    if (s == null) return null;
	    return s.replaceAll("\\s+", " ").trim();
	}
	/**
	 * Verifica si una cadena contiene a otra ignorando mayusculas/minusculas y espacios
	 *
	 * @param a primera cadena
	 * @param b segunda cadena
	 * @return true si alguna cadena contiene a la otra
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private boolean containsEitherCI(String a, String b) {
	    if (a == null || b == null) return false;
	    String na = norm(a);
	    String nb = norm(b);
	    return na.contains(nb) || nb.contains(na);
	}
	/**
	 * Compara dos cadenas ignorando mayusculas, minusculas y espacios
	 *
	 * @param a primera cadena
	 * @param b segunda cadena
	 * @return true si las cadenas son iguales normalizadas
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private boolean eqCI(String a, String b) {
	    if (a == null || b == null) return false;
	    return norm(a).equals(norm(b));
	}
	/**
	 * Normaliza una cadena eliminando acentos, caracteres especiales y espacios extras
	 *
	 * @param s cadena a normalizar
	 * @return cadena en minusculas, sin acentos y limpia de caracteres no permitidos
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private String norm(String s) {
	    if (s == null) return "";
	    String n = java.text.Normalizer.normalize(s, java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+", "");
	    return n.toLowerCase().replaceAll("[^a-z0-9\\s:\\-_/\\.]", " ").replaceAll("\\s+", " ").trim();
	}
	/**
	 * Compara dos valores monetarios ignorando simbolos de pesos, espacios y comas
	 *
	 * @param a primer valor monetario
	 * @param b segundo valor monetario
	 * @return true si los valores numericos coinciden
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private boolean eqMoney(String a, String b) {
	    if (a == null || b == null) return false;
	    String na = a.replaceAll("[^0-9.,-]", "").replace(",", "");
	    String nb = b.replaceAll("[^0-9.,-]", "").replace(",", "");
	    return na.equals(nb);
	}
	/**
	 * Compara dos cadenas considerando solo los digitos numericos
	 *
	 * @param a primera cadena
	 * @param b segunda cadena
	 * @return true si los digitos de ambas cadenas coinciden
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private boolean eqDigits(String a, String b) {
	    if (a == null || b == null) return false;
	    String na = a.replaceAll("\\D+", "");
	    String nb = b.replaceAll("\\D+", "");
	    return !na.isEmpty() && na.equals(nb);
	}
	/**
	 * Extrae y normaliza una fecha encontrada dentro de una cadena.
	 *
	 * Soporta los formatos:
	 * - yyyy-MM-dd
	 * - dd-MM-yyyy
	 * - dd/MM/yyyy
	 *
	 * Siempre devuelve la fecha en formato estandar yyyy-MM-dd
	 * para permitir comparaciones consistentes entre valores
	 * provenientes del grid y del PDF.
	 *
	 * @param s cadena que contiene la fecha en alguno de los formatos soportados
	 * @return fecha normalizada en formato yyyy-MM-dd o null si no se encuentra
	 * @author Jose Pecina
	 * @date Marzo 2026
	 */
	private String extractDate(String s) {
	    if (s == null) return null;

	    // 1) yyyy-MM-dd
	    java.util.regex.Matcher iso = java.util.regex.Pattern
	        .compile("(\\d{4}-\\d{2}-\\d{2})")
	        .matcher(s);
	    if (iso.find()) return iso.group(1);

	    // 2) dd-MM-yyyy o dd/MM/yyyy -> convertir a yyyy-MM-dd
	    java.util.regex.Matcher latam = java.util.regex.Pattern
	        .compile("(\\d{2})[-/](\\d{2})[-/](\\d{4})")
	        .matcher(s);
	    if (latam.find()) {
	        return latam.group(3) + "-" + latam.group(2) + "-" + latam.group(1);
	    }

	    return null;
	}
	/**
	 * Devuelve el primer valor no nulo y no vacio entre dos cadenas
	 *
	 * @param a primera cadena
	 * @param b segunda cadena
	 * @return primer valor no nulo/no vacio o null si ambos son nulos o vacios
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private String firstNonNull(String a, String b) {
	    return a != null && !a.trim().isEmpty() ? a.trim() : (b != null && !b.trim().isEmpty() ? b.trim() : null);
	}
	/**
	 * Devuelve una cadena segura reemplazando null por cadena vacia
	 *
	 * @param s cadena a validar
	 * @return cadena original o "" si es null
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private String safe(String s) { return s == null ? "" : s; }
	/**
	 * Busca de forma aproximada un valor asociado a uno o varios labels en un texto
	 *
	 * @param texto texto donde se buscara el valor
	 * @param labels etiquetas a buscar
	 * @return valor encontrado despues del label o null si no se encuentra
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private String lineaValorFuzzy(String texto, String... labels) {
	    if (texto == null) return null;
	    String[] lines = texto.split("\\R");
	    for (String lbl : labels) {
	        String nlbl = norm(lbl);
	        for (String line : lines) {
	            String nline = norm(line);
	            if (nline.contains(nlbl)) {
	                int idx = nline.indexOf(nlbl) + nlbl.length();
	                String raw = line.substring(Math.min(idx + (line.length() - nline.length()), line.length())).trim();
	                int sep = raw.indexOf(":");
	                if (sep >= 0) raw = raw.substring(sep + 1).trim();
	                return raw.isEmpty() ? null : raw;
	            }
	        }
	    }
	    return null;
	}
	/**
	 * Extrae la region de un valor de plaza (formato "Plaza Region")
	 *
	 * @param plazaVal valor de plaza que contiene region
	 * @return region extraida o null si no existe
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private String extraerRegionDePlaza(String plazaVal) {
	    if (plazaVal == null) return null;
	    String v = plazaVal.trim();
	    if (v.isEmpty()) return null;
	    String[] p = v.split("\\s+", 2);
	    return p.length >= 2 ? p[1].trim() : null;
	}
	/**
	 * Divide una cadena que contiene CR y Tienda en un arreglo de dos elementos
	 *
	 * @param crLinea cadena con formato "CR Tienda"
	 * @return arreglo [CR, Tienda], null en cada posicion si no aplica
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private String[] dividirCRyTienda(String crLinea) {
	    if (crLinea == null) return new String[]{null, null};
	    String v = crLinea.trim();
	    if (v.isEmpty()) return new String[]{null, null};
	    String[] p = v.split("\\s+", 2);
	    String cr = p[0].trim();
	    String tienda = p.length >= 2 ? p[1].trim() : null;
	    return new String[]{cr, tienda};
	}
	/**
	 * Extrae el valor de una linea que comienza con una etiqueta especifica seguida de ':'
	 *
	 * @param texto texto completo donde buscar
	 * @param etiqueta etiqueta que precede al valor
	 * @return valor encontrado despues de la etiqueta o null si no existe
	 * @author Jose Pecina
	 * @date Septiembre 2025
	 */
	private String lineaValor(String texto, String etiqueta) {
	    if (texto == null) return null;
	    String e = etiqueta.toLowerCase(Locale.ROOT);
	    String[] lines = texto.split("\\r?\\n");
	    for (String raw : lines) {
	        String l = raw == null ? "" : raw.trim();
	        String ll = l.toLowerCase(Locale.ROOT);
	        if (ll.startsWith(e + ":")) {
	            return l.substring(l.indexOf(':') + 1).trim();
	        }
	    }
	    return null;
	}
