	/**
	 * Metodo para validar la busqueda con filtro fecha en calendario
	 * considerando solo registros mayores a 1000 y dentro de 3 meses
	 *
	 * @param usuario usuario para validar perfil y obtener datos de BD
	 * @param screenshot true o false para guardar evidencia
	 * @return true si el filtro de fechas se visualiza y se puede seleccionar
	 * @throws Exception cuando ocurre un error en la ejecucion
	 * @author Jose Pecina
	 * @date Enero 2026
	 */
	public boolean SelecFecha1k(String usuario, boolean screenshot) throws Exception {
	    try {
	        boolean result;

	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	        String dbUser = GlobalVariables.DB_USER_Cometa;
	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	        String PCPERFIL =
	            "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' " +
	            "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

	        String PCRFC =
	            "select key_value from xxcm_user_keys where short_name in ('PCRFC', 'PCSUPPLIERID','PCPLAZA') " +
	            "and usuario_id in (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

	        String FechaBD = null;

	        // Validar que exista el filtro de fechas
	        if (u.isDisplayed(xmlRangoFechas)) {
	            u.highLight(xmlRangoFechas);

	            if (screenshot) {
	                testCase.addTextEvidenceCurrentStep("Se visualiza el filtro del rango de fechas");
	                testCase.addScreenShotCurrentStep(u, "FiltroFechas");
	            }

	            u.unhighLight(xmlRangoFechas);
	            result = true;
	        } else {
	            return false;
	        }

	        // Obtener fecha desde BD con conteo >=1000, considerando perfil
	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	             Statement stmt = connection.createStatement()) {

	            String perfil = null;

	            try (ResultSet rsPerfil = stmt.executeQuery(PCPERFIL)) {
	                if (rsPerfil.next()) {
	                    perfil = rsPerfil.getString("key_value");
	                    System.out.println("Usuario con perfil: " + perfil);
	                }
	            }

	            if (perfil != null) {

	                if (!"ADMIN".equalsIgnoreCase(perfil) && !"OXXO_OS".equalsIgnoreCase(perfil)) {

	                    String rfc = null;
	                    try (ResultSet rsRfc = stmt.executeQuery(PCRFC)) {
	                        if (rsRfc.next()) {
	                            rfc = rsRfc.getString("key_value");
	                        } else {
	                            System.out.println("No se obtuvo RFC.");
	                            return false;
	                        }
	                    }

	                    String sqlFechaMayor1000;

	                    if ("OXXO_PLAZA".equalsIgnoreCase(perfil)) {
	                        sqlFechaMayor1000 =
	                            "select fecha " +
	                            "from xxcm_dv " +
	                            "where cr_desc_plaza = '" + rfc + "' " +
	                            "group by fecha " +
	                            "having count(*) >= 1000 " +
	                            "order by fecha desc " +
	                            "limit 1";
	                    } else {
	                        sqlFechaMayor1000 =
	                            "select fecha " +
	                            "from xxcm_dv " +
	                            "where proveedor_rfc = '" + rfc + "' " +
	                            "group by fecha " +
	                            "having count(*) >= 1000 " +
	                            "order by fecha desc " +
	                            "limit 1";
	                    }

	                    try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMayor1000)) {
	                        if (rsFecha.next()) {
	                            FechaBD = rsFecha.getString("fecha");
	                            System.out.println("Fecha seleccionada (>=1000): " + FechaBD);
	                        } else {
	                            System.out.println("No se obtuvo informacion (sin fecha >=1000).");
	                            return false;
	                        }
	                    }

	                } else {
	                    // ADMIN / OXXO_OS => sin RFC
	                    String sqlFechaMayor1000Admin =
	                        "select fecha " +
	                        "from xxcm_dv " +
	                        "group by fecha " +
	                        "having count(*) >= 1000 " +
	                        "order by fecha desc " +
	                        "limit 1";

	                    try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMayor1000Admin)) {
	                        if (rsFecha.next()) {
	                            FechaBD = rsFecha.getString("fecha");
	                            System.out.println("Fecha seleccionada (ADMIN/OXXO_OS >=1000): " + FechaBD);
	                        } else {
	                            System.out.println("No se obtuvo informacion (ADMIN/OXXO_OS sin fecha >=1000).");
	                            return false;
	                        }
	                    }
	                }

	            } else {
	                // Fallback: si no hay perfil, usar RFC
	                String rfc = null;
	                try (ResultSet rsRfc = stmt.executeQuery(PCRFC)) {
	                    if (rsRfc.next()) {
	                        rfc = rsRfc.getString("key_value");
	                    } else {
	                        System.out.println("No se obtuvo RFC (fallback).");
	                        return false;
	                    }
	                }

	                String sqlFechaMayor1000Fallback =
	                    "select fecha " +
	                    "from xxcm_dv " +
	                    "where proveedor_rfc = '" + rfc + "' " +
	                    "group by fecha " +
	                    "having count(*) >= 1000 " +
	                    "order by fecha desc " +
	                    "limit 1";

	                try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMayor1000Fallback)) {
	                    if (rsFecha.next()) {
	                        FechaBD = rsFecha.getString("fecha");
	                        System.out.println("Fecha seleccionada (fallback >=1000): " + FechaBD);
	                    } else {
	                        System.out.println("No se obtuvo informacion (fallback sin fecha >=1000).");
	                        return false;
	                    }
	                }
	            }
	        }

	        if (FechaBD == null || FechaBD.trim().isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("No se obtuvo FechaBD valida");
	            return false;
	        }

	        centroDescargasFiltradoFecha = FechaBD;

	        // Parsear fecha
	        LocalDate fechaConvert;
	        try {
	            fechaConvert = LocalDateTime
	                .parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))
	                .toLocalDate();
	        } catch (Exception ex) {
	            fechaConvert = LocalDate.parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	        }

	        // Abrir datepicker y seleccionar rango
	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
	        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

	        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
	        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

	        By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
	        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

	        if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	        }

	        clickYear(driver, wait, fechaConvert.getYear());
	        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

	        clickDay(driver, wait, fechaConvert.minusDays(1).getDayOfMonth());
	        clickDay(driver, wait, fechaConvert.getDayOfMonth());

	        wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));

	        if (screenshot) {
	            testCase.addTextEvidenceCurrentStep(
	                "Se selecciono rango de fechas: " + fechaConvert.minusDays(1) + " a " + fechaConvert + " (BD >=1000)"
	            );
	            testCase.addScreenShotCurrentStep(u, "RangoFechasSeleccionado");
	        }

	        return result;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
