	/**
	 * Verifica que cajas de texto, botones y grid se muestren correctamente
	 * @param screenshot indica si se guardara screenshot en el reporte
	 * @return true si todos los elementos son visibles, false si falta alguno
	 * @throws Exception si ocurre algun error durante la ejecucion
	 * @author Jose Pecina
	 * @date Febrero 2026
	 */
	public boolean VerificarPaginaDevoluciones(boolean screenshot) throws Exception{
		try {
	
		WebDriver driver = u.getDriver();
		
        LinkedHashMap<String, By> botones = new LinkedHashMap<>();
        botones.put("Proveedor",  xmlFiltroProveedor);
        botones.put("Fuente de abasto",        xmlFiltrofuenteDeAbasto);
        botones.put("Zona",        xmlFiltrozona);
        botones.put("Region",        xmlFiltroregion);
        botones.put("Plaza",        xmlFiltroplaza);
        botones.put("Tienda",        xmlFiltrotienda);
        botones.put("Limpiar",        xmlLimpiarFiltroDevolu);
        botones.put("Fecha",        xmlFiltroFechaDevol);
        botones.put("Consultar",        xmlConsultarDeshabilitado);
        botones.put("Grid",        xmlGridInicioDevol);
        

        // 2) Validación uno por uno
        for (Map.Entry<String, By> entry : botones.entrySet()) {
            String nombre = entry.getKey();
            By by = entry.getValue();

            // Reencuentra el elemento siempre para evitar referencias obsoletas
            List<WebElement> encontrados = driver.findElements(by);
            if (encontrados.isEmpty()) {
                System.out.println("No se encontró el botón '" + nombre + "'");
                if (screenshot) {
                    testCase.addTextEvidenceCurrentStep("FALLO: No se encontró el botón '" + nombre + "'");
                    testCase.addScreenShotCurrentStep(u, "NoSeEncontro_" + nombre.replace(" ", "_"));
                }
                return false;
            }

            WebElement boton = encontrados.get(0);

            // Visible
            if (!boton.isDisplayed()) {
                System.out.println("El botón '" + nombre + "' no es visible");
                if (screenshot) {                    
                    testCase.addTextEvidenceCurrentStep("FALLO: El botón '" + nombre + "' no es visible");
                    testCase.addScreenShotCurrentStep(u, "NoVisible_" + nombre.replace(" ", "_"));
                }
                return false;
            }

            // OK individual
            if (screenshot) {
                u.highLight(by);
                testCase.addTextEvidenceCurrentStep("OK: '" + nombre + "' visible");
            }
        }

        if (screenshot) {
            testCase.addScreenShotCurrentStep(u, "Validados_OK");            
        }
        for (Map.Entry<String, By> entry : botones.entrySet()) {
            String nombre = entry.getKey();
            By by = entry.getValue();
            u.unhighLight(by);
        }
        return true;

	}catch (Exception e) {			
			testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
			throw new Exception ("Error " + e.getMessage());			
	}
	}
