	public boolean validarAutocompleteProveedor(boolean screenshot) throws Exception {
	    try {
	        WebDriver d = u.getDriver();

	        By selectProveedor = By.xpath("//ng-select[@bindlabel='supplierName' and @bindvalue='rfc']");
	        By inputProveedor = By.xpath("//ng-select[@bindlabel='supplierName' and @bindvalue='rfc']//input[@type='text' and @aria-autocomplete='list']");
	        By opcionesPanel = By.xpath(
	            "//ng-dropdown-panel[contains(@class,'ng-dropdown-panel')]" +
	            "//div[contains(@class,'ng-option') and @role='option']"
	        );

	        u.click(xmlFiltroProveedor);
	        u.waitWebElement(inputProveedor, 60, 5);
	        u.scrollToElement(selectProveedor);

	        WebElement input = d.findElement(inputProveedor);
	        input.click();
	        input.clear();

	        String txt = u.getText(xmlCRTiendaOp1).trim();
	        String textoEscrito = txt.substring(0, Math.min(3, txt.length())).trim();

	        if (textoEscrito.isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("Proveedor: El texto base para la busqueda esta vacio.");
	            if (screenshot) {
	                testCase.addScreenShotCurrentStep(u, "Proveedor_texto_vacio");
	            }
	            return false;
	        }

	        input.sendKeys(textoEscrito);

	        u.waitWebElement(opcionesPanel, 60, 5);
	        u.hardWait(1);

	        List<WebElement> opciones = d.findElements(opcionesPanel);

	        if (opciones.isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("Proveedor: No aparecieron sugerencias al escribir '" + textoEscrito + "'.");
	            if (screenshot) {
	                testCase.addScreenShotCurrentStep(u, "Proveedor_sin_sugerencias");
	            }
	            return false;
	        }

	        String needle = java.text.Normalizer.normalize(textoEscrito, java.text.Normalizer.Form.NFD)
	                .replaceAll("\\p{M}+", "")
	                .toLowerCase();

	        List<String> noCoinciden = new ArrayList<>();
	        List<String> todas = new ArrayList<>();

	        for (WebElement e : opciones) {
	            String raw = e.getText().trim();

	            if (raw.isEmpty()) {
	                continue;
	            }

	            todas.add(raw);

	            String normal = java.text.Normalizer.normalize(raw, java.text.Normalizer.Form.NFD)
	                    .replaceAll("\\p{M}+", "")
	                    .toLowerCase();

	            if (!normal.contains(needle)) {
	                noCoinciden.add(raw);
	            }
	        }

	        testCase.addTextEvidenceCurrentStep("Texto escrito en Proveedor: '" + textoEscrito + "'");
	        testCase.addTextEvidenceCurrentStep("Sugerencias encontradas: " + todas);

	        if (!noCoinciden.isEmpty()) {
	            testCase.addTextEvidenceCurrentStep("Estas opciones no contienen '" + textoEscrito + "': " + noCoinciden);
	        }

	        if (screenshot) {
	            testCase.addScreenShotCurrentStep(u, "Proveedor_autocomplete");
	        }

	        d.switchTo().activeElement().sendKeys(org.openqa.selenium.Keys.ESCAPE);
	        u.getDriver().findElement(By.tagName("body")).click();

	        return noCoinciden.isEmpty();

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error validarAutocompleteProveedor: " + e.getMessage());
	        throw e;
	    }
	}
