	/**
	 * Valida que los filtros de devoluciones directos coincidan con la base de datos
	 * Compara TIENDA, PLAZA y REGION usando SELECT DISTINCT y validacion 1:1 contra UI
	 * @param screenshot indica si se guardaran evidencias
	 * @return true si los filtros coinciden en contenido y cantidad, false si hay diferencias
	 * @throws Exception si ocurre algun error durante la ejecucion
	 * @author Jose Pecina
	 * @date Febrero 2026
	 */
	public boolean ComparafiltrosBD(boolean screenshot) throws Exception {
	    try {
	        WebDriver d = u.getDriver();

	        // ====== 1) Locators (tus ng-select) ======
	        final By xmlFiltroregion = By.xpath("//ng-select[contains(@bindlabel,'region')]");
	        final By xmlFiltroplaza  = By.xpath("//ng-select[contains(@bindlabel,'plaza')]");
	        final By xmlFiltrotienda = By.xpath("//ng-select[contains(@bindlabel,'tienda')]");

	        // Opciones dentro del panel de ng-select
	        final By ngSelectOptions = By.xpath(
	            "//div[contains(@class,'ng-dropdown-panel')]" +
	            "//*[self::div[@role='option' and contains(@class,'ng-option')]" +
	            "   or self::div[contains(@class,'ng-option')]//div[contains(@class,'ng-option-label')]" +
	            "   or self::div[contains(@class,'ng-option-label')]]"
	        );

	        // ====== 2) Config BD ======
	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	        String dbUser = GlobalVariables.DB_USER_Cometa;
	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	        // ====== 3) SELECT DISTINCT por columna ======
	        String qTienda = "SELECT DISTINCT tienda AS val FROM public.xxcm_dv";
	        String qPlaza  = "SELECT DISTINCT plaza  AS val FROM public.xxcm_dv";
	        String qRegion = "SELECT DISTINCT region AS val FROM public.xxcm_dv";

	        // Normalizador
	        java.util.function.Function<String, String> norm = s ->
	            (s == null ? "" : s.replace('\u00A0', ' ').replaceAll("\\s+", " ").trim());

	        // Ejecuta query y llena Set<String>
	        java.util.function.Function<String, java.util.Set<String>> runDistinct = (sql) -> {
	            Set<String> out = new java.util.TreeSet<>();
	            try (Connection cn = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	                 Statement st = cn.createStatement();
	                 ResultSet rs = st.executeQuery(sql)) {
	                while (rs.next()) {
	                    out.add(norm.apply(rs.getString("val")));
	                }
	            } catch (Exception e) {
	                testCase.addTextEvidenceCurrentStep("Error SQL: " + e.getMessage());
	            }
	            return out;
	        };

	        Set<String> bdTiendas  = runDistinct.apply(qTienda);
	        Set<String> bdPlazas   = runDistinct.apply(qPlaza);
	        Set<String> bdRegiones = runDistinct.apply(qRegion);

	        // ====== 4) Leer opciones de cada ng-select ======
	        java.util.function.BiFunction<By, String, Set<String>> readNgSelect = (ngSelect, nombre) -> {
	            try {
	                u.waitWebElement(ngSelect, 60, 5);
	                u.scrollToElement(ngSelect);
	                u.click(ngSelect);
	                u.highLight(ngSelect);
	                u.waitWebElement(ngSelectOptions, 60, 5);
	                u.highLight(ngSelectOptions);

	                java.util.List<WebElement> ops = d.findElements(ngSelectOptions);
	                Set<String> valores = new java.util.TreeSet<>();

	                for (WebElement e : ops) {
	                    String t = norm.apply(e.getText());
	                    if (!t.isEmpty()) {
	                        valores.add(t);
	                    }
	                }

	                if (screenshot) {
	                    testCase.addScreenShotCurrentStep(u, "ng-select_" + nombre);
	                }

	                u.unhighLight(ngSelect);
	                u.unhighLight(ngSelectOptions);
	                d.switchTo().activeElement().sendKeys(org.openqa.selenium.Keys.ESCAPE);

	                return valores;

	            } catch (Exception ex) {
	                testCase.addTextEvidenceCurrentStep("Error leyendo ng-select " + nombre + ": " + ex.getMessage());
	                return java.util.Collections.emptySet();
	            }
	        };

	        Set<String> uiTiendas  = readNgSelect.apply(xmlFiltrotienda, "TIENDA");
	        Set<String> uiPlazas   = readNgSelect.apply(xmlFiltroplaza, "PLAZA");
	        Set<String> uiRegiones = readNgSelect.apply(xmlFiltroregion, "REGION");

	        // ====== 5) Comparar y evidenciar ======
	        java.util.function.BiFunction<String, java.util.List<Set<String>>, Boolean> comparar =
	            (nombre, listas) -> {
	                Set<String> bd = listas.get(0);
	                Set<String> ui = listas.get(1);

	                testCase.addBoldTextEvidenceCurrentStep("[" + nombre + "] BD=" + bd.size() + " vs Portal=" + ui.size());

	                Set<String> faltan = new java.util.TreeSet<>(bd);
	                faltan.removeAll(ui);

	                Set<String> sobran = new java.util.TreeSet<>(ui);
	                sobran.removeAll(bd);

	                if (!faltan.isEmpty()) {
	                    testCase.addTextEvidenceCurrentStep("Faltan en UI: " + faltan);
	                }

	                if (!sobran.isEmpty()) {
	                    testCase.addTextEvidenceCurrentStep("Sobran en UI: " + sobran);
	                }

	                return faltan.isEmpty() && sobran.isEmpty();
	            };

	        boolean okTienda = comparar.apply("TIENDA", java.util.Arrays.asList(bdTiendas, uiTiendas));
	        boolean okPlaza  = comparar.apply("PLAZA", java.util.Arrays.asList(bdPlazas, uiPlazas));
	        boolean okRegion = comparar.apply("REGION", java.util.Arrays.asList(bdRegiones, uiRegiones));

	        boolean result = okTienda && okPlaza && okRegion;

	        if (result) {
	            testCase.addBoldTextEvidenceCurrentStep("Filtros de TIENDA/PLAZA/REGION coinciden con BD (contenido y cantidad).");
	        } else {
	            testCase.addBoldTextEvidenceCurrentStep("Diferencias detectadas entre filtros y BD.");
	        }

	        return result;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error ComparafiltrosBD: " + e.getMessage());
	        throw new Exception("Error ComparafiltrosBD: " + e.getMessage());
	    }
	}
	/**
	 * Valida que exista el key value en la BD y obtiene el perfil del usuario
	 * @param screenshot indica si se guardaran evidencias
	 * @param usuario usuario para obtener los datos de la consulta en BD
	 * @return true si se obtuvo el perfil del usuario, false si no
	 * @throws Exception si ocurre algun error durante la ejecucion
	 * @author Jose Pecina
	 * @date Febrero 2026
	 */
 	public boolean ConsultaKIBD(boolean screenshot, String usuario) throws Exception{
 		try {
 			
		boolean result;
		result = true;
		String dbUrl = GlobalVariables.DB_URL_Cometa;
        String dbUser = GlobalVariables.DB_USER_Cometa;
        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;
        String PCPERFIL = "SELECT \r\n"
        		+ "    u.usuario,\r\n"
        		+ "    k.short_name,\r\n"
        		+ "    k.key_value\r\n"
        		+ "FROM xxcm_user_keys k\r\n"
        		+ "JOIN xxcm_usuarios u \r\n"
        		+ "    ON k.usuario_id = u.usuario_id\r\n"
        		+ "WHERE k.short_name IN ('PCPERFIL','PCRFC','PCSUPPLIERID','PCPLAZA')\r\n"
        		+ "  AND u.usuario = '"+usuario+"';";
             
        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
                Statement stmt = connection.createStatement();
                ResultSet rs = stmt.executeQuery(PCPERFIL)) {

        	if (rs.next()) {  // hay resultado
        		
                String keyValue = rs.getString("key_value");
                System.out.println("Usuario con perfil: " + keyValue);
                
                	 if (screenshot) {
                		 testCase.addBoldTextEvidenceCurrentStep("Se valida ki con query: " + PCPERFIL);
                		 
                		 testCase.addBoldTextEvidenceCurrentStep("Y se valida usuario con ki: " + keyValue);
                		 }
                
                } else { //Usuario Cedis no tiene datos en BD, escenario solo funciona para usuarios con datos en KEY_VALUE
                	result = false;
                    System.out.println("No se obtuvo información.");
                }

               } catch (Exception e) {
                   e.printStackTrace();
               }
            
    		return result;

     		}catch (Exception e) {			
     			testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
     			throw new Exception ("Error " + e.getMessage()); 			
    		}
     	}        	 
                	 
