	/**
	 * Metodo para validar que el nombre del PDF tenga el formato:
	 * OC_xxx_yyyy-MM-dd.pdf
	 * 
	 * Ejemplo: OC_163782_2026-02-19.pdf
	 * 
	 * @author Alejandro Valdez
	 * @return True si el nombre se valida correctamente
	 * @date Agosto 2025
	 */
	public boolean validarformatoNombrePdfD() {
	    boolean result = false;

	    String home = System.getProperty("user.home") + "\\Downloads\\Extraidos";
	    File ultimoArchivo = getLastModified(home);

	    if (ultimoArchivo == null) {
	        return false;
	    }

	    String nombreArchivo = ultimoArchivo.getName();

	    // Validar formato: OC_123456_2026-02-19.pdf
	    if (nombreArchivo.matches("^OC_\\d+_\\d{4}-\\d{2}-\\d{2}\\.pdf$") && ultimoArchivo.exists()) {
	        mostrarExploradorParaEvidencia(home);
	        result = true;
	    }

	    return result;
	}

	
