 	/**
 	 * Valida la paginacion en la pantalla de devoluciones directos
 	 * da click en cada opcion disponible y valida la cantidad de registros mostrados
 	 * @param screenshot indica si se guardaran evidencias
 	 * @return true si todas las opciones de paginacion muestran la cantidad correcta de registros, false si no
 	 * @throws Exception si ocurre algun error durante la ejecucion
 	 * @author Jose Pecina
 	 * @date Agosto 2025
 	 */
 	public boolean SelecPaginacion(boolean screenshot) throws Exception{
 	   try {
 		  u.scrollToElement(xmlPaginacionvalue);
 		  WebDriver driver = u.getDriver();
 		// Abrir dropdown de paginacion
 		  WebElement dropdown = driver.findElement(By.xpath("//*[@id='mat-select-0']"));
 		  dropdown.click();

 		  // Esperar a que el overlay del panel aparezca
 		  WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(5));
 		  WebElement panel = wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("mat-select-0-panel")));

 		  // Obtener todas las opciones visibles
 		  List<WebElement> opciones = wait.until(ExpectedConditions.visibilityOfAllElementsLocatedBy(
 		          By.xpath("//div[@id='mat-select-0-panel']//span[@role='option'] | //div[@id='mat-select-0-panel']//mat-option")));
 		// Lista de opciones de paginacion 
 		  List<String> opcionesPaginacion = Arrays.asList("5", "10", "15", "20");
 		  for (String opcion : opcionesPaginacion) {
 		      boolean opcionEncontrada = false;

 		      for (WebElement opt : opciones) {
 		          if (opt.getText().trim().equals(opcion)) {
 		              opt.click();
 		              opcionEncontrada = true;
 		              break;
 		          }
 		      }

 		      if (!opcionEncontrada) {
 		          System.out.println("Opcion no encontrada: " + opcion);
 		          return false;
 		      }

 		      // Esperar a que el grid se actualice
 		      u.hardWait(2); 

 		      // Contar filas visibles
 		      List<WebElement> filas = driver.findElements(By.xpath("/html/body/app-root/app-directos-devoluciones/div/directos-devoluciones-grid/div/table/tbody/tr"));
 		      int totalFilas = filas.size();

 		      if (totalFilas <= Integer.parseInt(opcion)) {
 		          u.scrollToElement(xmlPaginacionvalue);
 		          u.highLight(xmlPaginacionvalue);

 		          if (screenshot) {
 		              testCase.addTextEvidenceCurrentStep("Se visualizan correctamente " + totalFilas + " registros para opcion " + opcion);
 		              testCase.addScreenShotCurrentStep(u, "Pantalla Devoluciones " + opcion);
 		          }
 		          u.unhighLight(xmlPaginacionvalue);

 		          System.out.println("Correcto, opcion " + opcion + ", filas mostradas: " + totalFilas);
 		      } else {
 		          System.out.println("Error, opcion " + opcion + ", hay mas filas visibles: " + totalFilas);
 		          return false;
 		      }

 		      // Volver a abrir dropdown para siguiente iteracion
 		      dropdown.click();
 		      // Esperar a que el panel se vuelva a cargar
 		      panel = wait.until(ExpectedConditions.visibilityOfElementLocated(By.id("mat-select-0-panel")));
 		      opciones = wait.until(ExpectedConditions.visibilityOfAllElementsLocatedBy(
 		              By.xpath("//div[@id='mat-select-0-panel']//span[@role='option'] | //div[@id='mat-select-0-panel']//mat-option")));
 		  }

 	        return true;

 	    } catch (Exception e) {
 	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
 	        throw new Exception("Error " + e.getMessage());
 	    }
 	}	
