	/**
	 * Metodo auxiliar para seleccionar fecha minima y maxima disponible en un calendario.
	 * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
	 * @throws Exception si ocurre algun error durante la seleccion de fechas
	 * @author Jose Pecina
	 * @date Agosto 2025
	 */
	public void seleccionarRangoFechasConClicks(boolean screenshot) throws Exception {
	    try {
	    	u.scrollToElement(xmlRangoFechas);
	        u.click(xmlRangoFechas);
	        
	        WebDriver driver = u.getDriver();


	        for (int i = 0; i < 2; i++) {
	            driver.findElement(xmlBotonFlechaIzquierda).click();
	      
	        }

	        //primer día habilitado del mes mínimo
	        By primerDiaHabilitado = By.xpath("(//button[starts-with(@class, 'mat-calendar-body-cell') and not(@aria-disabled)])[1]");
	        WebElement diaMin = driver.findElement(primerDiaHabilitado);
	        u.highLight(primerDiaHabilitado);
	        if (screenshot) {
				testCase.addTextEvidenceCurrentStep("Se selecciona primera fecha: "+ diaMin.getAttribute("aria-label"));
				testCase.addScreenShotCurrentStep(u, "Primera");
				}
	        u.unhighLight(primerDiaHabilitado);
	        diaMin.click();

	        System.out.println("Seleccionada fecha mínima: " + diaMin.getAttribute("aria-label"));

	        //mes actual para seleccionar la fecha máxima
	        for (int i = 0; i < 2; i++) {
	            driver.findElement(xmlBotonFlechaDerecha).click();
	
	        }

	        // Tomamos el último día habilitado del mes actual
	        WebElement diaMax = driver.findElement(xmlUltimoDiaHabilitado);
	        System.out.println("Seleccionada fecha máxima: " + diaMax.getAttribute("aria-label"));
	        u.highLight(xmlUltimoDiaHabilitado);
	        if (screenshot) {
				testCase.addTextEvidenceCurrentStep("Se selecciona segunda fecha: "+ diaMax.getAttribute("aria-label"));
				testCase.addScreenShotCurrentStep(u, "segunda");
				}
	        diaMax.click();
	        u.unhighLight(xmlUltimoDiaHabilitado);

	    } catch (Exception e) {            
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());            
	    }
	}
	/**
	 * Valida la busqueda con filtro de fecha en Directos-Devoluciones.
	 * Obtiene la informacion de plaza y fecha del usuario especificado.
	 * @param usuario Usuario a buscar en la BD para validar existencia de datos
	 * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
	 * @return true si se encuentra informacion de plaza empoderada, false en caso contrario
	 * @throws Exception si ocurre algun error durante la validacion
	 * @author Jose Pecina
	 * @date Agosto 2025
	 */
	public boolean busquedaFiltroFechaDirectosDevoluciones(String usuario, boolean screenshot) throws Exception {
	    try {
	        boolean result;

	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	        String dbUser = GlobalVariables.DB_USER_Cometa;
	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	        String PCPERFIL = "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' "
	                + "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

	        String PCRFC = "select key_value from xxcm_user_keys where short_name in ('PCRFC', 'PCSUPPLIERID','PCPLAZA') "
	                + "and usuario_id in (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

	        String FechaBD = null;

	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	             Statement stmt = connection.createStatement();
	             ResultSet rs = stmt.executeQuery(PCPERFIL)) {

	            if (rs.next()) {
	                String keyValue = rs.getString("key_value");
	                System.out.println("Usuario con perfil: " + keyValue);

	                if (!"ADMIN".equalsIgnoreCase(keyValue) && !"OXXO_OS".equalsIgnoreCase(keyValue)) {

	                    try (ResultSet rs2 = stmt.executeQuery(PCRFC)) {
	                        if (rs2.next()) {
	                            String RFC = rs2.getString("key_value");
	                            String queryFecha = null;

	                            if ("OXXO_PLAZA".equalsIgnoreCase(keyValue)) {
	                                queryFecha = "select fecha from xxcm_dv "
	                                        + "where cr_desc_plaza = '" + RFC + "' "
	                                        + "order by fecha desc limit 1";
	                            } else {
	                                queryFecha = "select fecha from xxcm_dv "
	                                        + "where proveedor_rfc = '" + RFC + "' "
	                                        + "order by fecha desc limit 1";
	                            }

	                            try (ResultSet rs3 = stmt.executeQuery(queryFecha)) {
	                                if (rs3.next()) {
	                                    FechaBD = rs3.getString("fecha");

	                                    if (screenshot) {
	                                        testCase.addBoldTextEvidenceCurrentStep("Se ejecuta script para obtener los datos: " + queryFecha);
	                                        testCase.addBoldTextEvidenceCurrentStep("Existen datos en la tabla xxcm_dv. Fecha: " + FechaBD);
	                                    }

	                                    System.out.println("Existen datos en la tabla xxcm_dv. Fecha: " + FechaBD);
	                                } else {
	                                    result = false;
	                                    System.out.println("No se obtuvo informacion.");
	                                    return result;
	                                }
	                            }
	                        } else {
	                            result = false;
	                            System.out.println("No se obtuvo informacion.");
	                            return result;
	                        }
	                    }

	                } else {

	                    String queryFechaAdmin = "select fecha from xxcm_dv order by fecha desc limit 1";

	                    try (ResultSet rs3 = stmt.executeQuery(queryFechaAdmin)) {
	                        if (rs3.next()) {
	                            FechaBD = rs3.getString("fecha");

	                            if (screenshot) {
	                                testCase.addBoldTextEvidenceCurrentStep("Se ejecuta script para obtener los datos: " + queryFechaAdmin);
	                                testCase.addBoldTextEvidenceCurrentStep("Existen datos en la tabla xxcm_dv. Fecha: " + FechaBD);
	                            }

	                            System.out.println("Existen datos en la tabla xxcm_dv. Fecha: " + FechaBD);
	                        } else {
	                            result = false;
	                            System.out.println("No se obtuvo informacion.");
	                            return result;
	                        }
	                    }
	                }

	            } else {

	                try (ResultSet rs2 = stmt.executeQuery(PCRFC)) {
	                    if (rs2.next()) {
	                        String RFC = rs2.getString("key_value");

	                        String queryFechaCedis = "select fecha from xxcm_dv "
	                                + "where proveedor_rfc = '" + RFC + "' "
	                                + "order by fecha desc limit 1";

	                        try (ResultSet rs3 = stmt.executeQuery(queryFechaCedis)) {
	                            if (rs3.next()) {
	                                FechaBD = rs3.getString("fecha");

	                                if (screenshot) {
	                                    testCase.addBoldTextEvidenceCurrentStep("Se ejecuta script para obtener los datos: " + queryFechaCedis);
	                                    testCase.addBoldTextEvidenceCurrentStep("Existen datos en la tabla xxcm_dv. Fecha: " + FechaBD);
	                                }

	                                System.out.println("Existen datos en la tabla xxcm_dv. Fecha: " + FechaBD);
	                            } else {
	                                result = false;
	                                System.out.println("No se obtuvo informacion.");
	                                return result;
	                            }
	                        }
	                    } else {
	                        result = false;
	                        System.out.println("No se obtuvo informacion.");
	                        return result;
	                    }
	                }
	            }

	            String fechaOriginal = FechaBD.trim();
	            LocalDate fechaConvert;

	            try {
	                fechaConvert = LocalDateTime.parse(fechaOriginal, DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")).toLocalDate();
	            } catch (Exception ex) {
	                fechaConvert = LocalDate.parse(fechaOriginal, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	            }

	            WebDriver driver = u.getDriver();
	            WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	            By btnToggle = By.xpath("//mat-datepicker-toggle/button");
	            wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

	            By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
	            wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

	            By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

	            if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
	                wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	            }

	            clickYear(driver, wait, fechaConvert.getYear());
	            clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

	            clickDay(driver, wait, fechaConvert.minusDays(1).getDayOfMonth());
	            clickDay(driver, wait, fechaConvert.getDayOfMonth());

	            wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));

	            consultarComprobantes(true);
	        }

	        result = true;
	        return result;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
	/**
	 * Valida la busqueda con filtro de Plaza y fecha en Directos.
	 * Obtiene la informacion de plaza y fecha del usuario especificado.
	 * @param usuario Usuario a buscar en la BD para validar existencia de datos
	 * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
	 * @return true si se encuentra informacion de plaza empoderada, false en caso contrario
	 * @throws Exception si ocurre algun error durante la validacion
	 * @author Jose Pecina
	 * @date Agosto 2025
	 */
	public boolean busquedaFiltroPlazaFechaCedis(String usuario, boolean screenshot) throws Exception {
	    try {
	        boolean result;
	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	        String dbUser = GlobalVariables.DB_USER_Cometa;
	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	        String PCPERFIL = "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' " +
	                "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

	        String PCRFC =
	                "select key_value " +
	                "from xxcm_user_keys " +
	                "where usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "') " +
	                "  and short_name in ('PCRFC','PCSUPPLIERID') " +
	                "order by case when short_name = 'PCRFC' then 0 else 1 end " +
	                "limit 1";

	        String FechaBD = null;

	        if (u.isDisplayed(xmlCRPLazaDirectos)) {
	            u.highLight(xmlCRPLazaDirectos);
	            u.mouseOverAndClick(xmlCRPLazaDirectos);
	            u.unhighLight(xmlCRPLazaDirectos);
	            u.waitWebElement(xmlCRPlazaOp1, 120, 10);
	            result = true;
	        } else {
	            return false;
	        }

	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	             Statement stmt = connection.createStatement();
	             ResultSet rs = stmt.executeQuery(PCPERFIL)) {

	            String perfil = null;
	            if (rs.next()) {
	                perfil = rs.getString("key_value");
	                System.out.println("Usuario con perfil: " + perfil);
	            }

	            boolean esAdmin = (perfil != null) &&
	                    ("ADMIN".equalsIgnoreCase(perfil) || "OXXO_OS".equalsIgnoreCase(perfil));

	            String RFC = null;
	            if (!esAdmin) {
	                try (ResultSet rs2 = stmt.executeQuery(PCRFC)) {
	                    if (!rs2.next()) {
	                        System.out.println("No se encontró PCRFC/PCSUPPLIERID para el usuario: " + usuario);
	                        return false;
	                    }
	                    RFC = rs2.getString("key_value");
	                }

	                if (RFC == null || RFC.trim().isEmpty()) {
	                    System.out.println("PCRFC/PCSUPPLIERID vacío para el usuario: " + usuario);
	                    return false;
	                }
	            }

	            String BodyPlaza = null;

	            if (!esAdmin) {
	                String Plazabd = "select plaza from xxcm_historico_cedis_view where supplier_id = '" + RFC + "' order by fecha_registro desc limit 1";
	                try (ResultSet rs5 = stmt.executeQuery(Plazabd)) {
	                    if (!rs5.next()) {
	                        System.out.println("No se obtuvo plaza para supplier_id: " + RFC);
	                        return false;
	                    }
	                    BodyPlaza = rs5.getString("plaza");
	                }
	            } else {
	                String Plazabd = "select plaza from xxcm_historico_cedis_view order by fecha_registro desc limit 1";
	                try (ResultSet rs5 = stmt.executeQuery(Plazabd)) {
	                    if (!rs5.next()) {
	                        System.out.println("No se obtuvo plaza (ADMIN).");
	                        return false;
	                    }
	                    BodyPlaza = rs5.getString("plaza");
	                }
	            }

	            By opcionPlaza = By.xpath("//div[contains(@class,'ng-option') and contains(normalize-space(),'" + BodyPlaza + "')]");
	            u.highLight(opcionPlaza);
	            if (screenshot) {
	                testCase.addScreenShotCurrentStep(u, "Seleccion de plaza");
	            }
	            u.click(opcionPlaza);
	            u.mouseOverAndClick(xmlCRPLazaDirectos);
	            u.getDriver().findElement(By.tagName("body")).click();

	            String sqlFechaRegistro;

	            if (!esAdmin) {
	                sqlFechaRegistro =
	                        "select fecha_registro " +
	                        "from xxcm_historico_cedis_view " +
	                        "where supplier_id = '" + RFC + "' " +
	                        "  and plaza = '" + BodyPlaza + "' " +
	                        "order by fecha_registro desc " +
	                        "limit 1";
	            } else {
	                sqlFechaRegistro =
	                        "select fecha_registro " +
	                        "from xxcm_historico_cedis_view " +
	                        "where plaza = '" + BodyPlaza + "' " +
	                        "order by fecha_registro desc " +
	                        "limit 1";
	            }

	            try (ResultSet rsFecha = stmt.executeQuery(sqlFechaRegistro)) {
	                if (!rsFecha.next()) {
	                    System.out.println("No se obtuvo fecha_registro.");
	                    return false;
	                }
	                java.sql.Timestamp ts = rsFecha.getTimestamp("fecha_registro");
	                if (ts == null) {
	                    System.out.println("fecha_registro viene null.");
	                    return false;
	                }
	                FechaBD = ts.toString();
	                System.out.println("Fecha seleccionada (fecha_registro): " + FechaBD);
	            }
	        }

	        if (FechaBD == null || FechaBD.trim().isEmpty()) {
	            return false;
	        }

	        LocalDate fechaConvert;
	        try {
	            fechaConvert = LocalDateTime.parse(FechaBD.replace(' ', 'T').substring(0, 19)).toLocalDate();
	        } catch (Exception ex) {
	            try {
	                fechaConvert = LocalDate.parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	            } catch (Exception ex2) {
	                fechaConvert = LocalDate.parse(FechaBD.substring(0, 10), DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	            }
	        }

	        WebDriver driver = u.getDriver();
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
	        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

	        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
	        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

	        By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
	        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

	        if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	        }

	        clickYear(driver, wait, fechaConvert.getYear());

	        // Si tu helper es 0-based, cambia a (fechaConvert.getMonthValue() - 1)
	        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

	        clickDay(driver, wait, fechaConvert.minusDays(1).getDayOfMonth());
	        clickDay(driver, wait, fechaConvert.getDayOfMonth());

	        wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));

	        consultarComprobantes(true);

	        return result;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
	/**
	 * Valida que exista informacion en la vista xxcm_historico_cedis_view.
	 * Obtiene los datos del usuario especificado para comprobar registros en BD.
	 * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
	 * @param usuario Usuario con el que se inicia sesion para obtener los datos requeridos
	 * @return true si se encuentran datos en la vista, false en caso contrario
	 * @throws Exception si ocurre algun error durante la validacion
	 * @author Jose Pecina
	 * @date Agosto 2025
	 */
	public boolean ValidaBDExistanDatosFiltrosGridCedis(boolean screenshot, String usuario) throws Exception {
	    try {
	        boolean result = true;

	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	        String dbUser = GlobalVariables.DB_USER_Cometa;
	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	        String queryPerfil =
	                "select key_value " +
	                "from xxcm_user_keys " +
	                "where short_name = 'PCPERFIL' " +
	                "and usuario_id = (" +
	                "    select usuario_id " +
	                "    from xxcm_usuarios " +
	                "    where usuario = ?" +
	                ") " +
	                "limit 1";

	        String queryRfc =
	                "select key_value " +
	                "from xxcm_user_keys " +
	                "where short_name in ('PCRFC', 'PCSUPPLIERID') " +
	                "and usuario_id = (" +
	                "    select usuario_id " +
	                "    from xxcm_usuarios " +
	                "    where usuario = ?" +
	                ") " +
	                "limit 1";

	        String queryExisteAdmin =
	                "select 1 " +
	                "from xxcm_historico_cedis_view " +
	                "limit 1";

	        String queryExistePorSupplier =
	                "select 1 " +
	                "from xxcm_historico_cedis_view " +
	                "where supplier_id::text = ? " +
	                "limit 1";

	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword)) {

	            String perfil = null;
	            try (PreparedStatement psPerfil = connection.prepareStatement(queryPerfil)) {
	                psPerfil.setString(1, usuario);
	                try (ResultSet rs = psPerfil.executeQuery()) {
	                    if (rs.next()) {
	                        perfil = rs.getString("key_value");
	                    }
	                }
	            }

	            if (perfil == null || perfil.trim().isEmpty()) {
	                perfil = "CEDIS";
	            }

	            if (screenshot) {
	                testCase.addBoldTextEvidenceCurrentStep("Usuario con perfil: " + perfil);
	            }
	            System.out.println("Usuario con perfil: " + perfil);

	            boolean esAdminUOxxoOs =
	                    "ADMIN".equalsIgnoreCase(perfil) ||
	                    "OXXO_OS".equalsIgnoreCase(perfil);

	            if (esAdminUOxxoOs) {
	                try (PreparedStatement psAdmin = connection.prepareStatement(queryExisteAdmin);
	                     ResultSet rs = psAdmin.executeQuery()) {

	                    if (rs.next()) {
	                        if (screenshot) {
	                            testCase.addBoldTextEvidenceCurrentStep("Existen datos en la tabla xxcm_historico_cedis_view");
	                        }
	                        System.out.println("Existen datos en la tabla xxcm_historico_cedis_view");
	                    } else {
	                        result = false;
	                        System.out.println("No se obtuvo informacion.");
	                    }
	                }
	            } else {
	                String rfc = null;

	                try (PreparedStatement psRfc = connection.prepareStatement(queryRfc)) {
	                    psRfc.setString(1, usuario);
	                    try (ResultSet rs = psRfc.executeQuery()) {
	                        if (rs.next()) {
	                            rfc = rs.getString("key_value");
	                        }
	                    }
	                }

	                if (rfc == null || rfc.trim().isEmpty()) {
	                    result = false;
	                    System.out.println("No se obtuvo RFC o SupplierId para el usuario.");
	                    return result;
	                }

	                try (PreparedStatement psExiste = connection.prepareStatement(queryExistePorSupplier)) {
	                    psExiste.setString(1, rfc.trim());
	                    try (ResultSet rs = psExiste.executeQuery()) {
	                        if (rs.next()) {
	                            if (screenshot) {
	                                testCase.addBoldTextEvidenceCurrentStep(
	                                        "Existen datos en la tabla xxcm_historico_cedis_view para supplier_id: " + rfc);
	                            }
	                            System.out.println("Existen datos en la tabla xxcm_historico_cedis_view para supplier_id: " + rfc);
	                        } else {
	                            result = false;
	                            System.out.println("No se obtuvo informacion.");
	                        }
	                    }
	                }
	            }
	        }

	        return result;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}
	/**
	 * Valida que las fechas en el grid esten ordenadas de mas recientes a mas antiguas.
	 * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
	 * @return true si todas las fechas estan en orden descendente, false si alguna no lo esta
	 * @throws Exception si ocurre algun error durante la validacion
	 * @author Jose Pecina
	 * @date Agosto 2025
	 */
	public boolean AutoGridDirectosFechas(boolean screenshot) throws Exception{
	    try {

	        u.waitWebElement(xmlDatosTablaDirect, 60, 5);
	        u.scrollToElement(xmlDatosTablaDirect);

	        String xpathBase = "/html/body/app-root/app-directos-devoluciones/div/directos-devoluciones-grid/div/table/tbody/tr/td[7]";

	        List<WebElement> fechasElems = u.getDriver().findElements(By.xpath(xpathBase));
	        List<LocalDate> fechas = new ArrayList<>();

	        DateTimeFormatter fmt = DateTimeFormatter.ofPattern("dd-MM-yyyy");

	        for (WebElement elem : fechasElems) {
	            String texto = elem.getText().trim();
	            if (!texto.isEmpty()) {
	                fechas.add(LocalDate.parse(texto, fmt));
	            }
	        }

	        for (int i = 0; i < fechas.size() - 1; i++) {
	            if (fechas.get(i).isBefore(fechas.get(i + 1))) {
	                System.out.println("Error: " + fechas.get(i) + " es más antigua que " + fechas.get(i+1));
	                return false;
	            }
	        }

	        if(screenshot) {
	            testCase.addTextEvidenceCurrentStep("Se visualizan los registros de Devoluciones ordenados del más reciente al más antiguo");
	            testCase.addScreenShotCurrentStep(u, "Pantalla Devoluciones");
	        }

	        System.out.println("Todas las fechas están en orden descendente");
	        return true;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception ("Error " + e.getMessage());
	    }
	}
