	/**
	 * Selecciona plazas una por una y toma evidencia visual del cambio en el campo Tienda.
	 * Solo valida un maximo de 5 plazas para evitar sesiones largas en el portal.
	 * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
	 * @return true si se encontraron tiendas para las plazas seleccionadas, false si no hay tiendas
	 * @throws Exception si ocurre algun error durante la seleccion o validacion
	 * @author Jose Pecina
	 * @date Agosto 2025
	 */
	public boolean SelectPlazaVsTienda(boolean screenshot) throws Exception {
	    try {
	        boolean hayTiendas = false;

	        u.waitWebElement(xmlCRPLazaDirectos, 5, 5);
	        if (!u.isDisplayed(xmlCRPLazaDirectos)) {
	            return false;
	        }

	        u.highLight(xmlCRPLazaDirectos);
	        u.mouseOverAndClick(xmlCRPLazaDirectos);
	        u.unhighLight(xmlCRPLazaDirectos);

	        u.waitWebElement(xmlCRPlazaOp1, 60, 5);

	        int totalPlazas = u.getDriver().findElements(
	                By.xpath("//div[@role='listbox']//div[@role='option']")
	        ).size();

	        int plazasAValidar = Math.min(totalPlazas, 5);

	        System.out.println("Cantidad de plazas encontradas: " + totalPlazas);
	        System.out.println("Cantidad de plazas a validar: " + plazasAValidar);

	        for (int i = 1; i <= plazasAValidar; i++) {
	            u.mouseOverAndClick(xmlCRPLazaDirectos);

	            By plazaActual = By.xpath("(//div[starts-with(@class, 'ng-option') and contains(@role, 'option')])[" + i + "]");
	            String nombrePlaza = u.getDriver().findElement(plazaActual).getText().trim();

	            u.highLight(plazaActual);
	            if (screenshot) {
	                testCase.addTextEvidenceCurrentStep("Plaza seleccionada: " + nombrePlaza);
	                testCase.addScreenShotCurrentStep(u, "Tiendas de plaza " + i + " - " + nombrePlaza);
	            }

	            u.click(plazaActual);
	            u.unhighLight(plazaActual);

	            u.hardWait(2);

	            u.mouseOverAndClick(xmlTiendaCedis);

	            if (screenshot) {
	                testCase.addTextEvidenceCurrentStep("Se muestran las tiendas de la plaza empoderada: " + nombrePlaza);
	                testCase.addScreenShotCurrentStep(u, "Tiendas de plaza " + i + " - " + nombrePlaza);
	            }

	            int totalTiendas = u.getDriver().findElements(
	                    By.xpath("//div[@role='listbox']//div[@role='option']")
	            ).size();

	            if (totalTiendas > 0) {
	                System.out.println("Tiendas encontradas para la plaza " + nombrePlaza + ": " + totalTiendas);
	                hayTiendas = true;
	            } else {
	                System.out.println("No se encontraron tiendas para la plaza " + nombrePlaza);
	            }
	        }

	        return hayTiendas;

	    } catch (Exception e) {
	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	        throw new Exception("Error " + e.getMessage());
	    }
	}


