    /**
     * Abre un archivo ZIP, valida cada PDF y verifica que el campo Plaza coincida con el filtro aplicado.
     * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
     * @return true si todos los PDF contienen la plaza correcta, false si alguna no coincide o no se encontro el archivo
     * @throws Exception si ocurre algun error al abrir el ZIP, leer los PDF o validar los datos
     * @author Jose Pecina
     * @date Agosto 2025
     */
	public Boolean validarTodasLasPlazasEnZIP(boolean screenshot) throws Exception {
	    String home = System.getProperty("user.home") + "\\Downloads";
	    File zipFile = getLastModified(home); // ZIP más reciente

	    if (zipFile == null || !zipFile.getName().endsWith(".zip")) {
	        return false;
	    }

	    // Crear carpeta temporal para extraer PDFs
	    File tempDir = new File(home, "temp_pdf_unzip_" + System.currentTimeMillis());
	    if (!tempDir.mkdir()) {
	        return false;
	    }

	    try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile))) {
	        ZipEntry entry;
	        while ((entry = zis.getNextEntry()) != null) {
	            if (!entry.isDirectory() && entry.getName().toLowerCase().endsWith(".pdf")) {
	                File pdfFile = new File(tempDir, entry.getName());
	                try (FileOutputStream fos = new FileOutputStream(pdfFile)) {
	                    byte[] buffer = new byte[1024];
	                    int len;
	                    while ((len = zis.read(buffer)) > 0) {
	                        fos.write(buffer, 0, len);
	                    }
	                }
	            }
	            zis.closeEntry();
	        }
	    }

	    String textoFiltro = u.getText(xmlDatoFiltroPlaza).trim();
	    File[] pdfs = tempDir.listFiles((dir, name) -> name.toLowerCase().endsWith(".pdf"));
	    
	    if (pdfs == null || pdfs.length == 0) {
	        return false;
	    }

	    for (File pdf : pdfs) {
	        try (PDDocument document = Loader.loadPDF(pdf)) {
	            PDFTextStripper stripper = new PDFTextStripper();
	            String textoCompleto = stripper.getText(document);
	            String[] lineas = textoCompleto.split("\\r?\\n");
	            String valorPlaza = null;

	            for (String linea : lineas) {
	                if (linea.trim().toLowerCase().startsWith("plaza:")) {
	                    valorPlaza = linea.substring(linea.indexOf(":") + 1).trim();
	                    break;
	                }
	            }

	            System.out.println("Texto filtro plaza: " + textoFiltro);
	            System.out.println("Plaza encontrada en PDF '" + pdf.getName() + "': " + valorPlaza);

	            if (valorPlaza == null) {
	                System.out.println("No se encontró ninguna línea con 'Plaza:' en el PDF.");
	                for (File f : pdfs) f.delete();
	                tempDir.delete();
	                return false;
	            }

	            if (!valorPlaza.equalsIgnoreCase(textoFiltro)) {
	                System.out.println("Plaza del PDF no coincide con el filtro.");
	                for (File f : pdfs) f.delete();
	                tempDir.delete();
	                return false;
	            } else {
	                System.out.println("Plaza del PDF coincide con el filtro.");
	            }

	        } catch (Exception e) {
	            // Falla si no se pudo leer algún PDF
	            for (File f : pdfs) f.delete();
	            tempDir.delete();
	            return false;
	        }
	    }
	    if (screenshot) {
	    	 java.awt.Desktop.getDesktop().open(zipFile);
	            u.hardWait(4);
	            testCase.addTextEvidenceCurrentStep("Plaza coincide en el o los PDF: " + textoFiltro);
	            testCase.addScreenShotCurrentStep("zip");
	            Robot robot = new Robot();
	            robot.keyPress(KeyEvent.VK_ALT);
	            robot.keyPress(KeyEvent.VK_F4);
	            robot.keyRelease(KeyEvent.VK_F4);
	            robot.keyRelease(KeyEvent.VK_ALT);
	    }
	    // Limpieza final
	    for (File f : pdfs) f.delete();
	    tempDir.delete();

	    return true;
	}
	
