 	/**
 	 * Valida que todos los valores de la columna "Plaza" en un archivo Excel coincidan con el filtro aplicado,
 	 * excepto el título de la columna.
 	 * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
 	 * @return true si todos los valores de la columna coinciden con el filtro, false si alguno no coincide o hay error
 	 * @author Jose Pecina
 	 * @date Agosto 2025
 	 */
	public Boolean validarColumnaPlazaConValor(boolean screenshot) {
	    String home = System.getProperty("user.home");
	    home = home + "\\Downloads";
	    File file = new File(getLastModified(home).getAbsolutePath());

	    try {
	    	String textoFiltro = u.getText(xmlDatoFiltroPlaza);
	        FileInputStream fis = new FileInputStream(file);
	        Workbook workbook = WorkbookFactory.create(fis);
	        Sheet sheet = workbook.getSheetAt(0);
	        Row headerRow = sheet.getRow(0);

	        int columnaPlaza = -1;

	        // Buscar el índice de la columna con encabezado "Plaza"
	        for (int i = 0; i < headerRow.getLastCellNum(); i++) {
	            String header = headerRow.getCell(i).getStringCellValue().trim();
	            if (header.equalsIgnoreCase("Plaza")) {
	                columnaPlaza = i;
	                break;
	            }
	        }

	        if (columnaPlaza == -1) {
	            testCase.addTextEvidenceCurrentStep("No se encontró la columna 'Plaza' en el archivo.");
	            System.out.println("Columna 'Plaza' no encontrada.");
	            workbook.close();
	            fis.close();
	            return false;
	        }

	        boolean todosIguales = true;

	        // Validar cada celda de la columna "Plaza"
	        for (int i = 1; i <= sheet.getLastRowNum(); i++) {
	            Row row = sheet.getRow(i);
	            if (row == null || row.getCell(columnaPlaza) == null) continue;

	            String valorCelda = row.getCell(columnaPlaza).toString().trim();
	            if (!valorCelda.equals(textoFiltro)) {
	                todosIguales = false;
	                testCase.addTextEvidenceCurrentStep("Fila " + (i + 1) + ": Se esperaba '" + textoFiltro + "', pero se encontró '" + valorCelda + "'");
	            }
	        }

	        workbook.close();
	        fis.close();

	        if (todosIguales) {
	        	if (screenshot) {
	            testCase.addTextEvidenceCurrentStep("Todos los valores de la columna 'Plaza' coinciden con '" + textoFiltro + "'");
	        	}
	            return true;
	        } else {
	            System.out.println("Algunos valores en la columna 'Plaza' no coinciden.");
	        }

	    } catch (IOException e) {
	        e.printStackTrace();
	    }

	    return false;
	}
	/**
	 * Abre el ultimo archivo ZIP descargado en la carpeta Downloads y toma screenshot.
	 * @param tipoArchivo Tipo de archivo que se va a abrir (para el nombre del screenshot)
	 * @param u Objeto Selenium para interacciones en la pagina
	 * @return true si el archivo se abre y se toma el screenshot correctamente, false si ocurre algun error o no se encuentra el archivo
	 * @author Jose Pecina
	 * @date Agosto 2025
	 */
	public boolean openLastFileZIPDownloadFolder(String tipoArchivo) {
	    String home = System.getProperty("user.home") + "\\Downloads";
	    File file = getLastModified(home);

	    if (file != null && file.exists() && file.getName().toLowerCase().endsWith(".zip")) {
	        try {
	            java.awt.Desktop.getDesktop().open(file);
	            u.hardWait(4);
	            testCase.addTextEvidenceCurrentStep("Se abre archivo correctamente");
	            testCase.addScreenShotCurrentStep(tipoArchivo);
	            Robot robot = new Robot();
	            robot.keyPress(KeyEvent.VK_ALT);
	            robot.keyPress(KeyEvent.VK_F4);
	            robot.keyRelease(KeyEvent.VK_F4);
	            robot.keyRelease(KeyEvent.VK_ALT);
	            return true;
	        } catch (Exception e) {
	            e.printStackTrace();
	            return false;
	        }
	    } else {
	        System.out.println("No se encontró archivo ZIP válido en la carpeta Downloads");
	        return false;
	    }
	}

	/**
	 * Abre el ultimo archivo PDF descargado en la carpeta Downloads y toma screenshot.
	 * @param tipoArchivo Tipo de archivo que se va a abrir (para el nombre del screenshot)
	 * @param u Objeto Selenium para interacciones en la pagina
	 * @return true si el archivo se abre y se toma el screenshot correctamente, false si ocurre algun error o no se encuentra el archivo
	 * @author Jose Pecina
	 * @date Agosto 2025
	 */
    public boolean openLastFilePDFDownloadFolder(String tipoArchivo) {
        String home = System.getProperty("user.home");
        home = home + "\\Downloads";
        System.out.println(home);
        System.out.println(getLastModified(home));

        File file = new File(getLastModified(home).getAbsolutePath());

        if(file.exists()) {
            try {
                u.getDriver().switchTo().newWindow(WindowType.WINDOW);
                ArrayList<String> tabs = new ArrayList<String> (u.getDriver().getWindowHandles());
                u.getDriver().switchTo().window(tabs.get(1)); //cambiar al tab del archivo
                u.get(file.getAbsolutePath());
                u.hardWait(4);
                testCase.addTextEvidenceCurrentStep("Se abre archivo correctamente");
                testCase.addScreenShotCurrentStep(tipoArchivo);
                u.getDriver().close();
				// Cerrar tab de el archivo
                u.getDriver().switchTo().window(tabs.get(0)); //regresar al tab de la pagina

            } catch (Exception e) {
                e.printStackTrace();
                return false;
            }
        } else {
            return false;
        }
        return true;
    }

	
	 /**
     * Metodo para abrir el ultimo archivo descargado
	 * @Param -> Tipo de archivo que se abrira
     * @author Yair Lizarraga
     * @return true si el archivo se abre y se toma el screenshot correctamente, false si ocurre algun error o no se encuentra el archivo
	 * @date Agosto 2024
     */
    public boolean openLastFileDownloadFolder(String tipoArchivo, boolean screenshot) {
        String home = System.getProperty("user.home");
        home = home + "\\Downloads";
        System.out.println(home);
        System.out.println(getLastModified(home));

        File file = new File(getLastModified(home).getAbsolutePath());

        //first check if Desktop is supported by Platform or not
        if(!Desktop.isDesktopSupported()){
            System.out.println("Desktop is not supported");
            return false;
        }

        Desktop desktop = Desktop.getDesktop();
        if(file.exists()) {
            try {
                desktop.open(file);
                u.hardWait(10);
                if (screenshot) {
                testCase.addTextEvidenceCurrentStep("Se abre archivo correctamente");
                testCase.addScreenShotCurrentStep(tipoArchivo);
                }
				Runtime.getRuntime().exec("cmd /c taskkill /f /im excel.exe");
            } catch (IOException e) {
                e.printStackTrace();
                return false;
            }
        } else {
            return false;
        }
        return true;
    }
    /**
     * Metodo para obtener el ultimo archivo descargado
	 * @param directoryFilePath -> direccion de el documento
     * @author Yair Lizarraga
	 * @date Agosto 2024
     */
    public static File getLastModified(String directoryFilePath) {
        File directory = new File(directoryFilePath);
        File[] files = directory.listFiles(File::isFile);
        long lastModifiedTime = Long.MIN_VALUE;
        File chosenFile = null;

        if (files != null)
        {
            for (File file : files)
            {
                if (file.lastModified() > lastModifiedTime)
                {
                    chosenFile = file;
                    lastModifiedTime = file.lastModified();
                }
            }
        }

        return chosenFile;
    }
	
