		/**
		 * Metodo para validar que los módulos del Portal Cometa se muestran centrados
		 * considerando layouts de 3 o 4 cards.
		 * 
		 * @author Alejandro Valdez
		 * @return True en caso de que se pueda validar que los modulos mostrados se 
		 * muestran centrados de manera correcta.
		 * @date Agosto 2025
		 */
		public boolean modulosCentrados() {
		    try {
		        WebDriver driver = u.getDriver();
		        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(15));
		        JavascriptExecutor js = (JavascriptExecutor) driver;

		        By cards = By.cssSelector("app-home a.card");

		        // Esperar a que haya al menos 3 módulos
		        wait.until(d -> d.findElements(cards).size() >= 3);

		        List<WebElement> listaCards = driver.findElements(cards);
		        int total = listaCards.size();

		        // Aceptamos solo 3 o 4 módulos
		        if (total != 3 && total != 4 && total != 5) {
		            System.out.println("[WARN] Cantidad de módulos inesperada: " + total);
		            testCase.addScreenShotCurrentStep("CantidadModulosInesperada_" + total);
		            return false;
		        }

		        // Tomar primera y última card visibles
		        WebElement primera = listaCards.get(0);
		        WebElement ultima = listaCards.get(total - 2);

		        @SuppressWarnings("unchecked")
		        Map<String, Number> rect = (Map<String, Number>) js.executeScript(
		            "const r1 = arguments[0].getBoundingClientRect();" +
		            "const r2 = arguments[1].getBoundingClientRect();" +
		            "return {left:r1.left, right:r2.right};",
		            primera, ultima
		        );

		        double left = rect.get("left").doubleValue();
		        double right = rect.get("right").doubleValue();

		        double viewportWidth = ((Number) js.executeScript(
		            "return document.documentElement.clientWidth;"
		        )).doubleValue();

		        double margenIzq = left;
		        double margenDer = viewportWidth - right;

		        double tolerancia = Math.max(20.0, viewportWidth * 0.05);

		        boolean centrado = Math.abs(margenIzq - margenDer) <= tolerancia;

		        testCase.addScreenShotCurrentStep("ModulosCentrados_" + total);

		        System.out.println("[INFO] módulos=" + total +
		                " margenIzq=" + margenIzq +
		                " margenDer=" + margenDer +
		                " tolerancia=" + tolerancia +
		                " centrado=" + centrado);

		        return centrado;

		    } catch (Exception e) {
		        System.out.println("[ERROR] Error en modulosCentrados: " + e.getMessage());
		        e.printStackTrace();
		        return false;
		    }
		}
	
