		/**
		 * Metodo para validar que la pantalla de Centro de Descargas en Portal Cometa 
		 * muestre los datos que fueron ingresados de manera correcta.
		 * @author Alejandro Valdez
		 * @return Retorna True si se valida que se muestra correctamente la información en los 
		 * campos de información de la pantalla de Centro de Descargas.
		 * @date Diciembre 2025
		 */
		public boolean valRegCentroDeDescargas() {
		    try {
		        if (!u.isDisplayed(btnLimpiarFiltros)) {
		            System.out.println("ERROR: No se visualiza btnLimpiarFiltros.");
		            return false;
		        }
		
		        u.hardWait(1);
		
		        boolean valid = true;
		        WebDriver driver = u.getDriver();
		
		        // ================= Fecha =================
		        System.out.println("=== Validando Fecha ===");
		        By celdaFecha = By.xpath("//app-centro-descargas//table//tbody/tr[1]/td[1]//span");
		        WebElement f = driver.findElement(celdaFecha);
		        String fechaRegistro = f.getText().trim();
		        System.out.println("Fecha en pantalla: " + fechaRegistro);
		
		        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
		        LocalDate fechaRegistroLD = LocalDate.parse(fechaRegistro, formatter);
		
		        System.out.println("Fecha esperada (fechaReg): " + fechaReg);
		        System.out.println("Fecha obtenida (fechaRegistroLD): " + fechaRegistroLD);
		
		        if (!fechaReg.equals(fechaRegistroLD)) {
		            System.out.println("ERROR: Las fechas NO coinciden");
		            valid = false;
		        } else {
		            System.out.println("SUCCESS: Las fechas coinciden");
		        }
		
		        // ================= Hora =================
		        System.out.println("=== Validando Hora ===");
		        By celdaHora = By.xpath("//app-centro-descargas//table//tbody/tr[1]/td[2]");
		        WebElement h = driver.findElement(celdaHora);
		        String horaRegistro = h.getText().trim();
		        System.out.println("Hora original en pantalla: " + horaRegistro);
		
		        // Normalizar "a.m." / "p.m." a "AM" / "PM"
		        horaRegistro = horaRegistro
		                .toLowerCase()
		                .replace("a. m.", "AM")
		                .replace("a.m.", "AM")
		                .replace("p. m.", "PM")
		                .replace("p.m.", "PM")
		                .trim();
		        System.out.println("Hora después de limpiar: " + horaRegistro);
		
		        DateTimeFormatter horaFormatter = DateTimeFormatter.ofPattern("h:mm a", Locale.ENGLISH);
		        LocalTime horaRegistroLT = LocalTime.parse(horaRegistro, horaFormatter);
		
		        LocalTime horaRegistroMin = horaRegistroLT.truncatedTo(ChronoUnit.MINUTES);
		        LocalTime horaRegMin = horaReg.truncatedTo(ChronoUnit.MINUTES);
		
		        System.out.println("Hora esperada (horaReg): " + horaRegMin);
		        System.out.println("Hora obtenida (horaRegistroMin): " + horaRegistroMin);
		
		        long diffMin = Math.abs(ChronoUnit.MINUTES.between(horaRegMin, horaRegistroMin));
		        if (diffMin > 1) { // tolerancia 1 minuto
		            System.out.println("ERROR: Las horas NO coinciden. Diferencia (min): " + diffMin);
		            valid = false;
		        } else {
		            System.out.println("SUCCESS: Hora dentro de tolerancia. Diferencia (min): " + diffMin);
		        }
		
		        // ================= Modulo =================
		        System.out.println("=== Validando Módulo ===");
		        By celdaModulo = By.xpath("//app-centro-descargas//table//tbody/tr[1]/td[3]");
		        WebElement m = driver.findElement(celdaModulo);
		        String moduloOrigen = m.getText().trim();
		
		        System.out.println("Módulo esperado: " + modulo);
		        System.out.println("Módulo obtenido: " + moduloOrigen);
		
		        if (!moduloOrigen.toLowerCase().contains(modulo.toLowerCase())) {
		            System.out.println("ERROR: Los módulos NO coinciden");
		            valid = false;
		        } else {
		            System.out.println("SUCCESS: Los módulos coinciden");
		        }
		
		        // ================= Nombre del Documento =================
		        System.out.println("=== Validando Nombre del Documento ===");
		        By celdaNombreDoc = By.xpath("//app-centro-descargas//table//tbody/tr[1]/td[4]");
		        WebElement nd = driver.findElement(celdaNombreDoc);
		        String nomDocumento = nd.getText().trim();
		
		        System.out.println("Nombre del documento en pantalla: " + nomDocumento);
		
		        LocalDate fechaConvert;
		        try {
		            // Si viene con hora (ej: 2025-11-18 15:44:05)
		            fechaConvert = LocalDateTime.parse(fecha, DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")).toLocalDate();
		        } catch (Exception ex) {
		            // Si viene solo fecha (ej: 2025-11-18)
		            fechaConvert = LocalDate.parse(fecha, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
		        }
		
		        // En UI el rango mostrado es mismo día (según tu HTML: 18_11_2025 al 18_11_2025)
		        String fechaFin = fechaConvert.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
		        String fechaInicioStr = fechaConvert.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
		
		        String nombreBaseEsperado = "Resumen_OC_" + fechaFin + "_" + fechaInicioStr;
		
		        System.out.println("Nombre esperado (base): " + nombreBaseEsperado);
		        System.out.println("Nombre obtenido: " + nomDocumento);
		
		        // UI suele traer extensión .xlsx, validamos por prefijo
		        if (!nomDocumento.startsWith(nombreBaseEsperado)) {
		            System.out.println("ERROR: El nombre del documento NO coincide");
		            valid = false;
		        } else {
		            System.out.println("SUCCESS: El nombre del documento coincide");
		        }
		
		        // ================= Filtros Aplicados =================
		        System.out.println("=== Validando Filtros ===");
		        By btnIconoFiltros = By.xpath("//app-centro-descargas//table//tbody/tr[1]/td[5]//mat-icon");
		        u.click(btnIconoFiltros);
		        u.hardWait(1);
		
		        // Tomar el rango de fecha (3er "cd-inner-cell") dentro del modal del dialog
		        By txtRangoFiltros = By.xpath(
		                "//app-centro-descargas-filters-dialog//div[contains(@class,'cd-inner-row')]//div[contains(@class,'cd-inner-cell')][3]"
		        );
		        WebElement fil = driver.findElement(txtRangoFiltros);
		        String filtros = fil.getText().trim();
		        System.out.println("Filtros en pantalla: '" + filtros + "'");
		
		        // UI usa dd_MM_yyyy
		        DateTimeFormatter uiFmt = DateTimeFormatter.ofPattern("dd_MM_yyyy");
		        String iniUI = fechaConvert.format(uiFmt);
		        String finUI = fechaConvert.format(uiFmt);
		        String txtEsperado = iniUI + " al " + finUI;
		
		        System.out.println("Filtros esperados: '" + txtEsperado + "'");
		
		        if (!txtEsperado.equals(filtros)) {
		            System.out.println("ERROR: Los filtros NO coinciden");
		            valid = false;
		        } else {
		            System.out.println("SUCCESS: Los filtros coinciden");
		        }
		
		        // Cerrar modal
		        By btnCerrarModal = By.xpath("//app-centro-descargas-filters-dialog//button[.//span[normalize-space()='Cerrar']]");
		        u.click(btnCerrarModal);
		        u.hardWait(1);
		
		        // ================= Estatus =================
		        System.out.println("=== Validando Estatus ===");
		        By iconoEstatus = By.xpath("//app-centro-descargas//table//tbody/tr[1]/td[6]//mat-icon");
		        WebElement est = driver.findElement(iconoEstatus);
		
		        if (!est.isDisplayed()) {
		            System.out.println("ERROR: No se encuentra visible el estatus");
		            valid = false;
		        } else {
		            System.out.println("SUCCESS: Estatus visible");
		        }
		
		        // ================= Descarga =================
		        System.out.println("=== Validando Descarga ===");
		        By iconoDescarga = By.xpath("//app-centro-descargas//table//tbody/tr[1]/td[7]//mat-icon");
		        WebElement downl = driver.findElement(iconoDescarga);
		
		        if (!downl.isDisplayed()) {
		            System.out.println("ERROR: No se encuentra visible el botón de descarga");
		            valid = false;
		        } else {
		            System.out.println("SUCCESS: Botón de descarga visible");
		        }
		
		        // ================= Eliminar =================
		        System.out.println("=== Validando Eliminar ===");
		        By iconoEliminar = By.xpath("//app-centro-descargas//table//tbody/tr[1]/td[8]//mat-icon");
		        WebElement delete = driver.findElement(iconoEliminar);
		
		        if (!delete.isDisplayed()) {
		            System.out.println("ERROR: No se encuentra visible el botón de Eliminar");
		            valid = false;
		        } else {
		            System.out.println("SUCCESS: Botón de eliminar visible");
		        }
		
		        System.out.println("=== RESULTADO FINAL: valid = " + valid + " ===");
		
		        u.hardWait(1);
		        testCase.addScreenShotCurrentStep("");
		        return valid;
		
		    } catch (Exception e) {
		        System.out.println("[ERROR] Ocurrió un error durante la ejecución: " + e.getMessage());
		        e.printStackTrace();
		        return false;
		    }
		}

		
