		/**
		 * Metodo para validar que el botón de descarga de comprobantes filtrados
		 * NO se muestre en la Pantalla de Comprobantes de Compra
		 * @author Alejandro Valdez
		 * @param tomarEvidencia true para capturar screenshot
		 * @return true si el botón NO se muestra, false si se muestra
		 * @date Enero 2026
		 */
		public boolean valDescargaCompFiltradosDeshabilitada(boolean tomarEvidencia) {
		    try {
		        u.hardWait(1);
		        WebDriver driver = u.getDriver();

		        List<WebElement> botones = driver.findElements(btnDescargaCompFilt);

		        //Caso 1: el botón NO existe en el DOM
		        if (botones.isEmpty()) {
		            System.out.println("SUCCESS: El botón NO existe en pantalla");

		            if (tomarEvidencia) {
		                testCase.addScreenShotCurrentStep("Botón NO visible (no existe)");
		            }
		            return true;
		        }

		        //Caso 2: existe pero NO es visible
		        if (!botones.get(0).isDisplayed()) {
		            System.out.println("SUCCESS: El botón existe pero NO es visible");

		            if (tomarEvidencia) {
		                testCase.addScreenShotCurrentStep("Botón NO visible");
		            }
		            return true;
		        }

		        //Caso incorrecto: el botón sí se muestra
		        System.out.println("ERROR: El botón SÍ se muestra en pantalla");

		        if (tomarEvidencia) {
		            u.highLight(btnDescargaCompFilt);
		            testCase.addScreenShotCurrentStep("ERROR - Botón visible");
		            u.unhighLight(btnDescargaCompFilt);
		        }

		        return false;

		    } catch (Exception e) {
		        System.out.println("Error al validar el botón: " + e.getMessage());
		        e.printStackTrace();
		        return false;
		    }
		}
		
