		/**
		 * Metodo para validar que el botón de descarga de comprobantes filtrados
		 * SÍ se muestre y esté habilitado en la Pantalla de Comprobantes de Compra
		 * 
		 * @author Alejandro Valdez
		 * @param tomarEvidencia true para capturar screenshot
		 * @return true si el botón está visible y habilitado, false en caso contrario
		 * @date Enero 2026
		 */
		public boolean valDescargaCompFiltradosHabilitada(boolean tomarEvidencia) {
		    try {
		        u.hardWait(1);
		        WebDriver driver = u.getDriver();

		        List<WebElement> botones = driver.findElements(btnDescargaCompFilt);

		        //Caso 1: el botón NO existe
		        if (botones.isEmpty()) {
		            System.out.println("ERROR: El botón NO existe en pantalla");

		            if (tomarEvidencia) {
		                testCase.addScreenShotCurrentStep("ERROR - Botón no existe");
		            }
		            return false;
		        }

		        WebElement boton = botones.get(0);

		        //Caso 2: existe pero NO es visible
		        if (!boton.isDisplayed()) {
		            System.out.println("ERROR: El botón existe pero NO es visible");

		            if (tomarEvidencia) {
		                testCase.addScreenShotCurrentStep("ERROR - Botón no visible");
		            }
		            return false;
		        }

		        //Caso 3: visible pero DESHABILITADO
		        if (!boton.isEnabled()) {
		            System.out.println("ERROR: El botón está visible pero DESHABILITADO");

		            if (tomarEvidencia) {
		                u.highLight(btnDescargaCompFilt);
		                testCase.addScreenShotCurrentStep("ERROR - Botón deshabilitado");
		                u.unhighLight(btnDescargaCompFilt);
		            }
		            return false;
		        }

		        //Caso correcto
		        System.out.println("SUCCESS: El botón está visible y HABILITADO");

		        if (tomarEvidencia) {
		        	u.scrollToElement(btnDescargaCompFilt);
		            u.highLight(btnDescargaCompFilt);
		            testCase.addScreenShotCurrentStep("Botón habilitado correctamente");
		            u.unhighLight(btnDescargaCompFilt);
		        }

		        return true;

		    } catch (Exception e) {
		        System.out.println("Error al validar el botón habilitado: " + e.getMessage());
		        e.printStackTrace();
		        return false;
		    }
		}
		
