		 /**
		 * Metodo para poder mostrar el explorador de archivos y mostrar la evidencia.
		 * 
		 * @date Agosto 2025
		 * @author Alejandro Valdez
		 * @param rutaCarpeta - Se realiza el apuntado al destino correspondiente
		 */
		 public void mostrarExploradorParaEvidencia(String rutaCarpeta) {
			    try {
			        // Abrir explorador en la ruta
			        String comandoAbrir = "cmd /c start \"\" explorer.exe \"" + rutaCarpeta + "\"";
			        Runtime.getRuntime().exec(comandoAbrir);

			        // Esperar a que abra
			        u.hardWait(4);

			        // Capturar evidencia
			        testCase.addScreenShotCurrentStep("Explorador_abierto");

			        // Esperar un poco
			        u.hardWait(2);

			        // Cerrar SOLO la ventana del explorador que tenga esa ruta
			        cerrarVentanaExplorerPorRuta(rutaCarpeta);

			        // Esperar a que cierre
			        u.hardWait(2);

			    } catch (Exception e) {
			        System.err.println("Error mostrando explorador: " + e.getMessage());
			    }
			}
		 /**
			 * Metodo para poder cerrar el explorador de archivos.
			 * 
			 * @date Agosto 2025
			 * @author Alejandro Valdez
			 * @param rutaCarpeta - Se realiza el apuntado al destino correspondiente
			 */
			private void cerrarVentanaExplorerPorRuta(String rutaCarpeta) {
			    try {
			        String ruta = new File(rutaCarpeta).getAbsolutePath();

			        // Escapar comillas para PowerShell
			        ruta = ruta.replace("\"", "\\\"");

			        String ps =
			            "$p = (Resolve-Path \"" + ruta + "\").Path; " +
			            "$sh = New-Object -ComObject Shell.Application; " +
			            "foreach($w in $sh.Windows()) { " +
			            "  try { " +
			            "    if($w -and $w.FullName -and ($w.FullName -like '*explorer.exe*')) { " +
			            "      $wp = $w.Document.Folder.Self.Path; " +
			            "      if($wp -eq $p) { $w.Quit() } " +
			            "    } " +
			            "  } catch {} " +
			            "}";

			        String comandoCerrar =
			            "powershell -NoProfile -ExecutionPolicy Bypass -Command \"" + ps + "\"";

			        Runtime.getRuntime().exec(comandoCerrar);

			    } catch (Exception e) {
			        System.err.println("Error cerrando ventana explorer por ruta: " + e.getMessage());
			    }
			}
		 /**
		 * Metodo para localizar y extraer el contenido del último archivo ZIP descargado hacia una carpeta específica.
		 * 
		 * @author Alejandro Valdez
		 * @param capturarEvidencia Booleano que determina si se debe abrir el explorador de archivos y capturar una captura de pantalla tras la extracción.
		 * @return True si el archivo ZIP fue localizado y extraído exitosamente; False si no se encontró el archivo o ocurrió un error durante el proceso.
		 * @date Agosto 2025
		 */
		 public boolean extraerZipSimple(boolean capturarEvidencia) {
		     try {
		         testCase.addTextEvidenceCurrentStep("Iniciando extracción de archivo ZIP...");
		         
		         String home = System.getProperty("user.home");
		         String downloadsPath = home + "\\Downloads";
		         testCase.addTextEvidenceCurrentStep("Buscando ZIP en: " + downloadsPath);

		         File ultimoZip = getLastModified(downloadsPath);

		         if (ultimoZip == null || !ultimoZip.getName().endsWith(".zip")) {
		             testCase.addTextEvidenceCurrentStep("ERROR: No se encontró archivo ZIP para extraer");
		             if (capturarEvidencia) {
		                 testCase.addScreenShotCurrentStep("No se encontró archivo ZIP");
		             }
		             return false;
		         }

		         testCase.addTextEvidenceCurrentStep("Archivo ZIP encontrado: " + ultimoZip.getName());
		         
		         String carpetaDestino = downloadsPath + "\\Extraidos";
		         new File(carpetaDestino).mkdirs();
		         testCase.addTextEvidenceCurrentStep("Carpeta de destino creada: " + carpetaDestino);

		         // Usar java.nio para extraer (Java 8+)
		         int archivosExtraidos = 0;
		         try (ZipInputStream zip = new ZipInputStream(new FileInputStream(ultimoZip))) {
		             ZipEntry entry;
		             while ((entry = zip.getNextEntry()) != null) {
		                 Path path = Paths.get(carpetaDestino, entry.getName());

		                 if (entry.isDirectory()) {
		                     Files.createDirectories(path);
		                     testCase.addTextEvidenceCurrentStep("Directorio creado: " + entry.getName());
		                 } else {
		                     Files.createDirectories(path.getParent());
		                     Files.copy(zip, path, StandardCopyOption.REPLACE_EXISTING);
		                     archivosExtraidos++;
		                 }
		             }
		         }
		         
		         testCase.addTextEvidenceCurrentStep("Extracción completada exitosamente.");
		         testCase.addTextEvidenceCurrentStep("Total de archivos extraídos: " + archivosExtraidos);
		         
		         if (capturarEvidencia) {
		             testCase.addTextEvidenceCurrentStep("Generando evidencia visual...");
		             mostrarExploradorParaEvidencia(carpetaDestino);
		         } else {
		             testCase.addTextEvidenceCurrentStep("Evidencia visual omitida (capturarEvidencia = false)");
		         }
		         
		         return true;

		     } catch (IOException ioEx) {
		         testCase.addTextEvidenceCurrentStep("ERROR DE I/O: No se pudo extraer el archivo ZIP");
		         testCase.addTextEvidenceCurrentStep("Mensaje de error: " + ioEx.getMessage());
		         if (capturarEvidencia) {
		             testCase.addScreenShotCurrentStep("Error extrayendo ZIP - IOException");
		         }
		         ioEx.printStackTrace();
		         return false;
		     } catch (Exception e) {
		         testCase.addTextEvidenceCurrentStep("ERROR INESPERADO al extraer ZIP");
		         testCase.addTextEvidenceCurrentStep("Mensaje de error: " + e.getMessage());
		         if (capturarEvidencia) {
		             testCase.addScreenShotCurrentStep("Error extrayendo ZIP: " + e.getMessage());
		         }
		         e.printStackTrace();
		         return false;
		     }
		 }
		 
