		 /**
		 * Metodo para validar que, al interactuar con un estatus fallido, se despliegue un Pop-up con el mensaje de error técnico esperado.
		 * @author Alejandro Valdez
		 * @param tomarEvidencia Booleano para capturar la evidencia del mensaje de error resaltado.
		 * @return True si el mensaje aparece y el texto coincide exactamente con "Este es un error de prueba".
		 * @date Diciembre 2025
		 */
		  public boolean valMensajeEstatusFallido(boolean tomarEvidencia) {
		         try {
		             if (u.waitWebElement(chkFalido, 30, 2).isDisplayed()) {
		                 u.mouseOverAndClick(chkFalido);

		                 try {
		                     WebDriverWait wait = new WebDriverWait(u.getDriver(), Duration.ofSeconds(10));
		                     WebElement mensaje = wait.until(
		                         ExpectedConditions.visibilityOfElementLocated(msgErrorCD)
		                     );

		                     String textoEsperado = "Este es un error de prueba";
		                     String textoObtenido = mensaje.getText().trim();

		                     System.out.println("Texto obtenido: [" + textoObtenido + "]");

		                     if (!textoObtenido.equals(textoEsperado)) {
		                         System.out.println("ERROR: El texto del mensaje no coincide");
		                         System.out.println("Esperado: [" + textoEsperado + "]");
		                         System.out.println("Obtenido: [" + textoObtenido + "]");

		                         if (tomarEvidencia) {
		                             u.highLight(msgErrorCD);
		                             testCase.addScreenShotCurrentStep("Error - Texto de mensaje incorrecto");
		                             u.unhighLight(msgErrorCD);
		                         }
		                         return false;
		                     }

		                     System.out.println("SUCCESS: Mensaje de error correcto mostrado");

		                     if (tomarEvidencia) {
		                         u.highLight(msgErrorCD);
		                         testCase.addScreenShotCurrentStep("Evidencia - Mensaje de error correcto");
		                         u.unhighLight(msgErrorCD);
		                     }

		                     return true;

		                 } catch (TimeoutException e) {
		                     System.out.println("ERROR: No se mostró el mensaje de error");
		                     if (tomarEvidencia) {
		                         testCase.addScreenShotCurrentStep("Error - Mensaje de error no apareció");
		                     }
		                     return false;
		                 }

		             } else {
		                 if (tomarEvidencia) {
		                     testCase.addScreenShotCurrentStep("Fallo - Mensaje Error no visible");
		                 }
		                 System.out.println("El Mensaje Error no está visible en pantalla.");
		                 return false;
		             }

		         } catch (Exception e) {
		             if (tomarEvidencia) {
		                 testCase.addScreenShotCurrentStep("Evidencia - Excepción en valMensajeEstatusFallido");
		             }
		             System.err.println("Error en valMensajeEstatusFallido: " + e.getMessage());
		             e.printStackTrace();
		             return false;
		         }
		     }

		 /**
		 * Metodo para validar que el nombre del archivo descargado físicamente en el equipo coincida con el nombre registrado en el portal.
		 * @author Alejandro Valdez
		 * @return True si el archivo existe en descargas y su nombre normalizado coincide con el del registro del portal.
		 * @date Diciembre 2025
		 */
		  public boolean validarDescargaCentroDescargas() {
		         u.hardWait(3);
		         String home = System.getProperty("user.home") + "\\Downloads";

		         String NomDocumento = nombreUltimoArchivoDescargas;
		         System.out.println("Nombre del documento en portal: " + NomDocumento);

		         try {
		             File ultimoArchivo = getLastModified(home);

		             String nombrePortalNormalizado = normalizarNombreDescarga(NomDocumento);
		             String nombreArchivoNormalizado = normalizarNombreDescarga(ultimoArchivo.getName());

		             boolean valid =
		                     ultimoArchivo.exists()
		                     && ultimoArchivo.isFile()
		                     && nombreArchivoNormalizado.contains(nombrePortalNormalizado);

		             mostrarExploradorParaEvidencia(home);

		             if (!valid) {
		                 System.out.println("ERROR: El archivo descargado no coincide con el nombre del portal");
		                 System.out.println("Portal normalizado: " + nombrePortalNormalizado);
		                 System.out.println("Archivo normalizado: " + nombreArchivoNormalizado);
		             } else {
		                 System.out.println("SUCCESS: El archivo descargado coincide con el nombre del portal");
		             }

		             return valid;

		         } catch (Exception e) {
		             mostrarExploradorParaEvidencia(home);
		             System.err.println("Error en validación de descarga: " + e.getMessage());
		             return false;
		         }
		     }

