		 /**
		 * Metodo para validar la integridad del grid de Devoluciones verificando la presencia de las 12 columnas obligatorias.
		 * @author Alejandro Valdez
		 * @return True si todas las columnas (FA, Proveedor, Región, Plaza, Tienda, Fecha, Folio, Tiempos y Totales) son visibles.
		 * @date Septiembre 2025
		 */
		 public boolean columnasGridDev() {
		     try {
		         boolean todasLasColumnasPresentes = true;
		         int columnasValidadas = 0;

		         // Array de columnas con sus nombres descriptivos
		         Object[][] columnas = {
		             {clmFa, "Fuente de Abasto"},
		             {clmNombreProv, "Nombre del proveedor"},
		             {clmRegion, "Región"},
		             {clmPlaza, "Plaza"},
		             {clmCrTienda, "CR Tienda"},
		             {clmDate, "Fecha"},
		             {clmFolio, "Folio"},
		             {clmTimeDev, "Tiempo de devolución"},
		             {clmTotArtDev, "Total de artículos a devolver"},
		             {clmTotPzaDev, "Total de piezas a devolver"},
		             {clmValorTot, "Valor Total"},
		             {clmTotalCost, "Total Costo"}
		         };

		         // Validar cada columna
		         for (Object[] columna : columnas) {
		             By localizador = (By) columna[0];
		             String nombreColumna = (String) columna[1];
		             
		             try {
		                 if (u.isDisplayed(localizador)) {
		                     System.out.println("Columna presente: " + nombreColumna);
		                     columnasValidadas++;
		                 } else {
		                     System.out.println("Columna NO visible: " + nombreColumna);
		                     todasLasColumnasPresentes = false;
		                 }
		             } catch (Exception e) {
		                 System.out.println("Columna NO encontrada: " + nombreColumna + " - Error: " + e.getMessage());
		                 todasLasColumnasPresentes = false;
		             }
		         }

		         System.out.println("Columnas validadas: " + columnasValidadas + "/" + columnas.length);
		         
		         if (todasLasColumnasPresentes) {
		             System.out.println("ÉXITO: Todas las columnas están presentes y visibles");
		             testCase.addScreenShotCurrentStep("Todas las columnas del grid validadas correctamente");
		             u.hardWait(1);
		             return true;
		         } else {
		             System.out.println("FALLO: No todas las columnas están presentes");
		             testCase.addScreenShotCurrentStep("Error: Faltan columnas en el grid - " + columnasValidadas + "/" + columnas.length + " presentes");
		             return false;
		         }

		     } catch (Exception e) {
		         System.err.println("Error general en columnasGridDev: " + e.getMessage());
		         testCase.addScreenShotCurrentStep("Error en validación de columnas: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

		 /**
		 * Metodo para validar mediante expresiones regulares que las columnas de costo y valor total tengan un formato de moneda correcto ($ X.XX).
		 * @author Alejandro Valdez
		 * @return True si ambas celdas contienen el símbolo de moneda y exactamente dos decimales.
		 * @date Septiembre 2025
		 */
		 public boolean validarFormatoMonedaElementosEspecificos() {
		     try {
		         WebDriver driver = u.getDriver();
		         
		         // Localizadores específicos para los elementos solicitados
		         By elementoValorTotal = By.xpath("//tbody/tr[1]/td[12]");
		         By elementoTotalCosto = By.xpath("//tbody/tr[1]/td[13]");
		         
		         // Patrón regex para validar formato de moneda: $ seguido de números con 2 decimales
		         String patronMoneda = "^\\$\\s?[\\d,]+\\.\\d{2}$";
		         
		         boolean validacionExitosa = true;
		         
		         System.out.println("=== Validando formato de moneda en elementos específicos ===");
		         
		         // Validar primer elemento (columna 12)
		         System.out.println("\n--- Validando elemento //tbody/tr[1]/td[12] ---");
		         WebElement elemento12 = driver.findElement(elementoValorTotal);
		         String valor12 = elemento12.getText().trim();
		         
		         if (valor12.isEmpty()) {
		             System.out.println("Elemento td[12]: Celda vacía");
		             validacionExitosa = false;
		         } else if (valor12.matches(patronMoneda)) {
		             System.out.println("Elemento td[12]: " + valor12 + " (formato correcto)");
		         } else {
		             System.out.println("Elemento td[12]: " + valor12 + " (formato incorrecto)");
		             System.out.println("Formato esperado: $X.XX (con $ y exactamente 2 decimales)");
		             validacionExitosa = false;
		         }
		         
		         // Validar segundo elemento (columna 13)
		         System.out.println("\n--- Validando elemento //tbody/tr[1]/td[13] ---");
		         WebElement elemento13 = driver.findElement(elementoTotalCosto);
		         String valor13 = elemento13.getText().trim();
		         
		         if (valor13.isEmpty()) {
		             System.out.println("Elemento td[13]: Celda vacía");
		             validacionExitosa = false;
		         } else if (valor13.matches(patronMoneda)) {
		             System.out.println("Elemento td[13]: " + valor13 + " (formato correcto)");
		         } else {
		             System.out.println("Elemento td[13]: " + valor13 + " (formato incorrecto)");
		             System.out.println("Formato esperado: $X.XX (con $ y exactamente 2 decimales)");
		             validacionExitosa = false;
		         }
		         
		         // Resumen final
		         System.out.println("\n=== Resumen de validación ===");
		         if (validacionExitosa) {
		             System.out.println("ÉXITO: Ambos elementos tienen el formato de moneda correcto");
		             System.out.println("td[12]: " + valor12);
		             System.out.println("td[13]: " + valor13);
		             testCase.addScreenShotCurrentStep("Formato de moneda validado - td[12]: " + valor12 + ", td[13]: " + valor13);
		         } else {
		             System.out.println("FALLO: Uno o ambos elementos NO tienen el formato de moneda correcto");
		             System.out.println("td[12]: " + valor12 + (valor12.matches(patronMoneda) ? " " : " "));
		             System.out.println("td[13]: " + valor13 + (valor13.matches(patronMoneda) ? " " : " "));
		             testCase.addScreenShotCurrentStep("Error en formato de moneda - td[12]: " + valor12 + ", td[13]: " + valor13);
		         }
		         
		         return validacionExitosa;
		         
		     } catch (Exception e) {
		         System.err.println("Error en validarFormatoMonedaElementosEspecificos: " + e.getMessage());
		         testCase.addScreenShotCurrentStep("Error al validar formato de moneda: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

