		 /**
		 * Metodo para navegar a la siguiente página de resultados y validar que el contenido de la tabla se haya actualizado efectivamente.
		 * @author Alejandro Valdez
		 * @param tomarEvidencia Booleano para capturar el estado antes del cambio de página.
		 * @return True si el registro de la nueva página es distinto al de la página anterior.
		 * @date Diciembre 2025
		 */
		 public boolean opcSigPaginaCD(boolean tomarEvidencia) {
		     try {
		         if (u.isDisplayed(btnPagSiguienteCD)) {
		             // Obtener el dato del ultimo registro mostrado en la pagina principal.
		             WebElement pP = u.getDriver().findElement(
		                     By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/table/tbody/tr[20]/td[2]/span")
		             );
		             String pagPrincipal = pP.getText().trim();
		             System.out.println("Registro antes de cambiar página: " + pagPrincipal);

		             u.highLight(btnPagSiguienteCD);

		             if (tomarEvidencia) {
		                 testCase.addScreenShotCurrentStep("Evidencia - Antes de ir a página siguiente");
		             }

		             u.click(btnPagSiguienteCD);
		             u.unhighLight(btnPagSiguienteCD);
		             u.hardWait(2); // Aumentar espera para que cargue la nueva página

		             // Obtener el dato del ultimo registro mostrado en la primera pagina.
		             WebElement pPg = u.getDriver().findElement(
		                     By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/table/tbody/tr[20]/td[2]/span")
		             );
		             String primPag = pPg.getText().trim();
		             System.out.println("Registro después de cambiar página: " + primPag);

		             if (primPag.equals(pagPrincipal)) {
		                 System.out.println("ERROR: Los datos de los registros NO cambiaron");
		                 return false;
		             } else {
		                 System.out.println("SUCCESS: Los datos cambiaron correctamente");
		             }

		             System.out.println("Botón 'Pagina Siguiente' seleccionado correctamente.");
		             return true;
		         } else {
		             System.out.println("Botón 'Pagina Siguiente' no está visible.");
		             return false;
		         }
		     } catch (Exception e) {
		         System.err.println("Error en opcSigPaginaCD: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

