		 /**
		 * Metodo para validar que la cantidad de filas renderizadas en la tabla sea idéntica al valor seleccionado en el paginador.
		 * @author Alejandro Valdez
		 * @param cantidad Número esperado de registros a visualizar.
		 * @param tomarEvidencia true = toma screenshot, false = no
		 * @return true si el conteo de elementos <tr> coincide con el parámetro de cantidad.
		 * @date Diciembre 2025
		 */
		 public boolean valCantidadRegistrosMostrados(int cantidad, boolean tomarEvidencia) {
		     try {
		         // Obtener todas las filas visibles del grid (pagina principal)
		         List<WebElement> filas = u.getDriver().findElements(
		             By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/table/tbody/tr")
		         );

		         int totalFilas = filas.size();

		         System.out.println("Cantidad seleccionada: " + cantidad);
		         System.out.println("Cantidad de registros mostrados: " + totalFilas);

		         // Validación estricta
		         if (totalFilas != cantidad) {
		             System.out.println("ERROR: La cantidad de registros NO coincide con la seleccionada");

		             if (tomarEvidencia) {
		                 testCase.addScreenShotCurrentStep(
		                     "Error - Registros mostrados: " + totalFilas + " / Esperados: " + cantidad
		                 );
		             }
		             return false;
		         }

		         // Evidencia opcional
		         if (tomarEvidencia) {
		             testCase.addScreenShotCurrentStep(
		                 "SUCCESS - Registros mostrados correctamente: " + totalFilas
		             );
		         }

		         System.out.println("SUCCESS: La cantidad de registros coincide exactamente");
		         return true;

		     } catch (Exception e) {
		         System.out.println("Error al validar cantidad de registros mostrados: " + e.getMessage());
		         e.printStackTrace();

		         if (tomarEvidencia) {
		             testCase.addScreenShotCurrentStep("Error - Excepción al validar registros");
		         }
		         return false;
		     }
		 }

