		 /**
		 * Metodo para seleccionar una cantidad específica de registros por página y validar que el cambio se refleje en el selector.
		 * @author Alejandro Valdez
		 * @param cantidad Valor numérico (5, 10, 15, 20) que se desea aplicar al filtro.
		 * @return True si la opción es seleccionada y el texto del componente se actualiza con el valor elegido.
		 * @date Diciembre 2025
		 */
		 public boolean selCantidadDeRegistrosPorPagina(int cantidad) {
		     try {
		         if (u.waitWebElement(btnFiltroPorPagina, 10, 2).isDisplayed()) {

		             // Seleccionar la cantidad de registros de acuerdo a lo que elija el usuario
		             u.click(By.xpath("(//span[normalize-space()='"+cantidad+"'])[1]"));
		             u.hardWait(1); // Esperar a que se actualice

		             // Validar que se muestre la cantidad seleccionada en el box del Filtro
		             WebElement fil = u.getDriver().findElement(
		                     By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/mat-paginator/div/div/div[1]/mat-form-field/div[1]/div/div[2]/mat-select/div/div[1]/span/span")
		             );
		             String filtros = fil.getText().trim();
		             String cantidadStr = String.valueOf(cantidad); // Convertir int a String

		             System.out.println("Cantidad esperada: " + cantidadStr);
		             System.out.println("Cantidad mostrada: " + filtros);

		             if (!filtros.equals(cantidadStr)) {
		                 System.out.println("ERROR: El filtro no coincide con la cantidad");
		                 testCase.addScreenShotCurrentStep("Error - Filtro no coincide");
		                 return false;
		             } else {
		                 System.out.println("SUCCESS: Los filtros coinciden");
		                 u.highLight(btnFiltroPorPagina);
		                 testCase.addScreenShotCurrentStep("Evidencia - Cantidad de registros seleccionada: " + cantidad);
		                 u.unhighLight(btnFiltroPorPagina);
		                 return true;
		             }
		         }
		         return false;
		     } catch (Exception e) {
		         System.out.println("Error al seleccionar cantidad de registros: " + e.getMessage());
		         e.printStackTrace();
		         testCase.addScreenShotCurrentStep("Error - Excepción al seleccionar registros");
		         return false;
		     }
		 }

