		 /**
		 * Metodo para validar que la fecha mínima habilitada en el calendario no exceda un límite de 7 días naturales hacia el pasado.
		 * @author Alejandro Valdez
		 * @param tomarEvidencia Booleano para capturar evidencia visual de la fecha mínima detectada en la UI.
		 * @return True si la fecha mínima seleccionable es igual o posterior a la fecha actual menos 7 días; False si permite fechas más antiguas o si ocurre un error.
		 * @date Diciembre 2025
		 */
		 public boolean validarFechaMinimaCalendarioCD(boolean tomarEvidencia) {
			    try {
			        WebDriver driver = u.getDriver();

			        // Header visible del calendario: ej "ENE 2026"
			        By headerPeriodo = By.cssSelector("mat-calendar mat-calendar-header .mat-calendar-period-button span[aria-hidden='true']");
			        WebElement header = driver.findElement(headerPeriodo);

			        String mesAnioTexto = header.getText();
			        if (mesAnioTexto == null) mesAnioTexto = "";
			        mesAnioTexto = mesAnioTexto.trim();
			        System.out.println("Header calendario: '" + mesAnioTexto + "'");

			        YearMonth mesAnio = parseYearMonthEs3(mesAnioTexto);
			        if (mesAnio == null) {
			            System.out.println("ERROR: No se pudo interpretar mes y año del header: '" + mesAnioTexto + "'");
			            return false;
			        }

			        // ======== PRIMER DIA HABILITADO ========
			        By primerDiaHabilitado = By.xpath(
			            "//mat-month-view//td[contains(@class,'mat-calendar-body-cell-container')]" +
			            "//button[contains(@class,'mat-calendar-body-cell') and not(contains(@class,'mat-calendar-body-disabled'))][1]"
			        );

			        WebElement btnDia = driver.findElement(primerDiaHabilitado);

			        String aria = btnDia.getAttribute("aria-label");
			        if (aria == null) aria = "";
			        aria = aria.trim();
			        System.out.println("aria-label primer dia habilitado: '" + aria + "'");

			        Integer diaMinimo = null;

			        try {
			            String[] parts = aria.split(" ");
			            if (parts.length > 0) {
			                diaMinimo = Integer.parseInt(parts[0].replaceAll("[^0-9]", ""));
			            }
			        } catch (Exception ignore) { }

			        if (diaMinimo == null) {

			            WebElement spanDia = btnDia.findElement(By.cssSelector("span.mat-calendar-body-cell-content"));
			            String txtDia = spanDia.getText();

			            if (txtDia == null) txtDia = "";
			            txtDia = txtDia.trim();

			            if (txtDia.isEmpty()) {
			                System.out.println("ERROR: No se pudo obtener el dia minimo habilitado.");
			                return false;
			            }

			            diaMinimo = Integer.parseInt(txtDia);
			        }

			        LocalDate fechaMinCalendario = LocalDate.of(
			            mesAnio.getYear(),
			            mesAnio.getMonth(),
			            diaMinimo
			        );

			        // ======== ULTIMO DIA HABILITADO (MAXIMO) ========

			        By ultimoDiaHabilitado = By.xpath(
			            "(//mat-month-view//button[contains(@class,'mat-calendar-body-cell') and not(contains(@class,'mat-calendar-body-disabled'))])[last()]"
			        );

			        WebElement btnUltimoDia = driver.findElement(ultimoDiaHabilitado);

			        String ariaMax = btnUltimoDia.getAttribute("aria-label");

			        if (ariaMax == null) ariaMax = "";
			        ariaMax = ariaMax.trim();

			        System.out.println("aria-label ultimo dia habilitado: '" + ariaMax + "'");

			        Integer diaMaximo = null;

			        try {
			            String[] parts = ariaMax.split(" ");
			            if (parts.length > 0) {
			                diaMaximo = Integer.parseInt(parts[0].replaceAll("[^0-9]", ""));
			            }
			        } catch (Exception ignore) {}

			        if (diaMaximo == null) {

			            WebElement spanDia = btnUltimoDia.findElement(By.cssSelector("span.mat-calendar-body-cell-content"));
			            String txtDia = spanDia.getText();

			            if (txtDia == null) txtDia = "";
			            txtDia = txtDia.trim();

			            diaMaximo = Integer.parseInt(txtDia);
			        }

			        fechaMaxCalendario = LocalDate.of(
			            mesAnio.getYear(),
			            mesAnio.getMonth(),
			            diaMaximo
			        );

			        System.out.println("Fecha máxima visible calendario: " + fechaMaxCalendario);

			        // ======== VALIDACION ORIGINAL ========

			        LocalDate fechaLimite = LocalDate.now().minusDays(6);

			        System.out.println("Fecha mínima UI: " + fechaMinCalendario);
			        System.out.println("Fecha límite permitida: " + fechaLimite);

			        if (tomarEvidencia) {
			            testCase.addScreenShotCurrentStep("Evidencia - Fecha mínima calendario");
			        }

			        if (fechaMinCalendario.isBefore(fechaLimite)) {
			            System.out.println("ERROR: El calendario permite seleccionar fechas mas antiguas que 7 dias.");
			            return false;
			        }

			        System.out.println("SUCCESS: Fecha mínima válida");
			        return true;

			    } catch (Exception e) {
			        System.out.println("ERROR validarFechaMinimaCalendarioCD: " + e.getMessage());
			        e.printStackTrace();
			        return false;
			    }
			}

		 /**
		 * Metodo para realizar un parseo robusto de cadenas de texto que representan Mes y Año (ej. "ENE 2026") a un objeto YearMonth.
		 * @author Alejandro Valdez
		 * @param mesAnioTexto Cadena de texto extraída del header del calendario.
		 * @return Un objeto YearMonth con el mes y año correspondientes; null si el formato es inválido o el mes no es reconocido.
		 * @date Diciembre 2025
		 */
		 private YearMonth parseYearMonthEs3(String mesAnioTexto) {
		     if (mesAnioTexto == null) return null;

		     String t = mesAnioTexto.trim().toLowerCase();
		     t = t.replace(".", "");
		     t = t.replaceAll("\\s+", " ");

		     String[] parts = t.split(" ");
		     if (parts.length < 2) return null;

		     String mes = parts[0];
		     String anioStr = parts[1];

		     int year;
		     try {
		         year = Integer.parseInt(anioStr.replaceAll("[^0-9]", ""));
		     } catch (Exception e) {
		         return null;
		     }

		     int month;
		     if ("ene".equals(mes)) month = 1;
		     else if ("feb".equals(mes)) month = 2;
		     else if ("mar".equals(mes)) month = 3;
		     else if ("abr".equals(mes)) month = 4;
		     else if ("may".equals(mes)) month = 5;
		     else if ("jun".equals(mes)) month = 6;
		     else if ("jul".equals(mes)) month = 7;
		     else if ("ago".equals(mes)) month = 8;
		     else if ("sep".equals(mes) || "set".equals(mes)) month = 9;
		     else if ("oct".equals(mes)) month = 10;
		     else if ("nov".equals(mes)) month = 11;
		     else if ("dic".equals(mes)) month = 12;
		     else return null;

		     return YearMonth.of(year, month);
		 }

