		 /**
		 * Metodo para seleccionar el rango completo de fechas habilitadas en el calendario, marcando desde el primer día disponible hasta el último.
		 * @author Alejandro Valdez
		 * @param tomarEvidencia Booleano para capturar registro visual de la selección del rango.
		 * @return True si se logran identificar días habilitados y se completan las selecciones del rango; False en caso de error.
		 * @date Diciembre 2025
		 */
		 public boolean seleccionarPrimerYUltimoDiaCalendarioCD(boolean tomarEvidencia) {
		     try {

		         // Obtener todos los días habilitados del calendario visible
		         List<WebElement> diasHabilitados = u.getDriver().findElements(
		             By.xpath(
		                 "//mat-month-view//button[contains(@class,'mat-calendar-body-cell')" +
		                 " and not(contains(@class,'mat-calendar-body-disabled'))]"
		             )
		         );

		         if (diasHabilitados.isEmpty()) {
		             System.out.println("ERROR: No se encontraron días habilitados en el calendario");
		             return false;
		         }

		         // Primer día habilitado
		         WebElement primerDia = diasHabilitados.get(0);;
		         primerDia.click();
		         u.hardWait(1);

		         // Volver a obtener los días (el calendario se refresca tras el primer click)
		         diasHabilitados = u.getDriver().findElements(
		             By.xpath(
		                 "//mat-month-view//button[contains(@class,'mat-calendar-body-cell')" +
		                 " and not(contains(@class,'mat-calendar-body-disabled'))]"
		             )
		         );

		         if (diasHabilitados.isEmpty()) {
		             System.out.println("ERROR: No se encontraron días habilitados tras seleccionar el primero");
		             return false;
		         }

		         // Último día habilitado
		         WebElement ultimoDia = diasHabilitados.get(diasHabilitados.size() - 1);
		         String txtPrimer = ultimoDia.getText();
		         System.out.println(txtPrimer);
		         ultimoDia.click();

		         if (tomarEvidencia) {
		             u.hardWait(1);
		             testCase.addScreenShotCurrentStep("Evidencia");
		         }

		         System.out.println("SUCCESS: Primer y último día habilitado seleccionados correctamente");
		         return true;

		     } catch (Exception e) {
		         System.out.println("ERROR seleccionarPrimerYUltimoDiaCalendarioCD: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

