		 /**
		 * Metodo para verificar que los registros mostrados en la tabla correspondan estrictamente al rango de fechas seleccionado.
		 * @author Alejandro Valdez
		 * @param tomarEvidencia Booleano para capturar evidencia visual de la validación entre páginas.
		 * @return True si tanto el primer registro de la lista como el último de la página final respetan los límites del filtro.
		 * @date Diciembre 2025
		 */
		 public boolean validarRegistrosContraRangoFechasCD(boolean tomarEvidencia) {
		     try {
		         WebDriver driver = u.getDriver();

		         // Acepta 21/1/2026 y 21/01/2026
		         DateTimeFormatter formatter = DateTimeFormatter.ofPattern("d/M/yyyy");

		         // ================= FECHA INICIO Y FIN DEL FILTRO =================
		         By inputInicio = By.xpath("//mat-date-range-input//input[contains(@class,'mat-start-date') or @data-mat-calendar='start']");
		         By inputFin    = By.xpath("//mat-date-range-input//input[contains(@class,'mat-end-date') or @data-mat-calendar='end']");

		         List<WebElement> inicios = driver.findElements(inputInicio);
		         List<WebElement> fines   = driver.findElements(inputFin);

		         WebElement fechaInicio = !inicios.isEmpty()
		                 ? inicios.get(0)
		                 : driver.findElement(By.xpath("//div[contains(@class,'mat-date-range-input-wrapper')][1]//input"));

		         WebElement fechaFin = !fines.isEmpty()
		                 ? fines.get(0)
		                 : driver.findElement(By.xpath("//div[contains(@class,'mat-date-range-input-end-wrapper')]//input"));

		         String vIni = fechaInicio.getAttribute("value");
		         String vFin = fechaFin.getAttribute("value");
		         if (vIni == null) vIni = "";
		         if (vFin == null) vFin = "";
		         vIni = vIni.trim();
		         vFin = vFin.trim();

		         LocalDate fechaInicioFiltro = LocalDate.parse(vIni, formatter);
		         LocalDate fechaFinFiltro    = LocalDate.parse(vFin, formatter);

		         System.out.println("Fecha inicio filtro: " + fechaInicioFiltro);
		         System.out.println("Fecha fin filtro: " + fechaFinFiltro);

		         // ================= PRIMER REGISTRO (PRIMERA PÁGINA) =================
		         By fechaPrimerReg = By.xpath("//app-centro-descargas//table//tbody/tr[1]/td[1]//span");
		         WebElement primerRegistro = driver.findElement(fechaPrimerReg);

		         String txtPrimer = primerRegistro.getText();
		         if (txtPrimer == null) txtPrimer = "";
		         txtPrimer = txtPrimer.trim();

		         LocalDate fechaPrimerRegistro = LocalDate.parse(txtPrimer, DateTimeFormatter.ofPattern("dd/MM/yyyy"));
		         System.out.println("Fecha primer registro: " + fechaPrimerRegistro);
		         
		         if (tomarEvidencia) {
		             testCase.addScreenShotCurrentStep("Evidencia - Validación rango de fechas");
		         }

		         // ================= IR A ÚLTIMA PÁGINA =================
		         scrollBott();
		         u.click(btnUltPaginaCD);
		         u.hardWait(2);
		         scrollBott();

		         // ================= ÚLTIMO REGISTRO (ÚLTIMA PÁGINA) =================
		         By fechasUltimaPagina = By.xpath("//app-centro-descargas//table//tbody/tr/td[1]//span");
		         List<WebElement> registrosUltimaPagina = driver.findElements(fechasUltimaPagina);

		         if (registrosUltimaPagina.isEmpty()) {
		             System.out.println("ERROR: No se encontraron registros en la última página");
		             return false;
		         }

		         WebElement ultimoRegistro = registrosUltimaPagina.get(registrosUltimaPagina.size() - 1);

		         String txtUlt = ultimoRegistro.getText();
		         if (txtUlt == null) txtUlt = "";
		         txtUlt = txtUlt.trim();

		         LocalDate fechaUltimoRegistro = LocalDate.parse(txtUlt, DateTimeFormatter.ofPattern("dd/MM/yyyy"));
		         System.out.println("Fecha último registro: " + fechaUltimoRegistro);

		         // ================= VALIDACIONES =================
		         boolean valido =
		                 !fechaPrimerRegistro.isBefore(fechaInicioFiltro) &&
		                 !fechaUltimoRegistro.isAfter(fechaFinFiltro);

		         if (tomarEvidencia) {
		             testCase.addScreenShotCurrentStep("Evidencia - Validación rango de fechas");
		         }

		         if (!valido) {
		             System.out.println("ERROR: Los registros no respetan el rango de fechas");
		             System.out.println("Detalle: primer=" + fechaPrimerRegistro + ", ultimo=" + fechaUltimoRegistro
		                     + ", inicioFiltro=" + fechaInicioFiltro + ", finFiltro=" + fechaFinFiltro);
		             return false;
		         }

		         System.out.println("SUCCESS: Registros corresponden al rango de fechas");
		         return true;

		     } catch (Exception e) {
		         System.out.println("ERROR validarRegistrosContraRangoFechasCD: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

