		 /**
		  * Metodo para validar que el calendario SOLO muestre 3 años consecutivos
		  * basados en la precondición (fecha de hace 3 años + 1 día).
		  *
		  * @author Alejandro Valdez
		  * @param screenshot indica si se toma evidencia
		  * @return true si cumple con exactamente 3 años consecutivos
		  */
		 public boolean valAñoCalendario(boolean screenshot) {
		     try {
		         WebDriver driver = u.getDriver();
		         WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(15));

		         By multiYearView = By.cssSelector("mat-datepicker-content mat-multi-year-view");
		         wait.until(ExpectedConditions.visibilityOfElementLocated(multiYearView));

		         u.hardWait(1);

		         if (screenshot) {
		             testCase.addScreenShotCurrentStep("Vista multi-año del calendario");
		         }

		         // 1) Obtener años habilitados visibles
		         List<WebElement> btnAnios = driver.findElements(By.cssSelector(
		             "mat-datepicker-content mat-multi-year-view button.mat-calendar-body-cell:not(.mat-calendar-body-disabled)"
		         ));

		         List<Integer> anios = new ArrayList<>();

		         for (WebElement el : btnAnios) {
		             try {
		                 if (!el.isDisplayed()) continue;

		                 String ariaDisabled = el.getAttribute("aria-disabled");
		                 if ("true".equalsIgnoreCase(ariaDisabled)) continue;

		                 String texto = el.getAttribute("aria-label"); // Ej: "2026"
		                 if (texto != null && texto.matches("\\d{4}")) {
		                     anios.add(Integer.parseInt(texto));
		                 }

		             } catch (Exception ignore) {}
		         }

		         System.out.println("Años detectados: " + anios);

		         Collections.sort(anios);

		         int min = anios.get(0);
		         int max = anios.get(anios.size() - 1);

		         // VALIDACIÓN REAL DEL NEGOCIO
		         if ((max - min) != 3) {
		             testCase.addCodeEvidenceCurrentStep(
		                 "Error: El rango de años no es de 3 años. Detectados: " + anios +
		                 " | Diferencia: " + (max - min)
		             );
		             if (screenshot) testCase.addScreenShotCurrentStep("Error rango años");
		             return false;
		         }

		         Collections.sort(anios);

		         int anio1 = anios.get(0);
		         int anio2 = anios.get(1);
		         int anio3 = anios.get(2);

		         // 3) Validar consecutividad estricta
		         if (!(anio2 == anio1 + 1 && anio3 == anio2 + 1)) {
		             testCase.addCodeEvidenceCurrentStep(
		                 "Error: Los años no son consecutivos. Años: " + anios
		             );
		             if (screenshot) testCase.addScreenShotCurrentStep("Error años no consecutivos");
		             return false;
		         }

		         // 4) Validación fuerte basada en precondición
		         // Año esperado = año actual - 3 + 1
		         int anioEsperadoBase = LocalDate.now().minusYears(3).plusDays(1).getYear();

		         if (anio1 != anioEsperadoBase) {
		             testCase.addCodeEvidenceCurrentStep(
		                 "Error: El año inicial no coincide con la precondición. " +
		                 "Esperado: " + anioEsperadoBase + " | Obtenido: " + anio1 +
		                 " | Años: " + anios
		             );
		             if (screenshot) testCase.addScreenShotCurrentStep("Error año base");
		             return false;
		         }

		         System.out.println("Validación exitosa: Años correctos -> " + anios);

		         if (screenshot) {
		             testCase.addScreenShotCurrentStep("Validación años correcta");
		         }

		         return true;

		     } catch (Exception e) {
		         testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

