		 /**
		 * Metodo para accionar el reintento de una descarga fallida y confirmar que su estatus cambia a "En Proceso".
		 * @author Alejandro Valdez
		 * @param tomarEvidencia Booleano para capturar evidencia visual del cambio de estatus en el grid.
		 * @return True si se detecta la transición visual hacia el estatus de proceso tras el reintento; False si ocurre un timeout.
		 * @date Diciembre 2025
		 */
		 public boolean valCambioEstatusProceso(boolean tomarEvidencia) {
		      try {
		             if (u.waitWebElement(chkReintentar, 30, 2).isDisplayed()) {
		                 u.mouseOverAndClick(chkReintentar);

		                 // Validar que se muestre el estatus de En Proceso
		                 try {
		                     WebDriverWait wait = new WebDriverWait(u.getDriver(), Duration.ofSeconds(10));
		                     WebElement estatusEnProceso = wait.until(ExpectedConditions.visibilityOfElementLocated(chkEnProceso));
		                     
		                     System.out.println("SUCCESS: Cambio de estatus exitoso");
		                     
		                     if (tomarEvidencia) {
		                         u.highLight(chkEnProceso);
		                         testCase.addScreenShotCurrentStep("Evidencia - Cambio de estatus exitoso");
		                         u.unhighLight(chkEnProceso);
		                     }
		                     
		                     return true;
		                     
		                 } catch (TimeoutException e) {
		                     System.out.println("ERROR: No se mostró el Cambio de estatus");
		                     if (tomarEvidencia) {
		                         testCase.addScreenShotCurrentStep("Error - Cambio de estatus no apareció");
		                     }
		                     return false;
		                 }
		                 
		             } else {
		                 if (tomarEvidencia) {
		                     testCase.addScreenShotCurrentStep("No se mostró el Cambio de estatus");
		                 }
		                 System.out.println("No se mostró el Cambio de estatus");
		                 return false;
		             }
		         } catch (Exception e) {
		             if (tomarEvidencia) {
		                 testCase.addScreenShotCurrentStep("Evidencia - Excepción en valCambioEstatusProceso");
		             }
		             System.err.println("Error en valCambioEstatusProceso: " + e.getMessage());
		             e.printStackTrace();
		             return false;
		         }
		 }

