		 /**
		 * Metodo que valida que las transferencias mostradas en la interfaz de Liquidación de Ruta coincidan con los registros históricos de la base de datos para una ruta específica.
		 * @author Alejandro Valdez - Jose Pecina
		 * @return True si se logra iterar sobre las transferencias visibles y se confirma su integridad contra la tabla 'xxcm_historico_correos' mediante SQL; False en caso contrario.
		 * @date Noviembre 2025
		 */
		 public boolean valInformacionLiqRutaAdmin() {
		     try {
		         if(u.isDisplayed(lbTotalTransferencias)){

		             WebDriver driver = u.getDriver();
		             WebElement elemento = driver.findElement(lbTotalTransferencias);
		             String textoCompleto = elemento.getText();

		             // Dividir por salto de línea y obtener la segunda parte
		             String[] partes = textoCompleto.split("\n");
		             String numeroStr = partes[1].trim(); // "1"
		             
		             //Número como int
		             int numero = Integer.parseInt(numeroStr);
		             System.out.println("Total de transferencias encontradas: " + numero);

		             // Ciclo que se ejecuta según el número de transferencias
		             Actions __actions__ = new Actions(driver);
		             List<WebElement> transferenciasDOM = driver.findElements(By.xpath("//p[contains(.,'Transferencia:')]"));

		             int index = 1;
		             for (WebElement p : transferenciasDOM) {
		                 System.out.println("Procesando transferencia visual " + index + " de " + transferenciasDOM.size());

		                 // Scroll + highlight usando By (para compatibilidad con SeleniumUtil)
		                 By xpathTransferencia = By.xpath("(//p[contains(.,'Transferencia:')])[" + index + "]");
		                 u.scrollToElement(xpathTransferencia);
		                 u.highLight(xpathTransferencia);

		                 // Texto visible en el párrafo
		                 String textoP = p.getText().trim();
		                 testCase.addTextEvidenceCurrentStep("Transferencia visible: " + textoP);

		                 // Captura de evidencia
		                 testCase.addScreenShotCurrentStep("Transferencia " + index + " de " + transferenciasDOM.size());

		                 // Scroll adicional (opcional)
		                 __actions__.scrollByAmount(0, 420).perform();

		                 index++;
		             }

		             System.out.println("Se procesaron " + numero + " transferencias exitosamente");
		             
		             String queryRegistros =
		                     "SELECT xhc.transferencia " +
		                     "FROM xxcm_historico_correos xhc " +
		                     "WHERE xhc.ruta_propuesta = '"+rutaPropuesta+"' " +
		                     "AND TRIM(xhc.ruta_propuesta) <> '' " +
		                     "ORDER BY xhc.fecha_registro DESC " +
		                     "LIMIT "+numero+";";
		                 
		             String bd = GlobalVariables.DB_URL_Cometa;
		             String user = GlobalVariables.DB_USER_Cometa;
		             String password = GlobalVariables.DB_PASSWORD_Cometa;
		             
		             boolean resultado = false;

		             try (Connection connection = DriverManager.getConnection(bd, user, password);
		                  Statement stmt = connection.createStatement();
		                  ResultSet rs = stmt.executeQuery(queryRegistros)) {

		                 System.out.println("Conexión exitosa con la base de datos de Cometa.");

		                 List<String> transferenciasObtenidas = new ArrayList<>();
		                 while (rs.next()) {
		                     transferenciasObtenidas.add(rs.getString("transferencia"));
		                 }

		                 if (transferenciasObtenidas.isEmpty()) {
		                     System.out.println("No se encontraron registros la ruta propuesta = "+rutaPropuesta+"");
		                     resultado = false;
		                 } else {
		                     testCase.addBoldTextEvidenceCurrentStep("Transferencias encontradas en la Base de datos:");
		                     for (String trasnferenc : transferenciasObtenidas) {
		                         testCase.addTextEvidenceCurrentStep(" -> " + trasnferenc);
		                     }
		                     resultado = true;
		                 }

		             } catch (SQLException e) {
		                 System.err.println("Error al ejecutar la consulta de id_retek:");
		                 e.printStackTrace();
		                 resultado = false;
		             }

		             return resultado;          
		         }
		         return false;
		     } catch (Exception e) {
		         System.out.println("[ERROR] Ocurrió un error durante la ejecución: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

		 /**
		 * Metodo para desactivar la sincronización automática de la hora del sistema operativo Windows mediante la detención del servicio 'w32time'.
		 * REQUIERE: Ejecutar la aplicación con privilegios de Administrador.
		 * @author Alejandro Valdez
		 * @return True si el comando 'net stop w32time' se ejecuta y finaliza exitosamente; False si el proceso retorna un error o falta de permisos.
		 * @date Noviembre 2025
		 */
		 public boolean desactivarHoraAutomatica() {
		     try {
		         // Comando para detener el servicio de sincronización de hora
		         String comando = "cmd /c net stop w32time";

		         Process proceso = Runtime.getRuntime().exec(comando);
		         proceso.waitFor();

		         if (proceso.exitValue() == 0) {
		             System.out.println("[SUCCESS] Servicio de sincronización de hora detenido correctamente.");
		             return true;
		         } else {
		             System.err.println("[ERROR] No se pudo detener el servicio. Ejecuta como administrador.");
		             return false;
		         }

		     } catch (Exception e) {
		         System.err.println("[ERROR] Excepción al intentar desactivar la sincronización automática: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

		 /**
		 * Metodo para atrasar la hora del sistema operativo Windows en exactamente una hora.
		 * REQUIERE: Ejecutar la aplicación con privilegios de Administrador.
		 * @author Alejandro Valdez
		 * @return True si el comando de sistema se ejecuta con éxito y se logra capturar la evidencia; False si falla la ejecución o faltan permisos.
		 * @date Noviembre 2025
		 */
		 public boolean atrasarHora() {
		     try {
		         // Obtener la hora actual del sistema
		         LocalDateTime horaActual = LocalDateTime.now();
		         LocalDateTime horaNueva = horaActual.minusHours(1);
		         
		         // Formatear para el comando de Windows (formato: HH:mm:ss)
		         DateTimeFormatter formatoHora = DateTimeFormatter.ofPattern("HH:mm:ss");
		         String nuevaHora = horaNueva.format(formatoHora);
		         
		         // Comando para cambiar la hora en Windows
		         String comando = "cmd /c time " + nuevaHora;
		         
		         System.out.println("Cambiando hora del sistema...");
		         System.out.println("Hora actual: " + horaActual.format(formatoHora));
		         System.out.println("Nueva hora: " + nuevaHora);
		         
		         Process proceso = Runtime.getRuntime().exec(comando);
		         proceso.waitFor();
		         
		         if (proceso.exitValue() == 0) {
		             System.out.println("[SUCCESS] Hora del sistema atrasada correctamente");
		             Robot robot = new Robot();
		             robot.keyPress(KeyEvent.VK_WINDOWS);
		             robot.keyPress(KeyEvent.VK_ALT);
		             robot.keyPress(KeyEvent.VK_D);
		             robot.keyRelease(KeyEvent.VK_D);
		             robot.keyRelease(KeyEvent.VK_ALT); 
		             robot.keyRelease(KeyEvent.VK_WINDOWS);
		             u.hardWait(2);
		             testCase.addScreenShotCurrentStep("");
		             u.hardWait(2);
		             robot.keyPress(KeyEvent.VK_WINDOWS);
		             robot.keyPress(KeyEvent.VK_ALT);
		             robot.keyPress(KeyEvent.VK_D);
		             robot.keyRelease(KeyEvent.VK_D);
		             robot.keyRelease(KeyEvent.VK_ALT); 
		             robot.keyRelease(KeyEvent.VK_WINDOWS);
		             return true;
		         } else {
		             System.out.println("[ERROR] No se pudo cambiar la hora. Ejecuta como Administrador");
		             return false;
		         }
		         
		     } catch (Exception e) {
		         System.out.println("[ERROR] Error al cambiar hora del sistema: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

		 /**
		 * Metodo para restaurar la hora del sistema adelantándola una hora (revirtiendo el atraso previo).
		 * REQUIERE: Ejecutar la aplicación con privilegios de Administrador.
		 * @author Alejandro Valdez
		 * @return True si la hora se actualiza correctamente mediante el comando de Windows; False en caso de error o falta de privilegios.
		 * @date Noviembre 2025
		 */
		 public boolean restaurarHoraSistemaConElevacion() {
		     try {
		         // Obtener la hora actual del sistema
		         LocalDateTime horaActual = LocalDateTime.now();
		         LocalDateTime horaNueva = horaActual.plusHours(1);
		         
		         // Formatear para el comando de Windows (formato: HH:mm:ss)
		         DateTimeFormatter formatoHora = DateTimeFormatter.ofPattern("HH:mm:ss");
		         String nuevaHora = horaNueva.format(formatoHora);
		         
		         // Comando para cambiar la hora en Windows
		         String comando = "cmd /c time " + nuevaHora;
		         
		         System.out.println("Cambiando hora del sistema...");
		         System.out.println("Hora actual: " + horaActual.format(formatoHora));
		         System.out.println("Nueva hora: " + nuevaHora);
		         
		         Process proceso = Runtime.getRuntime().exec(comando);
		         proceso.waitFor();
		         
		         if (proceso.exitValue() == 0) {
		             System.out.println("[SUCCESS] Hora del sistema atrasada correctamente");
		             return true;
		         } else {
		             System.out.println("[ERROR] No se pudo cambiar la hora. Ejecuta como Administrador");
		             return false;
		         }
		         
		     } catch (Exception e) {
		         System.out.println("[ERROR] Error al cambiar hora del sistema: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

		 /**
		 * Metodo para realizar el llenado de filtros de fecha y hora en la pantalla de Liquidación de Ruta utilizando datos de la base de datos.
		 * @author Alejandro Valdez
		 * @return True si se logra interactuar con todos los selectores y establecer los rangos de tiempo (Hora Inicial -1 y Hora Final +1); False si falla la visibilidad o interacción.
		 * @date Noviembre 2025
		 */
		 public boolean llenadoFiltrosLiquidacionRuta() {
		     try {
		         if(u.isDisplayed(btnFechaInicial)){
		             WebDriver driver = u.getDriver();
		             JavascriptExecutor js = (JavascriptExecutor) driver;

		             //Seleccionar la Fecha Inicial
		             u.click(btnFechaInicial);
		             u.click(By.xpath("(//span[normalize-space()='"+fechaFormateada+"'])[1]"));

		             //Seleccionar la Hora Inicial (hora -1)
		             DateTimeFormatter formatoHora = DateTimeFormatter.ofPattern("HH:mm");
		             LocalTime horaInicial = LocalTime.parse(horaFormateada, formatoHora);
		             LocalTime horaInicialMenos1 = horaInicial.minusHours(1);
		             String horaInicialFormateada = horaInicialMenos1.format(formatoHora);
		             
		             // Convertir a formato 12 horas con AM/PM
		             String horaInicialAMPM = convertirA12Horas(horaInicialFormateada);
		             System.out.println("Hora con AM/PM: " + horaInicialAMPM);
		             u.click(btnHoraInicial);
		             
		             // Esperar a que el dropdown se abra
		             Thread.sleep(500);
		             
		             // Localizar el panel del dropdown
		             WebElement dropdownPanel = driver.findElement(
		                 By.cssSelector("div.mat-mdc-select-panel[role='listbox']")
		             );
		             
		             // Localizar el elemento de la hora deseada dentro del panel
		             WebElement horaElemento = driver.findElement(
		                 By.xpath("(//span[normalize-space()='"+horaInicialAMPM+"'])[1]")
		             );
		             
		             // Hacer scroll hasta el elemento dentro del dropdown panel
		             js.executeScript("arguments[0].scrollIntoView({block: 'center', behavior: 'smooth'});", horaElemento);
		             
		             // Esperar un momento para que el scroll se complete
		             Thread.sleep(300);
		             
		             // Hacer click en la hora
		             horaElemento.click();
		             By xpathVisibleFechaFinal = By.xpath("//mat-option/span[normalize-space(text())='"+fechaFormateada+"' and ancestor::div[not(contains(@style,'display: none'))]]");
		            
		             //Seleccionar la Fecha Final
		             u.click(btnFechaFinal);
		             u.click(xpathVisibleFechaFinal);
		             
		             //Seleccionar la Hora Final (hora +1)

		             LocalTime horaFinal = LocalTime.parse(horaFormateada, formatoHora);
		             LocalTime horaFinalMas1 = horaFinal.plusHours(1);
		             String horaFinalFormateada = horaFinalMas1.format(formatoHora);
		             
		             // Convertir a formato 12 horas con AM/PM
		             String horaFinalAMPM = convertirA12Horas(horaFinalFormateada);
		             System.out.println("Hora con AM/PM: " + horaFinalAMPM);
		             u.click(btnHoraFinal);
		             
		             // Esperar a que el dropdown se abra
		             Thread.sleep(500);
		             
		             // Localizar el elemento de la hora deseada dentro del panel
		             WebElement horaElementoF = driver.findElement(
		                 By.xpath("(//span[normalize-space()='"+horaFinalAMPM+"'])[1]")
		             );
		             
		             // Hacer scroll hasta el elemento dentro del dropdown panel
		             js.executeScript("arguments[0].scrollIntoView({block: 'center', behavior: 'smooth'});", horaElementoF);
		             
		             // Esperar un momento para que el scroll se complete
		             Thread.sleep(300);
		             
		             // Hacer click en la hora
		             horaElementoF.click();
		             testCase.addScreenShotCurrentStep("");
		             return true;
		         }
		         return false;
		     } catch (Exception e) {
		         System.out.println("[ERROR] Ocurrió un error durante la ejecución: " + e.getMessage());
		         e.printStackTrace();
		         return false;
		     }
		 }

