		 /**
		 * Metodo para seleccionar una tienda filtrando por los primeros caracteres y validar que la selección se refleje en el campo de texto.
		 * @author Alejandro Valdez
		 * @return True si el nombre de la tienda seleccionada coincide con el valor esperado en el componente; False si la validación de texto falla.
		 * @date Agosto 2025
		 */
		 public boolean selectListaTiendayValidarSelección() {
		     try {
		         if (u.waitWebElement(tbTienda,10,2).isDisplayed()) {
		             WebDriver driver = u.getDriver();
		             Actions actions = new Actions(driver);
		             u.click(tbTienda);
		             
		             // Tomar primeros 4 caracteres como String
		             String primeros4Caracteres;
		             if (tienda != null && tienda.length() >= 4) {
		                 primeros4Caracteres = tienda.substring(0, 4);
		             } else if (tienda != null && tienda.length() > 0) {
		                 // Si la tienda tiene menos de 4 caracteres, tomar todos los disponibles
		                 primeros4Caracteres = tienda;
		             } else {
		                 System.out.println("Error: La tienda es null o vacía");
		                 return false;
		             }

		             // Enviar al input
		             actions.sendKeys(primeros4Caracteres).perform();                
		             u.hardWait(1);
		             u.click(lstFir);
		             actions.sendKeys(Keys.ESCAPE).perform();
		             
		             
		             //Primero encontrar el elemento, luego obtener el texto
		             WebElement elemento = driver.findElement(tbTienda);
		             String rg1 = elemento.getText();
		             
		             if (rg1.contains(tienda)) {
		                 System.out.println("Validación exitosa: El texto contiene el valor " + tienda);
		                 testCase.addScreenShotCurrentStep("");
		                 return true;
		             } else {
		                 System.out.println("Validación fallida: El texto NO contiene el valor " + tienda);
		                 testCase.addScreenShotCurrentStep("Validación fallida - Texto no contiene: " + tienda);
		                 return false;
		             }	            
		         }
		         return false;
		     } catch (Exception e) {
		         System.out.println("[ERROR] Ocurrió un error durante la ejecución: " + e.getMessage());
		         return false;
		     }
		 }

