		 /**
		 * Metodo para realizar la selección de un rango de fechas navegando por el calendario mediante el año, mes y día obtenidos de la base de datos.
		 * @author Alejandro Valdez
		 * @param tomarEvidencia Booleano para capturar evidencia visual del proceso final de selección.
		 * @return True si se completa la navegación y selección de fechas exitosamente; False si el calendario no es visible o el parseo de datos falla.
		 * @date Septiembre 2025
		 */
		 public boolean fechasBd(boolean tomarEvidencia) {
		     try {

		         WebDriver driver = u.getDriver();
		         WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(20));
		         
		         try {
		             wait.until(ExpectedConditions.visibilityOfElementLocated(btnCalendario));
		             System.out.println("SUCCESS: El calendario está visible");
		         } catch (TimeoutException e) {
		             System.out.println("ERROR: El calendario NO está visible después de esperar 15 segundos");
		             testCase.addScreenShotCurrentStep("Error - Calendario no visible");
		             return false;
		         }
		         
		         String fechaOriginal = fecha;
		         LocalDate fechaConvert;
		         
		         try {
		             System.out.println("Intentando parsear con formato 'yyyy-MM-dd HH:mm:ss'...");
		             fechaConvert = LocalDateTime.parse(fechaOriginal, DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")).toLocalDate();
		             System.out.println("Fecha parseada con hora exitosamente");
		         } catch (Exception ex) {
		             System.out.println("No se pudo parsear con hora, intentando formato 'yyyy-MM-dd'...");
		             try {
		                 fechaConvert = LocalDate.parse(fechaOriginal, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
		                 System.out.println("Fecha parseada sin hora exitosamente");
		             } catch (Exception ex2) {
		                 System.out.println("ERROR: No se pudo parsear la fecha en ningún formato");
		                 System.out.println("Formato esperado: yyyy-MM-dd o yyyy-MM-dd HH:mm:ss");
		                 ex2.printStackTrace();
		                 return false;
		             }
		         }
		         
		         By btnToggle = By.xpath("//mat-datepicker-toggle/button");
		         
		         try {
		             wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();
		             System.out.println("Clic en botón toggle ejecutado");
		         } catch (Exception e) {
		             System.out.println("ERROR: No se pudo hacer clic en el botón toggle");
		             e.printStackTrace();
		             return false;
		         }
		         
		         By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
		         
		         try {
		             wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));
		             System.out.println("Calendario abierto y visible");
		         } catch (Exception e) {
		             System.out.println("ERROR: El calendario no se abrió o no es visible");
		             e.printStackTrace();
		             return false;
		         }
		         
		         By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
		         By vistaAnios = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view");
		         
		         try {
		             wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
		             System.out.println("Primer clic en botón periodo ejecutado");
		             Thread.sleep(300);
		             
		             if (driver.findElements(vistaAnios).isEmpty()) {
		                 System.out.println("Vista de años no alcanzada, haciendo segundo clic...");
		                 wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
		                 System.out.println("Segundo clic en botón periodo ejecutado");
		                 Thread.sleep(300);
		             }
		             
		             System.out.println("Vista de años alcanzada");
		         } catch (Exception e) {
		             System.out.println("ERROR: No se pudo navegar a la vista de años");
		             e.printStackTrace();
		             return false;
		         }

		         try {
		             clickYear(driver, wait, fechaConvert.getYear());
		             System.out.println("Año seleccionado");
		         } catch (Exception e) {
		             System.out.println("ERROR: No se pudo seleccionar el año");
		             e.printStackTrace();
		             return false;
		         }
		         
		         try {
		             clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());
		             System.out.println("Mes seleccionado");
		         } catch (Exception e) {
		             System.out.println("ERROR: No se pudo seleccionar el mes");
		             e.printStackTrace();
		             return false;
		         }
		         
		         LocalDate fechaInicio = fechaConvert.minusDays(1);
		         
		         try {
		             clickDay(driver, wait, fechaConvert.getDayOfMonth());
		             System.out.println("Día inicio seleccionado");
		             
		             clickDay(driver, wait, fechaConvert.getDayOfMonth());
		             System.out.println("Día fin seleccionado");
		         } catch (Exception e) {
		             System.out.println("ERROR: No se pudo seleccionar los días");
		             e.printStackTrace();
		             return false;
		         }
		         
		         try {
		             wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));
		             System.out.println("Datepicker cerrado");
		         } catch (Exception e) {
		             System.out.println("ADVERTENCIA: El datepicker no se cerró automáticamente");
		         }
		         
		         // Tomar screenshot solo si se solicita
		         if (tomarEvidencia) {
		             testCase.addScreenShotCurrentStep("");
		             System.out.println("Screenshot capturado");
		         }
		         
		         System.out.println("=== FIN fechasBd - EXITOSO ===");
		         return true;
		         
		     } catch (Exception e) {
		         System.out.println("========================================");
		         System.out.println("ERROR GENERAL en fechasBd:");
		         System.out.println("Mensaje: " + e.getMessage());
		         System.out.println("Clase: " + e.getClass().getName());
		         System.out.println("========================================");
		         e.printStackTrace();
		         return false;
		     }
		 }

