		 /**
		 * Método interno para normalizar cadenas de fecha de diversos formatos (/, -, .) al formato estándar ISO yyyy-MM-dd.
		 * @author Alejandro Valdez
		 * @param fecha Cadena de texto que representa la fecha a convertir.
		 * @return La cadena de fecha convertida al formato yyyy-MM-dd; retorna la cadena original si el formato no es reconocido.
		 * @date Septiembre 2025
		 */
		 private String convertirFecha(String fecha) {
		     try {
		         // Limpiar la fecha de espacios extra
		         fecha = fecha.trim();
		         
		         System.out.println("Procesando fecha: '" + fecha + "'");
		         
		         // Si ya está en formato yyyy-MM-dd, devolverla tal como está
		         if (fecha.matches("\\d{4}-\\d{2}-\\d{2}")) {
		             System.out.println("Formato yyyy-MM-dd detectado");
		             return fecha;
		         }
		         
		         // Si está en formato d/M/yyyy o dd/MM/yyyy (ej: 15/8/2025 o 01/08/2025)
		         if (fecha.matches("\\d{1,2}/\\d{1,2}/\\d{4}")) {
		             System.out.println("Formato d/M/yyyy o dd/MM/yyyy detectado");
		             String[] partes = fecha.split("/");
		             String diaStr = partes[0];
		             String mesStr = partes[1];
		             String anio = partes[2];
		             
		             // Asumimos formato DD/MM/YYYY (día/mes/año) como estándar en muchos países
		             String dia = diaStr.length() == 1 ? "0" + diaStr : diaStr;
		             String mes = mesStr.length() == 1 ? "0" + mesStr : mesStr;
		             
		             String resultado = anio + "-" + mes + "-" + dia;
		             System.out.println("Convertido a: " + resultado);
		             return resultado;
		         }
		         
		         // Si está en formato dd-MM-yyyy
		         if (fecha.matches("\\d{1,2}-\\d{1,2}-\\d{4}")) {
		             System.out.println("Formato dd-MM-yyyy detectado");
		             String[] partes = fecha.split("-");
		             String dia = partes[0].length() == 1 ? "0" + partes[0] : partes[0];
		             String mes = partes[1].length() == 1 ? "0" + partes[1] : partes[1];
		             String anio = partes[2];
		             return anio + "-" + mes + "-" + dia;
		         }
		         
		         // Si está en formato yyyy/MM/dd
		         if (fecha.matches("\\d{4}/\\d{1,2}/\\d{1,2}")) {
		             System.out.println("Formato yyyy/MM/dd detectado");
		             String[] partes = fecha.split("/");
		             String anio = partes[0];
		             String mes = partes[1].length() == 1 ? "0" + partes[1] : partes[1];
		             String dia = partes[2].length() == 1 ? "0" + partes[2] : partes[2];
		             return anio + "-" + mes + "-" + dia;
		         }
		         
		         // Si está en formato dd.MM.yyyy
		         if (fecha.matches("\\d{1,2}\\.\\d{1,2}\\.\\d{4}")) {
		             System.out.println("Formato dd.MM.yyyy detectado");
		             String[] partes = fecha.split("\\.");
		             String dia = partes[0].length() == 1 ? "0" + partes[0] : partes[0];
		             String mes = partes[1].length() == 1 ? "0" + partes[1] : partes[1];
		             String anio = partes[2];
		             return anio + "-" + mes + "-" + dia;
		         }
		         
		         // Si no coincide con ningún patrón, devolver la fecha original
		         System.out.println("Formato de fecha no reconocido: " + fecha);
		         return fecha;
		         
		     } catch (Exception e) {
		         System.out.println("Error al convertir fecha: " + fecha + " - " + e.getMessage());
		         e.printStackTrace();
		         return fecha; // Devolver fecha original en caso de error
		     }
		 }

