		 /**
		 * Metodo para validar que el primer registro del grid se encuentre dentro del rango de fechas (Inicio y Fin) establecido en los inputs del calendario.
		 * @author Alejandro Valdez
		 * @return True si la fecha del primer registro coincide o es posterior a la fecha de inicio y anterior o igual a la de fin; False en caso contrario.
		 * @date Septiembre 2025
		 */
		 public boolean registroFechaDev() {
		     try {
		         if (!u.waitWebElement(firstRegDateGrid, 10, 2).isDisplayed()) return false;

		         WebDriver driver = u.getDriver();
		         u.hardWait(2);

		         String fechaInicioStr = driver.findElement(By.cssSelector("input.mat-start-date")).getAttribute("value");
		         String fechaFinStr = driver.findElement(By.cssSelector("input.mat-end-date")).getAttribute("value");

		         String fechaGridStr = driver.findElement(firstRegDateGrid).getText().trim();

		         System.out.println("Fecha inicio original: " + fechaInicioStr);
		         System.out.println("Fecha fin original: " + fechaFinStr);
		         System.out.println("Fecha grid original: " + fechaGridStr);

		         LocalDate fechaInicio = LocalDate.parse(convertirFecha(fechaInicioStr));
		         LocalDate fechaFin = LocalDate.parse(convertirFecha(fechaFinStr));
		         LocalDate fechaGrid = LocalDate.parse(convertirFecha(fechaGridStr));

		         boolean dentroRango = (fechaGrid.isEqual(fechaInicio) || fechaGrid.isAfter(fechaInicio))
		                            && (fechaGrid.isEqual(fechaFin) || fechaGrid.isBefore(fechaFin));

		         if (dentroRango) {
		             System.out.println("Validación exitosa: La fecha del registro está dentro del rango");
		             testCase.addScreenShotCurrentStep("");
		             return true;
		         } else {
		             System.out.println("Validación fallida: La fecha del registro NO está dentro del rango");
		             testCase.addScreenShotCurrentStep("");
		             return false;
		         }

		     } catch (Exception e) {
		         e.printStackTrace();
		         return false;
		     }
		 }

