		 /**
		 * Metodo para validar que el grid de resultados se encuentre ordenado de forma descendente (de más reciente a más antiguo), comparando el primer registro con el decimoquinto.
		 * @author Alejandro Valdez
		 * @return True si la fecha del primer registro es posterior a la del decimoquinto registro tras realizar scroll; False si el orden es incorrecto o falla el parseo.
		 * @date Septiembre 2025
		 */
		 public boolean registroFechaDevPrimUlt() {
		     try {
		         if (u.waitWebElement(firstRegDateGrid, 10, 2).isDisplayed()) {
		             WebDriver driver = u.getDriver();
		             u.hardWait(2);

		             // Obtener fecha del primer registro del grid
		             WebElement elementoPrimerRegistro = driver.findElement(firstRegDateGrid);
		             String fechaObtenida = elementoPrimerRegistro.getText().trim();

		             System.out.println("Fecha obtenida original: " + fechaObtenida);

		             scrollBott();
		             // Obtener fecha del último registro
		             WebElement elementoUltimoRegistro = driver.findElement(By.xpath("//tbody/tr[15]/td[7]"));
		             
		             String fechaFinal = elementoUltimoRegistro.getText().trim(); 

		             System.out.println("Fecha final original: " + fechaFinal);

		             // Convertir ambas fechas al mismo formato
		             String fechaFinalFormateada = convertirFecha(fechaFinal);
		             String fechaObtenidaFormateada = convertirFecha(fechaObtenida);

		             System.out.println("Fecha final formateada: " + fechaFinalFormateada);
		             System.out.println("Fecha obtenida formateada: " + fechaObtenidaFormateada);

		             // Convertir las fechas formateadas a objetos Date para comparación
		             Date fechaObtenidaDate = parsearFecha(fechaObtenidaFormateada);
		             Date fechaFinalDate = parsearFecha(fechaFinalFormateada);

		             if (fechaObtenidaDate == null || fechaFinalDate == null) {
		                 System.out.println("Error: No se pudieron parsear las fechas correctamente");
		                 testCase.addScreenShotCurrentStep("");
		                 return false;
		             }

		             // Validar que la fecha obtenida sea MAYOR que la fecha final
		             if (fechaObtenidaDate.after(fechaFinalDate)) {
		                 System.out.println("Validación exitosa: La fecha obtenida (" + fechaObtenidaFormateada + 
		                                  ") es mayor que la fecha final (" + fechaFinalFormateada + ")");
		                 testCase.addScreenShotCurrentStep("");
		                 return true;
		             } else {
		                 System.out.println("Validación fallida: La fecha obtenida NO es mayor que la fecha final");
		                 System.out.println("Fecha obtenida: " + fechaObtenidaFormateada);
		                 System.out.println("Fecha final: " + fechaFinalFormateada);
		                 
		                 if (fechaObtenidaDate.equals(fechaFinalDate)) {
		                     System.out.println("Las fechas son iguales");
		                 } else {
		                     System.out.println("La fecha obtenida es menor que la fecha final");
		                 }
		                 
		                 testCase.addScreenShotCurrentStep("");
		                 return false;
		             }
		         }
		         
		         System.out.println("El elemento del grid no está visible");
		         return false;
		         
		     } catch (Exception e) {
		         System.err.println("Error en registroFechaDevPrimUlt: " + e.getMessage());
		         e.printStackTrace();
		         testCase.addScreenShotCurrentStep("");
		         return false;
		     }
		 }

		 /**
		 * Método auxiliar para parsear cadenas de fecha a objetos de tipo Date intentando múltiples formatos comunes (dd/MM/yyyy, yyyy-MM-dd, etc.).
		 * @author Alejandro Valdez
		 * @param fechaFormateada Cadena de texto de la fecha a parsear.
		 * @return Objeto Date si el parseo tiene éxito; null si no coincide con ningún formato manejado.
		 * @date Septiembre 2025
		 */
		 private Date parsearFecha(String fechaFormateada) {
		     try {
		         // Ajusta el formato según lo que retorna tu método convertirFecha()
		         // Ejemplos comunes de formatos:
		         SimpleDateFormat formato1 = new SimpleDateFormat("dd/MM/yyyy");
		         SimpleDateFormat formato2 = new SimpleDateFormat("yyyy-MM-dd");
		         SimpleDateFormat formato3 = new SimpleDateFormat("MM/dd/yyyy");
		         SimpleDateFormat formato4 = new SimpleDateFormat("dd-MM-yyyy");
		         
		         // Intentar diferentes formatos comunes
		         try {
		             return formato1.parse(fechaFormateada);
		         } catch (ParseException e1) {
		             try {
		                 return formato2.parse(fechaFormateada);
		             } catch (ParseException e2) {
		                 try {
		                     return formato3.parse(fechaFormateada);
		                 } catch (ParseException e3) {
		                     try {
		                         return formato4.parse(fechaFormateada);
		                     } catch (ParseException e4) {
		                         System.err.println("No se pudo parsear la fecha: " + fechaFormateada);
		                         return null;
		                     }
		                 }
		             }
		         }
		     } catch (Exception e) {
		         System.err.println("Error al parsear fecha: " + e.getMessage());
		         return null;
		     }
		 }
		 
