		 /**
		 * Método para validar la existencia y el formato de los bloques BOL (Sobrantes, Faltantes, Dañados) asegurando que contengan un identificador de 4 dígitos.
		 * @author Alejandro Valdez
		 * @return True si todos los bloques BOL esperados son visibles y cumplen con el formato numérico de 4 dígitos; False si alguno falla.
		 * @date Octubre 2025
		 */
		 public boolean validarBols() {
		     try {
		         WebDriver driver = u.getDriver();

		         // Lista de elementos BOL a validar
		         By[] elementos = {
		             By.xpath("(//p[contains(text(),'LISTADO DE ARTICULOS SOBRANTES')])[1]"),
		             By.xpath("(//p[contains(text(),'LISTADO DE ARTICULOS Faltantes')])[1]"),
		             By.xpath("(//p[contains(text(),'LISTADO DE ARTICULOS DAÑADOS')])[1]")
		         };

		         boolean todosValidos = true;

		         for (By locator : elementos) {
		             try {
		                 u.scrollToElement(locator);

		                 if (u.waitWebElement(locator, 10, 2).isDisplayed()) {
		                     WebElement elemento = driver.findElement(locator);
		                     String texto = elemento.getText().trim();
		                     System.out.println("Texto obtenido: " + texto);

		                     // Buscar el número después de "BOL:"
		                     Pattern pattern = Pattern.compile("BOL:\\s*(\\d+)");
		                     Matcher matcher = pattern.matcher(texto);

		                     if (matcher.find()) {
		                         String numero = matcher.group(1);
		                         System.out.println("Número encontrado: " + numero);

		                         if (numero.matches("\\d{4}")) {
		                             System.out.println("El número tiene 4 dígitos.");
		                             u.highLight(locator);
		                             testCase.addScreenShotCurrentStep("Número de BOL válido: " + numero);
		                             u.unhighLight(locator);
		                         } else {
		                             System.out.println("El número no tiene 4 dígitos.");
		                             u.highLight(locator);
		                             testCase.addScreenShotCurrentStep("Número inválido: " + numero);
		                             u.unhighLight(locator);
		                             todosValidos = false;
		                         }
		                     } else {
		                         System.out.println("No se encontró el número después de 'BOL:'.");
		                         u.highLight(locator);
		                         testCase.addScreenShotCurrentStep("No se encontró número BOL.");
		                         u.unhighLight(locator);
		                         todosValidos = false;
		                     }
		                 } else {
		                     System.out.println("El elemento no está visible.");
		                     testCase.addScreenShotCurrentStep("Elemento no visible en pantalla.");
		                     todosValidos = false;
		                 }

		             } catch (Exception e1) {
		                 System.err.println("Error al validar un bloque BOL: " + e1.getMessage());
		                 testCase.addScreenShotCurrentStep("Error al validar un bloque BOL.");
		                 todosValidos = false;
		             }
		         }

		         return todosValidos;

		     } catch (Exception e) {
		         System.err.println("Error general en la validación: " + e.getMessage());
		         testCase.addScreenShotCurrentStep("Error general en la validación de BOLs.");
		         return false;
		     }
		 }

