	 	/**
	 	 * Metodo para obtener el rango de fechas seleccionado en el filtro
	 	 * de tipo mat-date-range-input en la pantalla de devoluciones.
	 	 * Primero intenta leer el atributo "value" de los inputs (inicio y fin).
	 	 * En caso de venir vacio, realiza fallback utilizando el span mirror.
	 	 * @author Jose Pecina
	 	 * @date Febrero 2026
	 	 * @return String - Devuelve el rango en formato "dd_MM_yyyy_dd_MM_yyyy"
	 	 * @throws Exception
	 	 */
	 	private String obtenerRangoFechasUI() throws Exception {
	 	    WebDriver driver = u.getDriver();

	 	    // 1) Intentar leer desde value de los inputs (lo mas confiable)
	 	    By inStart = By.xpath("//mat-date-range-input//input[@matstartdate]");
	 	    By inEnd = By.xpath("//mat-date-range-input//input[@matenddate]");

	 	    String inicioTxt = safeTrim(driver.findElement(inStart).getAttribute("value"));
	 	    String finTxt = safeTrim(driver.findElement(inEnd).getAttribute("value"));

	 	    // 2) Fallback: leer desde mirror si viene vacio
	 	    if (inicioTxt.isEmpty() || finTxt.isEmpty()) {
	 	        By mirrors = By.xpath("//mat-date-range-input//span[contains(@class,'mat-date-range-input-mirror')]");
	 	        List<WebElement> spans = driver.findElements(mirrors);

	 	        if (spans != null && spans.size() >= 2) {
	 	            if (inicioTxt.isEmpty()) inicioTxt = safeTrim(spans.get(0).getText());
	 	            if (finTxt.isEmpty()) finTxt = safeTrim(spans.get(1).getText());
	 	        }
	 	    }

	 	    // 3) Validacion final
	 	    if (inicioTxt.isEmpty() || finTxt.isEmpty()) {
	 	        throw new Exception("No se pudieron obtener las fechas del rango en UI. inicio=" + inicioTxt + " fin=" + finTxt);
	 	    }

	 	    String inicio = formatearFechaUIaNombreArchivo(inicioTxt);
	 	    String fin = formatearFechaUIaNombreArchivo(finTxt);

	 	    return inicio + "_" + fin;
	 	}
	 	/**
	 	 * Metodo para convertir una fecha proveniente del filtro UI
	 	 * en formato "d/M/yyyy" a formato compatible con nombre de archivo
	 	 * tipo "dd_MM_yyyy".
	 	 * @author Jose Pecina
	 	 * @date Febrero 2026
	 	 * @return String - Fecha formateada en patron "dd_MM_yyyy"
	 	 * @throws Exception
	 	 * @param fechaUI - Fecha obtenida desde el filtro UI en formato texto
	 	 */
	 	private String formatearFechaUIaNombreArchivo(String fechaUI) throws Exception {
	 	    // Soporta "24/6/2025" o "24/06/2025"
	 	    DateTimeFormatter inFmt = DateTimeFormatter.ofPattern("d/M/yyyy");
	 	    DateTimeFormatter outFmt = DateTimeFormatter.ofPattern("dd_MM_yyyy");

	 	    try {
	 	        LocalDate d = LocalDate.parse(fechaUI, inFmt);
	 	        return d.format(outFmt);
	 	    } catch (Exception ex) {
	 	        throw new Exception("No se pudo parsear fecha UI: " + fechaUI);
	 	    }
	 	}
	 	/**
	 	 * Metodo helper para validar nulos y eliminar espacios en blanco
	 	 * en textos obtenidos desde la UI.
	 	 * @author Jose Pecina
	 	 * @date Febrero 2026
	 	 * @return String - Texto limpio sin espacios o vacio si es null
	 	 * @param s - Texto a normalizar
	 	 */
	 	private String safeTrim(String s) {
	 	    return (s == null) ? "" : s.trim();
	 	}


	 	/**
	 	* Metodo para normalizar cadenas de fecha en diversos formatos a una representación uniforme YYYYMMDD para facilitar comparaciones lógicas.
	 	* @author Alejandro Valdez
	 	* @param fecha Cadena de texto de la fecha original a transformar.
	 	* @return Cadena de 8 dígitos con el formato yyyyMMdd; si el parseo falla, retorna únicamente los caracteres numéricos de la cadena original.
	 	* @date Octubre 2025
	 	*/
	 	private String normalizarFecha(String fecha) {
	 	     try {
	 	         if (fecha == null || fecha.isEmpty()) {
	 	             return "";
	 	         }
	 	         
	 	         // Remover espacios
	 	         fecha = fecha.trim();
	 	         
	 	         SimpleDateFormat formatoSalida = new SimpleDateFormat("yyyyMMdd");
	 	         
	 	         // Intentar diferentes formatos
	 	         String[] formatosPosibles = {
	 	             "yyyy-MM-dd",
	 	             "dd-MM-yyyy",
	 	             "yyyy/MM/dd",
	 	             "dd/MM/yyyy",
	 	             "MM/dd/yyyy",
	 	             "dd-MM-yy",
	 	             "yyyy-MM-dd HH:mm:ss",
	 	             "dd_MM_yyyy",      // Agregar formato con guiones bajos
	 	             "yyyy_MM_dd"       // Por si acaso viene al revés
	 	         };
	 	         
	 	         for (String formato : formatosPosibles) {
	 	             try {
	 	                 SimpleDateFormat sdf = new SimpleDateFormat(formato);
	 	                 sdf.setLenient(false);
	 	                 java.util.Date fechaParseada = sdf.parse(fecha);
	 	                 return formatoSalida.format(fechaParseada);
	 	             } catch (Exception e) {
	 	                 // Continuar con el siguiente formato
	 	             }
	 	         }
	 	         
	 	         // Si no se pudo parsear, devolver solo números
	 	         return fecha.replaceAll("[^0-9]", "");
	 	         
	 	     } catch (Exception e) {
	 	         System.out.println("Error al normalizar fecha: " + e.getMessage());
	 	         return fecha.replaceAll("[^0-9]", "");
	 	     }
	 	 }

