	 	/**
	 	* Metodo para localizar el archivo Excel (.xlsx o .xls) más recientemente modificado dentro de la carpeta de descargas del sistema.
	 	* @author Alejandro Valdez
	 	* @return Ruta absoluta del archivo Excel más reciente; null si la carpeta está vacía o no contiene archivos Excel válidos.
	 	* @date Octubre 2025
	 	*/
	 	private String obtenerUltimoArchivoDescargado() {
	 	    try {
	 	        String rutaDescargas = System.getProperty("user.home") + "/Downloads";
	 	        File carpetaDescargas = new File(rutaDescargas);
	 	        
	 	        if (!carpetaDescargas.exists()) {
	 	            System.out.println("La carpeta de descargas no existe");
	 	            return null;
	 	        }
	 	        
	 	        File[] archivos = carpetaDescargas.listFiles();
	 	        
	 	        if (archivos == null || archivos.length == 0) {
	 	            System.out.println("No hay archivos en la carpeta de descargas");
	 	            return null;
	 	        }
	 	        
	 	        // Filtrar solo archivos (no directorios) y archivos Excel
	 	        File archivoMasReciente = null;
	 	        long tiempoMasReciente = 0;
	 	        
	 	        for (File archivo : archivos) {
	 	            if (archivo.isFile() && 
	 	                (archivo.getName().endsWith(".xlsx") || archivo.getName().endsWith(".xls"))) {
	 	                
	 	                long tiempoModificacion = archivo.lastModified();
	 	                
	 	                if (tiempoModificacion > tiempoMasReciente) {
	 	                    tiempoMasReciente = tiempoModificacion;
	 	                    archivoMasReciente = archivo;
	 	                }
	 	            }
	 	        }
	 	        
	 	        if (archivoMasReciente != null) {
	 	            System.out.println("Último archivo descargado: " + archivoMasReciente.getName());
	 	            return archivoMasReciente.getAbsolutePath();
	 	        } else {
	 	            System.out.println("No se encontró ningún archivo Excel en Descargas");
	 	            return null;
	 	        }
	 	        
	 	    } catch (Exception e) {
	 	        System.out.println("Error al buscar último archivo: " + e.getMessage());
	 	        e.printStackTrace();
	 	        return null;
	 	    }
	 	}

	 	/**
	 	* Metodo para iterar sobre un archivo Excel de devoluciones y verificar que las celdas de importes financieros posean un formato de moneda válido.
	 	* @author Alejandro Valdez
	 	* @return True si todos los valores en las columnas monetarias definidas cumplen con el formato numérico esperado (con o sin símbolos); False si se detecta un formato inválido.
	 	* @date Octubre 2025
	 	*/
	 	public boolean validarFormatoMonetarioDevoluciones() {

	 	    // 1. Obtiene la ruta del último archivo descargado
	 	    String rutaExcel = obtenerUltimoArchivoDescargado();
	 	    System.out.println("Archivo detectado para validar: " + rutaExcel);

	 	    // Columnas a validar como formato monetario
	 	    // Nota: Excel empieza en 0, O=14, Q=16, U=20, V=21 por ejemplo
	 	    int[] columnasMonetarias = {15, 17, 21, 22};
	 	    System.out.println("Columnas a validar: " + Arrays.toString(columnasMonetarias));

	 	    try (FileInputStream file = new FileInputStream(new File(rutaExcel));
	 	         Workbook workbook = new XSSFWorkbook(file)) {

	 	        Sheet sheet = workbook.getSheetAt(0); // Primera hoja
	 	        System.out.println("Validando hoja: " + sheet.getSheetName());

	 	        DataFormatter formatter = new DataFormatter();

	 	        // Recorre las filas (empieza en 1 porque 0 suele ser encabezado)
	 	        for (int fila = 1; fila <= sheet.getLastRowNum(); fila++) {
	 	            Row row = sheet.getRow(fila);
	 	            if (row == null) {
	 	                System.out.println("Fila vacía, se omite -> " + (fila + 1));
	 	                continue;
	 	            }

	 	            System.out.println("Revisando fila: " + (fila + 1));

	 	            // Recorre las columnas monetarias definidas
	 	            for (int col : columnasMonetarias) {
	 	                Cell cell = row.getCell(col, Row.MissingCellPolicy.RETURN_BLANK_AS_NULL);

	 	                if (cell == null) {
	 	                    System.out.println("Celda vacía en columna " + (col + 1));
	 	                    continue;
	 	                }

	 	                // Obtiene el valor tal como se muestra en Excel (respetando formato aplicado en la celda)
	 	                String valor = formatter.formatCellValue(cell).trim();

	 	                if (valor.isEmpty()) {
	 	                    System.out.println("Celda vacía (string) en columna " + (col + 1));
	 	                    continue;
	 	                }

	 	               testCase.addTextEvidenceCurrentStep("Valor leído en fila " + (fila + 1) + " columna " + (col + 1) + ": '" + valor + "'");

	 	                // Validación del formato
	 	                if (!validarFormatoMoneda(valor)) {
	 	                    System.err.println("Formato inválido detectado en fila " + (fila + 1) + ", columna " + (col + 1) + " -> '" + valor + "'");
	 	                    return false;
	 	                }
	 	            }
	 	        }
	 	        
	 	        System.out.println("Validación completada: Todos los valores cumplen el formato monetario.");
	 	        
	 	        testCase.addTextEvidenceCurrentStep("Validación completada: Todos los valores cumplen el formato monetario.");
	 	        return true;

	 	    } catch (IOException e) {
	 	        System.err.println("Error al abrir/leer el archivo Excel: " + e.getMessage());
	 	        e.printStackTrace();
	 	        return false;
	 	    }
	 	}

	 	/**
	 	* Metodo para normalizar y validar cadenas de texto monetarias, admitiendo diversos separadores de miles/decimales y símbolos de divisa.
	 	* @author Alejandro Valdez
	 	* @param valor Cadena de texto que representa el importe a validar.
	 	* @return True si la cadena (tras remover símbolos y normalizar el punto decimal) representa un número válido con hasta 2 decimales; False en caso contrario.
	 	* @date Octubre 2025
	 	*/
	 	private boolean validarFormatoMoneda(String valor) {
	 	    if (valor == null) return false;

	 	    String normalized = valor;

	 	    // Quitar símbolos de moneda comunes
	 	    normalized = normalized.replace("$", "")
	 	                           .replace("€", "")
	 	                           .replace("\u00A0", " "); // NBSP -> espacio normal

	 	    // Quitar cualquier espacio/tab interno (incluye tabs)
	 	    normalized = normalized.trim().replaceAll("\\s+", "");

	 	    if (normalized.isEmpty()) return false;

	 	    // Si usa coma decimal (ej. "1.234,56"), pasar a "1234.56"
	 	    if (normalized.matches(".*,[0-9]{2}$") && !normalized.matches(".*\\.[0-9]{2}$")) {
	 	        normalized = normalized.replace(".", "").replace(",", ".");
	 	    } else {
	 	        normalized = normalized.replace(",", "");
	 	    }

	 	    // Acepta: 0, 220.50, 1234.56
	 	    return normalized.matches("\\d+(?:\\.\\d{2})?");
	 	}

	 	/**
	 	* Metodo para validar que los datos de la columna "Tasa Fiscal" en el archivo Excel descargado cumplan con el formato de porcentaje y dos decimales (ej. 16.00%).
	 	* @author Alejandro Valdez
	 	* @return True si todos los registros en la columna fiscal poseen el sufijo % y la precisión decimal correcta; False si se detecta un formato erróneo o fallo de lectura.
	 	* @date Octubre 2025
	 	*/
	 	public boolean validarFormatoTasaFiscal() {
	 	    // Obtiene el archivo descargado más reciente
	 	    String rutaExcel = obtenerUltimoArchivoDescargado();
	 	    System.out.println("Validando archivo: " + rutaExcel);

	 	// Índice de columna S = 18 (porque empieza en 0: A=0, B=1, ..., S=18)
	 	   int columnaTasaFiscal = 18;


	 	    try (FileInputStream file = new FileInputStream(new File(rutaExcel));
	 	         Workbook workbook = new XSSFWorkbook(file)) {

	 	        Sheet sheet = workbook.getSheetAt(0);
	 	        DataFormatter formatter = new DataFormatter();

	 	        // Recorre las filas (empieza en 1 para saltar encabezado)
	 	        for (int fila = 1; fila <= sheet.getLastRowNum(); fila++) {
	 	            Row row = sheet.getRow(fila);
	 	            if (row == null) continue;

	 	            Cell cell = row.getCell(columnaTasaFiscal, Row.MissingCellPolicy.RETURN_BLANK_AS_NULL);
	 	            if (cell == null) {
	 	                System.out.println("Fila " + (fila + 1) + " columna R vacía, se omite.");
	 	                continue;
	 	            }

	 	            // Obtiene valor como se muestra en Excel
	 	            String valor = formatter.formatCellValue(cell).trim();
	 	            testCase.addTextEvidenceCurrentStep("Fila " + (fila + 1) + " valor leído: '" + valor + "'");

	 	            // Validar con expresión regular: número con dos decimales y un %
	 	            if (!valor.matches("^\\d+\\.\\d{2}%$")) {
	 	                System.err.println("Formato inválido en fila " + (fila + 1) + " columna R -> '" + valor + "'");
	 	                return false;
	 	            }
	 	        }
	 	        System.out.println("Validación exitosa: Todas las tasas fiscales tienen % y dos decimales.");
	 	       testCase.addTextEvidenceCurrentStep("Validación exitosa: Todas las tasas fiscales tienen % y dos decimales.");
	 	        return true;

	 	    } catch (IOException e) {
	 	        System.err.println("Error al leer el archivo: " + e.getMessage());
	 	        e.printStackTrace();
	 	        return false;
	 	    }
	 	}

