	 	/**
	 	* Metodo para validar que los campos operativos (Fuente, Región, Plaza, Tienda, Fecha) del primer registro en el Excel de Cambios Físicos coincidan con los registros de la BD.
	 	* @author Alejandro Valdez
	 	* @param rutaExcel Ruta absoluta del archivo Excel de Cambios Físicos a procesar.
	 	* @return True si todos los datos clave coinciden íntegramente tras la normalización; False si se detectan variaciones entre la BD y el archivo físico.
	 	* @date Octubre 2025
	 	*/
	 	public boolean validarDatosCFEnExcel(String rutaExcel) {
	 	    try {
	 	        FileInputStream file = new FileInputStream(new File(rutaExcel));
	 	        Workbook workbook = rutaExcel.endsWith(".xlsx") 
	 	                          ? new XSSFWorkbook(file) 
	 	                          : new HSSFWorkbook(file);
	 	        
	 	        Sheet sheet = workbook.getSheetAt(0);
	 	        
	 	        // Leer el primer registro de datos (fila 1, índice 1)
	 	        // La fila 0 son los encabezados
	 	        Row primeraFila = sheet.getRow(1);
	 	        
	 	        if (primeraFila == null) {
	 	            System.out.println("No hay datos en el Excel");
	 	            workbook.close();
	 	            file.close();
	 	            return false;
	 	        }
	 	        
	 	        // Extraer datos del Excel según las columnas de la imagen
	 	        String excelFuente = obtenerValorCelda(primeraFila.getCell(0)); // Columna A: Fuente de Abasto
	 	        String excelRegion = obtenerValorCelda(primeraFila.getCell(2)); // Columna C: Región
	 	        String excelPlaza = obtenerValorCelda(primeraFila.getCell(3)); // Columna D: Plaza
	 	        String excelNombreTienda = obtenerValorCelda(primeraFila.getCell(5)); // Columna F: Nombre de Tienda
	 	        String excelFecha = obtenerValorCelda(primeraFila.getCell(8)); 
        
	 	        workbook.close();
	 	        file.close();
	 	        
	 	        // Comparar datos
	 	        boolean coincidencias = true;
	 	        StringBuilder diferencias = new StringBuilder();
	 	        diferencias.append("Validación de datos Excel vs BD:\n\n");
	 	        
	 	        // Comparar Fuente
	 	        if (!fuente.trim().equals(excelFuente.trim())) {
	 	            diferencias.append("Fuente NO coincide - BD: '" + fuente + "' | Excel: '" + excelFuente + "'\n");
	 	            coincidencias = false;
	 	        } else {
	 	            diferencias.append("Fuente coincide: " + fuente + "\n");
	 	        }
	 	        
	 	        // Comparar Plaza
	 	        if (!plaza.trim().contains(excelPlaza.trim()) && !excelPlaza.trim().contains(plaza.trim())) {
	 	            diferencias.append("Plaza NO coincide - BD: '" + plaza + "' | Excel: '" + excelPlaza + "'\n");
	 	            coincidencias = false;
	 	        } else {
	 	            diferencias.append("Plaza coincide: " + plaza + "\n");
	 	        }
	 	        
	 	        // Comparar Tienda
	 	        if (!tienda.trim().contains(excelNombreTienda.trim()) && !excelNombreTienda.trim().contains(tienda.trim())) {
	 	            diferencias.append("Tienda NO coincide - BD: '" + tienda + "' | Excel: '" + excelNombreTienda + "'\n");
	 	            coincidencias = false;
	 	        } else {
	 	            diferencias.append("Tienda coincide: " + tienda + "\n");
	 	        }
	 	        
	 	        // Comparar Fecha - Normalizar ambos formatos antes de comparar
	 	       String fechaBDNormalizada = normalizarFecha(fecha.trim());
	 	       String fechaExcelNormalizada = normalizarFecha(excelFecha.trim());

	 	       if (!fechaBDNormalizada.equals(fechaExcelNormalizada)) {
	 	           diferencias.append("Fecha NO coincide - BD: '" + fecha + "' | Excel: '" + excelFecha + "'\n");
	 	           coincidencias = false;
	 	       } else {
	 	           diferencias.append("Fecha coincide: " + fecha + "\n");
	 	       }
	 	        
	 	        System.out.println(diferencias.toString());
	 	        testCase.addTextEvidenceCurrentStep(diferencias.toString());
	 	        
	 	        if (coincidencias) {
	 	            System.out.println("TODOS los datos coinciden entre BD y Excel");
	 	            testCase.addTextEvidenceCurrentStep("Validación exitosa: Datos de BD coinciden con el Excel");
	 	        } else {
	 	            System.out.println("HAY DIFERENCIAS entre BD y Excel");
	 	            testCase.addTextEvidenceCurrentStep("Validación fallida: Hay diferencias entre BD y Excel");
	 	        }
	 	        
	 	        return coincidencias;
	 	        
	 	    } catch (Exception e) {
	 	        System.out.println("Error al validar datos en Excel: " + e.getMessage());
	 	        e.printStackTrace();
	 	        testCase.addTextEvidenceCurrentStep("Error al validar Excel: " + e.getMessage());
	 	        return false;
	 	    }
	 	}

