	 	/**
	 	* Metodo para verificar de forma exhaustiva que un archivo Excel contenga una lista predefinida de 21 encabezados específicos (desde FA hasta Precio Total).
	 	* @author Alejandro Valdez
	 	* @param rutaExcel Ruta del archivo Excel a auditar.
	 	* @return True si el archivo físico presenta exactamente todos los encabezados obligatorios en la primera fila; False si faltan elementos, generando un reporte de discrepancias.
	 	* @date Octubre 2025
	 	*/
	 	public boolean validarEncabezadosExcel(String rutaExcel) {
	 	    try {
	 	        FileInputStream file = new FileInputStream(new File(rutaExcel));
	 	        Workbook workbook = rutaExcel.endsWith(".xlsx") 
	 	                          ? new XSSFWorkbook(file) 
	 	                          : new HSSFWorkbook(file);
	 	        
	 	        Sheet sheet = workbook.getSheetAt(0);
	 	        Row headerRow = sheet.getRow(0); // Primera fila con encabezados
	 	        
	 	        if (headerRow == null) {
	 	            System.out.println("No se encontró la fila de encabezados");
	 	            workbook.close();
	 	            file.close();
	 	            return false;
	 	        }
	 	        
	 	        // Lista de encabezados requeridos
	 	        String[] encabezadosRequeridos = {
	 	            "Fuente de Abasto",
	 	            "Nombre del Proveedor",
	 	            "Región",
	 	            "Plaza",
	 	            "CR Tienda",
	 	            "Nombre de la Tienda",
	 	            "Tipo de ticket",
	 	            "Sub tipo de ticket",
	 	            "Fecha",
	 	            "Hora",
	 	            "Remisión",
	 	            "Tiempo de Captura",
	 	            "CVE Artículo",
	 	            "Descripción",
	 	            "Fecha de captura",
	 	            "Días transcurridos",
	 	            "Cantidad",
	 	            "Costo Unitario",
	 	            "Costo Total",
	 	            "Precio unitario",
	 	            "Precio Total"
	 	        };
	 	        
	 	        // Obtener todos los encabezados del Excel
	 	        List<String> encabezadosEncontrados = new ArrayList<>();
	 	        for (Cell cell : headerRow) {
	 	            if (cell != null && cell.getCellType() != CellType.BLANK) {
	 	                String encabezado = obtenerValorCelda(cell).trim();
	 	                encabezadosEncontrados.add(encabezado);
	 	            }
	 	        }
	 	        
	 	        // Validar que existan todos los encabezados requeridos
	 	        List<String> encabezadosFaltantes = new ArrayList<>();
	 	        List<String> encabezadosEncontradosValidos = new ArrayList<>();
	 	        
	 	        for (String requerido : encabezadosRequeridos) {
	 	            boolean encontrado = false;
	 	            
	 	            for (String encontradoExcel : encabezadosEncontrados) {
	 	                // Comparar ignorando mayúsculas/minúsculas y espacios extras
	 	                if (encontradoExcel.equalsIgnoreCase(requerido.trim())) {
	 	                    encontrado = true;
	 	                    encabezadosEncontradosValidos.add(requerido);
	 	                    break;
	 	                }
	 	            }
	 	            
	 	            if (!encontrado) {
	 	                encabezadosFaltantes.add(requerido);
	 	            }
	 	        }
	 	        
	 	        workbook.close();
	 	        file.close();
	 	        
	 	        // Generar reporte
	 	        StringBuilder reporte = new StringBuilder();
	 	        reporte.append("=== VALIDACIÓN DE ENCABEZADOS ===\n\n");
	 	        reporte.append("Total de encabezados requeridos: ").append(encabezadosRequeridos.length).append("\n");
	 	        reporte.append("Encabezados encontrados: ").append(encabezadosEncontradosValidos.size()).append("\n");
	 	        reporte.append("Encabezados faltantes: ").append(encabezadosFaltantes.size()).append("\n\n");
	 	        
	 	        if (encabezadosFaltantes.isEmpty()) {
	 	            reporte.append("TODOS los encabezados requeridos están presentes\n\n");
	 	            reporte.append("Encabezados validados:\n");
	 	            for (String enc : encabezadosEncontradosValidos) {
	 	                reporte.append("  -> ").append(enc).append("\n");
	 	            }
	 	            
	 	            System.out.println(reporte.toString());
	 	            testCase.addTextEvidenceCurrentStep(reporte.toString());
	 	            return true;
	 	            
	 	        } else {
	 	            reporte.append("FALTAN los siguientes encabezados:\n");
	 	            for (String faltante : encabezadosFaltantes) {
	 	                reporte.append("  X ").append(faltante).append("\n");
	 	            }
	 	            
	 	            reporte.append("\nEncabezados encontrados:\n");
	 	            for (String enc : encabezadosEncontradosValidos) {
	 	                reporte.append(" -> ").append(enc).append("\n");
	 	            }
	 	            
	 	            System.out.println(reporte.toString());
	 	            testCase.addTextEvidenceCurrentStep(reporte.toString());
	 	            return false;
	 	        }
	 	        
	 	    } catch (Exception e) {
	 	        System.out.println("Error al validar encabezados: " + e.getMessage());
	 	        e.printStackTrace();
	 	        testCase.addTextEvidenceCurrentStep("Error al validar encabezados: " + e.getMessage());
	 	        return false;
	 	    }
	 	}

	 	/**
	 	* Metodo para validar que todas las filas de las columnas financieras (índices 18 a 21) en el Excel de Cambios Físicos cumplan con un formato monetario válido.
	 	* @author Alejandro Valdez
	 	* @return True si todos los valores leídos en las columnas de Costos y Precios poseen la estructura numérica correcta (hasta 2 decimales); False si se detecta un formato inválido.
	 	* @date Octubre 2025
	 	*/
	 	public boolean validarFormatoMonetarioCF() {

	 	    // 1. Obtiene la ruta del último archivo descargado
	 	    String rutaExcel = obtenerUltimoArchivoDescargado();
	 	    System.out.println("Archivo detectado para validar: " + rutaExcel);

	 	    // Columnas a validar como formato monetario
	 	    // Nota: Excel empieza en 0, O=14, Q=16, U=20, V=21 por ejemplo
	 	   int[] columnasMonetarias = {18, 19, 20, 21};
	 	    System.out.println("Columnas a validar: " + Arrays.toString(columnasMonetarias));

	 	    try (FileInputStream file = new FileInputStream(new File(rutaExcel));
	 	         Workbook workbook = new XSSFWorkbook(file)) {

	 	        Sheet sheet = workbook.getSheetAt(0); // Primera hoja
	 	        System.out.println("Validando hoja: " + sheet.getSheetName());

	 	        DataFormatter formatter = new DataFormatter();

	 	        // Recorre las filas (empieza en 1 porque 0 suele ser encabezado)
	 	        for (int fila = 1; fila <= sheet.getLastRowNum(); fila++) {
	 	            Row row = sheet.getRow(fila);
	 	            if (row == null) {
	 	                System.out.println("Fila vacía, se omite -> " + (fila + 1));
	 	                continue;
	 	            }

	 	            System.out.println("Revisando fila: " + (fila + 1));

	 	            // Recorre las columnas monetarias definidas
	 	            for (int col : columnasMonetarias) {
	 	                Cell cell = row.getCell(col, Row.MissingCellPolicy.RETURN_BLANK_AS_NULL);

	 	                if (cell == null) {
	 	                    System.out.println("Celda vacía en columna " + (col + 1));
	 	                    continue;
	 	                }

	 	                // Obtiene el valor tal como se muestra en Excel (respetando formato aplicado en la celda)
	 	                String valor = formatter.formatCellValue(cell).trim();

	 	                if (valor.isEmpty()) {
	 	                    System.out.println("Celda vacía (string) en columna " + (col + 1));
	 	                    continue;
	 	                }

	 	               testCase.addTextEvidenceCurrentStep("Valor leído en fila " + (fila + 1) + " columna " + (col + 1) + ": '" + valor + "'");

	 	                // Validación del formato
	 	                if (!validarFormatoMoneda(valor)) {
	 	                    System.err.println("Formato inválido detectado en fila " + (fila + 1) + ", columna " + (col + 1) + " -> '" + valor + "'");
	 	                    return false;
	 	                }
	 	            }
	 	        }
	 	        
	 	        System.out.println("Validación completada: Todos los valores cumplen el formato monetario.");
	 	        
	 	        testCase.addTextEvidenceCurrentStep("Validación completada: Todos los valores cumplen el formato monetario.");
	 	        return true;

	 	    } catch (IOException e) {
	 	        System.err.println("Error al abrir/leer el archivo Excel: " + e.getMessage());
	 	        e.printStackTrace();
	 	        return false;
	 	    }
	 	}

	 	/**
	 	* Metodo para obtener el registro histórico de CEDIS más reciente que posea un formato de verificación activo, vinculando datos de correo y jerarquía de tiendas.
	 	* @author Alejandro Valdez
	 	* @param imprimirDatos Booleano para capturar un resumen descriptivo de la transferencia, plaza y ruta obtenidas en el reporte.
	 	* @return True si se localiza un registro histórico válido de tipo 'cedis-devolucion' visible; False si no hay resultados o ocurre un fallo de SQL.
	 	* @date Octubre 2025
	 	*/
	 	public boolean obtenerRegistroCedis(boolean imprimirDatos) {
	 	    String query = "SELECT t.transferencia, t.plaza, t.tienda, t.ruta, t.fecha_registro " +
	 	                  "FROM xxcm_historico_cedis_view AS t " +
	 	                  "WHERE t.transferencia IN ( " +
	 	                  "SELECT DISTINCT H.TRANSFERENCIA " +
	 	                  "FROM XXCM_HISTORICO_CORREOS H " +
	 	                  "JOIN XXCM_CEDIS C ON H.SUPPLIABLE_ID = C.ID_SUPPLIER " +
	 	                  "JOIN XXCM_REGION_PLAZA_TIENDA_JOB_SYNC T ON H.ID_RETEK = T.ID_RETEK " +
	 	                  "JOIN XXCM_DIM_TIENDA DTC ON T.ID_RETEK = DTC.RETEK_LOC_ID " +
	 	                  "WHERE H.ORIGEN::TEXT = 'cedis-devolucion'::TEXT " +
	 	                  "AND H.IS_VISIBLE = TRUE " +
	 	                  "AND H.FECHA_REGISTRO::DATE >= '2025-06-01'::DATE " +
	 	                  ") " +
	 	                  "ORDER BY t.fecha_registro DESC " +
	 	                  "LIMIT 1";

	 	    String dbUrl = GlobalVariables.DB_URL_Cometa;
	 	    String dbUser = GlobalVariables.DB_USER_Cometa;
	 	    String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	 	    try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	 	         Statement stmt = connection.createStatement();
	 	         ResultSet rs = stmt.executeQuery(query)) {
	 	                        
	 	        if (rs.next()) {
	 	            // Guardar valores en las variables globales existentes
	 	            transferencia = rs.getString("transferencia") != null 
	 	                    ? rs.getString("transferencia") : "";
	 	            plaza = rs.getString("plaza") != null 
	 	                   ? rs.getString("plaza") : "";
	 	            tienda = rs.getString("tienda") != null 
	 	                    ? rs.getString("tienda") : "";
	 	            ruta = rs.getString("ruta") != null 
	 	                    ? rs.getString("ruta") : "";
	 	            fecha = rs.getString("fecha_registro") != null 
	 	                    ? rs.getString("fecha_registro") : "";
	 	            
	 	            System.out.println("Datos de CEDIS obtenidos exitosamente:");
	 	            System.out.println("Transferencia: " + transferencia);
	 	            System.out.println("Plaza: " + plaza);
	 	            System.out.println("Tienda: " + tienda);
	 	            System.out.println("Ruta: " + ruta);
	 	            System.out.println("Fecha Registro: " + fecha);
	 	            
	 	            // Imprimir datos solo si se solicita
	 	            if (imprimirDatos) {
	 	                String datosObtenidos = "Transferencia: " + transferencia + "\n" +
	 	                                       "Plaza: " + plaza + "\n" +
	 	                                       "Tienda: " + tienda + "\n" +
	 	                                       "Ruta: " + ruta + "\n" +
	 	                                       "Fecha Registro: " + fecha;
	 	                testCase.addTextEvidenceCurrentStep(datosObtenidos);
	 	            }
	 	            
	 	            return true;
	 	            
	 	        } else {
	 	            System.out.println("La consulta no contiene resultados");
	 	            // Limpiar variables globales
	 	            limpiarVariablesGlobalesCedis();
	 	            return false;
	 	        }
	 	        
	 	    } catch (SQLException e) {
	 	        System.out.println("Error al ejecutar la consulta SQL: " + e.getMessage());
	 	        e.printStackTrace();
	 	        // Limpiar variables globales en caso de error
	 	        limpiarVariablesGlobalesCedis();
	 	        return false;
	 	    }
	 	}

	 	/**
	 	* Metodo para limpiar y resetear los valores de las variables globales de gestión de registros de CEDIS (Transferencia, Plaza, Tienda, Ruta, Fecha).
	 	* @author Alejandro Valdez
	 	* @date Octubre 2025
	 	*/
	 	private void limpiarVariablesGlobalesCedis() {
	 	    transferencia = "";
	 	    plaza = "";
	 	    tienda = "";
	 	    ruta = "";
	 	    fecha = "";
	 	}

	 	/**
	 	* Metodo para extraer el texto de un archivo PDF descargado y validar que los campos operativos (FA, CR Tienda y Fecha) coincidan exactamente con los filtros aplicados en el portal.
	 	* @author Alejandro Valdez
	 	* @return True si se localiza el PDF y tras la extracción de texto se confirma que los valores normalizados coinciden con las variables de entrada; False en caso de discrepancia o fallo de lectura.
	 	* @date Octubre 2025
	 	*/
	 	public boolean validarCamposEnPDFConFiltros() throws Exception {
	 	    try {
	 	        // PASO 1: Localizar el archivo PDF
	 	        testCase.addTextEvidenceCurrentStep("Iniciando validación de campos en PDF...");
	 	        String home = System.getProperty("user.home") + "\\Downloads";
	 	        testCase.addTextEvidenceCurrentStep("Buscando PDF en: " + home);
	 	        
	 	        File file = new File(getLastModified(home).getAbsolutePath());
	 	        testCase.addTextEvidenceCurrentStep("Archivo encontrado: " + file.getName());
	 	        
	 	        if (!file.exists()) {
	 	            testCase.addTextEvidenceCurrentStep("ERROR: No se encontró el archivo PDF en la ruta especificada.");
	 	            return false;
	 	        }
	 	        
	 	        // PASO 2: Cargar y extraer texto del PDF
	 	        try (PDDocument document = Loader.loadPDF(file)) { 	            
	 	            PDFTextStripper stripper = new PDFTextStripper();
	 	            String textoCompleto = stripper.getText(document);
	 	            
	 	            
	 	            // PASO 3: Buscar los campos específicos en el PDF
	 	            String[] lineas = textoCompleto.split("\\r?\\n");
	 	            
	 	            String valorFA = null;
	 	            String valorCRTienda = null;
	 	            String valorFecha = null;
	 	            
	 	            for (int i = 0; i < lineas.length; i++) {
	 	                String linea = lineas[i];
	 	                String lineaTrim = linea.trim().toLowerCase();
	 	                
	 	                if (lineaTrim.startsWith("fa:") && valorFA == null) {
	 	                    valorFA = linea.substring(linea.indexOf(":") + 1).trim();
	 	                    testCase.addTextEvidenceCurrentStep("Campo FA encontrado en línea " + (i+1) + ": '" + valorFA + "'");
	 	                } else if (lineaTrim.startsWith("cr tienda:") && valorCRTienda == null) {
	 	                    valorCRTienda = linea.substring(linea.indexOf(":") + 1).trim();
	 	                    testCase.addTextEvidenceCurrentStep("Campo CR tienda encontrado en línea " + (i+1) + ": '" + valorCRTienda + "'");
	 	                } else if (lineaTrim.startsWith("fecha:") && valorFecha == null) {
	 	                    valorFecha = linea.substring(linea.indexOf(":") + 1).trim();
	 	                    testCase.addTextEvidenceCurrentStep("Campo Fecha encontrado en línea " + (i+1) + ": '" + valorFecha + "'");
	 	                }
	 	            }
	 	            
	 	            // PASO 4: Validar que se encontraron todos los campos
	 	            boolean todosEncontrados = true;
	 	            StringBuilder camposFaltantes = new StringBuilder();
	 	            
	 	            if (valorFA == null) {
	 	                camposFaltantes.append("FA, ");
	 	                todosEncontrados = false;
	 	            }
	 	            if (valorCRTienda == null) {
	 	                camposFaltantes.append("CR tienda, ");
	 	                todosEncontrados = false;
	 	            }
	 	            if (valorFecha == null) {
	 	                camposFaltantes.append("Fecha, ");
	 	                todosEncontrados = false;
	 	            }
	 	            
	 	            if (!todosEncontrados) {
	 	                testCase.addTextEvidenceCurrentStep("ERROR: No se encontraron los siguientes campos en el PDF: " 
	 	                    + camposFaltantes.toString().replaceAll(", $", ""));
	 	                testCase.addTextEvidenceCurrentStep("Revise el formato del PDF o los nombres de los campos.");
	 	                return false;
	 	            }
	 	            
	 	            testCase.addTextEvidenceCurrentStep("Todos los campos requeridos fueron encontrados en el PDF.");
	 	            
	 	            // PASO 5: Validar que los valores coincidan con los filtros
	 	           testCase.addBoldTextEvidenceCurrentStep("Comparando valores del PDF con los filtros esperados...");
	 	           testCase.addTextEvidenceCurrentStep("Filtro FA esperado: '" + fuente + "'");
	 	           testCase.addTextEvidenceCurrentStep("Filtro CR tienda esperado: '" + tienda + "'");
	 	           testCase.addTextEvidenceCurrentStep("Filtro Fecha esperado: '" + fecha + "'");

	 	           boolean todosCoinciden = true;
	 	           StringBuilder errores = new StringBuilder();

	 	           // Normalizar espacios: reemplazar múltiples espacios por uno solo
	 	           String valorFANormalizado = valorFA.replaceAll("\\s+", " ");
	 	           String valorCRTiendaNormalizado = valorCRTienda.replaceAll("\\s+", " ");
	 	           String valorFechaNormalizado = valorFecha.replaceAll("\\s+", " ");

	 	           testCase.addBoldTextEvidenceCurrentStep("Valores normalizados del PDF:");
	 	           testCase.addTextEvidenceCurrentStep("FA normalizado: '" + valorFANormalizado + "'");
	 	           testCase.addTextEvidenceCurrentStep("CR tienda normalizado: '" + valorCRTiendaNormalizado + "'");
	 	           testCase.addTextEvidenceCurrentStep("Fecha normalizado: '" + valorFechaNormalizado + "'");

	 	           // Validar FA
	 	           if (!valorFANormalizado.contains(fuente)) {
	 	               errores.append("FA: Se esperaba que contuviera '" + fuente + "' pero se encontró '" + valorFANormalizado + "'. ");
	 	               todosCoinciden = false;
	 	               testCase.addTextEvidenceCurrentStep("FA NO coincide");
	 	           } else {
	 	               testCase.addBoldTextEvidenceCurrentStep("FA coincide correctamente");
	 	           }

	 	           // Validar CR tienda
	 	           if (!valorCRTiendaNormalizado.contains(tienda)) {
	 	               errores.append("CR tienda: Se esperaba que contuviera '" + tienda + "' pero se encontró '" + valorCRTiendaNormalizado + "'. ");
	 	               todosCoinciden = false;
	 	               testCase.addTextEvidenceCurrentStep("CR tienda NO coincide");
	 	           } else {
	 	               testCase.addBoldTextEvidenceCurrentStep("CR tienda coincide correctamente");
	 	           }

	 	           // Validar Fecha
	 	           if (!valorFechaNormalizado.contains(fecha)) {
	 	               errores.append("Fecha: Se esperaba que contuviera '" + fecha + "' pero se encontró '" + valorFechaNormalizado + "'. ");
	 	               todosCoinciden = false;
	 	               testCase.addTextEvidenceCurrentStep("Fecha NO coincide");
	 	           } else {
	 	               testCase.addBoldTextEvidenceCurrentStep("Fecha coincide correctamente");
	 	           }
	 	            
	 	            // PASO 6: Resultado final
	 	            if (todosCoinciden) {
	 	                testCase.addBoldTextEvidenceCurrentStep("ÉXITO: Todos los campos en el PDF coinciden con los filtros.");
	 	        
	 	                return true;
	 	            } else {
	 	                testCase.addTextEvidenceCurrentStep("ERROR: Los campos en el PDF NO coinciden con los filtros esperados.");
	 	                testCase.addTextEvidenceCurrentStep("Detalles de los errores: " + errores.toString());
	 	                return false;
	 	            }
	 	        }
	 	    } catch (IOException ioEx) {
	 	        testCase.addTextEvidenceCurrentStep("ERROR DE LECTURA: No se pudo leer el archivo PDF.");
	 	        testCase.addTextEvidenceCurrentStep("Mensaje de error: " + ioEx.getMessage());
	 	        testCase.addTextEvidenceCurrentStep("Causa posible: Archivo corrupto, en uso, o sin permisos de lectura.");
	 	        ioEx.printStackTrace();
	 	        return false;
	 	    } catch (NullPointerException npEx) {
	 	        testCase.addTextEvidenceCurrentStep("ERROR: Valor nulo detectado.");
	 	        testCase.addTextEvidenceCurrentStep("Mensaje de error: " + npEx.getMessage());
	 	        testCase.addTextEvidenceCurrentStep("Causa posible: Variables 'fuente', 'tienda' o 'fecha' no inicializadas.");
	 	        npEx.printStackTrace();
	 	        return false;
	 	    } catch (Exception e) {
	 	        testCase.addTextEvidenceCurrentStep("ERROR INESPERADO durante la validación del PDF.");
	 	        testCase.addTextEvidenceCurrentStep("Tipo de error: " + e.getClass().getName());
	 	        testCase.addTextEvidenceCurrentStep("Mensaje de error: " + e.getMessage());
	 	        testCase.addTextEvidenceCurrentStep("Stack trace completo impreso en consola.");
	 	        e.printStackTrace();
	 	        return false;
	 	    }
	 	}

	 	/**
	 	* Metodo para consultar y listar todos los identificadores "Retek ID" asociados a una fuente de abasto específica en la base de datos de histórico.
	 	* @author Alejandro Valdez
	 	* @return True si se encuentran y listan uno o más identificadores Retek para la fuente activa; False si no hay registros o ocurre una excepción de SQL.
	 	* @date Octubre 2025
	 	*/
	 	public boolean obtenerReteksId() {

	 	    String queryReteks = 
	 	        "WITH cte_data AS ( " +
	 	        "SELECT " +
	 	        "t.id, " +
	 	        "t.rfc, " +
	 	        "t.fuente_de_abasto, " +
	 	        "t.supplier, " +
	 	        "t.supplier_name, " +
	 	        "t.body ->> 'Plaza' AS region, " +
	 	        "t.zona, " +
	 	        "t.plaza, " +
	 	        "t.cr_plaza, " +
	 	        "t.desc_plaza, " +
	 	        "(t.cr_plaza::text || ' '::text) || t.desc_plaza::text AS cr_desc_plaza, " +
	 	        "t.cr_tienda, " +
	 	        "t.tienda, " +
	 	        "t.body ->> 'Tienda' AS desc_tienda, " +
	 	        "t.id_retek, " +
	 	        "CASE  " +
	 	        "    WHEN t.body->>'Fecha_Fin_estadia' IS NOT NULL AND t.body->>'Fecha_Fin_estadia' <> ''  " +
	 	        "    THEN TO_TIMESTAMP(t.body->>'Fecha_Fin_estadia', 'DD-MM-YYYY HH24:MI:SS')  " +
	 	        "    ELSE t.fecha_registro  " +
	 	        "END AS fecha, " +
	 	        "t.body ->> 'Remision' AS remision1, " +
	 	        "d.remision AS remision2, " +
	 	        "t.body ->> 'DoneQty' AS piezas_realizadas, " +
	 	        "t.body ->> 'DoneTotal' AS precio, " +
	 	        "t.body ->> 'PendingQty' AS piezas_pendientes, " +
	 	        "t.body ->> 'Tipo' AS tipo_ticket " +
	 	        "FROM xxcm_historico_directos_cf_view AS t " +
	 	        "LEFT JOIN ( " +
	 	        "    SELECT t1.id, string_agg(t2 ->> 'remision', ',') AS remision  " +
	 	        "    FROM xxcm_historico_directos_cf_view t1, jsonb_array_elements(t1.body -> 'Detalle_Realizados') t2 " +
	 	        "    GROUP BY t1.id " +
	 	        ") AS d ON t.id = d.id " +
	 	        "), " +
	 	        "cte_data_union_remision AS ( " +
	 	        "    SELECT  " +
	 	        "        t.id, " +
	 	        "        t.rfc, " +
	 	        "        t.fuente_de_abasto, " +
	 	        "        t.supplier, " +
	 	        "        t.supplier_name, " +
	 	        "        t.region, " +
	 	        "        t.zona, " +
	 	        "        t.plaza, " +
	 	        "        t.cr_plaza, " +
	 	        "        t.desc_plaza, " +
	 	        "        t.cr_desc_plaza, " +
	 	        "        t.cr_tienda, " +
	 	        "        t.tienda, " +
	 	        "        t.desc_tienda, " +
	 	        "        t.id_retek, " +
	 	        "        t.fecha::date AS fecha, " +
	 	        "        CASE WHEN t.tipo_ticket = '1' THEN t.remision1 ELSE t.remision2 END AS remision, " +
	 	        "        t.piezas_realizadas, " +
	 	        "        t.precio, " +
	 	        "        t.piezas_pendientes, " +
	 	        "        t.tipo_ticket " +
	 	        "    FROM cte_data AS t " +
	 	        ") " +
	 	        "SELECT DISTINCT t.id_retek  " +
	 	        "FROM cte_data_union_remision AS t " +
	 	        "WHERE t.fuente_de_abasto = '" + fuente + "' " +
	 	        "ORDER BY t.id_retek;";

	 	    String bd = GlobalVariables.DB_URL_Cometa;
	 	    String user = GlobalVariables.DB_USER_Cometa;
	 	    String password = GlobalVariables.DB_PASSWORD_Cometa;

	 	    boolean resultado = false;

	 	    try (Connection connection = DriverManager.getConnection(bd, user, password);
	 	         Statement stmt = connection.createStatement();
	 	         ResultSet rs = stmt.executeQuery(queryReteks)) {

	 	        System.out.println("Conexión exitosa con la base de datos de Cometa.");
	 	        System.out.println("Ejecutando consulta de id_retek...\n");

	 	        List<String> idReteks = new ArrayList<>();
	 	        while (rs.next()) {
	 	            idReteks.add(rs.getString("id_retek"));
	 	        }

	 	        if (idReteks.isEmpty()) {
	 	            System.out.println("No se encontraron registros para fuente_de_abasto = "+fuente+"");
	 	            resultado = false;
	 	        } else {
	 	            testCase.addBoldTextEvidenceCurrentStep("IDs encontrados:");
	 	            for (String id : idReteks) {
	 	                testCase.addTextEvidenceCurrentStep(" - " + id);
	 	            }
	 	            resultado = true;
	 	        }

	 	    } catch (SQLException e) {
	 	        System.err.println("Error al ejecutar la consulta de id_retek:");
	 	        e.printStackTrace();
	 	        resultado = false;
	 	    }

	 	    return resultado;
	 	}

	 	/**
	 	 * Metodo para obtener la fecha operativa mas reciente de la base de datos basandose en el perfil de jerarquia
	 	 * (ADMIN, OXXO_PLAZA, Proveedor) del usuario ingresado.
	 	 * @author Jose Pecina / Alejandro Valdez
	 	 * @param usuario Nombre de usuario para determinar el alcance geografico o de proveedor de la consulta.
	 	 * @return Cadena con la fecha mas reciente detectada en formato YYYY-MM-DD; null si no se localizan registros.
	 	 * @date Diciembre 2025
	 	 */
	 	public String obtenerFechaPorUsuario(String usuario) throws Exception {
	 	    try {
	 	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	 	        String dbUser = GlobalVariables.DB_USER_Cometa;
	 	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	 	        String PCPERFIL = "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' "
	 	                + "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

	 	        String PCRFC = "select key_value from xxcm_user_keys where short_name in ('PCRFC', 'PCSUPPLIERID','PCPLAZA') "
	 	                + "and usuario_id in (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

	 	        String FechaBD = null;

	 	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	 	             Statement stmt = connection.createStatement();
	 	             ResultSet rs = stmt.executeQuery(PCPERFIL)) {

	 	            if (rs.next()) {  // Usuario con perfil definido
	 	                String keyValue = rs.getString("key_value");
	 	                System.out.println("Usuario con perfil: " + keyValue);

	 	                if (!"ADMIN".equalsIgnoreCase(keyValue) && !"OXXO_OS".equalsIgnoreCase(keyValue)) {

	 	                    try (ResultSet rs2 = stmt.executeQuery(PCRFC)) {
	 	                        if (rs2.next()) {
	 	                            String RFC = rs2.getString("key_value");
	 	                            String sqlPlaza;

	 	                            if ("OXXO_PLAZA".equalsIgnoreCase(keyValue)) {
	 	                                sqlPlaza = "select plaza from xxcm_cc "
	 	                                        + "where cr_desc_plaza = '" + RFC + "' "
	 	                                        + "order by fecha desc limit 1";
	 	                            } else {
	 	                                sqlPlaza = "select plaza from xxcm_cc "
	 	                                        + "where proveedor_rfc = '" + RFC + "' "
	 	                                        + "order by fecha desc limit 1";
	 	                            }

	 	                            ResultSet rs5 = stmt.executeQuery(sqlPlaza);

	 	                            if (rs5.next()) {
	 	                                String BodyPlaza = rs5.getString("plaza");
	 	                                String sqlFecha;

	 	                                if ("OXXO_PLAZA".equalsIgnoreCase(keyValue)) {
	 	                                    sqlFecha = "select fecha from xxcm_cc "
	 	                                            + "where cr_desc_plaza = '" + RFC + "' "
	 	                                            + "and plaza = '" + BodyPlaza + "' "
	 	                                            + "order by fecha desc limit 1";
	 	                                } else {
	 	                                    sqlFecha = "select fecha from xxcm_cc "
	 	                                            + "where proveedor_rfc = '" + RFC + "' "
	 	                                            + "and plaza = '" + BodyPlaza + "' "
	 	                                            + "order by fecha desc limit 1";
	 	                                }

	 	                                try (ResultSet rs3 = stmt.executeQuery(sqlFecha)) {
	 	                                    if (rs3.next()) {
	 	                                        Timestamp ts = rs3.getTimestamp("fecha");
	 	                                        if (ts != null) {
	 	                                            FechaBD = ts.toLocalDateTime().toLocalDate().toString();
	 	                                        } else {
	 	                                            FechaBD = rs3.getString("fecha");
	 	                                            if (FechaBD != null && FechaBD.contains(" ")) {
	 	                                                FechaBD = FechaBD.split(" ")[0];
	 	                                            }
	 	                                        }
	 	                                        System.out.println("Fecha mas reciente obtenida: " + FechaBD);
	 	                                    } else {
	 	                                        System.out.println("No se obtuvo informacion de la fecha.");
	 	                                        return null;
	 	                                    }
	 	                                }
	 	                            } else {
	 	                                System.out.println("No se obtuvo informacion de la plaza.");
	 	                                return null;
	 	                            }
	 	                        } else {
	 	                            System.out.println("No se obtuvo informacion del RFC.");
	 	                            return null;
	 	                        }
	 	                    }

	 	                } else { // ADMIN u OXXO_OS

	 	                    String sqlPlaza = "select plaza from xxcm_cc order by fecha desc limit 1";
	 	                    ResultSet rs5 = stmt.executeQuery(sqlPlaza);

	 	                    if (rs5.next()) {
	 	                        String BodyPlaza = rs5.getString("plaza");
	 	                        String sqlFecha = "select fecha from xxcm_cc "
	 	                                + "where plaza = '" + BodyPlaza + "' "
	 	                                + "order by fecha desc limit 1";

	 	                        try (ResultSet rs2 = stmt.executeQuery(sqlFecha)) {
	 	                            if (rs2.next()) {
	 	                                Timestamp ts = rs2.getTimestamp("fecha");
	 	                                if (ts != null) {
	 	                                    FechaBD = ts.toLocalDateTime().toLocalDate().toString();
	 	                                } else {
	 	                                    FechaBD = rs2.getString("fecha");
	 	                                    if (FechaBD != null && FechaBD.contains(" ")) {
	 	                                        FechaBD = FechaBD.split(" ")[0];
	 	                                    }
	 	                                }
	 	                                System.out.println("Fecha mas reciente obtenida: " + FechaBD);
	 	                            } else {
	 	                                System.out.println("No se obtuvo informacion de la fecha.");
	 	                                return null;
	 	                            }
	 	                        }
	 	                    } else {
	 	                        System.out.println("No se obtuvo informacion de la plaza.");
	 	                        return null;
	 	                    }
	 	                }

	 	            } else { // Usuario sin perfil definido (CEDIS)

	 	                try (ResultSet rs2 = stmt.executeQuery(PCRFC)) {
	 	                    if (rs2.next()) {
	 	                        String RFC = rs2.getString("key_value");
	 	                        String sqlPlaza = "select plaza from xxcm_cc "
	 	                                + "where proveedor_rfc = '" + RFC + "' "
	 	                                + "order by fecha desc limit 1";

	 	                        ResultSet rs5 = stmt.executeQuery(sqlPlaza);

	 	                        if (rs5.next()) {
	 	                            String BodyPlaza = rs5.getString("plaza");
	 	                            String sqlFecha = "select fecha from xxcm_cc "
	 	                                    + "where proveedor_rfc = '" + RFC + "' "
	 	                                    + "and plaza = '" + BodyPlaza + "' "
	 	                                    + "order by fecha desc limit 1";

	 	                            try (ResultSet rs3 = stmt.executeQuery(sqlFecha)) {
	 	                                if (rs3.next()) {
	 	                                    Timestamp ts = rs3.getTimestamp("fecha");
	 	                                    if (ts != null) {
	 	                                        FechaBD = ts.toLocalDateTime().toLocalDate().toString();
	 	                                    } else {
	 	                                        FechaBD = rs3.getString("fecha");
	 	                                        if (FechaBD != null && FechaBD.contains(" ")) {
	 	                                            FechaBD = FechaBD.split(" ")[0];
	 	                                        }
	 	                                    }
	 	                                    System.out.println("Fecha mas reciente obtenida: " + FechaBD);
	 	                                } else {
	 	                                    System.out.println("No se obtuvo informacion de la fecha.");
	 	                                    return null;
	 	                                }
	 	                            }
	 	                        } else {
	 	                            System.out.println("No se obtuvo informacion de la plaza.");
	 	                            return null;
	 	                        }
	 	                    } else {
	 	                        System.out.println("No se obtuvo informacion del RFC.");
	 	                        return null;
	 	                    }
	 	                }
	 	            }
	 	        }

	 	        return FechaBD;

	 	    } catch (Exception e) {
	 	        System.out.println("[ERROR] Error al obtener fecha: " + e.getMessage());
	 	        e.printStackTrace();
	 	        throw new Exception("Error al obtener fecha: " + e.getMessage());
	 	    }
	 	}

