	 	/**
	 	* Metodo para recuperar el primer registro Tipo 2 de Cambios Físicos de la base de datos, aplicando filtros de jerarquía dinámicos según el perfil detectado.
	 	* @author Alejandro Valdez
	 	* @param usuario Nombre del usuario para realizar la consulta de jerarquía y registros asociados.
	 	* @param imprimirDatos Booleano para generar un bloque de evidencia con el resumen de campos (ID, Fuente, Zona, Precio, etc.) en el reporte.
	 	* @return True si se localiza al menos un registro Tipo 2 compatible con el alcance jerárquico; False si no hay coincidencias o ocurre un error.
	 	* @date Diciembre 2025
	 	*/
	 	public boolean obtenerRegistroCF(String usuario, boolean imprimirDatos) {

	 	    String dbUrl = GlobalVariables.DB_URL_Cometa;
	 	    String dbUser = GlobalVariables.DB_USER_Cometa;
	 	    String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	 	    String perfilQuery =
	 	        "SELECT uk.short_name, uk.key_value " +
	 	        "FROM xxcm_user_keys uk " +
	 	        "JOIN xxcm_usuarios u ON uk.usuario_id = u.usuario_id " +
	 	        "WHERE u.usuario = '" + usuario + "' " +
	 	        "AND uk.short_name IN ('PCPERFIL','PCRFC','PCSUPPLIERID','PCPLAZA')";

	 	    try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	 	         Statement stmt = connection.createStatement();
	 	         ResultSet rsPerfil = stmt.executeQuery(perfilQuery)) {

	 	        String perfil = null;
	 	        String rfc = null;

	 	        while (rsPerfil.next()) {
	 	            String key = rsPerfil.getString("short_name");
	 	            String value = rsPerfil.getString("key_value");

	 	            if ("PCPERFIL".equals(key)) {
	 	                perfil = value;
	 	            } else {
	 	                rfc = value;
	 	            }
	 	        }

	 	        String filtroWhere = "";

	 	        if (perfil == null) {
	 	            // CEDIS
	 	            filtroWhere = "AND t.rfc = '" + rfc + "'";

	 	        } else if ("ADMIN".equalsIgnoreCase(perfil) || "OXXO_OS".equalsIgnoreCase(perfil)) {
	 	            // Sin filtro adicional
	 	            filtroWhere = "";

	 	        } else if ("OXXO_PLAZA".equalsIgnoreCase(perfil)) {
	 	            filtroWhere = "AND t.cr_desc_plaza = '" + rfc + "'";

	 	        } else {
	 	            filtroWhere = "AND t.rfc = '" + rfc + "'";
	 	        }

	 	        String queryFinal =
	 	            "WITH cte_data AS ( " +
	 	            "SELECT t.id, t.rfc, t.fuente_de_abasto, t.zona, " +
	 	            "t.body ->> 'Plaza' AS region, t.plaza, t.tienda, " +
	 	            "t.body ->> 'DoneTotal' AS precio, " +
	 	            "CASE WHEN t.body->>'Fecha_Fin_estadia' IS NOT NULL AND t.body->>'Fecha_Fin_estadia' <> '' " +
	 	            "THEN TO_TIMESTAMP(t.body->>'Fecha_Fin_estadia', 'DD-MM-YYYY HH24:MI:SS') " +
	 	            "ELSE t.fecha_registro END AS fecha, " +
	 	            "t.body ->> 'Tipo' AS tipo_ticket " +
	 	            "FROM xxcm_historico_directos_cf_view t " +
	 	            "), cte_final AS ( " +
	 	            "SELECT * FROM cte_data t WHERE t.tipo_ticket = '2' " + filtroWhere +
	 	            ") " +
	 	            "SELECT * FROM cte_final ORDER BY fecha DESC LIMIT 1";

	 	        try (ResultSet rs = stmt.executeQuery(queryFinal)) {

	 	            if (!rs.next()) {
	 	                System.out.println("No se encontraron registros Tipo 2");
	 	                limpiarVariablesGlobales();
	 	                return false;
	 	            }

	 	            id = rs.getString("id");
	 	            fuente = rs.getString("fuente_de_abasto");
	 	            zona = rs.getString("zona");
	 	            region = rs.getString("region");
	 	            plaza = rs.getString("plaza");
	 	            tienda = rs.getString("tienda");
	 	            precio = rs.getString("precio");
	 	            fecha = rs.getString("fecha");
	 	            tipoTicket = rs.getString("tipo_ticket");

	 	            System.out.println("SUCCESS: Registro Tipo 2 obtenido");

	 	            if (imprimirDatos) {
	 	                testCase.addTextEvidenceCurrentStep(
	 	                    "ID: " + id + "\n" +
	 	                    "Fuente: " + fuente + "\n" +
	 	                    "Zona: " + zona + "\n" +
	 	                    "Región: " + region + "\n" +
	 	                    "Plaza: " + plaza + "\n" +
	 	                    "Tienda: " + tienda + "\n" +
	 	                    "Precio: " + precio + "\n" +
	 	                    "Fecha: " + fecha + "\n" +
	 	                    "Tipo Ticket: " + tipoTicket
	 	                );
	 	            }

	 	            return true;
	 	        }

	 	    } catch (Exception e) {
	 	        System.out.println("[ERROR] Error al obtener registro Tipo 2: " + e.getMessage());
	 	        e.printStackTrace();
	 	        limpiarVariablesGlobales();
	 	        return false;
	 	    }
	 	}
		 	
		 /**
		  * Metodo para validar la busqueda con filtro de fecha en el calendario del modulo CF
		  * Considera solo registros menores a 1000 y muestra rango de fechas no mayor a 3 meses
		  * @param usuario Usuario con el que se realizara la validacion en BD
		  * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
		  * @return true si se pudo seleccionar correctamente el rango de fechas con los registros filtrados, false si no se obtuvo informacion
		  * @throws Exception si ocurre algun error durante la consulta o seleccion del rango de fechas
		  * @author Jose Pecina
		  * @date Septiembre 2025
		  */
	 	public boolean SelecFechaCFMenosMil(String usuario, boolean screenshot) throws Exception {
	 	    try {
	 	        boolean result;

	 	        String dbUrl = GlobalVariables.DB_URL_Cometa;
	 	        String dbUser = GlobalVariables.DB_USER_Cometa;
	 	        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	 	        String PCPERFIL =
	 	            "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' " +
	 	            "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

	 	        String PCRFC =
	 	            "select key_value from xxcm_user_keys where short_name in ('PCRFC', 'PCSUPPLIERID','PCPLAZA') " +
	 	            "and usuario_id in (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

	 	        String FechaBD = null;

	 	        // Validar que exista el filtro de fechas
	 	        if (u.isDisplayed(xmlRangoFechas)) {
	 	            u.highLight(xmlRangoFechas);

	 	            if (screenshot) {
	 	                testCase.addTextEvidenceCurrentStep("Se visualiza el filtro del rango de fechas");
	 	                testCase.addScreenShotCurrentStep(u, "FiltroFechas");
	 	            }

	 	            u.unhighLight(xmlRangoFechas);
	 	            result = true;
	 	        } else {
	 	            return false;
	 	        }

	 	        // Obtener fecha desde BD con conteo <=999, considerando perfil
	 	        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	 	             Statement stmt = connection.createStatement()) {

	 	            String perfil = null;

	 	            try (ResultSet rsPerfil = stmt.executeQuery(PCPERFIL)) {
	 	                if (rsPerfil.next()) {
	 	                    perfil = rsPerfil.getString("key_value");
	 	                    System.out.println("Usuario con perfil: " + perfil);
	 	                }
	 	            }

	 	            if (perfil != null) {

	 	                if (!"ADMIN".equalsIgnoreCase(perfil) && !"OXXO_OS".equalsIgnoreCase(perfil)) {

	 	                    String rfc = null;
	 	                    try (ResultSet rsRfc = stmt.executeQuery(PCRFC)) {
	 	                        if (rsRfc.next()) {
	 	                            rfc = rsRfc.getString("key_value");
	 	                        } else {
	 	                            System.out.println("No se obtuvo RFC.");
	 	                            return false;
	 	                        }
	 	                    }

	 	                    String sqlFechaMenor1000;

	 	                    if ("OXXO_PLAZA".equalsIgnoreCase(perfil)) {
	 	                        sqlFechaMenor1000 =
	 	                            "select fecha " +
	 	                            "from xxcm_cf " +
	 	                            "where cr_desc_plaza = '" + rfc + "' " +
	 	                            "group by fecha " +
	 	                            "having count(*) <= 999 " +
	 	                            "order by fecha desc " +
	 	                            "limit 1";
	 	                    } else {
	 	                        sqlFechaMenor1000 =
	 	                            "select fecha " +
	 	                            "from xxcm_cf " +
	 	                            "where proveedor_rfc = '" + rfc + "' " +
	 	                            "group by fecha " +
	 	                            "having count(*) <= 999 " +
	 	                            "order by fecha desc " +
	 	                            "limit 1";
	 	                    }

	 	                    try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMenor1000)) {
	 	                        if (rsFecha.next()) {
	 	                            FechaBD = rsFecha.getString("fecha");
	 	                            System.out.println("Fecha seleccionada (<=999): " + FechaBD);
	 	                        } else {
	 	                            System.out.println("No se obtuvo informacion (sin fecha <=999).");
	 	                            return false;
	 	                        }
	 	                    }

	 	                } else {
	 	                    // ADMIN / OXXO_OS => sin RFC
	 	                    String sqlFechaMenor1000Admin =
	 	                        "select fecha " +
	 	                        "from xxcm_cf " +
	 	                        "group by fecha " +
	 	                        "having count(*) <= 999 " +
	 	                        "order by fecha desc " +
	 	                        "limit 1";

	 	                    try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMenor1000Admin)) {
	 	                        if (rsFecha.next()) {
	 	                            FechaBD = rsFecha.getString("fecha");
	 	                            System.out.println("Fecha seleccionada (ADMIN/OXXO_OS <=999): " + FechaBD);
	 	                        } else {
	 	                            System.out.println("No se obtuvo informacion (ADMIN/OXXO_OS sin fecha <=999).");
	 	                            return false;
	 	                        }
	 	                    }
	 	                }

	 	            } else {
	 	                // Fallback: si no hay perfil, usar RFC
	 	                String rfc = null;
	 	                try (ResultSet rsRfc = stmt.executeQuery(PCRFC)) {
	 	                    if (rsRfc.next()) {
	 	                        rfc = rsRfc.getString("key_value");
	 	                    } else {
	 	                        System.out.println("No se obtuvo RFC (fallback).");
	 	                        return false;
	 	                    }
	 	                }

	 	                String sqlFechaMenor1000Fallback =
	 	                    "select fecha " +
	 	                    "from xxcm_cf " +
	 	                    "where proveedor_rfc = '" + rfc + "' " +
	 	                    "group by fecha " +
	 	                    "having count(*) <= 999 " +
	 	                    "order by fecha desc " +
	 	                    "limit 1";

	 	                try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMenor1000Fallback)) {
	 	                    if (rsFecha.next()) {
	 	                        FechaBD = rsFecha.getString("fecha");
	 	                        System.out.println("Fecha seleccionada (fallback <=999): " + FechaBD);
	 	                    } else {
	 	                        System.out.println("No se obtuvo informacion (fallback sin fecha <=999).");
	 	                        return false;
	 	                    }
	 	                }
	 	            }
	 	        }

	 	        if (FechaBD == null || FechaBD.trim().isEmpty()) {
	 	            testCase.addTextEvidenceCurrentStep("No se obtuvo FechaBD valida");
	 	            return false;
	 	        }

	 	        centroDescargasFiltradoFecha = FechaBD;

	 	        // Parsear fecha
	 	        LocalDate fechaConvert;
	 	        try {
	 	            fechaConvert = LocalDateTime
	 	                .parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))
	 	                .toLocalDate();
	 	        } catch (Exception ex) {
	 	            fechaConvert = LocalDate.parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
	 	        }

	 	        // Abrir datepicker y seleccionar rango
	 	        WebDriver driver = u.getDriver();
	 	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

	 	        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
	 	        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

	 	        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
	 	        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

	 	        By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
	 	        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

	 	        if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
	 	            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
	 	        }

	 	        clickYear(driver, wait, fechaConvert.getYear());
	 	        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

	 	        clickDay(driver, wait, fechaConvert.minusDays(1).getDayOfMonth());
	 	        clickDay(driver, wait, fechaConvert.getDayOfMonth());

	 	        wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));

	 	        if (screenshot) {
	 	            testCase.addTextEvidenceCurrentStep(
	 	                "Se selecciono rango de fechas: " + fechaConvert.minusDays(1) + " a " + fechaConvert + " (BD <=999 )"
	 	            );
	 	            testCase.addScreenShotCurrentStep(u, "RangoFechasSeleccionado");
	 	        }

	 	        return result;

	 	    } catch (Exception e) {
	 	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	 	        throw new Exception("Error " + e.getMessage());
	 	    }
	 	}
	 	
			/**
			* Metodo para obtener la Región desde la función get_cambios_fisicos_directos_pendientes_paginated según el perfil del usuario (ADMIN, OXXO_OS o por RFC).
			* @author Alejandro Valdez
			* @param screenshot Booleano para imprimir logs detallados del perfil y región detectados.
			* @param usuario Identificador del usuario logueado para consultar sus llaves de acceso en la BD.
			* @return True si se localiza una región válida y se asigna a la variable global; False en caso contrario.
			* @date Enero 2026
			*/
			public boolean obtenerRegionCambiosFisicosPendientes(boolean screenshot, String usuario) throws Exception {

			    try {
			        boolean result = true;
			        region = null;

			        String dbUrl = GlobalVariables.DB_URL_Cometa;
			        String dbUser = GlobalVariables.DB_USER_Cometa;
			        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

			        String PCPERFIL =
			            "select key_value " +
			            "from xxcm_user_keys " +
			            "where short_name = 'PCPERFIL' " +
			            "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

			        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
			             Statement stmt = connection.createStatement();
			             ResultSet rsPerfil = stmt.executeQuery(PCPERFIL)) {

			            if (rsPerfil.next()) {

			                String perfil = rsPerfil.getString("key_value");
			                System.out.println("Perfil del usuario: " + perfil);

			                if (screenshot) {
			                    System.out.println("Perfil detectado: " + perfil);
			                }

			                // =========================
			                // ADMIN / OXXO_OS
			                // =========================
			                if ("ADMIN".equalsIgnoreCase(perfil) ||
			                    "OXXO_OS".equalsIgnoreCase(perfil)) {

			                    String queryAdmin =
			                        "SELECT DISTINCT region " +
			                        "FROM public.get_cambios_fisicos_directos_pendientes_paginated(" +
			                        "  1, 200, " +
			                        "  null, null, null, null, null, null, null, null, null, null, null, null" +
			                        ") " +
			                        "WHERE remision_number IS NOT NULL " +
			                        "  AND TRIM(remision_number) <> '' " +
			                        "ORDER BY region " +
			                        "LIMIT 1";

			                    try (ResultSet rsAdmin = stmt.executeQuery(queryAdmin)) {
			                        if (rsAdmin.next()) {
			                            region = rsAdmin.getString("region");
			                            System.out.println("Región (ADMIN): " + region);
			                        } else {
			                            result = false;
			                            System.out.println("No se obtuvo región válida para ADMIN");
			                        }
			                    }

			                } else {
			                    // =========================
			                    // OTROS USUARIOS (RFC dinámico)
			                    // =========================
			                    String queryUsuario =
			                        "SELECT DISTINCT region " +
			                        "FROM public.get_cambios_fisicos_directos_pendientes_paginated(" +
			                        "  1, 20, " +
			                        "  ARRAY( " +
			                        "    SELECT k.key_value " +
			                        "    FROM xxcm_user_keys k " +
			                        "    JOIN xxcm_usuarios u ON k.usuario_id = u.usuario_id " +
			                        "    WHERE u.usuario = '" + usuario + "' " +
			                        "      AND k.short_name = 'PCRFC' " +
			                        "  ), " +
			                        "  null, null, null, null, null, null, null, null, null, null, null" +
			                        ") " +
			                        "WHERE remision_number IS NOT NULL " +
			                        "  AND TRIM(remision_number) <> '' " +
			                        "ORDER BY region " +
			                        "LIMIT 1";

			                    try (ResultSet rsUser = stmt.executeQuery(queryUsuario)) {
			                        if (rsUser.next()) {
			                            region = rsUser.getString("region");
			                            System.out.println("Región (Usuario): " + region);
			                        } else {
			                            result = false;
			                            System.out.println("No se obtuvo región válida para el usuario: " + usuario);
			                        }
			                    }
			                }

			            } else {
			                result = false;
			                System.out.println("No se obtuvo perfil del usuario: " + usuario);
			            }

			        } catch (Exception e) {
			            System.err.println("Error en consulta BD: " + e.getMessage());
			            e.printStackTrace();
			            result = false;
			        }

			        // =========================
			        // Validación final
			        // =========================
			        if (region == null || region.trim().isEmpty()) {
			            result = false;
			            System.out.println("Región es null o vacía");
			            if (screenshot) {
			                System.out.println("Error: Región es null o vacía");
			            }
			        } else if (screenshot) {
			            System.out.println("Región obtenida exitosamente: " + region);
			        }

			        return result;

			    } catch (Exception e) {
			        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
			        throw new Exception("Error " + e.getMessage());
			    }
			}

