			/**
			* Metodo para eliminar físicamente del almacenamiento local el último archivo descargado en la carpeta predeterminada de descargas (Downloads).
			* @author Alejandro Valdez
			* @return True si se identifica el archivo más reciente y se elimina exitosamente; False si la carpeta no existe, está vacía o el archivo está bloqueado.
			* @date Enero 2026
			*/
			public boolean eliminarUltimoArchivoDescargado() {
			    try {
			        String downloadsPath = System.getProperty("user.home") + "\\Downloads";
			        File carpetaDescargas = new File(downloadsPath);

			        if (!carpetaDescargas.exists() || !carpetaDescargas.isDirectory()) {
			            System.out.println("La carpeta Downloads no existe o no es válida");
			            return false;
			        }

			        File[] archivos = carpetaDescargas.listFiles(File::isFile);

			        if (archivos == null || archivos.length == 0) {
			            System.out.println("No hay archivos en la carpeta Downloads");
			            return false;
			        }

			        File ultimoArchivo = Arrays.stream(archivos)
			                .max(Comparator.comparingLong(File::lastModified))
			                .orElse(null);

			        if (ultimoArchivo == null) {
			            System.out.println("No se pudo determinar el último archivo descargado");
			            return false;
			        }

			        System.out.println("Eliminando archivo: " + ultimoArchivo.getName());

			        boolean eliminado = ultimoArchivo.delete();

			        if (!eliminado) {
			            System.out.println("No se pudo eliminar el archivo (posiblemente esté en uso)");
			            return false;
			        }

			        System.out.println("Archivo eliminado correctamente");
			        return true;

			    } catch (Exception e) {
			        System.err.println("Error eliminando el último archivo descargado: " + e.getMessage());
			        return false;
			    }
			}

			/**
			* Metodo para extraer texto de un archivo PDF descargado y validar que los campos de CR Tienda, Nombre de Tienda y Transferencia coincidan con los datos de entrada.
			* @author Alejandro Valdez
			* @return True si se localiza el PDF y tras la extracción se confirma la integridad de los datos normalizados; False si hay discrepancias o errores de lectura.
			* @date Enero 2026
			*/
			public boolean validarCamposEnPDF() throws Exception {

			    File file = null;

			    try {
			        System.out.println("Iniciando validación de campos en PDF...");

			        String home = System.getProperty("user.home") + "\\Downloads";
			        file = new File(getLastModified(home).getAbsolutePath());

			        System.out.println("Archivo PDF encontrado: " + file.getName());

			        if (!file.exists()) {
			            System.out.println("ERROR: No se encontró el archivo PDF.");
			            return false;
			        }

			        // ================= ABRIR PDF PARA EVIDENCIA =================
			        try {
			            System.out.println("Abriendo PDF...");
			            Desktop.getDesktop().open(file);
			            u.hardWait(4);
			            testCase.addScreenShotCurrentStep("Evidencia - PDF abierto");
			            u.hardWait(2);
			        } catch (Exception e) {
			            System.err.println("No se pudo abrir el PDF: " + e.getMessage());
			        }

			        try (PDDocument document = Loader.loadPDF(file)) {

			            PDFTextStripper stripper = new PDFTextStripper();
			            String textoCompleto = stripper.getText(document);
			            String[] lineas = textoCompleto.split("\\r?\\n");

			            String crTiendaPDF = null;
			            String nombreTiendaPDF = null;
			            String transferenciaPDF = null;

			            for (String linea : lineas) {
			                String lineaLower = linea.toLowerCase().trim();

			                if (lineaLower.startsWith("cr tienda:") && crTiendaPDF == null) {
			                    crTiendaPDF = linea.substring(linea.indexOf(":") + 1).trim();
			                } else if (lineaLower.startsWith("nombre tienda:") && nombreTiendaPDF == null) {
			                    nombreTiendaPDF = linea.substring(linea.indexOf(":") + 1).trim();
			                } else if (lineaLower.startsWith("transferencia:") && transferenciaPDF == null) {
			                    transferenciaPDF = linea.substring(linea.indexOf(":") + 1).trim();
			                }
			            }

			            if (crTiendaPDF == null || nombreTiendaPDF == null || transferenciaPDF == null) {
			                testCase.addTextEvidenceCurrentStep(
			                    "ERROR: No se encontraron todos los campos en el PDF. " +
			                    "CR Tienda=" + crTiendaPDF +
			                    ", Nombre Tienda=" + nombreTiendaPDF +
			                    ", Transferencia=" + transferenciaPDF
			                );
			                return false;
			            }

			            System.out.println("Campos encontrados en el PDF:");
			            System.out.println("CR Tienda PDF: " + crTiendaPDF);
			            System.out.println("Nombre Tienda PDF: " + nombreTiendaPDF);
			            System.out.println("Transferencia PDF: " + transferenciaPDF);

			            // ================= NORMALIZACIÓN =================
			            String tiendaGlobalNorm = tienda.toLowerCase().replaceAll("\\s+", " ");
			            String crtiendaGlobalNorm = crTiendaFV.replaceAll("\\s+", " ");
			            
			            String crPDFNorm = crTiendaPDF.replaceAll("\\s+", " ");
			            String nombrePDFNorm = nombreTiendaPDF.toLowerCase().replaceAll("\\s+", " ");
			            String transferenciaPDFNorm = transferenciaPDF.replaceAll("\\s+", "");
			            
			            System.out.println(crtiendaGlobalNorm);
			            System.out.println(crPDFNorm);


			            boolean valido = true;
			            StringBuilder errores = new StringBuilder();

			            if (!crtiendaGlobalNorm.contains(crPDFNorm)) {
			                errores.append("CR Tienda no coincide. ");
			                valido = false;
			            }

			            if (!tiendaGlobalNorm.contains(nombrePDFNorm)) {
			                errores.append("Nombre Tienda no coincide. ");
			                valido = false;
			            }

			            if (!transferenciaPDFNorm.equals(transferencia)) {
			                errores.append("Transferencia no coincide. ");
			                valido = false;
			            }

			            if (valido) {
			                testCase.addBoldTextEvidenceCurrentStep(
			                    "ÉXITO: Los datos del PDF coinciden correctamente."
			                );
			                return true;
			            } else {
			                testCase.addTextEvidenceCurrentStep(
			                    "ERROR: Validación fallida. Detalle: " + errores
			                );
			                return false;
			            }
			        }

			    } catch (Exception e) {
			        testCase.addTextEvidenceCurrentStep(
			            "ERROR inesperado durante validación del PDF: " + e.getMessage()
			        );
			        e.printStackTrace();
			        return false;

			    } 
			}
		
			/**
			 * Metodo para validar la busqueda con filtro de fecha en calendario del modulo CF
			 * Considera registros mayores o iguales a 1000
			 * @param usuario Usuario con el que se realizara la validacion en BD
			 * @param screenshot true si se desea guardar screenshot en el reporte, false en caso contrario
			 * @return true si se pudo seleccionar correctamente el rango de fechas con los registros filtrados, false si no se obtuvo informacion
			 * @throws Exception si ocurre algun error durante la consulta o seleccion del rango de fechas
			 * @author Jose Pecina
			 * @date Septiembre 2025
			 */
			public boolean SelecFechaCFMasMil(String usuario, boolean screenshot) throws Exception {
			    try {
			        boolean result;

			        String dbUrl = GlobalVariables.DB_URL_Cometa;
			        String dbUser = GlobalVariables.DB_USER_Cometa;
			        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

			        String PCPERFIL =
			            "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' " +
			            "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "');";

			        String PCRFC =
			            "select key_value from xxcm_user_keys where short_name in ('PCRFC', 'PCSUPPLIERID','PCPLAZA') " +
			            "and usuario_id in (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

			        String FechaBD = null;

			        // Validar que exista el filtro de fechas
			        if (u.isDisplayed(xmlRangoFechas)) {
			            u.highLight(xmlRangoFechas);

			            if (screenshot) {
			                testCase.addTextEvidenceCurrentStep("Se visualiza el filtro del rango de fechas");
			                testCase.addScreenShotCurrentStep(u, "FiltroFechas");
			            }

			            u.unhighLight(xmlRangoFechas);
			            result = true;
			        } else {
			            return false;
			        }

			        // Obtener fecha desde BD
			        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
			             Statement stmt = connection.createStatement()) {

			            String perfil = null;

			            try (ResultSet rsPerfil = stmt.executeQuery(PCPERFIL)) {
			                if (rsPerfil.next()) {
			                    perfil = rsPerfil.getString("key_value");
			                    System.out.println("Usuario con perfil: " + perfil);
			                }
			            }

			            if (perfil != null) {

			                if (!"ADMIN".equalsIgnoreCase(perfil) && !"OXXO_OS".equalsIgnoreCase(perfil)) {

			                    String rfc = null;
			                    try (ResultSet rsRfc = stmt.executeQuery(PCRFC)) {
			                        if (rsRfc.next()) {
			                            rfc = rsRfc.getString("key_value");
			                        } else {
			                            System.out.println("No se obtuvo RFC.");
			                            return false;
			                        }
			                    }

			                    String sqlFechaMayor1000;

			                    if ("OXXO_PLAZA".equalsIgnoreCase(perfil)) {
			                        sqlFechaMayor1000 =
			                            "select fecha " +
			                            "from xxcm_cf " +
			                            "where cr_desc_plaza = '" + rfc + "' " +
			                            "group by fecha " +
			                            "having count(*) >= 999 " +
			                            "order by fecha desc " +
			                            "limit 1";
			                    } else {
			                        sqlFechaMayor1000 =
			                            "select fecha " +
			                            "from xxcm_cf " +
			                            "where proveedor_rfc = '" + rfc + "' " +
			                            "group by fecha " +
			                            "having count(*) >= 999 " +
			                            "order by fecha desc " +
			                            "limit 1";
			                    }

			                    try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMayor1000)) {
			                        if (rsFecha.next()) {
			                            FechaBD = rsFecha.getString("fecha");
			                            System.out.println("Fecha seleccionada (>=999): " + FechaBD);
			                        } else {
			                            System.out.println("No se obtuvo informacion (sin fecha >=999).");
			                            return false;
			                        }
			                    }

			                } else {
			                    // ADMIN / OXXO_OS => sin RFC
			                    String sqlFechaMayor1000Admin =
			                        "select fecha " +
			                        "from xxcm_cf " +
			                        "group by fecha " +
			                        "having count(*) >= 999 " +
			                        "order by fecha desc " +
			                        "limit 1";

			                    try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMayor1000Admin)) {
			                        if (rsFecha.next()) {
			                            FechaBD = rsFecha.getString("fecha");
			                            System.out.println("Fecha seleccionada (ADMIN/OXXO_OS >=999): " + FechaBD);
			                        } else {
			                            System.out.println("No se obtuvo informacion (ADMIN/OXXO_OS sin fecha >=999).");
			                            return false;
			                        }
			                    }
			                }

			            } else {
			                // Fallback: si no hay perfil, usar RFC
			                String rfc = null;
			                try (ResultSet rsRfc = stmt.executeQuery(PCRFC)) {
			                    if (rsRfc.next()) {
			                        rfc = rsRfc.getString("key_value");
			                    } else {
			                        System.out.println("No se obtuvo RFC (fallback).");
			                        return false;
			                    }
			                }

			                String sqlFechaMayor1000Fallback =
			                    "select fecha " +
			                    "from xxcm_cf " +
			                    "where proveedor_rfc = '" + rfc + "' " +
			                    "group by fecha " +
			                    "having count(*) >= 999 " +
			                    "order by fecha desc " +
			                    "limit 1";

			                try (ResultSet rsFecha = stmt.executeQuery(sqlFechaMayor1000Fallback)) {
			                    if (rsFecha.next()) {
			                        FechaBD = rsFecha.getString("fecha");
			                        System.out.println("Fecha seleccionada (fallback >=999): " + FechaBD);
			                    } else {
			                        System.out.println("No se obtuvo informacion (fallback sin fecha >=999).");
			                        return false;
			                    }
			                }
			            }
			        }

			        if (FechaBD == null || FechaBD.trim().isEmpty()) {
			            testCase.addTextEvidenceCurrentStep("No se obtuvo FechaBD valida");
			            return false;
			        }

			        centroDescargasFiltradoFecha = FechaBD;

			        // Parsear fecha
			        LocalDate fechaConvert;
			        try {
			            fechaConvert = LocalDateTime
			                .parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))
			                .toLocalDate();
			        } catch (Exception ex) {
			            fechaConvert = LocalDate.parse(FechaBD, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
			        }

			        // Abrir datepicker y seleccionar rango
			        WebDriver driver = u.getDriver();
			        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(12));

			        By btnToggle = By.xpath("//mat-datepicker-toggle/button");
			        wait.until(ExpectedConditions.elementToBeClickable(btnToggle)).click();

			        By dpContent = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-datepicker-content");
			        wait.until(ExpectedConditions.visibilityOfElementLocated(dpContent));

			        By btnPeriodo = By.xpath("//div[contains(@class,'cdk-overlay-pane')]//button[contains(@class,'mat-calendar-period-button')]");
			        wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();

			        if (driver.findElements(By.xpath("//div[contains(@class,'cdk-overlay-pane')]//mat-multi-year-view")).isEmpty()) {
			            wait.until(ExpectedConditions.elementToBeClickable(btnPeriodo)).click();
			        }

			        clickYear(driver, wait, fechaConvert.getYear());
			        clickMonthByIndex(driver, wait, fechaConvert.getMonthValue());

			        clickDay(driver, wait, fechaConvert.minusDays(1).getDayOfMonth());
			        clickDay(driver, wait, fechaConvert.getDayOfMonth());

			        wait.until(ExpectedConditions.invisibilityOfElementLocated(dpContent));

			        if (screenshot) {
			            testCase.addTextEvidenceCurrentStep(
			                "Se selecciono rango de fechas: " + fechaConvert.minusDays(1) + " a " + fechaConvert + " (BD >=999)"
			            );
			            testCase.addScreenShotCurrentStep(u, "RangoFechasSeleccionado");
			        }

			        return result;

			    } catch (Exception e) {
			        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
			        throw new Exception("Error " + e.getMessage());
			    }
			}
		
