	 	/**
	 	* Metodo auxiliar para desplazar la vista hasta un elemento y asegurar que esté presente en el DOM antes de interactuar.
	 	* @author Maximino Ramirez
	 	* @param locator Localizador del elemento hacia el cual se realizará el desplazamiento.
	 	* @return El objeto WebElement localizado y centrado en pantalla; null si ocurre un error o el elemento no aparece.
	 	* @date Enero 2026
	 	*/
	 	public WebElement prepararElemento(By locator) {
	 	    try {
	 	        WebDriverWait wait = new WebDriverWait(u.getDriver(), Duration.ofSeconds(10));
	 	        WebElement elemento = wait.until(ExpectedConditions.presenceOfElementLocated(locator));
	 	        JavascriptExecutor js = (JavascriptExecutor) u.getDriver();
	 	        js.executeScript("arguments[0].scrollIntoView({block: 'center', behavior: 'smooth'});", elemento);
	 	        Thread.sleep(500); 
	 	        return elemento;
	 	    } catch (Exception e) {
	 	        System.err.println("Error al localizar o desplazar hacia el elemento: " + locator.toString());
	 	        return null;
	 	    }
	 	}

	 	/**
	 	* Metodo para realizar una búsqueda con un SKU aleatorio inexistente y confirmar que se muestra el mensaje de "No se encontró información".
	 	* @author Maximino Ramirez
	 	* @param tomarEvidencia Booleano para capturar evidencia visual del mensaje de falta de coincidencia.
	 	* @return True si el mensaje mostrado coincide con el esperado tras la búsqueda fallida; False si el mensaje no aparece.
	 	* @date Enero 2026
	 	*/
	 	public boolean buscarSkuSinCoincidencias(boolean tomarEvidencia) {
	 	    By lbLoader = By.xpath("//div[contains(text(), 'Espere un momento')]");
	 	    int numeroAleatorio = (int)(Math.random() * 9000000) + 1000000;
	 	    String skuAleatorio = String.valueOf(numeroAleatorio);
	 	    
	 	    WebElement campo = prepararElemento(lbBuscarSkuOdescripcion);
	 	    if (campo == null) {
	 	        return false;
	 	    }

	 	    campo.clear();
	 	    campo.sendKeys(skuAleatorio);
	 	    campo.sendKeys(Keys.ENTER);

	 	    try {
	 	        WebDriverWait wait = new WebDriverWait(u.getDriver(), Duration.ofSeconds(15));
	 	        try {
	 	            wait.until(ExpectedConditions.invisibilityOfElementLocated(lbLoader));
	 	        } catch (Exception e) {}

	 	        WebElement mensajeElemento = wait.until(ExpectedConditions.visibilityOfElementLocated(lbNoSeEncontroInfo));
	 	        String textoReal = mensajeElemento.getAttribute("innerText").trim();
	 	        String mensajeEsperado = "No se encontró información con los filtros proporcionados.";

	 	        if (textoReal.equals(mensajeEsperado)) {
	 	            if (tomarEvidencia) {
	 	                u.hardWait(1); 
	 	                testCase.addScreenShotCurrentStep("MensajeSinCoincidencias_SKU_" + skuAleatorio);
	 	            }
	 	            return true;
	 	        } else {
	 	            return false;
	 	        }
	 	    } catch (Exception e) {
	 	        if (tomarEvidencia) {
	 	            testCase.addScreenShotCurrentStep("Error_MensajeNoEncontrado");
	 	        }
	 	        return false;
	 	    }
	 	}

	 	/**
	 	* Metodo para buscar un SKU válido obtenido de la base de datos (con fallback al grid) y confirmar la interacción con el campo de búsqueda.
	 	* @author Maximino Ramirez
	 	* @param usuarioSesion Identificador del usuario actual para la consulta en BD.
	 	* @param tomarEvidencia Booleano para registrar el ingreso del SKU en el portal.
	 	* @return True siempre que se intente realizar la búsqueda; asigna el SKU y remisión a variables globales si se localizan datos.
	 	* @date Enero 2026
	 	*/
	 	public boolean buscarSkuConCoincidencias(String usuarioSesion, boolean tomarEvidencia) {
	 	    String skuABuscar = null;
	 	    String remisionAux = null;
	 	    String bd = GlobalVariables.DB_URL_Cometa;
	 	    String userBD = GlobalVariables.DB_USER_Cometa;
	 	    String passwordBD = GlobalVariables.DB_PASSWORD_Cometa;

	 	    String queryUsuario = "SELECT sku, remision_number as remision FROM public.get_cambios_fisicos_directos_pendientes_paginated(1, 20, ARRAY(SELECT k.key_value FROM xxcm_user_keys k JOIN xxcm_usuarios u ON k.usuario_id = u.usuario_id WHERE u.usuario = '" + usuarioSesion + "'), null, null, null, null, null, null, null, null, null, null, null) ORDER BY random() LIMIT 1;";
	 	    String queryGeneral = "SELECT sku, remision_number as remision FROM public.get_cambios_fisicos_directos_pendientes_paginated(1, 200, null, null, null, null, null, null, null, null, null, null, null, null) ORDER BY random() LIMIT 1;";

	 	    try (Connection conn = DriverManager.getConnection(bd, userBD, passwordBD);
	 	         Statement stmt = conn.createStatement()) {

	 	        try (ResultSet rs = stmt.executeQuery(queryUsuario)) {
	 	            if (rs.next()) {
	 	                skuABuscar = rs.getString("sku");
	 	                remisionAux = rs.getString("remision");
	 	            }
	 	        }

	 	        if (skuABuscar == null) {
	 	            try (ResultSet rsGen = stmt.executeQuery(queryGeneral)) {
	 	                if (rsGen.next()) {
	 	                    skuABuscar = rsGen.getString("sku");
	 	                    remisionAux = rsGen.getString("remision");
	 	                }
	 	            }
	 	        }
	 	    } catch (Exception e) {}

	 	    if (skuABuscar == null) {
	 	        skuABuscar = obtenerTextoDeGrid("(//table//tr[1]//td[contains(@class, 'sku')])[1]");
	 	        remisionAux = obtenerTextoDeGrid("(//table//tr[1]//td[contains(@class, 'remision')])[1]");
	 	    }

	 	    if ((skuABuscar == null || skuABuscar.isEmpty()) && !ultimoSkuExitoso.isEmpty()) {
	 	        skuABuscar = ultimoSkuExitoso;
	 	        remisionAux = ultimaRemisionExitosa;
	 	    }

	 	    if (skuABuscar != null && !skuABuscar.isEmpty()) {
	 	        ultimoSkuExitoso = skuABuscar;
	 	        ultimaRemisionExitosa = remisionAux;

	 	        PortalCometaMVP4.SKU = skuABuscar;
	 	        PortalCometaMVP4.id = remisionAux;

	 	        WebElement campo = prepararElemento(lbBuscarSkuOdescripcion);
	 	        if (campo != null) {
	 	            campo.clear();
	 	            campo.sendKeys(skuABuscar);
	 	            u.hardWait(1);
	 	            campo.sendKeys(Keys.ENTER);
	 	            u.hardWait(2);
	 	            
	 	            if (tomarEvidencia) {
	 	                testCase.addScreenShotCurrentStep("Busqueda_SKU_Realizada_" + skuABuscar);
	 	            }
	 	        }
	 	    } else {
	 	        if (tomarEvidencia) {
	 	            testCase.addScreenShotCurrentStep("Sin_Datos_Disponibles_Para_Busqueda");
	 	        }
	 	    }
	 	    return true; 
	 	}

