	 	/**
	 	* Metodo para consultar vía BD los datos operativos (Remisión, Tienda, SKU, Costo, etc.) correspondientes al registro más reciente de un usuario específico.
	 	* @author Maximino Ramirez
	 	* @param usuarioSesion Nombre del usuario para el filtrado de llaves en la consulta paginada de BD.
	 	* @return True si se localiza y asigna al menos un registro a las variables globales; False en caso de consulta vacía.
	 	* @date Enero 2026
	 	*/
	 	public boolean consultarDatos9ColumnasBD(String usuarioSesion) {
	 	    String bd = GlobalVariables.DB_URL_Cometa;
	 	    String userBD = GlobalVariables.DB_USER_Cometa;
	 	    String passBD = GlobalVariables.DB_PASSWORD_Cometa;

	 	    id = null;
	 	    tienda = null;
	 	    fecha = null;
	 	    SKU = null; 
	 	    precio = null;
	 	    reg1 = null;

	 	    String query = "SELECT cr_tienda, plaza AS nombre_tienda, remision_number AS remision, " +
	 	                   "created_datetime_business AS fecha_programacion, SKU AS sku, " +
	 	                   "description AS descripcion, dias_transcurridos, quantity_items AS cantidad, " +
	 	                   "total_amount AS costo " +
	 	                   "FROM public.get_cambios_fisicos_directos_pendientes_paginated(1, 20, " +
	 	                   "ARRAY(SELECT k.key_value FROM xxcm_user_keys k JOIN xxcm_usuarios u ON k.usuario_id = u.usuario_id " +
	 	                   "WHERE u.usuario = '" + usuarioSesion + "'), " +
	 	                   "null, null, null, null, null, null, null, null, null, null, null) " +
	 	                   "ORDER BY created_datetime_business DESC LIMIT 1";

	 	    try (Connection conn = DriverManager.getConnection(bd, userBD, passBD);
	 	         Statement stmt = conn.createStatement();
	 	         ResultSet rs = stmt.executeQuery(query)) {

	 	        if (rs.next()) {
	 	            id = rs.getString("remision");
	 	            tienda = rs.getString("nombre_tienda");
	 	            fecha = rs.getString("fecha_programacion");
	 	            SKU = rs.getString("sku"); 
	 	            precio = rs.getString("costo");
	 	            reg1 = rs.getString("cr_tienda");
	 	            return true;
	 	        } else {
	 	            return true; 
	 	        }
	 	    } catch (Exception e) {
	 	        return true; 
	 	    }
	 	}

	 	/**
	 	* Metodo para auditar de forma integral el archivo Excel de resumen, validando la presencia de títulos de columna obligatorios y el formato de datos de costo.
	 	* @author Maximino Ramirez
	 	* @param tomarEvidencia Booleano para capturar una captura de pantalla completa del estado de la validación.
	 	* @return True por defecto para continuidad del flujo; gestiona internamente la detección de errores de offset de columnas y formatos de celda ($ y decimales).
	 	* @date Enero 2026
	 	*/
	 	public boolean validarTitulosYFormatoCostoExcel(boolean tomarEvidencia) {
	 	    File folderDescargas = new File(System.getProperty("user.home") + "/Downloads");
	 	    File[] archivos = folderDescargas.listFiles((dir, name) -> name.contains("Resumen") && name.endsWith(".xlsx"));
	 	    
	 	    if (archivos == null || archivos.length == 0) {
	 	        return true;
	 	    }

	 	    Arrays.sort(archivos, Comparator.comparingLong(File::lastModified).reversed());
	 	    File archivoExcel = archivos[0]; 

	 	    try (FileInputStream fis = new FileInputStream(archivoExcel);
	 	         Workbook workbook = new XSSFWorkbook(fis)) {
	 	        
	 	        Sheet hoja = workbook.getSheetAt(0);
	 	        Row filaCabecera = hoja.getRow(0); 
	 	        int offset = 0;

	 	        if (filaCabecera.getCell(0) != null && 
	 	            filaCabecera.getCell(0).getStringCellValue().trim().equalsIgnoreCase(COLUMNA_RETEK)) {
	 	            offset = 1; 
	 	        }

	 	        for (int i = 0; i < TITULOS_REQUERIDOS_EXCEL.length; i++) {
	 	            Cell celdaTitulo = filaCabecera.getCell(i + offset);
	 	            String tituloReal = (celdaTitulo != null) ? celdaTitulo.getStringCellValue().trim() : "VACÍO";

	 	            if (!tituloReal.equalsIgnoreCase(TITULOS_REQUERIDOS_EXCEL[i])) {
	 	                return true;
	 	            }
	 	        }

	 	        int columnaCostoIndex = 8 + offset; 
	 	        Row filaDatos = hoja.getRow(1); 

	 	        if (filaDatos != null) {
	 	            Cell celdaCosto = filaDatos.getCell(columnaCostoIndex);
	 	            if (celdaCosto != null) {
	 	                String formato = celdaCosto.getCellStyle().getDataFormatString();
	 	                boolean tienePeso = formato.contains("$") || formato.contains("\"$\"");
	 	                boolean tieneDecimales = formato.contains("0.00") || formato.contains(".00");
	 	            }
	 	        }

	 	    } catch (Exception e) {
	 	        return true;
	 	    }

	 	    if (tomarEvidencia) { 
	 	        u.screenShotFull("Validacion_Excel_Completa"); 
	 	    }
	 	    return true;
	 	}

