	 	/**
	 	* Metodo para realizar una búsqueda por rango de fechas navegando manualmente en el calendario del portal.
	 	* @author Alejandro Valdez
	 	* @param meses Cantidad de meses a retroceder en el calendario para fijar el inicio del rango.
	 	* @return True si se completa la navegación (atrás y adelante) y se seleccionan las fechas límite; captura evidencia visual.
	 	* @date Agosto 2025
	 	*/
	 	public boolean sltFechase(int meses){ 
	 	    try {
	 	        if(u.isDisplayed(rangoFechasCedisR)){
	 	            u.hardWait(1);
	 	            u.mouseOverAndClick(rangoFechasCedisR);

	 	            // mover meses atrás
	 	            for (int i = 0; i < meses; i++) {
	 	                u.mouseOverAndClick(btnFlechaIzq);
	 	            }

	 	            // FECHA INICIO (primer día habilitado)
	 	            u.mouseOverAndClick(fechaInicioMes);

	 	            // mover meses adelante
	 	            for (int i = 0; i < 4; i++) {
	 	                u.mouseOverAndClick(btnFlechaDer);
	 	            }

	 	            // FECHA FIN (NO el mismo locator)
	 	            By fechaFinMes = By.xpath(
	 	                "(//button[contains(@class,'mat-calendar-body-cell') " +
	 	                "and not(contains(@class,'mat-calendar-body-disabled'))])[last()]"
	 	            );
	 	            u.mouseOverAndClick(fechaFinMes);

	 	            testCase.addScreenShotCurrentStep("");
	 	            return true;
	 	        }
	 	        return false;
	 	    } catch (Exception e) {
	 	        System.out.println("[ERROR] Ocurrió un error durante la ejecución: " + e.getMessage());
	 	        return false;
	 	    }
	 	}

