	 	/**
	 	* Metodo auxiliar para seleccionar un rango de fechas de 2 meses navegando hacia atrás y seleccionando los días habilitados.
	 	* @author Alejandro Valdez
	 	* @return True si se completa la navegación (atrás y retorno al presente) seleccionando fechas extremas habilitadas; False si algún botón está bloqueado.
	 	* @date Agosto 2025
	 	*/
	 	 public boolean seleccionarRangoFechasConClicks() {
	 	    try {
	 	        // Hacer clic en el elemento de rango de fechas
	 	        u.click(xmlRangoFechas);
	 	        WebDriver driver = u.getDriver();

	 	        // Navegar 2 meses hacia atrás para encontrar el mes mínimo
	 	        for (int i = 0; i < 2; i++) {
	 	            WebElement botonIzquierda = driver.findElement(xmlBotonFlechaIzquier);
	 	            if (!botonIzquierda.isEnabled()) {
	 	                System.err.println("Error: No se puede navegar más hacia atrás");
	 	                testCase.addCodeEvidenceCurrentStep("Error: Botón de navegación izquierda deshabilitado");
	 	                return false;
	 	            }
	 	            botonIzquierda.click();
	 	        }

	 	        // Seleccionar el primer día habilitado del mes mínimo
	 	        By primerDiaHabilitado = By.xpath("(//button[starts-with(@class, 'mat-calendar-body-cell') and not(@aria-disabled)])[1]");
	 	        WebElement diaMin = driver.findElement(primerDiaHabilitado);
	 	        
	 	        if (!diaMin.isDisplayed() || !diaMin.isEnabled()) {
	 	            System.err.println("Error: El primer día habilitado no está disponible");
	 	            testCase.addCodeEvidenceCurrentStep("Error: Primer día habilitado no disponible");
	 	            return false;
	 	        }
	 	        
	 	        diaMin.click();
	 	        String fechaMinima = diaMin.getAttribute("aria-label");
	 	        System.out.println("Seleccionada fecha mínima: " + fechaMinima);

	 	        // Navegar 2 meses hacia adelante para llegar al mes actual
	 	        for (int i = 0; i < 2; i++) {
	 	            WebElement botonDerecha = driver.findElement(xmlBotonFlechaDerecha);
	 	            if (!botonDerecha.isEnabled()) {
	 	                System.err.println("Error: No se puede navegar más hacia adelante");
	 	                testCase.addCodeEvidenceCurrentStep("Error: Botón de navegación derecha deshabilitado");
	 	                return false;
	 	            }
	 	            botonDerecha.click();
	 	        }

	 	        // Seleccionar el último día habilitado del mes actual
	 	        WebElement diaMax = driver.findElement(xmlUltimoDiaHabilitad);
	 	        
	 	        if (!diaMax.isDisplayed() || !diaMax.isEnabled()) {
	 	            System.err.println("Error: El último día habilitado no está disponible");
	 	            testCase.addCodeEvidenceCurrentStep("Error: Último día habilitado no disponible");
	 	            return false;
	 	        }
	 	        
	 	        String fechaMaxima = diaMax.getAttribute("aria-label");
	 	        System.out.println("Seleccionada fecha máxima: " + fechaMaxima);
	 	        diaMax.click();

	 	        // Si llegamos hasta aquí, la operación fue exitosa
	 	        System.out.println("Rango de fechas seleccionado correctamente");
	 	        return true;

	 	    } catch (Exception e) {
	 	        System.err.println("Error en seleccionarRangoFechasConClicks: " + e.getMessage());
	 	        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	 	        e.printStackTrace();
	 	        return false;
	 	    }
	 	}

	 	/**
	 	* Metodo para validar que el rango de fechas seleccionado en los inputs del portal no exceda los 3 meses (90 días).
	 	* @author Alejandro Valdez
	 	* @return True si la diferencia entre la fecha inicial y final es menor o igual a 3 meses; False si excede el límite o falla el parseo.
	 	* @date Septiembre 2025
	 	*/
	 	public boolean validarRangoFechas() {
	 	    try {
	 	        WebElement fechaInicio = u.getDriver().findElement(By.xpath("//div[@class='mat-date-range-input-wrapper']//input"));
	 	        String Finicio = fechaInicio.getAttribute("value");
	 	        System.out.println("Fecha inicio " + Finicio);

	 	        WebElement fechaFin = u.getDriver().findElement(By.xpath("//div[@class='mat-date-range-input-wrapper mat-date-range-input-end-wrapper']//input"));
	 	        String FFin = fechaFin.getAttribute("value");
	 	        System.out.println("Fecha fin " + FFin);

	 	        // Convertir las fechas a LocalDate para poder calcular la diferencia
	 	        LocalDate fechaInicioDate = parsearFechaRango(Finicio);
	 	        LocalDate fechaFinDate = parsearFechaRango(FFin);

	 	        if (fechaInicioDate == null || fechaFinDate == null) {
	 	            System.out.println("Error: No se pudieron parsear las fechas");
	 	            testCase.addScreenShotCurrentStep("Error al parsear fechas");
	 	            return false;
	 	        }

	 	        System.out.println("Fecha inicio parseada: " + fechaInicioDate);
	 	        System.out.println("Fecha fin parseada: " + fechaFinDate);

	 	        // Validar que la fecha inicio no sea posterior a la fecha fin
	 	        if (fechaInicioDate.isAfter(fechaFinDate)) {
	 	            System.out.println("Error: La fecha de inicio es posterior a la fecha fin");
	 	            testCase.addScreenShotCurrentStep("Fecha inicio posterior a fecha fin");
	 	            return false;
	 	        }

	 	        // Calcular la diferencia en meses
	 	        long mesesDiferencia = ChronoUnit.MONTHS.between(fechaInicioDate, fechaFinDate);
	 	        
	 	        // También calcular días para casos límite
	 	        long diasDiferencia = ChronoUnit.DAYS.between(fechaInicioDate, fechaFinDate);
	 	        
	 	        System.out.println("Diferencia en meses: " + mesesDiferencia);
	 	        System.out.println("Diferencia en días: " + diasDiferencia);

	 	        // Validar que no exceda 3 meses (consideramos ~90 días como límite)
	 	        if (mesesDiferencia <= 3 && diasDiferencia <= 90) {
	 	            System.out.println("Validación exitosa: El rango de fechas es válido (máximo 3 meses)");
	 	            testCase.addScreenShotCurrentStep("Rango de fechas válido");
	 	            return true;
	 	        } else {
	 	            System.out.println("Validación fallida: El rango excede los 3 meses permitidos");
	 	            System.out.println("Meses: " + mesesDiferencia + ", Días: " + diasDiferencia);
	 	            testCase.addScreenShotCurrentStep("Rango de fechas excede 3 meses");
	 	            return false;
	 	        }

	 	    } catch (Exception e) {
	 	        System.out.println("Error en validarRangoFechas: " + e.getMessage());
	 	        e.printStackTrace();
	 	        return false;
	 	    }
	 	}

	 	/**
	 	* Método auxiliar para parsear fechas de texto a objetos LocalDate intentando múltiples formatos comunes (dd/MM/yyyy, yyyy-MM-dd, etc.).
	 	* @author Alejandro Valdez
	 	* @param fecha Cadena de texto de la fecha a transformar.
	 	* @return Objeto LocalDate correspondiente; null si no coincide con ningún formato predefinido.
	 	* @date Septiembre 2025
	 	*/
	 	private LocalDate parsearFechaRango(String fecha) {
	 	    if (fecha == null || fecha.trim().isEmpty()) {
	 	        return null;
	 	    }
	 	    
	 	    fecha = fecha.trim();
	 	    System.out.println("Parseando fecha: '" + fecha + "'");
	 	    
	 	    // Lista de formatos posibles para las fechas
	 	    List<DateTimeFormatter> formatters = Arrays.asList(
	 	        DateTimeFormatter.ofPattern("dd/MM/yyyy"),     // 18/06/2025
	 	        DateTimeFormatter.ofPattern("d/M/yyyy"),       // 18/6/2025
	 	        DateTimeFormatter.ofPattern("MM/dd/yyyy"),     // 06/18/2025
	 	        DateTimeFormatter.ofPattern("M/d/yyyy"),       // 6/18/2025
	 	        DateTimeFormatter.ofPattern("yyyy-MM-dd"),     // 2025-06-18
	 	        DateTimeFormatter.ofPattern("dd-MM-yyyy"),     // 18-06-2025
	 	        DateTimeFormatter.ofPattern("d-M-yyyy"),       // 18-6-2025
	 	        DateTimeFormatter.ofPattern("yyyy/MM/dd"),     // 2025/06/18
	 	        DateTimeFormatter.ofPattern("dd.MM.yyyy"),     // 18.06.2025
	 	        DateTimeFormatter.ofPattern("d.M.yyyy")        // 18.6.2025
	 	    );
	 	    
	 	    for (DateTimeFormatter formatter : formatters) {
	 	        try {
	 	            LocalDate fechaParseada = LocalDate.parse(fecha, formatter);
	 	            System.out.println("Fecha parseada exitosamente con formato: " + formatter.toString());
	 	            return fechaParseada;
	 	        } catch (DateTimeParseException e) {
	 	            // Continuar con el siguiente formato
	 	        }
	 	    }
	 	    
	 	    System.out.println("No se pudo parsear la fecha: " + fecha);
	 	    return null;
	 	}

