	 	/**
	 	* Metodo para validar la integridad de la información del primer registro en el grid de Centro de Descargas (Fecha, Hora, Módulo, Nombre, Estatus y Acciones).
	 	* @author Alejandro Valdez
	 	* @param esMasMil Booleano que indica si se debe omitir la validación estricta del nombre del archivo (para casos con alto volumen de registros).
	 	* @return True si todos los campos validados (con normalización de formatos de tiempo y fechas) coinciden con los registros previos del sistema; False si hay discrepancias.
	 	* @date Enero 2026
	 	*/
	 	public boolean valRegCentroDeDescargas(boolean esMasMil) {
	 	    try {
	 	        if (u.isDisplayed(btnLimpiarFiltros)) {
	 	            u.hardWait(1);

	 	            boolean valid = true;

	 	            // ================= Fecha =================
	 	            System.out.println("=== Validando Fecha ===");
	 	            WebElement f = u.getDriver().findElement(
	 	                By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/table/tbody/tr[1]/td[1]/span")
	 	            );
	 	            String fechaRegistro = f.getText();
	 	            DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
	 	            LocalDate fechaRegistroLD = LocalDate.parse(fechaRegistro, formatter);

	 	            if (!fechaReg.equals(fechaRegistroLD)) {
	 	                System.out.println("ERROR: Las fechas NO coinciden");
	 	                valid = false;
	 	            } else {
	 	                System.out.println("SUCCESS: Las fechas coinciden");
	 	            }

	 	            // ================= Hora =================
	 	            System.out.println("=== Validando Hora ===");
	 	            WebElement h = u.getDriver().findElement(
	 	                By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/table/tbody/tr[1]/td[2]")
	 	            );
	 	            String horaRegistro = h.getText()
	 	                    .toLowerCase()
	 	                    .replace("a.m.", "AM")
	 	                    .replace("p.m.", "PM")
	 	                    .trim();

	 	            DateTimeFormatter horaFormatter = DateTimeFormatter.ofPattern("h:mm a", Locale.ENGLISH);
	 	            LocalTime horaRegistroMin = LocalTime
	 	                    .parse(horaRegistro, horaFormatter)
	 	                    .truncatedTo(ChronoUnit.MINUTES);

	 	            if (!horaReg.truncatedTo(ChronoUnit.MINUTES).equals(horaRegistroMin)) {
	 	                System.out.println("ERROR: Las horas NO coinciden");
	 	                valid = false;
	 	            } else {
	 	                System.out.println("SUCCESS: Las horas coinciden");
	 	            }

	 	            // ================= Modulo =================
	 	            System.out.println("=== Validando Módulo ===");
	 	            WebElement m = u.getDriver().findElement(
	 	                By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/table/tbody/tr[1]/td[3]")
	 	            );
	 	            String moduloOrigen = m.getText();

	 	            if (!moduloOrigen.toLowerCase().contains(modulo.toLowerCase())) {
	 	                System.out.println("ERROR: Los módulos NO coinciden");
	 	                valid = false;
	 	            } else {
	 	                System.out.println("SUCCESS: Los módulos coinciden");
	 	            }

	 	            // ================= Nombre del Documento =================
	 	            if (!esMasMil) {
	 	                System.out.println("=== Validando Nombre del Documento (menos de 1000) ===");

	 	                WebElement nd = u.getDriver().findElement(
	 	                    By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/table/tbody/tr[1]/td[4]")
	 	                );
	 	                String nomDocumento = nd.getText().trim();

	 	                File carpeta = Paths.get(System.getProperty("user.home"), "Downloads").toFile();

	 	                if (!carpeta.exists() || !carpeta.isDirectory()) {
	 	                    System.out.println("ERROR: La carpeta Descargas no existe");
	 	                    valid = false;
	 	                } else {

	 	                    File[] archivos = carpeta.listFiles(File::isFile);

	 	                    if (archivos == null || archivos.length == 0) {
	 	                        System.out.println("ERROR: No hay archivos en Descargas");
	 	                        valid = false;
	 	                    } else {

	 	                        File ultimoArchivo = Arrays.stream(archivos)
	 	                                .max(Comparator.comparingLong(File::lastModified))
	 	                                .orElse(null);

	 	                        nombreUltimoArchivoDescargas = normalizarNombreDescarga((ultimoArchivo != null)
	 	                                ? ultimoArchivo.getName()
	 	                                : "");

	 	                        System.out.println("Documento portal : " + nomDocumento);
	 	                        System.out.println("Documento descarga: " + nombreUltimoArchivoDescargas);

	 	                        if (!nomDocumento.equals(nombreUltimoArchivoDescargas)) {
	 	                            System.out.println("ERROR: El nombre del documento NO coincide");
	 	                            valid = false;
	 	                        } else {
	 	                            System.out.println("SUCCESS: El nombre del documento coincide");
	 	                        }
	 	                    }
	 	                }

	 	            } else {
	 	                System.out.println("=== Se omite validación de Nombre del Documento (más de 1000) ===");
	 	            }


	 	            // ================= Estatus =================
	 	            System.out.println("=== Validando Estatus ===");
	 	            WebElement est = u.getDriver().findElement(
	 	                By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/table/tbody/tr[1]/td[6]/div/span")
	 	            );
	 	            if (!est.isDisplayed()) valid = false;

	 	            // ================= Descarga =================
	 	            WebElement downl = u.getDriver().findElement(
	 	                By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/table/tbody/tr[1]/td[7]/div/span/mat-icon")
	 	            );
	 	            if (!downl.isDisplayed()) valid = false;

	 	            // ================= Eliminar =================
	 	            WebElement delete = u.getDriver().findElement(
	 	                By.xpath("/html/body/app-root/app-centro-descargas/div/div[3]/div/table/tbody/tr[1]/td[8]/div/span/mat-icon")
	 	            );
	 	            if (!delete.isDisplayed()) valid = false;

	 	            u.highLight(gridCentroDescargas);
	 	            testCase.addScreenShotCurrentStep("");
	 	            return valid;
	 	        }
	 	        return false;
	 	    } catch (Exception e) {
	 	        e.printStackTrace();
	 	        return false;
	 	    }
	 	}

