	 	/**
	 	* Metodo para seleccionar un rango de fechas en la pantalla de Cambios Físicos (Apartado Directos) navegando por meses a partir de la fecha actual.
	 	* @author Alejandro Valdez
	 	* @param meses Cantidad de meses a retroceder en el calendario para establecer el inicio de la búsqueda.
	 	* @return True si se completa la selección del rango (Inicio del mes anterior y fin del mes posterior); lanza evidencia visual en el reporte.
	 	* @date Agosto 2025
	 	*/
	 	public boolean sltFechasCF(int meses){ 
	 	    try {
	 	        if(u.isDisplayed(rangoFechasCF)){
	 	            u.hardWait(1);
	 	            u.highLight(rangoFechasCF);
	 	            u.click(rangoFechasCF);
	 	            
	 	            u.hardWait(1);

	 	            // mover meses atrás
	 	            for (int i = 0; i < meses; i++) {
	 	                u.mouseOverAndClick(btnFlechaIzqCF);
	 	            }

	 	            // FECHA INICIO (primer día habilitado)
	 	            u.mouseOverAndClick(fechaInicioMes);

	 	            // mover meses adelante
	 	            for (int i = 0; i < 4; i++) {
	 	                u.mouseOverAndClick(btnFlechaDerCF);
	 	            }

	 	            // FECHA FIN (NO el mismo locator)
	 	            By fechaFinMes = By.xpath(
	 	                "(//button[contains(@class,'mat-calendar-body-cell') " +
	 	                "and not(contains(@class,'mat-calendar-body-disabled'))])[last()]"
	 	            );
	 	            u.mouseOverAndClick(fechaFinMes);

	 	            testCase.addScreenShotCurrentStep("");
	 	            return true;
	 	        }
	 	        return false;
	 	    } catch (Exception e) {
	 	        System.out.println("[ERROR] Ocurrió un error durante la ejecución: " + e.getMessage());
	 	        return false;
	 	    }
	 	}

