	  /**
	  * Método para obtener el dato de Tienda y Proveedor de la BD de CF Pendientes
	  * aplicando filtro de proveedor_rfc según el perfil del usuario.
	  * @author Alejandro Valdez
	  * @param imprimirDatos Booleano para imprimir evidencia textual.
	  * @param usuario Usuario con el que se inicia sesión.
	  * @return True si se obtienen los datos correctamente; False en caso contrario.
	  * @date Marzo 2026
	  */
	  public boolean obtenerTndyProveedorCambiosFisicosPendientes(boolean screenshot, String usuario) throws Exception {

		    try {
		        boolean result = true;

		        String dbUrl      = GlobalVariables.DB_URL_Cometa;
		        String dbUser     = GlobalVariables.DB_USER_Cometa;
		        String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

		        System.out.println("[DEBUG] Iniciando obtenerTndyProveedorCambiosFisicosPendientes");
		        System.out.println("[DEBUG] Usuario: " + usuario);

		        String PCPERFIL = "select key_value from xxcm_user_keys where short_name = 'PCPERFIL' "
		                + "and usuario_id = (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

		        String PCRFC = "select key_value from xxcm_user_keys where short_name in ('PCRFC','PCPLAZA') "
		                + "and usuario_id in (select usuario_id from xxcm_usuarios where usuario = '" + usuario + "')";

		        try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
		             Statement stmt        = connection.createStatement();
		             ResultSet rsPerfil    = stmt.executeQuery(PCPERFIL)) {

		            if (rsPerfil.next()) {

		                String perfil = rsPerfil.getString("key_value");
		                System.out.println("[DEBUG] Perfil obtenido: " + perfil);

		                String queryFinal = null;

		                // ================= ADMIN / OXXO_OS =================
		                if ("ADMIN".equalsIgnoreCase(perfil) ||
		                    "OXXO_OS".equalsIgnoreCase(perfil)) {

		                    queryFinal =
		                        "SELECT f.supplier_name, f.fuente_de_abasto, p.remision_number " +
		                        "FROM public.get_cambios_fisicos_directos_pendientes_filters() f " +
		                        "INNER JOIN public.get_cambios_fisicos_directos_pendientes_paginated(" +
		                        "  1, 200, " +
		                        "  null, null, null, null, null, null, null, null, null, null, null, null" +
		                        ") p ON f.supplier_name = p.supplier_name " +
		                        "WHERE p.remision_number IS NOT NULL " +
		                        "AND TRIM(p.remision_number) <> '' " +
		                        "ORDER BY p.created_datetime_business " +
		                        "LIMIT 1";

		                // ================= OXXO_PLAZA =================
		                } else if ("OXXO_PLAZA".equalsIgnoreCase(perfil)) {

		                    try (ResultSet rsRFC = stmt.executeQuery(PCRFC)) {

		                        if (rsRFC.next()) {

		                            String filtro = rsRFC.getString("key_value");

		                            queryFinal =
		                                "SELECT f.supplier_name, f.fuente_de_abasto, p.remision_number " +
		                                "FROM public.get_cambios_fisicos_directos_pendientes_filters() f " +
		                                "INNER JOIN public.get_cambios_fisicos_directos_pendientes_paginated(" +
		                                "  1, 20, " +
		                                "  null, null, null, null, null, null, " +
		                                "  ARRAY['" + filtro + "'], " +
		                                "  null, null, null, null, null" +
		                                ") p ON f.supplier_name = p.supplier_name " +
		                                "WHERE p.remision_number IS NOT NULL " +
		                                "AND TRIM(p.remision_number) <> '' " +
		                                "ORDER BY p.created_datetime_business " +
		                                "LIMIT 1";

		                        } else {
		                            return false;
		                        }
		                    }

		                // ================= OTROS PERFILES =================
		                } else {

		                    try (ResultSet rsRFC = stmt.executeQuery(PCRFC)) {

		                        if (rsRFC.next()) {

		                            String filtro = rsRFC.getString("key_value");

		                            queryFinal =
		                                "SELECT f.supplier_name, f.fuente_de_abasto, p.remision_number " +
		                                "FROM public.get_cambios_fisicos_directos_pendientes_filters() f " +
		                                "INNER JOIN public.get_cambios_fisicos_directos_pendientes_paginated(" +
		                                "  1, 20, " +
		                                "  ARRAY['" + filtro + "'], " +
		                                "  null, null, null, null, null, null, null, null, null, null, null" +
		                                ") p ON f.supplier_name = p.supplier_name " +
		                                "WHERE p.remision_number IS NOT NULL " +
		                                "AND TRIM(p.remision_number) <> '' " +
		                                "ORDER BY p.created_datetime_business " +
		                                "LIMIT 1";

		                        } else {
		                            return false;
		                        }
		                    }
		                }

		                if (queryFinal != null) {

		                    System.out.println("[DEBUG] Query Final: " + queryFinal);

		                    try (ResultSet rs = stmt.executeQuery(queryFinal)) {

		                        if (rs.next()) {

		                            proveedor     = rs.getString("supplier_name");
		                            fuenteAbasto  = rs.getString("fuente_de_abasto");
		                            remision      = rs.getString("remision_number");

		                            System.out.println("[DEBUG] Proveedor: " + proveedor);
		                            System.out.println("[DEBUG] Fuente Abasto: " + fuenteAbasto);
		                            System.out.println("[DEBUG] Remisión: " + remision);

		                        } else {
		                            result = false;
		                        }
		                    }
		                }

		            } else {

		                // ================= SIN PERFIL (CEDIS) =================
		                try (ResultSet rsRFC = stmt.executeQuery(PCRFC)) {

		                    if (rsRFC.next()) {

		                        String filtro = rsRFC.getString("key_value");

		                        String queryCed =
		                            "SELECT f.supplier_name, f.fuente_de_abasto, p.remision_number " +
		                            "FROM public.get_cambios_fisicos_directos_pendientes_filters() f " +
		                            "INNER JOIN public.get_cambios_fisicos_directos_pendientes_paginated(" +
		                            "  1, 20, " +
		                            "  ARRAY['" + filtro + "'], " +
		                            "  null, null, null, null, null, null, null, null, null, null, null" +
		                            ") p ON f.supplier_name = p.supplier_name " +
		                            "WHERE p.remision_number IS NOT NULL " +
		                            "AND TRIM(p.remision_number) <> '' " +
		                            "ORDER BY p.created_datetime_business " +
		                            "LIMIT 1";

		                        try (ResultSet rs = stmt.executeQuery(queryCed)) {

		                            if (rs.next()) {

		                                proveedor     = rs.getString("supplier_name");
		                                fuenteAbasto  = rs.getString("fuente_de_abasto");
		                                remision      = rs.getString("remision_number");

		                            } else {
		                                result = false;
		                            }
		                        }

		                    } else {
		                        result = false;
		                    }
		                }
		            }

		            return result;

		        }

		    } catch (Exception e) {
		        e.printStackTrace();
		        testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
		        throw new Exception("Error " + e.getMessage());
		    }
		}
	  
