	 /**
	  * Método para validar que los SKUs mostrados en el grid coinciden con los de la BD.
	  * @author Alejandro Valdez
	  * @param screenshot Si true, agrega evidencia visual
	  * @param proveedor Nombre del proveedor a filtrar en la consulta
	  * @return True si los SKUs del DOM coinciden con los de la BD
	  * @date Marzo 2026
	  */
	 public boolean validarSkusGridConBD(boolean screenshot) throws Exception {

	     try {
	         boolean result = true;
	         
	         u.scrollToElement(By.xpath("//html/body/app-root/app-directos-cambios-fisicos-pendientes/div/div/div[2]/data-grid/div/table/tbody/tr[1]/td[5]"));
	         u.hardWait(1);
	         // ================================
	         // PASO 1: Obtener SKUs del DOM
	         // ================================
	         String xpathSku1 = "//html/body/app-root/app-directos-cambios-fisicos-pendientes/div/div/div[2]/data-grid/div/table/tbody/tr[1]/td[5]";
	         String xpathSku2 = "//html/body/app-root/app-directos-cambios-fisicos-pendientes/div/div/div[2]/data-grid/div/table/tbody/tr[2]/td[5]";

	         WebElement elementoSku1 = u.getDriver().findElement(By.xpath(xpathSku1));
	         WebElement elementoSku2 = u.getDriver().findElement(By.xpath(xpathSku2));

	         String skuDOM1 = elementoSku1.getText().trim();
	         String skuDOM2 = elementoSku2.getText().trim();

	         System.out.println("SKU DOM fila 1: " + skuDOM1);
	         System.out.println("SKU DOM fila 2: " + skuDOM2);

	         if (screenshot) {
	             u.highLight(By.xpath(xpathSku1));
	             u.highLight(By.xpath(xpathSku2));
	             testCase.addScreenShotCurrentStep("SKUs obtenidos del grid");
	         }

	         // ================================
	         // PASO 2: Consultar SKUs en la BD
	         // ================================
	         String dbUrl      = GlobalVariables.DB_URL_Cometa;
	         String dbUser     = GlobalVariables.DB_USER_Cometa;
	         String dbPassword = GlobalVariables.DB_PASSWORD_Cometa;

	         String query =
	             "SELECT sku " +
	             "FROM public.get_cambios_fisicos_directos_pendientes_paginated( " +
	             "  1, 200, " +
	             "  null, null, null, null, null, null, null, null, null, null, null, null " +
	             ") " +
	             "WHERE remision_number IS NOT NULL " +
	             "  AND TRIM(remision_number) <> '' " +
	             "  AND supplier_name = '" + proveedor + "'";

	         List<String> skusBD = new ArrayList<>();

	         try (Connection connection = DriverManager.getConnection(dbUrl, dbUser, dbPassword);
	              Statement stmt       = connection.createStatement();
	              ResultSet rs         = stmt.executeQuery(query)) {

	             while (rs.next()) {
	                 String sku = rs.getString("sku");
	                 if (sku != null) {
	                     skusBD.add(sku.trim());
	                 }
	             }

	         } catch (Exception e) {
	             System.err.println("Error en consulta BD: " + e.getMessage());
	             e.printStackTrace();
	             return false;
	         }

	         // ================================
	         // PASO 3: Comparar DOM vs BD
	         // ================================
	         if (!skusBD.contains(skuDOM1)) {
	             System.out.println("[FAIL] SKU fila 1 no encontrado en BD: " + skuDOM1);
	             result = false;
	         } else {
	             System.out.println("[OK] SKU fila 1 encontrado en BD: " + skuDOM1);
	         }

	         if (!skusBD.contains(skuDOM2)) {
	             System.out.println("[FAIL] SKU fila 2 no encontrado en BD: " + skuDOM2);
	             result = false;
	         } else {
	             System.out.println("[OK] SKU fila 2 encontrado en BD: " + skuDOM2);
	         }

	         if (screenshot) {
	             String evidencia =
	                 "SKU DOM 1: " + skuDOM1 + "\n" +
	                 "SKU DOM 2: " + skuDOM2 + "\n" +
	                 "SKUs en BD: " + skusBD.toString() + "\n" +
	                 "Resultado: " + (result ? "PASS" : "FAIL");
	             testCase.addTextEvidenceCurrentStep(evidencia);
	         }

	         return result;

	     } catch (Exception e) {
	         testCase.addCodeEvidenceCurrentStep("Error: " + e.getMessage());
	         throw new Exception("Error en validarSkusGridConBD: " + e.getMessage());
	     }
	 }

	 /**
	  * Método para obtener la Hora desde el texto del PDF visible.
	  * @author Alejandro Valdez
	  * @return True si se encontró y guardó la hora correctamente. Falso en caso contrario.
	  * @date Marzo 2026
	  */
	 public boolean obtenerHoraDesdeTexto() {
	     try {
	         String texto = capturarTextoPDFVisible();

	         // Buscar hora con formato HH:mm:ss después de "Hora: "
	         Pattern pattern = Pattern.compile("Hora:\\s*(\\d{2}:\\d{2}:\\d{2})");
	         Matcher matcher = pattern.matcher(texto);

	         if (matcher.find()) {
	             hora = matcher.group(1); // Captura solo el valor "11:30:19"
	             System.out.println("Hora obtenida: " + hora);
	             return true;
	         }

	         System.out.println("No se encontró la hora en el texto.");
	         return false;

	     } catch (Exception e) {
	         System.out.println("Error procesando texto: " + e.getMessage());
	         return false;
	     }
	 }
	 
	 /**
	  * Método para comparar la hora obtenida del PDF vs la mostrada en el Excel descargado.
	  * @author Alejandro Valdez
	  * @return True si la hora del PDF coincide con la del Excel.
	  * @date Marzo 2026
	  */
	 public boolean compararHoraConExcel() {
	     try {
	         String rutaArchivo = obtenerUltimoArchivoDescargado();
	         FileInputStream fis = new FileInputStream(new File(rutaArchivo));
	         Workbook workbook   = new XSSFWorkbook(fis);
	         Sheet sheet         = workbook.getSheetAt(0);
	         Row headerRow       = sheet.getRow(0);

	         int colHora = -1;

	         // Buscar columna "Hora" por nombre
	         for (int i = 0; i < headerRow.getLastCellNum(); i++) {
	             String header = headerRow.getCell(i).getStringCellValue().trim();
	             if (header.equalsIgnoreCase("Hora")) {
	                 colHora = i;
	             }
	         }

	         if (colHora == -1) {
	             System.out.println("No se encontró la columna 'Hora' en el Excel.");
	             workbook.close();
	             return false;
	         }

	         // Obtener valor de la primera fila de datos (fila 1)
	         Row dataRow        = sheet.getRow(1);
	         Cell celdaHora     = dataRow.getCell(colHora);

	         // La hora puede venir como String o como tipo fecha en Excel
	         String horaExcel;
	         if (celdaHora.getCellType() == CellType.NUMERIC) {
	             // Excel guarda horas como número, se formatea a HH:mm:ss
	             DataFormatter formatter = new DataFormatter();
	             horaExcel = formatter.formatCellValue(celdaHora).trim();
	         } else {
	             horaExcel = celdaHora.getStringCellValue().trim();
	         }

	         workbook.close();

	         System.out.println("Hora PDF:   " + hora);
	         System.out.println("Hora Excel: " + horaExcel);

	         // Comparación
	         if (hora.equals(horaExcel)) {
	             testCase.addBoldTextEvidenceCurrentStep("La hora coincide correctamente.");
	             testCase.addTextEvidenceCurrentStep("Hora PDF: " + hora + " | Hora Excel: " + horaExcel);
	             return true;
	         } else {
	             System.out.println("[FAIL] Las horas no coinciden.");
	             System.out.println("Hora PDF: " + hora + " | Hora Excel: " + horaExcel);
	             testCase.addTextEvidenceCurrentStep("[FAIL] Hora PDF: " + hora + " | Hora Excel: " + horaExcel);
	             return false;
	         }

	     } catch (Exception e) {
	         System.out.println("Error comparando hora con Excel: " + e.getMessage());
	         return false;
	     }
	 }
	
 	/**
 	 * Método para verificar que columnas no permitidas NO existen en el archivo Excel.
 	 * Valida la ausencia de: "Total de Artículos A Devolver", "Total de piezas a devolver",
 	 * "Valor Total" y "Total Costo".
 	 * @author Alejandro Valdez
 	 * @param rutaExcel Ruta del archivo Excel a auditar.
 	 * @return True si NINGUNA columna prohibida está presente; False si se encuentra alguna.
 	 * @date Marzo 2026
 	 */
 	public boolean validarColumnaNoExistentes() {
 	    try {
 	    	
 	    	String rutaExcel = obtenerUltimoArchivoDescargado();
 	    	
 	        FileInputStream file  = new FileInputStream(new File(rutaExcel));
 	        Workbook workbook     = rutaExcel.endsWith(".xlsx")
 	                              ? new XSSFWorkbook(file)
 	                              : new HSSFWorkbook(file);

 	        Sheet sheet     = workbook.getSheetAt(0);
 	        Row headerRow   = sheet.getRow(0);

 	        if (headerRow == null) {
 	            System.out.println("No se encontró la fila de encabezados.");
 	            workbook.close();
 	            file.close();
 	            return false;
 	        }

 	        // Columnas que NO deben existir
 	        String[] columnasProhibidas = {
 	            "Total de Artículos A Devolver",
 	            "Total de piezas a devolver",
 	            "Valor Total",
 	            "Total Costo"
 	        };

 	        // Obtener todos los encabezados del Excel
 	        List<String> encabezadosEncontrados = new ArrayList<>();
 	        for (Cell cell : headerRow) {
 	            if (cell != null && cell.getCellType() != CellType.BLANK) {
 	                encabezadosEncontrados.add(obtenerValorCelda(cell).trim());
 	            }
 	        }

 	        // Verificar que las columnas prohibidas NO estén presentes
 	        List<String> columnasEncontradas  = new ArrayList<>();
 	        List<String> columnasAusentes     = new ArrayList<>();

 	        for (String prohibida : columnasProhibidas) {
 	            boolean encontrada = false;

 	            for (String encabezado : encabezadosEncontrados) {
 	                if (encabezado.equalsIgnoreCase(prohibida.trim())) {
 	                    encontrada = true;
 	                    columnasEncontradas.add(prohibida); // No debería estar
 	                    break;
 	                }
 	            }

 	            if (!encontrada) {
 	                columnasAusentes.add(prohibida); // Correcto, no está
 	            }
 	        }

 	        workbook.close();
 	        file.close();

 	        // Generar reporte
 	        StringBuilder reporte = new StringBuilder();
 	        reporte.append("=== VALIDACIÓN DE COLUMNAS NO PERMITIDAS ===\n\n");
 	        reporte.append("Total columnas prohibidas verificadas: ").append(columnasProhibidas.length).append("\n");
 	        reporte.append("Columnas prohibidas ausentes (correcto): ").append(columnasAusentes.size()).append("\n");
 	        reporte.append("Columnas prohibidas encontradas (error): ").append(columnasEncontradas.size()).append("\n\n");

 	        if (columnasEncontradas.isEmpty()) {
 	            reporte.append("CORRECTO: Ninguna columna prohibida está presente.\n\n");
 	            reporte.append("Columnas verificadas como ausentes:\n");
 	            for (String ausente : columnasAusentes) {
 	                reporte.append("  -> ").append(ausente).append("\n");
 	            }

 	            System.out.println(reporte.toString());
 	            testCase.addTextEvidenceCurrentStep(reporte.toString());
 	            return true;

 	        } else {
 	            reporte.append("X ERROR: Se encontraron columnas que NO deberían existir:\n");
 	            for (String encontrada : columnasEncontradas) {
 	                reporte.append(" X ").append(encontrada).append("\n");
 	            }

 	            reporte.append("\nColumnas correctamente ausentes:\n");
 	            for (String ausente : columnasAusentes) {
 	                reporte.append("  -> ").append(ausente).append("\n");
 	            }

 	            System.out.println(reporte.toString());
 	            testCase.addTextEvidenceCurrentStep(reporte.toString());
 	            return false;
 	        }

 	    } catch (Exception e) {
 	        System.out.println("Error al validar columnas no permitidas: " + e.getMessage());
 	        e.printStackTrace();
 	        testCase.addTextEvidenceCurrentStep("Error al validar columnas no permitidas: " + e.getMessage());
 	        return false;
 	    }
 	}
 	
